locals {
  prefix_parameter = "/WebsiteCv/production"

  tags = {
    Project     = "Website CV"
    Environment = "production"
  }
}

resource "aws_route53_delegation_set" "name_servers" {
  // Group of 4 name servers, generated by AWS. These four values must be 
  // the same for both the hosted zone and the registered domain.
  reference_name = "WebsiteDNS"
}

// File: outputs.tf
output "delegation_set_id" {
  description = "Use this ID in the website_contents terraform"
  value       = aws_route53_delegation_set.name_servers.id
}

output "delegation_set_name_servers" {
  description = "Set these servers for the registered domain"
  value       = aws_route53_delegation_set.name_servers.name_servers
}

resource "aws_ssm_parameter" "delegation_set_id" {
  name  = "${local.prefix_parameter}/Route53/DelegationSetId"
  type  = "String"
  value = aws_route53_delegation_set.name_servers.id
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls   = false
  block_public_policy = false

  depends_on = [
    aws_s3_bucket_public_access_block.this,
  ]
}

variable "aws_profile" { default = "benchmark" }
variable "bucket_name" { default = "benchmark-bucket-tf5x" }
variable "bucket_force_destroy" { default = true }

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  tags = {
    Name = var.aws_profile
  }

  force_destroy = var.bucket_force_destroy

  # lifecycle {
  #   prevent_destroy = true
  # }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.bucket
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [
    aws_s3_bucket.this,
  ]
}

resource "aws_kms_key" "this" {
  description         = "CMK for the S3 bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.bucket
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

#--------------------------------------------------------------
# This module creates the S3 resource for Cloud trail
#--------------------------------------------------------------
variable "name" { default = "benchmark" }
variable "aws_region" { default = "us-east-1" }

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "${var.name}-cloudtrail-${var.aws_region}"
  force_destroy = true
  policy        = data.aws_iam_policy_document.cloudtrail.json
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket                  = aws_s3_bucket.cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "cloudtrail" {
  description         = "CMK for the CloudTrail log bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

data "aws_iam_policy_document" "cloudtrail" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = ["arn:aws:s3:::${var.name}-cloudtrail-${var.aws_region}"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["arn:aws:s3:::${var.name}-cloudtrail-${var.aws_region}/*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

output "cloudtrail_bucket_id" {
  value = "${aws_s3_bucket.cloudtrail.id}"
}

