## Transit gateway
data "aws_ec2_transit_gateway" "tgw" {
  count = var.existing_tgw == null ? 0 : length(var.existing_tgw) == 0 ? 0 : 1

  id = lookup(var.existing_tgw, "id", null)
  dynamic "filter" {
    for_each = lookup(var.existing_tgw, "filter", {})
    content {
      name   = filter.key
      values = filter.value
    }
  }
}

resource "aws_ec2_transit_gateway" "tgw" {
  count = var.existing_tgw == null ? 1 : length(var.existing_tgw) == 0 ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = var.default_route_table_association
  default_route_table_propagation = var.default_route_table_propagation
  vpn_ecmp_support                = var.vpn_ecmp_support
  dns_support                     = var.dns_support
  description                     = var.tgw_description
  tags = merge(
    {
      Name = var.tgw_name
    },
    lookup(var.tags, "general", {}),
    lookup(var.tags, "tgw", {})
  )
}

## Transit gateway VPC attachment
resource "aws_ec2_transit_gateway_vpc_attachment" "tgw_attachments" {
  for_each = var.tgw_attachments

  subnet_ids                                      = each.value.subnet_ids
  transit_gateway_id                              = local.tgw_id
  vpc_id                                          = each.value.vpc_id
  appliance_mode_support                          = lookup(each.value, "appliance_mode_support", "disable")
  dns_support                                     = lookup(each.value, "dns_support", "enable")
  ipv6_support                                    = lookup(each.value, "ipv6_support", "disable")
  transit_gateway_default_route_table_association = lookup(each.value, "transit_gateway_default_route_table_association", true)
  transit_gateway_default_route_table_propagation = lookup(each.value, "transit_gateway_default_route_table_propagation", true)
  tags = merge(
    {
      Name = each.key
    },
    lookup(var.tags, "general", {}),
    lookup(var.tags, "tgw_attachment", {})
  )
}

// File: outputs.tf
output "tgw" {
  value = local.tgw
}

output "tgw_attachments" {
  value = {
    for tgw_attachment in aws_ec2_transit_gateway_vpc_attachment.tgw_attachments :
    tgw_attachment.tags.Name => tgw_attachment.id
  }
}

// File: variables.tf
## Transit gateway
variable "existing_tgw" {
  description = <<-EOF
    Using existing Transit gateway. 
    If the id is specified, will use this Transit gateway ID. Otherwise, will search the Transit gateway based on the given infomation.
    Options:
        - id         :  ID of the specific Transit gateway.
        - filter     :  Map of the filters. Value should be a list.     
    Example:
    ```
    existing_tgw = {
        filter = {
            "options.amazon-side-asn" = ["64512"]
        }
    }
    ```
    EOF
  type        = any
  default     = null
  validation {
    condition = var.existing_tgw == null ? true : alltrue([
      for k, v in var.existing_tgw : contains([
        "id",
        "filter"
      ], k)
    ])
    error_message = "One or more argument(s) can not be identified, available options: id, filter."
  }
}

variable "tgw_name" {
  description = "Transit gateway name"
  default     = ""
  type        = string
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session. The range is 64512 to 65534 for 16-bit ASNs and 4200000000 to 4294967294 for 32-bit ASNs. Default value: 64512."
  default     = "64512"
  type        = string
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachment requests are automatically accepted. Valid values: disable, enable. Default value: disable."
  default     = "disable"
  type        = string
}

variable "default_route_table_association" {
  description = "Whether resource attachments are automatically associated with the default association route table. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "default_route_table_propagation" {
  description = "Whether resource attachments automatically propagate routes to the default propagation route table. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "dns_support" {
  description = "Whether DNS support is enabled. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "tgw_description" {
  description = "Description of the EC2 Transit Gateway."
  default     = ""
  type        = string
}

## Transit gateway attachment
variable "tgw_attachments" {
  description = <<-EOF
    Transit gateway VPC attachments for the Transit gateway. 
    Format:
    ```
        tgw_attachments = {
            \<Attachment name\> = {
                subnet_ids         = \<Subnet_id\>  
                transit_gateway_id = \<Transit_gateway_id\>
                vpc_id             = \<VPC_id\> 
                \<Option\> = \<Option value\>
            }
        }
    ```
    Options:
        - subnet_ids                                      : (Required|list) Identifiers of EC2 Subnets.
        - vpc_id                                          : (Required|string) Identifier of EC2 VPC.
        - appliance_mode_support                          : (Optional|string) Whether Appliance Mode support is enabled. If enabled, a traffic flow between a source and destination uses the same Availability Zone for the VPC attachment for the lifetime of that flow. Valid values: disable, enable. Default value: disable.
        - dns_support                                     : (Optional|string) Whether DNS support is enabled. Valid values: disable, enable. Default value: enable.
        - ipv6_support                                    : (Optional|string) Whether IPv6 support is enabled. Valid values: disable, enable. Default value: disable.
        - transit_gateway_default_route_table_association : (Optional|bool) Boolean whether the VPC Attachment should be associated with the EC2 Transit Gateway association default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true.
        - transit_gateway_default_route_table_propagation : (Optional|bool) Boolean whether the VPC Attachment should propagate routes with the EC2 Transit Gateway propagation default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true.

    Example:
    ```
    tgw_attachments = {
        security_vpc = {
            subnet_ids         = \<Subnet_id\>  
            vpc_id             = \<VPC_id\> 
        }
    }
    ```
    EOF
  type        = any
  default     = {}
  validation {
    condition = length(var.tgw_attachments) == 0 ? true : alltrue([
      for k, v in var.tgw_attachments : alltrue([
        for sk, sv in v : contains([
          "subnet_ids",
          "vpc_id",
          "appliance_mode_support",
          "dns_support",
          "ipv6_support",
          "transit_gateway_default_route_table_association",
          "transit_gateway_default_route_table_propagation"
        ], sk)
      ])
    ])
    error_message = "One or more argument(s) can not be identified, available options: subnet_ids, vpc_id, appliance_mode_support, dns_support, ipv6_support, transit_gateway_default_route_table_association, transit_gateway_default_route_table_propagation."
  }
}

## Tag related
variable "tags" {
  description = <<-EOF
  Tags that applies to related resources.
  Format:
  ```
    tags = {
        \<Option\> = \<Option value\>
    }
  ```
  Options:
    - general         :  Tags will add to all resources.
    - tgw             :  Tags for Transit gateway.
    - tgw_attachment  :  Tags for Transit gateway attachment.

  Example:
  ```
  tags = {
    general = {
      Created_from = "Terraform"
    },
    tgw = {
      Used_to = "ASG"
    }
  }
  ```
  EOF

  default = {}
  type    = map(map(string))
  validation {
    condition = var.tags == null ? true : alltrue([
      for k, v in var.tags : contains([
        "general",
        "tgw",
        "tgw_attachment"
      ], k)
    ])
    error_message = "One or more argument(s) can not be identified, available options: general, tgw, tgw_attachment."
  }
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
  required_version = ">= 1.3, < 2.0.0"
}

# Setting up the VPC
resource "aws_vpc" "ecs_network" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

# Add Security Group + Rules to the VPC
resource "aws_security_group" "ecs_fargate_sg" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Allow unrestricted outbound egress"
  vpc_id      = aws_vpc.ecs_network.id

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

resource "aws_security_group_rule" "egress" {
  security_group_id = aws_security_group.ecs_fargate_sg.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.ecs_network.cidr_block]
}


# Routes table definition to internet
resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.ecs_network.id

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

resource "aws_route_table" "public_subnets_route_table" {
  vpc_id = aws_vpc.ecs_network.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }

  tags = merge(
    { origin = "dragondrop-compute-module", name = "ecs fargate routes table" },
    var.tags,
  )
}

# Creating a Public Subnet with access to the internet
resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.ecs_network.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false

  tags = merge(
    { origin = "dragondrop-compute-module", name = "ecs fargate routes table" },
    var.tags,
  )
}

resource "aws_route_table_association" "link_public_access_route_table" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_subnets_route_table.id
}

output "security_group" {
  description = "Security group for ECS fargate task networking."
  value       = aws_security_group.ecs_fargate_sg.id
}

output "subnet" {
  description = "Subnet within which the ECS Fargate Task is placed."
  value       = aws_subnet.public_subnet.id
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

// File: aggregate_metrics_table.tf
resource "aws_dynamodb_table" "aggregate_metrics" {

  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  server_side_encryption {
    enabled = true
  }

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

}

// File: outputs.tf
output "raw_metrics_name" {
  value = aws_dynamodb_table.raw_metrics.id
}

output "raw_metrics_arn" {
  value = aws_dynamodb_table.raw_metrics.arn
}

output "raw_metrics_stream_arn" {
  value = aws_dynamodb_table.raw_metrics.stream_arn
}

output "aggregate_metrics_name" {
  value = aws_dynamodb_table.aggregate_metrics.id
}

output "aggregate_metrics_arn" {
  value = aws_dynamodb_table.aggregate_metrics.arn
}

// File: raw_metrics.table.tf
resource "aws_dynamodb_table" "raw_metrics" {
  # checkov:skip=CKV_AWS_28:RAW metrics are discarded after 24 hours (no backup required)
  name         = "raw_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  server_side_encryption {
    enabled = true
  }

  attribute {
    name = "uuid"
    type = "S"
  }

}

data "aws_ami" "latest_amazon_linux" {
  owners      = ["amazon"]
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Self-contained VPC (replacing the default-VPC dependency -- AWS-0101).
resource "aws_vpc" "web" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.web.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = element(data.aws_availability_zones.available.names, 0)
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "web" {
  vpc_id = aws_vpc.web.id
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.web.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.web.id
  }
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_instance" "web" {
  ami                         = data.aws_ami.latest_amazon_linux.id
  instance_type               = var.server_size
  subnet_id                   = aws_subnet.web.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = true
  user_data                   = <<EOF
#!/bin/bash
yum -y update
yum -y install httpd
myip=`curl http://169.254.169.254/latest/meta-data/local-ipv4`
echo "<h2>${var.server_name}-WebServer with IP: $myip</h2><br>Build by Terraform!"  >  /var/www/html/index.html
sudo service httpd start
chkconfig httpd on
EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name  = "${var.server_name}-WebServer"
    Owner = "Denis Astahov"
  }
}

resource "aws_security_group" "web" {
  name_prefix = "${var.server_name}-WebServer-SG"
  vpc_id      = aws_vpc.web.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.web.cidr_block]
  }

  tags = {
    Name  = "${var.server_name}-WebServer SecurityGroup"
    Owner = "Denis Astahov"
  }
}

resource "aws_eip" "web" {
 domain    = "vpc" # Need to add in new AWS Provider version
  instance = aws_instance.web.id
  tags = {
    Name  = "${var.server_name}-WebServer-IP"
    Owner = "Denis Astahov"
  }
}

output "web_public_ip" {
  value = aws_eip.web.public_ip
}

variable "server_name" {
  description = "Name for WebServer"
  type        = string
  default     = "demo"
}


variable "server_size" {
  description = "Server Size for WebServer"
  type        = string
  default     = "t3.micro"
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "sns" {
  description             = "CMK for this scenario's SNS topics"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_sns_topic" "test" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns.id
}

resource "aws_sns_topic_policy" "default" {
  arn = aws_sns_topic.test.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic" "test2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns.id
}

resource "aws_sns_topic_policy" "default2" {
  arn = aws_sns_topic.test2.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    actions = [
      "SNS:Subscribe",
      "SNS:SetTopicAttributes",
      "SNS:RemovePermission",
      "SNS:Receive",
      "SNS:Publish",
      "SNS:ListSubscriptionsByTopic",
      "SNS:GetTopicAttributes",
      "SNS:DeleteTopic",
      "SNS:AddPermission",
    ]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values = []
    }

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [
      aws_sns_topic.test.arn,
    ]

    sid = "__default_statement_ID"
  }
}

resource "aws_sns_topic" "user_updates" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns.id
  delivery_policy = <<EOF
{
  "http": {
    "defaultHealthyRetryPolicy": {
      "minDelayTarget": 20,
      "maxDelayTarget": 20,
      "numRetries": 3,
      "numMaxDelayRetries": 0,
      "numNoDelayRetries": 0,
      "numMinDelayRetries": 0,
      "backoffFunction": "linear"
    },
    "disableSubscriptionOverrides": false,
    "defaultThrottlePolicy": {
      "maxReceivesPerSecond": 1
    }
  }
}
EOF
}

