  profile                 = "default"
}
provider "null" {}
provider "external" {}

// File: az.tf
data "aws_availability_zones" "az" {
  state = "available"
}

// File: my-eip.tf
resource "aws_eip" "my-eip" {
  public_ipv4_pool = "amazon"
