terraform {
  required_version = ">= 0.14.11"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

locals {
  create_iam_group                                          = var.create_iam_group
  create_iam_read_only_and_s3_full_access_policy            = var.create_iam_read_only_and_s3_full_access_policy
  create_iam_read_only_and_s3_full_access_policy_attachment = var.create_iam_read_only_and_s3_full_access_policy_attachment
  create_iam_users                                          = var.create_iam_users
  create_iam_ec2_get_console_screenshot_policy              = var.create_iam_ec2_get_console_screenshot_policy
  create_iam_ec2_get_console_screenshot_policy_attachment   = var.create_iam_ec2_get_console_screenshot_policy_attachment
  create_iam_user_group_membership                          = var.create_iam_user_group_membership
  create_iam_role_with_policy                               = var.create_iam_role_with_policy
}

resource "aws_iam_group" "developers_group" {
  count = local.create_iam_group ? 1 : 0
  name  = var.group_info["name"]
  path  = var.group_info["path"]
}

data "aws_iam_policy_document" "iam_read_only_and_s3_full_access" {

  dynamic "statement" {
    for_each = var.iam_read_only_and_s3_full_access
    content {
      actions   = statement.value["actions"]
      resources = statement.value["resources"]
      effect    = statement.value["effect"]
    }
  }
}

resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count       = local.create_iam_read_only_and_s3_full_access_policy ? 1 : 0
  name        = "iam_read_only_and_s3_full_access"
  path        = "/"
  description = "Read Only Access to IAM and Full Access to S3"
  policy      = data.aws_iam_policy_document.iam_read_only_and_s3_full_access.json
}

resource "aws_iam_group_policy_attachment" "group_policy_attachment" {
  count      = local.create_iam_group && local.create_iam_read_only_and_s3_full_access_policy && local.create_iam_read_only_and_s3_full_access_policy_attachment ? 1 : 0
  group      = aws_iam_group.developers_group[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

resource "aws_iam_user" "users" {
  count = local.create_iam_users ? length(var.users) : 0
  name  = var.users[count.index]["name"]
  path  = var.users[count.index]["path"]

  tags = {
    user_created_by = "terraform"
  }
}

data "aws_iam_policy_document" "ec2_get_console_screenshot" {

  dynamic "statement" {
    for_each = var.ec2_get_console_screenshot
    content {
      actions   = statement.value["actions"]
      resources = statement.value["resources"]
      effect    = statement.value["effect"]
    }
  }
}

resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count       = local.create_iam_ec2_get_console_screenshot_policy ? 1 : 0
  name        = "ec2_get_console_screenshot"
  path        = "/"
  description = "EC2 Get Console Screenshot"
  policy      = data.aws_iam_policy_document.ec2_get_console_screenshot.json
}

resource "aws_iam_user_policy_attachment" "user_policy_attachment" {
  count      = local.create_iam_users && local.create_iam_ec2_get_console_screenshot_policy && local.create_iam_ec2_get_console_screenshot_policy_attachment ? length(var.users) : 0
  user       = var.users[count.index]["name"]
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

resource "aws_iam_user_group_membership" "group_membership" {

  count = local.create_iam_users && local.create_iam_group && local.create_iam_user_group_membership ? length(var.users) : 0
  user  = var.users[count.index]["name"]

  groups = [
    aws_iam_group.developers_group[0].name,
  ]
}

data "aws_iam_policy_document" "instance_assume_role_policy" {

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy" "iam_read_only_access" {
  arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_role" "instance" {
  count               = local.create_iam_role_with_policy ? 1 : 0
  name                = "instance_role"
  path                = "/"
  assume_role_policy  = data.aws_iam_policy_document.instance_assume_role_policy.json
  managed_policy_arns = [data.aws_iam_policy.iam_read_only_access.arn]
}



variable "create_iam_group" {
  type    = bool
  default = true
}

variable "create_iam_read_only_and_s3_full_access_policy" {
  type    = bool
  default = true
}

variable "create_iam_read_only_and_s3_full_access_policy_attachment" {
  type    = bool
  default = true
}

variable "create_iam_users" {
  type    = bool
  default = true
}

variable "create_iam_ec2_get_console_screenshot_policy" {
  type    = bool
  default = true
}

variable "create_iam_ec2_get_console_screenshot_policy_attachment" {
  type    = bool
  default = true
}

variable "create_iam_user_group_membership" {
  type    = bool
  default = true
}

variable "create_iam_role_with_policy" {
  type    = bool
  default = true
}

variable "group_info" {
  type = map(string)
  default = {
    name = "developers"
    path = "/"
  }
}

variable "iam_read_only_and_s3_full_access" {
  type = map(object({
    actions   = list(string)
    resources = list(string)
    effect    = string
  }))
  default = {
    iam_read_only = {
      actions = [
        "iam:Get*",
        "iam:List*"
      ]
      resources = ["*"]
      effect    = "Allow"
    },
    s3_full_access = {
      actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket", "s3:GetBucketLocation", "s3:ListAllMyBuckets"]
      resources = ["*"]
      effect    = "Allow"
    }
  }
}

variable "users" {
  type = list(map(string))
  default = [
    {
      name = "jack"
      path = "/"
    },
    {
      name = "jones"
      path = "/"
    }
  ]
}

variable "ec2_get_console_screenshot" {
  type = map(object({
    actions   = list(string)
    resources = list(string)
    effect    = string
  }))
  default = {
    ec2_get_console_screenshot = {
      actions = [
        "ec2:GetConsoleScreenshot"
      ]
      resources = ["*"]
      effect    = "Allow"
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.20"
    }
  }
}

provider "aws" {
  region = local.region
}

data "aws_availability_zones" "available" {}

locals {
  cluster_name = format("%s-%s", basename(path.cwd), "shared")
  region       = "eu-west-1"

  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  tags = {
    Blueprint  = local.cluster_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

################################################################################
# VPC
################################################################################

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.cluster_name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 4, k)]
  public_subnets  = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 8, k + 48)]

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

################################################################################
# Cluster 1 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Allow communication from cluster2 SG to cluster1 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster1_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster1_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  ip_protocol                   = "-1"
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
}

################################################################################
# Cluster 2 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Allow communication from cluster1 SG to cluster2 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster2_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster2_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  ip_protocol                   = "-1"
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
}

################################################################################
# cross SG  ingress rules Cluster 2 allow to cluster 1
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster2_to_cluster_1" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

################################################################################
# cross SG  ingress rules Cluster 1 allow to cluster 2
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster1_to_cluster_2" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

output "vpc_id" {
  description = "Amazon EKS VPC ID"
  value       = module.vpc.vpc_id
}

output "subnet_ids" {
  description = "Amazon EKS Subnet IDs"
  value       = module.vpc.private_subnets
}

output "vpc_cidr" {
  description = "Amazon EKS VPC CIDR Block."
  value       = local.vpc_cidr
}

output "cluster1_additional_sg_id" {
  description = "Cluster1 additional SG"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "Cluster2 additional SG"
  value       = aws_security_group.cluster2_additional_sg.id
}



terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.47"
    }
  }

  # ##  Used for end-to-end testing on project; update to suit your needs
  # backend "s3" {
  #   bucket = "<BUCKET_NAME>"
  #   region = "<AWS_REGION>"
  #   key    = "e2e/istio-multi-cluster-vpc/terraform.tfstate"
  # }
}

// File: clients.tf
resource "aws_cognito_user_pool_client" "client" {
  for_each = toset(var.clients)

  name            = each.value
  generate_secret = var.generate_secret
  user_pool_id    = aws_cognito_user_pool.pool.id

  access_token_validity                = var.access_token_validity
  allowed_oauth_flows_user_pool_client = var.allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.enable_token_revocation
  explicit_auth_flows                  = var.explicit_auth_flows
  id_token_validity                    = var.id_token_validity
  prevent_user_existence_errors        = var.prevent_user_existence_errors
  read_attributes                      = var.read_attributes
  refresh_token_validity               = var.refresh_token_validity
  write_attributes                     = var.write_attributes
  callback_urls                        = var.callback_urls
  logout_urls                          = var.logout_urls
  allowed_oauth_flows                  = var.allowed_oauth_flows
  allowed_oauth_scopes                 = var.allowed_oauth_scopes
  supported_identity_providers         = var.supported_identity_providers
  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }
}

// File: domain.tf
resource "aws_cognito_user_pool_domain" "main" {
  count = (var.domain != "") ? 1 : 0

  domain          = var.domain
  certificate_arn = var.cert_arn
  user_pool_id    = aws_cognito_user_pool.pool.id
}

resource "aws_route53_record" "auth-cognito-A" {
  count = var.create_route53_record ? 1 : 0

  name    = aws_cognito_user_pool_domain.main[0].domain
  type    = "A"
  zone_id = var.zone_id
  alias {
    evaluate_target_health = false
    name                   = aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn
    # This zone_id is fixed
    zone_id = "Z2FDTNDATAQYW2"
  }
}

// File: group.tf
resource "aws_cognito_user_group" "group" {
  count = (var.user_group != "") ? 1 : 0

  name         = var.user_group
  user_pool_id = aws_cognito_user_pool.pool.id
  precedence   = var.precedence
  role_arn     = var.role_arn
}

// File: output.tf
output "arn" {
  value       = aws_cognito_user_pool.pool.arn
  description = "AWS Cognito User Pool ARN"
}

output "clients_id" {
  value = values(tomap(aws_cognito_user_pool_client.client)).*.id
}

// File: pool.tf
resource "aws_cognito_user_pool" "pool" {
  name = var.name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "sms_configuration" {
    for_each = (var.sms_configuration.external_id != "" && var.sms_configuration.sns_caller_arn != "") ? [1] : []

    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  verification_message_template {
    email_message_by_link = var.verification_message_template.email_message_by_link
    email_subject_by_link = var.verification_message_template.email_subject_by_link
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanism

      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.allow_admin_create_user_only

    invite_message_template {
      email_message = var.invite_message_template.email_message
      email_subject = var.invite_message_template.email_subject
      sms_message   = var.invite_message_template.sms_message
    }
  }

  dynamic "device_configuration" {
    for_each = (var.challenge_required_on_new_device != null || var.device_only_remembered_on_user_prompt != null) ? [{
      challenge_required_on_new_device      = var.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_only_remembered_on_user_prompt
    }] : []

    content {
      challenge_required_on_new_device      = device_configuration.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) != 0 ? [1] : []

    content {
      kms_key_id                     = try(var.lambda_config.kms_key_id, null)
      create_auth_challenge          = try(var.lambda_config.create_auth_challenge, null)
      define_auth_challenge          = try(var.lambda_config.define_auth_challenge, null)
      verify_auth_challenge_response = try(var.lambda_config.verify_auth_challenge_response, null)

      dynamic "custom_email_sender" {
        for_each = (try(var.lambda_config.custom_email_sender.lambda_arn, null) != null && try(var.lambda_config.custom_email_sender.lambda_version, null) != null) ? [1] : []

        content {
          lambda_arn     = var.lambda_config.custom_email_sender.lambda_arn
          lambda_version = var.lambda_config.custom_email_sender.lambda_version
        }
      }
    }
  }

  dynamic "schema" {
    for_each = [for item in var.schema : item if(try(item.string_attribute_constraints.max_length, null) != null && try(item.string_attribute_constraints.min_length, null) != null)]

    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable                  = schema.value.mutable
      name                     = schema.value.name
      required                 = schema.value.required

      string_attribute_constraints {
        max_length = schema.value.string_attribute_constraints.max_length
        min_length = schema.value.string_attribute_constraints.min_length
      }
    }
  }

  dynamic "schema" {
    for_each = [for item in var.schema : item if(try(item.string_attribute_constraints.max_length, null) == null || try(item.string_attribute_constraints.min_length, null) == null)]

    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable                  = schema.value.mutable
      name                     = schema.value.name
      required                 = schema.value.required

      string_attribute_constraints {}
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = (var.software_token_mfa_configuration == true || var.software_token_mfa_configuration == false) ? [1] : []

    content {
      enabled = var.software_token_mfa_configuration
    }
  }

  dynamic "username_configuration" {
    for_each = (var.case_sensitive == true || var.case_sensitive == false) ? [1] : []

    content {
      case_sensitive = var.case_sensitive
    }
  }

  lifecycle {
    ignore_changes = [
      estimated_number_of_users
    ]
  }
}

