// File: main.tf
resource "aws_kms_key" "aws_backup" {
  enable_key_rotation = true
  tags                = var.tags
}

resource "aws_backup_vault" "aws_backup" {
  name        = var.backup_vault_name
  kms_key_arn = aws_kms_key.aws_backup.arn
  tags        = var.tags
}

resource "aws_backup_selection" "daily" {
  iam_role_arn = aws_iam_role.aws_backup.arn
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  resources    = ["*"]
  condition {
    string_like {
      key   = "aws:ResourceTag/${var.selection_tag}"
      value = "*daily*"
    }
  }
}

resource "aws_backup_plan" "daily" {
  name = "${var.backup_vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.aws_backup.name
    schedule                 = var.daily_cron_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = var.daily_backup_lifecycledays
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }
}

resource "aws_backup_selection" "weekly" {
  iam_role_arn = aws_iam_role.aws_backup.arn
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  resources    = ["*"]
  condition {
    string_like {
      key   = "aws:ResourceTag/${var.selection_tag}"
      value = "*weekly*"
    }
  }
}

resource "aws_backup_plan" "weekly" {
  name = "${var.backup_vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.aws_backup.name
    schedule          = var.weekly_cron_schedule

    lifecycle {
      delete_after = var.weekly_backup_lifecycledays
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }
}

resource "aws_backup_selection" "monthly" {
  iam_role_arn = aws_iam_role.aws_backup.arn
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  resources    = ["*"]
  condition {
    string_like {
      key   = "aws:ResourceTag/${var.selection_tag}"
      value = "*monthly*"
    }
  }
}

resource "aws_backup_plan" "monthly" {
  name = "${var.backup_vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.aws_backup.name
    schedule          = var.monthly_cron_schedule

    lifecycle {
      delete_after = var.monthly_backup_lifecycledays
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }
}

resource "aws_iam_role" "aws_backup" {
  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": ["sts:AssumeRole"],
      "Effect": "allow",
      "Principal": {
        "Service": ["backup.amazonaws.com"]
      }
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "aws_backup" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.aws_backup.name
}

resource "aws_backup_vault_notifications" "vault_notifications" {
  count               = var.backup_notifications_enabled ? 1 : 0
  backup_vault_name   = aws_backup_vault.aws_backup.name
  sns_topic_arn       = var.backup_notifications_topic
  backup_vault_events = var.backup_notifications_events
}

// File: provider.tf
terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: variables.tf
variable "tags" {
  type        = map(any)
  default     = null
  description = "Tags to tag all resources with"
}

variable "selection_tag" {
  default     = "backup"
  description = "Tag that is used to target resources to backup"
  type        = string
}

variable "backup_vault_name" {
  default     = "my-backup-vault"
  description = "Name of the backup vault"
  type        = string
}

variable "daily_cron_schedule" {
  default     = "cron(0 12 ? * * *)"
  type        = string
  description = "Cron schedule for daily backups"
}

variable "weekly_cron_schedule" {
  default     = "cron(0 12 ? * 1 *)"
  type        = string
  description = "Cron schedule for weekly backups"
}

variable "monthly_cron_schedule" {
  default     = "cron(0 12 1 * ? *)"
  type        = string
  description = "Cron schedule for monthly backups"
}

variable "daily_backup_lifecycledays" {
  default     = 7
  type        = string
  description = "How many days to store daily backups"
}

variable "weekly_backup_lifecycledays" {
  default     = 31
  type        = string
  description = "How many days to store weekly backups"
}

variable "monthly_backup_lifecycledays" {
  default     = 366
  type        = string
  description = "How many days to store monthly backups"
}

variable "backup_notifications_topic" {
  type        = string
  default     = null
  description = "SNS Topic for backup alerts eg. failed backup."
}

variable "backup_notifications_enabled" {
  type        = bool
  default     = false
  description = "Enable if you want to receive notifications. Requires backup_notifications_topic to be set"
}

variable "enable_continuous_backup" {
  type        = bool
  default     = false
  description = "Enable continuous backup for supported resources"
}

variable "backup_notifications_events" {
  type = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
  description = "Default list of events"
}

# Global 
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}
data "aws_caller_identity" "current" {}

output "region" {
  value = data.aws_region.current.description
}

output "account_id" {
  value = data.aws_caller_identity.current.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public_subnets[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private_subnets[*].id
}

output "vpc_cidr" {
  value = var.vpc_cidr
}

output "public_subnet_cidrs" {
  value = var.public_subnet_cidrs
}

output "private_subnet_cidrs" {
  value = var.private_subnet_cidrs
}

# Public subnets
resource "aws_subnet" "public_subnets" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name   = "${var.env}-public-subnet-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table" "public_subnets" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name   = "${var.env}-route-public-subnets"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table_association" "public_routes" {
  count          = length(aws_subnet.public_subnets[*].id)
  route_table_id = aws_route_table.public_subnets.id
  subnet_id      = element(aws_subnet.public_subnets[*].id, count.index)
}

# Private subnets
resource "aws_subnet" "private_subnets" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.common_tags, {
    Name   = "${var.env}-private-subnet-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  tags = merge(var.common_tags, {
    Name   = "${var.env}-nat-eip-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_nat_gateway" "nat" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = element(aws_subnet.public_subnets[*].id, count.index)

  tags = merge(var.common_tags, {
    Name   = "${var.env}-nat-gw-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table" "private_subnets" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(var.common_tags, {
    Name   = "${var.env}-route-private-subnets-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table_association" "private_routes" {
  count          = length(aws_subnet.private_subnets[*].id)
  route_table_id = aws_route_table.private_subnets[count.index].id
  subnet_id      = element(aws_subnet.private_subnets[*].id, count.index)
}

variable "region" {
  default = "us-east-1"
}

variable "env" {
  default = "test"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  default = [
    "10.0.10.0/24",
    "10.0.11.0/24"
  ]
}

variable "private_subnet_cidrs" {
  default = [
    "10.0.20.0/24",
    "10.0.21.0/24"
  ]
}

variable "common_tags" {
  default = {
    Owner: "Valerii Vasianovych"
    Project: "Terraform AWS"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = "Region: ${var.region}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name   = "${var.env}-igw"
    Region = "Region: ${var.region}"
  })
}

// File: eks_roles.tf
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

# IAM role to allow the Kubernetes control plane to manage AWS resources on your behalf. This property cannot be changed after the cluster is created.
resource "aws_iam_role" "this" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy_attachment" "AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.this.name
}

# Optionally, enable Security Groups for Pods
# Reference: https://docs.aws.amazon.com/eks/latest/userguide/security-groups-for-pods.html
resource "aws_iam_role_policy_attachment" "AmazonEKSVPCResourceController" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.this.name
}

// File: main.tf
resource "aws_eks_cluster" "this" {
  name     = var.cluster_name
  role_arn = aws_iam_role.this.arn
  count    = var.create_eks ? 1 : 0
  version  = var.cluster_version

  vpc_config {
    subnet_ids = coalescelist(var.control_plane_subnet_ids, var.subnet_ids)
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }


  # Ensure that IAM Role permissions are created before and deleted after EKS Cluster handling.
  # Otherwise, EKS will not be able to properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.AmazonEKSVPCResourceController,
  ]
}

