// File: defaults.tf
### default values

### aws partitions
module "aws" {
  source = "Young-ook/spinnaker/aws//modules/aws-partitions"
}

locals {
  aws = {
    dns       = module.aws.partition.dns_suffix
    partition = module.aws.partition.partition
    region    = module.aws.region.name
  }
}

locals {
  default_rule = {
    description         = null
    schedule_expression = null
    event_pattern       = null
  }
  default_bus = {
    event_source_name = null
  }
}

// File: labels.tf
### frigga name
module "frigga" {
  source  = "Young-ook/spinnaker/aws//modules/frigga"
  version = "2.3.5"
  name    = var.name == null || var.name == "" ? "default" : var.name
  petname = false
}

locals {
  name = module.frigga.name
  default-tags = merge(
    { "terraform.io" = "managed" },
    { "Name" = local.name },
  )
}

// File: main.tf
### features
locals {
  custom_bus = local.name != "default" ? true : false
}

### event rules
resource "aws_cloudwatch_event_bus" "bus" {
  for_each          = toset(local.custom_bus ? ["custom"] : [])
  name              = local.name
  tags              = merge(local.default-tags, var.tags)
  event_source_name = lookup(var.bus, "event_source_name", local.default_bus.event_source_name)
}

### event rules
### At least one of `schedule_expression` or `event_pattern` is required.
resource "aws_cloudwatch_event_rule" "rule" {
  for_each            = { for r in var.rules : r.name => r }
  name                = each.key
  tags                = merge(local.default-tags, var.tags)
  description         = lookup(each.value, "description", local.default_rule.description)
  event_bus_name      = local.custom_bus ? aws_cloudwatch_event_bus.bus["custom"].id : null
  event_pattern       = lookup(each.value, "event_pattern", local.default_rule.event_pattern)
  schedule_expression = lookup(each.value, "schedule_expression", local.default_rule.schedule_expression)
}

### security/policy
resource "aws_iam_role" "invoke" {
  name = join("-", [local.name, "invoke"])
  tags = merge(local.default-tags, var.tags)
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = format("events.%s", local.aws.dns)
      }
    }]
  })

  inline_policy {
    name = join("-", [local.name, "invoke-targets"])
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [{
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution",
        ]
        Effect   = "Allow"
        Resource = ["*"]
      }]
    })
  }
}

### https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-targets.html
### choreography/route
resource "aws_cloudwatch_event_target" "target" {
  depends_on     = [aws_cloudwatch_event_rule.rule]
  for_each       = { for t in var.targets : t.name => t }
  event_bus_name = local.custom_bus ? aws_cloudwatch_event_bus.bus["custom"].id : null
  rule           = lookup(each.value, "rule")
  arn            = lookup(each.value, "arn")
  role_arn       = strcontains(lookup(each.value, "arn", ""), "stateMachine") ? aws_iam_role.invoke.arn : null
}

// File: outputs.tf
output "bus" {
  description = "The attributes of generated event bridge bus"
  value       = aws_cloudwatch_event_bus.bus
}

output "rules" {
  description = "The attributes of generated event bridge rules"
  value       = aws_cloudwatch_event_rule.rule
}

// File: variables.tf
### event bridge
variable "bus" {
  description = "Event bus configuration"
  default     = {}
  validation {
    condition     = var.bus != null
    error_message = "Configuration for custom eventbridge bus must not be null."
  }
}

variable "rules" {
  description = "A configuration list of event rules"
  default     = []
  validation {
    condition     = var.rules != null
    error_message = "List of eventbridge rules is not valid."
  }
}

variable "targets" {
  description = "A configuration list of event route target definitions"
  type        = any
  default     = []
  validation {
    condition     = var.targets != null
    error_message = "List of eventbridge rule targets is not valid."
  }
}

### description
variable "name" {
  description = "Event bus name"
  type        = string
  default     = null
}

### tags
variable "tags" {
  description = "The key-value maps for tagging"
  type        = map(string)
  default     = {}
}

// File: _data.tf
data "aws_caller_identity" "current" {}

// File: iam.tf
resource "aws_iam_role" "backup_role" {
  name_prefix        = "aws-backup-"
  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": ["sts:AssumeRole"],
      "Effect": "allow",
      "Principal": {
        "Service": ["backup.amazonaws.com"]
      }
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "backup_policy_attach" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

// File: main.tf
# AWS Backup vault
resource "aws_backup_vault" "backup_vault" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.vault_kms_key_arn
  tags = {
    Job = "${var.name}-backup"
  }
}

resource "aws_backup_vault_policy" "backup_vault" {
  count             = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.backup_vault.name
  policy            = var.vault_policy
}

# AWS Backup plan
resource "aws_backup_plan" "backup_plan" {
  name = "plan-${var.name}-backup"
  tags = {
    Job = "${var.name}-backup"
  }

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = var.rule_schedule
    start_window      = var.rule_start_window
    completion_window = var.rule_completion_window

    lifecycle {
      cold_storage_after = var.rule_lifecycle_cold_storage_after
      delete_after       = var.rule_lifecycle_delete_after
    }
    recovery_point_tags = {
      Job = "${var.name}-backup"
    }

    dynamic "copy_action" {
      for_each = var.rule_copy_action_destination_vault
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after
          delete_after       = copy_action.value.delete_after
        }
      }
    }
  }
}

# AWS Backup selection - tag
resource "aws_backup_selection" "backup_selection" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup_role.arn

  plan_id = aws_backup_plan.backup_plan.id

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }

  condition {}
}

# AWS Backup vault notification
resource "aws_backup_vault_notifications" "default" {
  count               = var.vault_notification_sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.backup_vault.name
  sns_topic_arn       = var.vault_notification_sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

// File: variables.tf
#
# AWS Backup vault
#
variable "name" {
  description = "Name of the backup vault to create."
  type        = string
  default     = ""
}

variable "vault_kms_key_arn" {
  description = "The server-side encryption key that is used to protect your backups"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "The backup vault access policy document in JSON format"
  type        = string
  default     = ""
}

variable "vault_notification_sns_topic_arn" {
  description = "he Amazon Resource Name (ARN) that specifies the topic for a backup vaults events"
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "An array of events that indicate the status of jobs to back up resources to the backup vault"
  type        = list(any)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

# Default rule
variable "rule_schedule" {
  description = "A CRON expression specifying when AWS Backup initiates a backup job"
  type        = string
  default     = null
}

variable "rule_start_window" {
  description = "The amount of time in minutes before beginning a backup"
  type        = number
  default     = 60
}

variable "rule_completion_window" {
  description = "The amount of time AWS Backup attempts a backup before canceling the job and returning an error"
  type        = number
  default     = 120
}

# Rule lifecycle
variable "rule_lifecycle_cold_storage_after" {
  description = "Specifies the number of days after creation that a recovery point is moved to cold storage"
  type        = number
  default     = 30
}

variable "rule_lifecycle_delete_after" {
  description = "Specifies the number of days after creation that a recovery point is deleted. Must be 90 days greater than `cold_storage_after`"
  type        = number
  default     = 120
}

variable "rule_copy_action_destination_vault" {
  description = "Configuration block(s) with copy operation settings"
  type        = map(any)
  default     = {}
}

# Selection
variable "selection_resources" {
  description = "An array of strings that either contain Amazon Resource Names (ARNs) or match patterns of resources to assign to a backup plan"
  type        = list(any)
  default     = []
}

variable "selection_tag_type" {
  description = "An operation, such as StringEquals, that is applied to a key-value pair used to filter resources in a selection"
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "The key in a key-value pair"
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "The value in a key-value pair"
  type        = string
  default     = "true"
}

// File: versions.tf
terraform {
  required_version = ">= 0.12.0"
}

// File: _terraform.tf
terraform {
  required_version = "~> 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.64"
    }
  }
}

// File: main.tf
resource "aws_iam_role_policy" "tf-policy" {
  name = "WizCustomPolicy"
  role = aws_iam_role.user-role-tf.id

  policy = jsonencode({
    "Statement" : [
      {
        "Action" : [
          "acm:GetCertificate",
          "apigateway:GET",
          "backup:DescribeGlobalSettings",
          "backup:GetBackupVaultAccessPolicy",
          "backup:GetBackupVaultNotifications",
          "backup:ListBackupVaults",
          "backup:ListTags",
          "cloudtrail:GetInsightSelectors",
          "cloudtrail:ListTrails",
          "codebuild:BatchGetProjects",
          "codebuild:GetResourcePolicy",
          "codebuild:ListProjects",
          "cognito-identity:DescribeIdentityPool",
          "connect:ListInstances",
          "connect:ListInstanceAttributes",
          "connect:ListInstanceStorageConfigs",
          "connect:ListSecurityKeys",
          "connect:ListLexBots",
          "connect:ListLambdaFunctions",
          "connect:ListApprovedOrigins",
          "connect:ListIntegrationAssociations",
          "dynamodb:DescribeExport",
          "dynamodb:DescribeKinesisStreamingDestination",
          "dynamodb:ListExports",
          "ec2:GetEbsEncryptionByDefault",
          "ec2:SearchTransitGatewayRoutes",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:GetAuthorizationToken",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListTagsForResource",
          "ecr:GetRegistryPolicy",
          "ecr:DescribeRegistry",
          "ecr-public:BatchGetImage",
          "ecr-public:DescribeImages",
          "ecr-public:GetAuthorizationToken",
          "ecr-public:GetDownloadUrlForLayer",
          "ecr-public:ListTagsForResource",
          "ecr-public:GetRegistryPolicy",
          "eks:ListTagsForResource",
          "elasticfilesystem:DescribeAccessPoints",
          "elasticfilesystem:DescribeFileSystemPolicy",
          "elasticmapreduce:GetAutoTerminationPolicy",
          "elasticmapreduce:GetManagedScalingPolicy",
          "emr-serverless:ListApplications",
          "emr-serverless:ListJobRuns",
          "ssm:GetDocument",
          "ssm:GetServiceSetting",
          "glacier:GetDataRetrievalPolicy",
          "glacier:GetVaultLock",
          "glue:GetConnection",
          "glue:GetSecurityConfiguration",
          "glue:GetTags",
          "health:DescribeAffectedAccountsForOrganization",
          "health:DescribeAffectedEntities",
          "health:DescribeAffectedEntitiesForOrganization",
          "health:DescribeEntityAggregates",
          "health:DescribeEventAggregates",
          "health:DescribeEventDetails",
          "health:DescribeEventDetailsForOrganization",
          "health:DescribeEventTypes",
          "health:DescribeEvents",
          "health:DescribeEventsForOrganization",
          "health:DescribeHealthServiceStatusForOrganization",
          "kafka:ListClusters",
          "kendra:DescribeDataSource",
          "kendra:DescribeIndex",
          "kendra:ListDataSources",
          "kendra:ListIndices",
          "kendra:ListTagsForResource",
          "kinesisanalytics:ListApplications",
          "kinesisanalytics:DescribeApplication",
          "kinesisanalytics:ListTagsForResource",
          "kinesisvideo:ListStreams",
          "kinesisvideo:ListTagsForStream",
          "kinesisvideo:GetDataEndpoint",
          "kms:GetKeyRotationStatus",
          "kms:ListResourceTags",
          "lambda:GetFunction",
          "lambda:GetLayerVersion",
          "logs:ListTagsForResource",
          "profile:GetDomain",
          "profile:ListDomains",
          "profile:ListIntegrations",
          "s3:GetBucketNotification",
          "s3:GetMultiRegionAccessPointPolicy",
          "s3:ListMultiRegionAccessPoints",
          "ses:DescribeActiveReceiptRuleSet",
          "ses:GetAccount",
          "ses:GetConfigurationSet",
          "ses:GetConfigurationSetEventDestinations",
          "ses:GetDedicatedIps",
          "ses:GetEmailIdentity",
          "ses:ListConfigurationSets",
          "ses:ListDedicatedIpPools",
          "ses:ListReceiptFilters",
          "voiceid:DescribeDomain",
          "wafv2:GetLoggingConfiguration",
          "wafv2:GetWebACLForResource",
          "wisdom:GetAssistant",
          "macie2:ListFindings",
          "macie2:GetFindings",
          "identitystore:List*",
          "identitystore:Describe*",
          "sso-directory:Describe*",
          "sso-directory:ListMembersInGroup",
          "cloudwatch:GetMetricStatistics"
        ],
        "Effect" : "Allow",
        "Resource" : "*"
      },
      {
        "Action" : [
          "ec2:CopySnapshot",
          "ec2:CreateSnapshot",
          "ec2:GetEbsEncryptionByDefault",
          "ec2:DescribeSnapshots"
        ],
        "Effect" : "Allow",
        "Resource" : "*"
      },
      {
        "Action" : [
          "ec2:CreateTags"
        ],
        "Effect" : "Allow",
        "Resource" : "arn:aws:ec2:*::snapshot/*"
      },
      {
        "Action" : "kms:CreateAlias",
        "Effect" : "Allow",
        "Resource" : [
          "arn:aws:kms:*:*:alias/wizKey",
          "arn:aws:kms:*:*:key/*"
        ]
      },
      {
        "Action" : [
          "kms:GetKeyPolicy",
          "kms:PutKeyPolicy"
        ],
        "Condition" : {
          "StringEquals" : {
            "aws:ResourceTag/wiz" : "auto-gen-cmk"
          }
        },
        "Effect" : "Allow",
        "Resource" : "*"
      },
      {
        "Action" : [
          "ec2:DeleteSnapshot",
          "ec2:ModifySnapshotAttribute"
        ],
        "Condition" : {
          "StringEquals" : {
            "ec2:ResourceTag/wiz" : "auto-gen-snapshot"
          }
        },
        "Effect" : "Allow",
        "Resource" : "*"
      },
      {
        "Action" : [
          "s3:GetObject"
        ],
        "Effect" : "Deny",
        "Resource" : [
          "*"
        ],
        "Sid" : "WizAccessS3"
      }
    ]
    "Version" : "2012-10-17"
    }
  )
}

// File: outputs.tf
output "role_arn" {
  value = aws_iam_role.user-role-tf.arn
}

// File: role.tf
resource "aws_iam_role" "user-role-tf" {
  name = var.rolename
  assume_role_policy = jsonencode(
    {
      "Version" : "2012-10-17",
      "Statement" : [
        {
          "Effect" : "Allow",
          "Principal" : {
            "AWS" : var.remote-arn
          },
          "Action" : "sts:AssumeRole",
          "Condition" : {
            "StringEquals" : {
              "sts:ExternalId" : var.external-id
            }
          }
        }
      ]
    }
  )
}

data "aws_iam_policy" "view_only_access" {
  arn = "arn:aws:iam::aws:policy/job-function/ViewOnlyAccess"
}

data "aws_iam_policy" "security_audit" {
  arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy_attachment" "view_only_access_role_policy_attach" {
  role       = aws_iam_role.user-role-tf.name
  policy_arn = data.aws_iam_policy.view_only_access.arn
}
resource "aws_iam_role_policy_attachment" "security_audit_role_policy_attach" {
  role       = aws_iam_role.user-role-tf.name
  policy_arn = data.aws_iam_policy.security_audit.arn
}

// File: variables.tf
variable "external-id" {
  type    = string
  default = "fc959d31-537c-4108-8b87-9af9e0c9b8d2"
}

variable "rolename" {
  type    = string
  default = "WizAccess-Role"
}

variable "remote-arn" {
  type    = string
  default = "arn:aws:iam::830522659852:role/prod-us43-AssumeRoleDelegator"
}

// File: main.tf
###########################################################################################
# Locals to uniformly combine both the newly created objects and the pre-existing objects.
# The former are `resources`, the latter are `data` for Terraform.
###########################################################################################

locals {
  transit_gateway              = var.create ? aws_ec2_transit_gateway.this[0] : data.aws_ec2_transit_gateway.this[0]
  transit_gateway_route_tables = { for k, v in var.route_tables : k => v.create ? aws_ec2_transit_gateway_route_table.this[k] : data.aws_ec2_transit_gateway_route_table.this[k] }
}

##############################################################################
# Transit Gateway (TGW)
##############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  tags                            = merge(var.tags, { Name = var.name })
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create == false ? 1 : 0

  # ID of an existing TGW. By default set to `null` hence can be referenced directly.
  id = var.id
  # Filtering existing TGWs by name, only in case no ID was provided.
  dynamic "filter" {
    for_each = var.id == null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]

    }
  }
}

#### Route Tables ####

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway.id
  tags               = merge(var.tags, lookup(each.value, "local_tags", {}), { Name = coalesce(lookup(each.value, "name", ""), var.name) })
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create == false }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway.id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name]
  }
}

##############################################################################
# Resource Shares for TGW
##############################################################################

# Create Resource Share if shared_principals contains any entries.
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) != 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name)
  tags                      = merge(var.tags, { Name = coalesce(var.ram_resource_share_name, var.name) })
  allow_external_principals = true
}

# Associate TGW to the Share.
resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) != 0 ? 1 : 0

  resource_arn       = local.transit_gateway.arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Associate each Account to the Share.
resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

// File: outputs.tf
output "name" {
  description = "Transit Gateway Name tag."
  # Referencing the actual NAME TAG gives us access to it's value for TGWs referenced only by ID.
  value = try(local.transit_gateway.tags.Name, null)
}

output "transit_gateway" {
  description = "The entire object `aws_ec2_transit_gateway`."
  value       = local.transit_gateway
}

output "route_tables" {
  description = "Transit Gateway's route tables."
  value       = local.transit_gateway_route_tables
}

// File: variables.tf
variable "create" {
  description = "Trigger module mode between creating a new TGW or retrieving an existing one."
  default     = true
  type        = bool
}

variable "name" {
  description = "Name tag for the Transit Gateway and associated resources."
  default     = null
  type        = string
}

variable "id" {
  description = "ID of an existing Transit Gateway. Used in conjunction with `create = false`. When set, takes precedence over `var.name`."
  default     = null
  type        = string
}

variable "asn" {
  description = "BGP Autonomous System Number of the AWS Transit Gateway."
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "dns_support" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "vpn_ecmp_support" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "route_tables" {
  default = {}
}

variable "ram_resource_share_name" {
  default = null
}

variable "shared_principals" {
  default = {}
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the transit gateway. Must be a size /24 CIDR block or larger for IPv4, or a size /64 CIDR block or larger for IPv6."
  default     = []
  type        = set(string)
  validation {
    condition     = alltrue([for cidr in var.transit_gateway_cidr_blocks : can(cidrsubnet(cidr, 0, 0))])
    error_message = "Transit gateway CIDR blocks must contain valid IPv4 or IPv6 CIDR."
  }
}

variable "tags" {
  description = "Optional Map of arbitrary tags to apply to all resources"
  type        = map(string)
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= 1.0.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.17"
    }
  }
}

// File: Bronze_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_Bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_Bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    schedule          = "cron(0 0 ? * FRI *)"
    target_vault_name = aws_backup_vault.BackupVault_Bronze.id
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_Bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.BackupPlan_Bronze.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

// File: Gold_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    schedule          = "cron(0 0 * * ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    schedule          = "cron(0 0 1 1/1 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    schedule          = "cron(0 0 31 12 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.BackupPlan_gold.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

// File: Premium_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    schedule          = "cron(0 0/4 ? * * *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "Premium_Daily_Backup"
    schedule          = "cron(0 0 * * ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Premium_Monthly"
    schedule          = "cron(0 0 1 1/1 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after       = 365
      cold_storage_after = 15
    }
  }
  rule {
    rule_name         = "Premium_Yearly"
    schedule          = "cron(0 0 31 12 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after       = 2555
      cold_storage_after = 15
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.BackupPlan_premium.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

