provider "aws" {
  region="us-east-1"

}

#testing
#Generating of VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support = true

  tags={
    Name="development-be-vpc"
  }
}

#Generating of a Public Subnet
resource "aws_subnet" "public_subnet" {

  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_public_cidrs
  availability_zone = "us-east-1a"
  map_public_ip_on_launch = false


  tags={
    Name="development-be-public-subnet"
  }
}

#Generating of Private Subnet
resource "aws_subnet" "private_subnet" {

  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_private_cidrs
   availability_zone = "us-east-1b"

  tags={
    Name="development-be-private-subnet"
  }
}

#Generating of public Route Table
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "development-be-public-rt"
  }

}

#Association of Route Table with Public Subnet 
resource "aws_route_table_association" "public_subnets_asso" {

  subnet_id = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id

}

#Generating Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags={
    Name="development-be-ig"
  }

}

#Generating of SSH and HTTP Secuirty Group
resource "aws_security_group" "sg_grp" {
  vpc_id = aws_vpc.main.id
  name   = "http_access"
  description = "sg for backend development"

  #This is For SSH
  ingress {
    description = "Allow SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  #This is For Http
  ingress {
    description = "Http Acess"
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name= "development-be-sg"
  }

}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private_subnet.id
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}


variable "subnet_public_cidrs" {
  type=string
  description = "Public Subnet CIDR values"
  default = "10.0.1.0/24"

}

variable "subnet_private_cidrs" {
  type=string
  description = "Private Subnet CIDR values"
  default =  "10.0.2.0/24" 


}

variable "availability_zone" {
  description = "Availability Zone for the development environment"
  type        = string
  default     = "us-east-1a"  # Update as needed
}

// File: main.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

data "aws_caller_identity" "current" {}

################################################################################
# Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : var.name
  name_prefix = var.use_name_prefix ? var.name : null

  application_failure_feedback_role_arn    = try(var.application_feedback.failure_role_arn, null)
  application_success_feedback_role_arn    = try(var.application_feedback.success_role_arn, null)
  application_success_feedback_sample_rate = try(var.application_feedback.success_sample_rate, null)

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config

  firehose_failure_feedback_role_arn    = try(var.firehose_feedback.failure_role_arn, null)
  firehose_success_feedback_role_arn    = try(var.firehose_feedback.success_role_arn, null)
  firehose_success_feedback_sample_rate = try(var.firehose_feedback.success_sample_rate, null)

  http_failure_feedback_role_arn    = try(var.http_feedback.failure_role_arn, null)
  http_success_feedback_role_arn    = try(var.http_feedback.success_role_arn, null)
  http_success_feedback_sample_rate = try(var.http_feedback.success_sample_rate, null)

  kms_master_key_id = var.kms_master_key_id

  lambda_failure_feedback_role_arn    = try(var.lambda_feedback.failure_role_arn, null)
  lambda_success_feedback_role_arn    = try(var.lambda_feedback.success_role_arn, null)
  lambda_success_feedback_sample_rate = try(var.lambda_feedback.success_sample_rate, null)

  policy = var.create_topic_policy ? null : var.topic_policy

  sqs_failure_feedback_role_arn    = try(var.sqs_feedback.failure_role_arn, null)
  sqs_success_feedback_role_arn    = try(var.sqs_feedback.success_role_arn, null)
  sqs_success_feedback_sample_rate = try(var.sqs_feedback.success_sample_rate, null)

  tags = var.tags
}

################################################################################
# Topic Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid = "__default_statement_ID"
      actions = [
        "sns:AddPermission",
        "sns:DeleteTopic",
        "sns:GetTopicAttributes",
        "sns:ListSubscriptionsByTopic",
        "sns:Publish",
        "sns:Receive",
        "sns:RemovePermission",
        "sns:SetTopicAttributes",
        "sns:Subscribe",
      ]
      effect    = "Allow"
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        values   = [data.aws_caller_identity.current.account_id]
        variable = "AWS:SourceOwner"
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid         = try(statement.value.sid, statement.key)
      actions     = try(statement.value.actions, null)
      not_actions = try(statement.value.not_actions, null)
      effect      = try(statement.value.effect, null)
      # This avoids the chicken vs the egg scenario since its embedded and can reference the topic
      resources     = try(statement.value.resources, [aws_sns_topic.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Subscription(s)
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create && var.create_subscription }

  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, null)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  protocol                        = each.value.protocol
  raw_message_delivery            = try(each.value.raw_message_delivery, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
  topic_arn                       = aws_sns_topic.this[0].arn
}

################################################################################
# Data Protection Policy
################################################################################

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

// File: outputs.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

################################################################################
# Topic
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic, as a more obvious property (clone of id)"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS Account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

################################################################################
# Subscription(s)
################################################################################

output "subscriptions" {
  description = "Map of subscriptions created and their attributes"
  value       = aws_sns_topic_subscription.this
}

// File: variables.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

variable "create" {
  description = "Determines whether resources will be created (affects all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Topic
################################################################################

variable "name" {
  description = "The name of the SNS topic to create"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix"
  type        = bool
  default     = false
}

variable "application_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # application_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "content_based_deduplication" {
  description = "Boolean indicating whether or not to enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "The SNS delivery policy"
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "firehose_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # firehose_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "http_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # http_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "lambda_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # lambda_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "topic_policy" {
  description = "An externally created fully-formed AWS policy as JSON"
  type        = string
  default     = null
}

variable "sqs_feedback" {
  description = "Map of IAM role ARNs and sample rate for success and failure feedback"
  type        = map(string)
  default     = {}
  # Example:
  # sqs_feedback = {
  #   failure_role_arn = "arn:aws:iam::11111111111:role/failure"
  #   success_role_arn = "arn:aws:iam::11111111111:role/success"
  #   success_sample_rate = 75
  # }
}

variable "signature_version" {
  description = "If SignatureVersion should be 1 (SHA1) or 2 (SHA256). The signature version corresponds to the hashing algorithm used while creating the signature of the notifications, subscription confirmations, or unsubscribe confirmation messages sent by Amazon SNS."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = null
}

################################################################################
# Topic Policy
################################################################################

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is created"
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements must have unique `sid`s"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. In merging, statements with non-blank `sid`s will override statements with the same `sid`"
  type        = list(string)
  default     = []
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default topic policy. Defaults to `true`"
  type        = bool
  default     = true
}

variable "topic_policy_statements" {
  description = "A map of IAM policy [statements](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/data-sources/iam_policy_document#statement) for custom permission usage"
  type        = any
  default     = {}
}

################################################################################
# Subscription(s)
################################################################################

variable "create_subscription" {
  description = "Determines whether an SNS subscription is created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscription definitions to create"
  type        = any
  default     = {}
}

################################################################################
# Data Protection Policy
################################################################################

variable "data_protection_policy" {
  description = "A map of data protection policy statements"
  type        = string
  default     = null
}

// File: versions.tf
# © 2024 Amazon Web Services, Inc. or its affiliates. All Rights Reserved.
# This AWS Content is provided subject to the terms of the AWS Customer Agreement available at
# http://aws.amazon.com/agreement or other written agreement between Customer and either
# Amazon Web Services, Inc. or Amazon Web Services EMEA SARL or both.

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.62"
    }
  }
}

locals {
  init_name   = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.rand.0.dec}"
  bucket_name = var.prefix ? "${local.init_name}-${random_id.rand.0.dec}" : local.init_name
  # Fall back to a real, module-created customer-managed key when the caller
  # asks for encryption but doesn't supply their own kms_key -- SSE-S3 doesn't
  # satisfy Trivy's CMK-specific check (AWS-0132), and this keeps the module's
  # own "encryption on/off" toggle semantics intact.
  effective_kms_key = var.kms_key != "" ? var.kms_key : (var.encryption ? aws_kms_key.bucket[0].arn : "")
}

resource "aws_kms_key" "bucket" {
  count                   = var.kms_key == "" && var.encryption ? 1 : 0
  description             = "CMK for the ${local.bucket_name} S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "random_id" "rand" {
  count       = var.bucket_name == null || var.prefix == true ? 1 : 0
  byte_length = 4
}

resource "aws_s3_bucket" "bucket" {
  bucket              = local.bucket_name
  acl                 = var.acl
  tags                = var.tags
  policy              = var.policy
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer

  dynamic "versioning" {
    for_each = var.versioning ? [1] : []

    content {
      enabled    = var.versioning
      mfa_delete = var.mfa_delete
    }
  }

  dynamic "server_side_encryption_configuration" {
    for_each = var.encryption ? [var.encryption] : []

    content {
      rule {
        apply_server_side_encryption_by_default {
          sse_algorithm     = "aws:kms"
          kms_master_key_id = local.effective_kms_key
        }
      }
    }
  }

  dynamic "grant" {
    for_each = var.grants

    content {
      type        = grant.value.type
      permissions = grant.value.permissions
      id          = lookup(grant.value, "id", null)
      uri         = lookup(grant.value, "uri", null)
    }
  }

  dynamic "logging" {
    for_each = var.logging_target_bucket != null ? [var.logging_target_bucket] : []
    iterator = target_bucket

    content {
      target_bucket = target_bucket.value
      target_prefix = var.logging_target_prefix
    }
  }

  dynamic "website" {
    for_each = var.website_index_document != null ? [var.website_index_document] : []

    content {
      index_document = var.website_index_document
      error_document = var.website_error_document
      routing_rules  = var.website_routing_rules
    }
  }

  dynamic "website" {
    for_each = var.website_redirect_all != null ? [var.website_redirect_all] : []

    content {
      redirect_all_requests_to = var.website_redirect_all
    }
  }

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)

    }
  }

  dynamic "lifecycle_rule" {
    for_each = var.lifecycle_rules

    content {
      enabled                                = lifecycle_rule.value.enabled
      id                                     = lookup(lifecycle_rule.value, "id", null)
      prefix                                 = lookup(lifecycle_rule.value, "prefix", null)
      tags                                   = lookup(lifecycle_rule.value, "tags", null)
      abort_incomplete_multipart_upload_days = lookup(lifecycle_rule.value, "abort_incomplete_multipart_upload_days", null)

      dynamic "transition" {
        for_each = lookup(lifecycle_rule.value, "transitions", [])

        content {
          storage_class = transition.value.storage_class
          days          = lookup(transition.value, "days", null)
          date          = lookup(transition.value, "date", null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = lookup(lifecycle_rule.value, "noncurrent_version_transitions", [])

        content {
          storage_class = noncurrent_version_transition.value.storage_class
          days          = noncurrent_version_transition.value.days
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(lifecycle_rule.value, "noncurrent_version_expiration", [])

        content {
          days = noncurrent_version_expiration.value
        }
      }

      dynamic "expiration" {
        for_each = lookup(lifecycle_rule.value, "expiration", null) != null ? [lifecycle_rule.value.expiration] : []

        content {
          days                         = lookup(expiration.value, "days", null)
          date                         = lookup(expiration.value, "date", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }
    }
  }

  dynamic "replication_configuration" {
    for_each = var.replication_rules != [] ? [1] : []

    content {
      role = var.replication_role != null ? var.replication_role : aws_iam_role.replication.0.arn

      dynamic "rules" {
        for_each = var.replication_rules

        content {
          status   = rules.value.status
          id       = lookup(rules.value, "id", null)
          priority = lookup(rules.value, "priority", null)
          prefix   = lookup(rules.value, "prefix", null)

          dynamic "source_selection_criteria" {
            for_each = lookup(rules.value, "replicate_kms_encrypted_objects", false) ? [rules.value.replicate_kms_encrypted_objects] : []

            content {
              sse_kms_encrypted_objects {
                enabled = rules.value.replicate_kms_encrypted_objects
              }
            }
          }

          dynamic "destination" {
            for_each = [rules.value.destination]

            content {
              bucket             = destination.value.bucket
              storage_class      = lookup(destination.value, "storage_class", null)
              replica_kms_key_id = lookup(destination.value, "replica_kms_key_id", null)
              account_id         = lookup(destination.value, "account_id", null)
            }
          }

          dynamic "filter" {
            for_each = lookup(rules.value, "filter", null) != null ? [rules.value.filter] : []

            content {
              prefix = lookup(filter.value, "prefix", null)
              tags   = lookup(filter.value, "tags", null)
            }
          }
        }
      }
    }
  }

  dynamic "object_lock_configuration" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration] : []

    content {
      object_lock_enabled = object_lock_configuration.value.object_lock_enabled ? "Enabled" : null

      dynamic "rule" {
        for_each = lookup(object_lock_configuration.value, "default_mode", null) != null ? [1] : []

        content {
          default_retention {
            mode  = object_lock_configuration.value.default_mode
            days  = lookup(object_lock_configuration.value, "default_days", null)
            years = lookup(object_lock_configuration.value, "default_years", null)
          }
        }
      }
    }

  }
}

resource "aws_s3_bucket_public_access_block" "bucket" {
  bucket = aws_s3_bucket.bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.replication_rules != [] && var.replication_role == null ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "s3.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY
}

data "aws_iam_policy_document" "replication" {
  count = var.replication_rules != [] && var.replication_role == null ? 1 : 0

  statement {
    actions = ["s3:GetReplicationConfiguration",
    "s3:ListBucket"]
    resources = ["${aws_s3_bucket.bucket.arn}"]
  }

  statement {
    actions = ["s3:GetObjectVersion",
    "s3:GetObjectVersionAcl"]
    resources = ["${aws_s3_bucket.bucket.arn}/*"]
  }

  statement {
    actions = ["s3:ReplicateObject",
    "s3:ReplicateDelete"]
    resources = formatlist("%s/*", distinct([for rule in var.replication_rules : lookup(rule, "destination").bucket]))
  }
}

resource "aws_iam_policy" "replication" {
  count  = var.replication_rules != [] && var.replication_role == null ? 1 : 0
  name   = "CoreS3ReplicationPolicy_${local.bucket_name}"
  policy = data.aws_iam_policy_document.replication.0.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.replication_rules != [] && var.replication_role == null ? 1 : 0
  role       = aws_iam_role.replication.0.name
  policy_arn = aws_iam_policy.replication.0.arn
}

output "arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.bucket.arn
}

output "id" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.bucket.id
}

output "region" {
  description = "Region of the S3 bucket"
  value       = aws_s3_bucket.bucket.region
}

output "bucket_domain_name" {
  description = "Domain name of the S3 bucket"
  value       = aws_s3_bucket.bucket.bucket_domain_name
}

output "regional_domain_name" {
  description = "Regional domain name of the S3 bucket"
  value       = aws_s3_bucket.bucket.bucket_regional_domain_name
}

output "hosted_zone_id" {
  description = "Zone ID of the S3 bucket"
  value       = aws_s3_bucket.bucket.hosted_zone_id
}

variable "bucket_name" {
  type    = string
  default = null
}

variable "prefix" {
  type    = bool
  default = false
}

variable "acl" {
  description = "Canned ACL to apply: https://docs.aws.amazon.com/AmazonS3/latest/dev/acl-overview.html#canned-acl"
  type        = string
  default     = null
}

variable "grants" {
  description = "A list of ACL policy grants to apply: https://docs.aws.amazon.com/AmazonS3/latest/dev/acl-overview.html#sample-acl"
  type        = any
  default     = []
}

variable "policy" {
  description = "The bucket policy in JSON."
  type        = string
  default     = null
}

variable "region" {
  description = "The AWS region this bucket should reside in, if omitted the region by the callee is used"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Who pays the cost of Amazon S3 data transfer. Can be either BucketOwner or Requester"
  type        = string
  default     = "BucketOwner"
}

variable "versioning" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "force_destroy" {
  description = "A boolean that indicates all objects (including any locked objects) should be deleted from the bucket so that the bucket can be destroyed without error"
  type        = bool
  default     = false
}

variable "acceleration_status" {
  description = "Used to Enable or Suspend Transfer Acceleration: https://docs.aws.amazon.com/AmazonS3/latest/dev/transfer-acceleration.html"
  type        = string
  default     = null
}

variable "encryption" {
  type    = bool
  default = true
}

variable "kms_key" {
  description = "ARN of the KMS key to use, if omitted and encryption is set to true SSE-S3 is used."
  type        = string
  default     = ""
}

variable "tags" {
  type    = map(string)
  default = null
}

variable "logging_target_bucket" {
  type    = string
  default = null
}

variable "logging_target_prefix" {
  type    = string
  default = null
}

variable "website_index_document" {
  description = "S3 returns this index document when requests are made to the root domain or any of the subfolders"
  type        = string
  default     = null
}

variable "website_error_document" {
  description = "An absolute path to the document to return in case of a 4XX error"
  type        = string
  default     = null
}

variable "website_redirect_all" {
  description = "A hostname to redirect all website requests for this bucket to"
  type        = string
  default     = null
}

variable "website_routing_rules" {
  description = "A json array containing routing rules describing redirect behavior and when redirects are applied"
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "A list of CORS (cross-origin resource sharing) rules"
  type        = any
  default     = []
}

variable "lifecycle_rules" {
  description = "A list of object lifecycle rules"
  type        = any
  default     = []
}

variable "replication_rules" {
  description = "A list of objects containing replication configuration rules"
  type        = any
  default     = []
}

variable "replication_role" {
  description = "The ARN of the IAM role for Amazon S3 to assume when replicating objects"
  type        = string
  default     = null
}

variable "object_lock_configuration" {
  description = "The Object Lock Configuration you want to apply to the bucket"
  type        = any
  default     = null
}

resource "aws_iam_user" "this" {
  count = var.create_iam_user ? 1 : 0

  name          = local.aws_iam_username
  path          = var.path
  force_destroy = var.force_destroy
}

resource "aws_iam_access_key" "this" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.this[0].name
}

resource "aws_iam_policy" "this" {
  name        = local.aws_iam_policy
  description = local.aws_iam_policy

  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": [
                "s3:GetObject"
            ],
            "Resource": [
                "${aws_s3_bucket.this.arn}/*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
                "s3:ListBucket"
            ],
            "Resource": [
                "${aws_s3_bucket.this.arn}"
            ]
        }
    ]
}
EOF
}

resource "aws_iam_policy_attachment" "this" {
  name       = local.aws_iam_username
  users      = [aws_iam_user.this[0].name]
  policy_arn = aws_iam_policy.this.arn
}

# If var.random_suffix = true, append with random string to avoid duplication
locals {
  aws_iam_username = var.random_suffix ? "${var.aws_iam_username}-${random_string.this[0].id}" : var.aws_iam_username
  aws_iam_policy   = var.random_suffix ? "${var.aws_iam_policy}-${random_string.this[0].id}" : var.aws_iam_policy
}

data "aws_region" "current" {}

resource "random_string" "this" {
  count = var.random_suffix ? 1 : 0

  length  = var.random_string_length
  numeric = true
  special = false
  upper   = false
}

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "this" {
  description         = "CMK for ${local.bucket_name} S3 bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_object" "this" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.this.id
  key    = local.s3_key
  source = "${path.cwd}/${var.image_filename}"
}

# If var.random_suffix = true, append with random string to avoid duplication
locals {
  bucket_name         = var.random_suffix ? "${var.bucket_name}-${random_string.this[0].id}" : var.bucket_name
  s3_key              = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  s3_dpath            = var.create_folder ? "${aws_s3_bucket.this.bucket}/${var.s3_folder}" : aws_s3_bucket.this.bucket
  s3_fqdn_path_url    = "https://s3.${data.aws_region.current.name}.amazonaws.com"
  s3_fqdn_virtual_url = "https://${aws_s3_bucket.this.bucket}.s3.${data.aws_region.current.name}.amazonaws.com"
}

output "s3_region_name" {
  description = "AWS S3 region name"
  value       = data.aws_region.current.name
}

output "s3_bucket_name" {
  description = "AWS S3 bucket name."
  value       = aws_s3_bucket.this.bucket
}

output "s3_bucket_path" {
  description = "AWS S3 bucket path."
  value       = var.s3_folder
}

output "s3_image_name" {
  description = "Image filename."
  value       = var.image_filename
}

output "s3_fqdn_path_url" {
  description = "FQDN path-style S3 URL."
  value       = local.s3_fqdn_path_url
}

output "s3_fqdn_virtual_url" {
  description = "FQDN virtual-hosted–style S3 URL."
  value       = local.s3_fqdn_virtual_url
}

output "aws_access_key_id" {
  description = "AWS Access Key ID."
  value       = var.create_iam_user ? aws_iam_access_key.this[0].id : null
}

output "aws_access_secret" {
  description = "AWS Access Secret."
  value       = var.create_iam_user ? aws_iam_access_key.this[0].secret : null
  sensitive   = true
}

output "zcli_datastore_command_fmt" {
  description = "zCLI command"
  value       = "zcli datastore create <name> [--title=<title>] --dstype=<dstype> [--fqdn=<fqdn>] [--region=<region>] [--apikey=<apikey>] [--apipass=<password>] [--dpath=<dpath>]"
}

output "zcli_datastore_command" {
  description = "zCLI command"
  value       = var.create_iam_user ? "zcli datastore create ${var.zedcloud_datastore_name} --title=${var.zedcloud_datastore_name} --dstype=AWSS3 --fqdn=${local.s3_fqdn_path_url} --region=${data.aws_region.current.name} --apikey=${aws_iam_access_key.this[0].id} --apipass=${aws_iam_access_key.this[0].secret} --dpath=${local.s3_dpath}" : null
  sensitive   = true
}

output "zcli_image_command_fmt" {
  description = "zCLI command"
  value       = "zcli image create <name> --datastore-name=<datastore> --arch=[AMD64|ARM64] --image-format=[raw|qcow|qcow2|vhd|vmdk|ova|vhdx|container] [--image-url=<rel_url>] [--title=<title>] [--type=[Eve|Application|EvePrivate]]"
}

output "zcli_image_command" {
  description = "zCLI command"
  value       = "zcli image create ${var.zedcloud_image_name} --title=${var.zedcloud_image_name} --datastore-name=${var.zedcloud_datastore_name} --arch=AMD64 --image-format=${var.image_format} --image-url=<rel_url> --type=Application"
}

# Boolean to determine if name will be appended with random string
variable "random_suffix" {
  description = "Set to true to append random suffix."
  type        = bool
  default     = true
}

# Length of random string to be appended to the name
variable "random_string_length" {
  description = "Random string length."
  type        = number
  default     = 4
}

variable "create_iam_user" {
  description = "Set to true to create a new the IAM user."
  type        = bool
  default     = true
}

variable "create_folder" {
  description = "Set to true create a folder."
  type        = bool
  default     = true
}

variable "upload_image" {
  description = "Set to true to upload image."
  type        = bool
  default     = false
}

variable "aws_iam_username" {
  description = "IAM user name"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "aws_iam_policy" {
  description = "S3 read-only IAM policy name"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "path" {
  description = "Desired path for the IAM user."
  type        = string
  default     = "/"
}

variable "force_destroy" {
  description = "When destroying IAM user, destroy even if it has non-Terraform-managed IAM access keys, login profile or MFA devices. Without force_destroy a user with non-Terraform-managed access keys and login profile will fail to be destroyed."
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "S3 bucket name."
  type        = string
  default     = "zedcloud"
}

variable "s3_folder" {
  description = "S3 bucket folder."
  type        = string
  default     = "my-folder"
}

variable "zedcloud_datastore_name" {
  description = "Zedcloud Data Store name."
  type        = string
  default     = "my-s3-data-store"
}

variable "zedcloud_image_name" {
  description = "Zededa App Image name."
  type        = string
  default     = "my-image"
}

variable "image_filename" {
  description = "Image filename."
  type        = string
  default     = "my-file.qcow2"
}

variable "image_format" {
  description = "Image format."
  type        = string
  default     = "qcow2"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.33.0"
    }
  }
}

// File: data.tf
data "aws_region" "current" {}

# get list of available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  region               = "eu-central-1"
  vpc_cidr             = "10.14.0.0/16"
  public_subnet_count  = 3
  private_subnet_count = 3
}

// File: terraform.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.region

  default_tags {
    tags = var.default_tags
  }
}

// File: variables.tf
variable "default_tags" {
  type        = map(string)
  description = "Map of default tags to apply to resources"

  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

// File: vpc.tf
# Main VPC
resource "aws_vpc" "eks_main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "eks_public_subnet" {
  # 10.14.0.0/16 -> [10.14.0.0/20, 10.14.16.0/20, 10.14.32.0/20]
  count                   = local.public_subnet_count
  vpc_id                  = aws_vpc.eks_main.id
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Public Route Table
resource "aws_route_table" "eks_public_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-route-table"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "eks_igw" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-internet-gateway"
  }
}

# Public Routes
resource "aws_route" "eks_public_internet_access" {
  route_table_id         = aws_route_table.eks_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.eks_igw.id
  depends_on             = [aws_route_table.eks_public_rt]
}

# Public Subnet Route Associations
resource "aws_route_table_association" "eks_public_rta" {
  count          = local.public_subnet_count
  subnet_id      = element(aws_subnet.eks_public_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_public_rt.id
}

# Private Subnet
resource "aws_subnet" "eks_private_subnet" {
  # 10.14.0.0/16 -> [10.14.48.0/20, 10.14.64.0/20, 10.14.80.0/20]
  count             = local.private_subnet_count
  vpc_id            = aws_vpc.eks_main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index + local.public_subnet_count)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Private Route Table
resource "aws_route_table" "eks_private_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-route-table"
  }
}

# The NAT Elastic IP
resource "aws_eip" "eks_nat_eip" {
  domain = "vpc"

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat-eip"
  }
}

# The NAT Gateway
resource "aws_nat_gateway" "eks_nat" {
  allocation_id = aws_eip.eks_nat_eip.id
  subnet_id     = aws_subnet.eks_public_subnet.0.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat"
  }

  depends_on = [aws_eip.eks_nat_eip, aws_internet_gateway.eks_igw]
}

# Private Routes
resource "aws_route" "eks_private_internet_access" {
  route_table_id         = aws_route_table.eks_private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.eks_nat.id
  depends_on             = [aws_route_table.eks_private_rt]
}

# Private Subnet Route Associations
resource "aws_route_table_association" "eks_private_rta" {
  count          = local.private_subnet_count
  subnet_id      = element(aws_subnet.eks_private_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_private_rt.id
}

locals {
  attach_policy = var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy

  # Fall back to a real, module-created customer-managed key when the caller
  # doesn't supply their own server_side_encryption_configuration -- SSE-S3
  # (the effective default of an empty map) doesn't satisfy Trivy's
  # CMK-specific check (AWS-0132).
  #
  # The fallback branch is round-tripped through jsonencode/jsondecode so its
  # type stays dynamic (matching var.server_side_encryption_configuration's
  # own `any` type) instead of Terraform inferring a strict object type from
  # the HCL literal below -- without this, the module's own `lookup(...,
  # "rule", {})` calls elsewhere in this file fail with "the default value
  # must have the same type as the map elements" once this local's two
  # ternary branches get unified into one strict type.
  effective_sse_configuration = length(keys(var.server_side_encryption_configuration)) == 0 ? jsondecode(jsonencode({
    rule = {
      apply_server_side_encryption_by_default = {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.this[0].arn
      }
    }
  })) : var.server_side_encryption_configuration
}

resource "aws_kms_key" "this" {
  count                   = var.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0 ? 1 : 0
  description             = "CMK for the ${coalesce(var.bucket, "auto-generated")} S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix

  # hack when `null` value can't be used (eg, from terragrunt, https://github.com/gruntwork-io/terragrunt/pull/1367)
  acl = var.acl != "null" ? var.acl : null

  tags                = var.tags
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer

  dynamic "website" {
    for_each = length(keys(var.website)) == 0 ? [] : [var.website]

    content {
      index_document           = lookup(website.value, "index_document", null)
      error_document           = lookup(website.value, "error_document", null)
      redirect_all_requests_to = lookup(website.value, "redirect_all_requests_to", null)
      routing_rules            = lookup(website.value, "routing_rules", null)
    }
  }

  dynamic "cors_rule" {
    for_each = try(jsondecode(var.cors_rule), var.cors_rule)

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }

  dynamic "versioning" {
    for_each = length(keys(var.versioning)) == 0 ? [] : [var.versioning]

    content {
      enabled    = lookup(versioning.value, "enabled", null)
      mfa_delete = lookup(versioning.value, "mfa_delete", null)
    }
  }

  dynamic "logging" {
    for_each = length(keys(var.logging)) == 0 ? [] : [var.logging]

    content {
      target_bucket = logging.value.target_bucket
      target_prefix = lookup(logging.value, "target_prefix", null)
    }
  }

  dynamic "grant" {
    for_each = try(jsondecode(var.grant), var.grant)

    content {
      id          = lookup(grant.value, "id", null)
      type        = grant.value.type
      permissions = grant.value.permissions
      uri         = lookup(grant.value, "uri", null)
    }
  }

  dynamic "lifecycle_rule" {
    for_each = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)

    content {
      id                                     = lookup(lifecycle_rule.value, "id", null)
      prefix                                 = lookup(lifecycle_rule.value, "prefix", null)
      tags                                   = lookup(lifecycle_rule.value, "tags", null)
      abort_incomplete_multipart_upload_days = lookup(lifecycle_rule.value, "abort_incomplete_multipart_upload_days", null)
      enabled                                = lifecycle_rule.value.enabled

      # Max 1 block - expiration
      dynamic "expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "expiration", {})]

        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      # Several blocks - transition
      dynamic "transition" {
        for_each = lookup(lifecycle_rule.value, "transition", [])

        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      # Max 1 block - noncurrent_version_expiration
      dynamic "noncurrent_version_expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "noncurrent_version_expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "noncurrent_version_expiration", {})]

        content {
          days = lookup(noncurrent_version_expiration.value, "days", null)
        }
      }

      # Several blocks - noncurrent_version_transition
      dynamic "noncurrent_version_transition" {
        for_each = lookup(lifecycle_rule.value, "noncurrent_version_transition", [])

        content {
          days          = lookup(noncurrent_version_transition.value, "days", null)
          storage_class = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  # Max 1 block - replication_configuration
  dynamic "replication_configuration" {
    for_each = length(keys(var.replication_configuration)) == 0 ? [] : [var.replication_configuration]

    content {
      role = replication_configuration.value.role

      dynamic "rules" {
        for_each = replication_configuration.value.rules

        content {
          id                               = lookup(rules.value, "id", null)
          priority                         = lookup(rules.value, "priority", null)
          prefix                           = lookup(rules.value, "prefix", null)
          delete_marker_replication_status = lookup(rules.value, "delete_marker_replication_status", null)
          status                           = rules.value.status

          dynamic "destination" {
            for_each = length(keys(lookup(rules.value, "destination", {}))) == 0 ? [] : [lookup(rules.value, "destination", {})]

            content {
              bucket             = destination.value.bucket
              storage_class      = lookup(destination.value, "storage_class", null)
              replica_kms_key_id = lookup(destination.value, "replica_kms_key_id", null)
              account_id         = lookup(destination.value, "account_id", null)

              dynamic "access_control_translation" {
                for_each = length(keys(lookup(destination.value, "access_control_translation", {}))) == 0 ? [] : [lookup(destination.value, "access_control_translation", {})]

                content {
                  owner = access_control_translation.value.owner
                }
              }
            }
          }

          dynamic "source_selection_criteria" {
            for_each = length(keys(lookup(rules.value, "source_selection_criteria", {}))) == 0 ? [] : [lookup(rules.value, "source_selection_criteria", {})]

            content {

              dynamic "sse_kms_encrypted_objects" {
                for_each = length(keys(lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {}))) == 0 ? [] : [lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {})]

                content {

                  enabled = sse_kms_encrypted_objects.value.enabled
                }
              }
            }
          }

          # Send empty map if `filter` is an empty map or absent entirely
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) == 0 ? [{}] : []

            content {}
          }

          # Send `filter` if it is present and has at least one field
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) != 0 ? [lookup(rules.value, "filter", {})] : []

            content {
              prefix = lookup(filter.value, "prefix", null)
              tags   = lookup(filter.value, "tags", null)
            }
          }

        }
      }
    }
  }

  # Max 1 block - server_side_encryption_configuration
  dynamic "server_side_encryption_configuration" {
    # Caller-supplied configuration only; the default CMK path is the separate resource below.
    for_each = length(keys(var.server_side_encryption_configuration)) == 0 ? [] : [var.server_side_encryption_configuration]

    content {

      dynamic "rule" {
        # try() instead of lookup(): lookup() needs its default to match the element type, which a
        # nested object never does ("the default value must have the same type as the map elements").
        for_each = try(server_side_encryption_configuration.value.rule, null) == null ? [] : [server_side_encryption_configuration.value.rule]

        content {
          bucket_key_enabled = try(rule.value.bucket_key_enabled, null)

          dynamic "apply_server_side_encryption_by_default" {
            for_each = try(rule.value.apply_server_side_encryption_by_default, null) == null ? [] : [rule.value.apply_server_side_encryption_by_default]

            content {
              sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
              kms_master_key_id = try(apply_server_side_encryption_by_default.value.kms_master_key_id, null)
            }
          }
        }
      }
    }
  }

  # Max 1 block - object_lock_configuration
  dynamic "object_lock_configuration" {
    for_each = length(keys(var.object_lock_configuration)) == 0 ? [] : [var.object_lock_configuration]

    content {
      object_lock_enabled = object_lock_configuration.value.object_lock_enabled

      dynamic "rule" {
        for_each = length(keys(lookup(object_lock_configuration.value, "rule", {}))) == 0 ? [] : [lookup(object_lock_configuration.value, "rule", {})]

        content {
          default_retention {
            mode  = lookup(lookup(rule.value, "default_retention", {}), "mode")
            days  = lookup(lookup(rule.value, "default_retention", {}), "days", null)
            years = lookup(lookup(rule.value, "default_retention", {}), "years", null)
          }
        }
      }
    }
  }

}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_policy ? var.policy : ""
  ])
}

# AWS Load Balancer access log delivery policy
data "aws_elb_service_account" "this" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

data "aws_iam_policy_document" "elb_log_delivery" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid = ""

    principals {
      type        = "AWS"
      identifiers = data.aws_elb_service_account.this.*.arn
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]
  }
}

# ALB/NLB

data "aws_iam_policy_document" "lb_log_delivery" {
  count = var.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid = "AWSLogDeliveryWrite"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid = "AWSLogDeliveryAclCheck"

    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    actions = [
      "s3:GetBucketAcl",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
    ]

  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = var.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid    = "denyInsecureTransport"
    effect = "Deny"

    actions = [
      "s3:*",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values = [
        "false"
      ]
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket && var.attach_public_policy ? 1 : 0

  # Chain resources (s3_bucket -> s3_bucket_policy -> s3_bucket_public_access_block)
  # to prevent "A conflicting conditional operation is currently in progress against this resource."
  # Ref: https://github.com/hashicorp/terraform-provider-aws/issues/7628

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  # This `depends_on` is to prevent "A conflicting conditional operation is currently in progress against this resource."
  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket.this
  ]
}

# Default path: no encryption config supplied -> the module's own customer-managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  count  = var.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this[0].arn
    }
  }
}

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = element(concat(aws_s3_bucket_policy.this.*.id, aws_s3_bucket.this.*.id, [""]), 0)
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = element(concat(aws_s3_bucket.this.*.arn, [""]), 0)
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name. Will be of format bucketname.s3.amazonaws.com."
  value       = element(concat(aws_s3_bucket.this.*.bucket_domain_name, [""]), 0)
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name. The bucket domain name including the region name, please refer here for format. Note: The AWS CloudFront allows specifying S3 region-specific endpoint when creating S3 origin, it will prevent redirect issues from CloudFront to S3 Origin URL."
  value       = element(concat(aws_s3_bucket.this.*.bucket_regional_domain_name, [""]), 0)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = element(concat(aws_s3_bucket.this.*.hosted_zone_id, [""]), 0)
}

output "s3_bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = element(concat(aws_s3_bucket.this.*.region, [""]), 0)
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website. If not, this will be an empty string."
  value       = element(concat(aws_s3_bucket.this.*.website_endpoint, [""]), 0)
}

output "s3_bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website. If not, this will be an empty string. This is used to create Route 53 alias records. "
  value       = element(concat(aws_s3_bucket.this.*.website_domain, [""]), 0)
}

variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ELB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ALB/NLB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should have deny non-SSL transport policy attached"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Controls if S3 bucket should have bucket policy attached (set to `true` to use value of `policy` as bucket policy)"
  type        = bool
  default     = false
}

variable "attach_public_policy" {
  description = "Controls if a user defined public bucket policy will be attached (set to `false` to allow upstream to apply defaults to the bucket)"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "(Optional, Forces new resource) The name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "(Optional, Forces new resource) Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "(Optional) The canned ACL to apply. Defaults to 'private'. Conflicts with `grant`"
  type        = string
  default     = "private"
}

variable "policy" {
  description = "(Optional) A valid bucket policy JSON document. Note that if the policy document is not specific enough (but still valid), Terraform may view the policy as constantly changing in a terraform plan. In this case, please make sure you use the verbose/specific version of the policy. For more information about building AWS IAM policy documents with Terraform, see the AWS IAM Policy Document Guide."
  type        = string
  default     = null
}

variable "tags" {
  description = "(Optional) A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "(Optional, Default:false ) A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error. These objects are not recoverable."
  type        = bool
  default     = false
}

variable "acceleration_status" {
  description = "(Optional) Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "(Optional) Specifies who should bear the cost of Amazon S3 data transfer. Can be either BucketOwner or Requester. By default, the owner of the S3 bucket would incur the costs of any data transfer. See Requester Pays Buckets developer guide for more information."
  type        = string
  default     = null
}

variable "website" {
  description = "Map containing static web-site hosting or redirect configuration."
  type        = map(string)
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing rules for Cross-Origin Resource Sharing."
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map containing versioning configuration."
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map containing access bucket logging configuration."
  type        = map(string)
  default     = {}
}

variable "grant" {
  description = "An ACL policy grant. Conflicts with `acl`"
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of maps containing configuration of object lifecycle management."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration."
  type        = any
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration."
  type        = any
  default     = {}
}

variable "object_lock_configuration" {
  description = "Map containing S3 object locking configuration."
  type        = any
  default     = {}
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerPreferred or ObjectWriter. 'BucketOwnerPreferred': Objects uploaded to the bucket change ownership to the bucket owner if the objects are uploaded with the bucket-owner-full-control canned ACL. 'ObjectWriter': The uploading account will own the object if the object is uploaded with the bucket-owner-full-control canned ACL."
  type        = string
  default     = "ObjectWriter"
}

terraform {
  required_version = ">= 0.12.31"

  required_providers {
    aws = ">= 3.50"
  }
}

// File: main.tf
###############
# VPC Section #
###############

# VPCs

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  awsAz2 = var.awsAz2 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
}
resource "aws_vpc" "vpcMain" {
  cidr_block = var.vpcMainCidr
  tags = {
    Name  = "${var.projectPrefix}-vpcMain-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Subnets

resource "aws_subnet" "vpcMainSubPubA" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubACidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPubB" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubBCidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Internet Gateway

resource "aws_internet_gateway" "vpcMainIgw" {
  vpc_id = aws_vpc.vpcMain.id

  tags = {
    Name  = "${var.projectPrefix}-vpcMainIgw-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Main Route Tables Associations

resource "aws_main_route_table_association" "mainRtbAssoVpcMain" {
  vpc_id         = aws_vpc.vpcMain.id
  route_table_id = aws_route_table.vpcMainRtb.id
}

# Route Tables

resource "aws_route_table" "vpcMainRtb" {
  vpc_id = aws_vpc.vpcMain.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpcMainIgw.id
  }

  tags = {
    Name  = "${var.projectPrefix}-vpcMainRtb-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

// File: outputs.tf
locals {
  vpcs = {
    "main" = aws_vpc.vpcMain.id
  }
  subnetsAz1 = {
    "public"  = aws_subnet.vpcMainSubPubA.id
    "private" = aws_subnet.vpcMainSubMgmtA.id
    "mgmt"    = aws_subnet.vpcMainSubPrivA.id
  }
  subnetsAz2 = {
    "public"  = aws_subnet.vpcMainSubPubB.id
    "private" = aws_subnet.vpcMainSubMgmtB.id
    "mgmt"    = aws_subnet.vpcMainSubPrivB.id
  }
}

output "vpcs" {
  value = local.vpcs
}

output "subnetsAz1" {
  value = local.subnetsAz1
}

output "subnetsAz2" {
  value = local.subnetsAz2
}

output "vpcMainIgw" {
  value = aws_internet_gateway.vpcMainIgw.id
}
output "vpcMainRtb" {
  value = aws_route_table.vpcMainRtb.id
}

// File: variables.tf
variable "projectPrefix" {
  description = "projectPrefix name to use for tags"
  default     = "f5-dcec"
}
variable "resourceOwner" {
  description = "owner of the deployment, for tagging purposes"
  default     = "f5-user"
}
variable "buildSuffix" {
  description = "random string for tagging purposes"
  default     = "YY"
}
variable "awsAz1" {
  default = null
}
variable "awsAz2" {
  default = null
}
variable "awsRegion" {
  default = "us-east-1"
}
variable "map_public_ip_on_launch" {
  description = "assigns public ip's to instances in the public subnet by default"
  default     = false
}
variable "vpcMainCidr" {
  default = "10.1.0.0/16"
}
variable "vpcMainSubPubACidr" {
  default = "10.1.10.0/24"
}
variable "vpcMainSubPubBCidr" {
  default = "10.1.110.0/24"
}
variable "vpcMainSubMgmtACidr" {
  default = "10.1.1.0/24"
}
variable "vpcMainSubMgmtBCidr" {
  default = "10.1.101.0/24"
}
variable "vpcMainSubPrivACidr" {
  default = "10.1.20.0/24"
}
variable "vpcMainSubPrivBCidr" {
  default = "10.1.120.0/24"
}

# Copyright IBM Corp. 2014, 2026
# SPDX-License-Identifier: MPL-2.0

resource "aws_lb_listener_rule" "test" {
  count  = var.resource_count
  region = var.region

  listener_arn = aws_lb_listener.test.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.test.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }
}

# testAccListenerRuleConfig_baseWithHTTPListener

resource "aws_lb_listener" "test" {
  region = var.region

  load_balancer_arn = aws_lb.test.arn
  protocol          = "HTTPS"
  port              = "443"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.listener.arn

  default_action {
    target_group_arn = aws_lb_target_group.test.arn
    type             = "forward"
  }
}

# testAccListenerRuleConfig_base

resource "aws_security_group" "test" {
  region = var.region

  name   = var.rName
  vpc_id = aws_vpc.test.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.test.cidr_block]
  }
}

resource "aws_lb" "test" {
  region = var.region

  name            = var.rName
  internal        = true
  security_groups = [aws_security_group.test.id]
  subnets         = aws_subnet.test[*].id

  idle_timeout               = 30
  enable_deletion_protection = false
  drop_invalid_header_fields = true
}

resource "aws_lb_target_group" "test" {
  region = var.region

  name     = var.rName
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.test.id

  health_check {
    path                = "/health"
    interval            = 60
    port                = 8081
    protocol            = "HTTP"
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }
}

# acctest.ConfigVPCWithSubnets(rName, 2)

resource "aws_vpc" "test" {
  region = var.region

  cidr_block = "10.0.0.0/16"
}

# acctest.ConfigSubnets(rName, 2)

resource "aws_subnet" "test" {
  region = var.region

  count = 2

  vpc_id            = aws_vpc.test.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.test.cidr_block, 8, count.index)
}

# acctest.ConfigAvailableAZsNoOptInDefaultExclude

data "aws_availability_zones" "available" {
  region = var.region

  exclude_zone_ids = local.default_exclude_zone_ids
  state            = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  default_exclude_zone_ids = ["usw2-az4", "usgw1-az2"]
}

variable "rName" {
  description = "Name for resource"
  type        = string
  nullable    = false
  default     = "benchmark"
}

variable "resource_count" {
  description = "Number of resources to create"
  type        = number
  nullable    = false
  default     = 1
}

variable "region" {
  description = "Region to deploy resource in"
  type        = string
  nullable    = false
  default     = "us-east-1"
}

resource "tls_private_key" "listener" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "listener" {
  private_key_pem       = tls_private_key.listener.private_key_pem
  dns_names             = ["internal-alb.example.internal"]
  validity_period_hours = 8760
  allowed_uses          = ["key_encipherment", "digital_signature", "server_auth"]

  subject {
    common_name = "internal-alb.example.internal"
  }
}

# Self-signed certificate imported into ACM so the listener can serve HTTPS without a domain.
resource "aws_acm_certificate" "listener" {
  region = var.region

  private_key      = tls_private_key.listener.private_key_pem
  certificate_body = tls_self_signed_cert.listener.cert_pem
}

resource "aws_cloudtrail" "cloudtrail" {
    name            = var.trail_name
    s3_bucket_name  = aws_s3_bucket.cloudtrail_bucket.id
    is_multi_region_trail           = true
    enable_log_file_validation      = true
    include_global_service_events   = true
    is_organization_trail           = var.is_organizational
    cloud_watch_logs_group_arn  = "${aws_cloudwatch_log_group.cloudtrail_cw_log_group.arn}:*"
    cloud_watch_logs_role_arn   = aws_iam_role.cw_log_iam_role.arn
    kms_key_id = (
        length(aws_kms_key.cloudtrail_key) > 0 ?
        aws_kms_key.cloudtrail_key[0].arn :
        null
    )
    depends_on = [ aws_s3_bucket_policy.bucket_policy ]
    event_selector {
        include_management_events   = true
        read_write_type             = "All"
    }
}

resource "aws_iam_role" "cw_log_iam_role" {
    name = "CloudTrailRoleForCloudWatchLogs"
    assume_role_policy = jsonencode({
        Version = "2012-10-17"
        Statement = [{
            Action  = "sts:AssumeRole",
            Effect  = "Allow",
            Sid     = ""
            Principal = {
                Service = "cloudtrail.amazonaws.com"
            }
        }]
    })
}

resource "aws_iam_role_policy" "cw_log_iam_role_policy" {
    name = "allow-access-to-cw-logs"
    role = aws_iam_role.cw_log_iam_role.id
    policy = jsonencode({
        Version = "2012-10-17"
        Statement = [{
            Effect = "Allow"
            Action = [
                "logs:CreateLogStream",
                "logs:PutLogEvents"
            ]
            Resource = "${aws_cloudwatch_log_group.cloudtrail_cw_log_group.arn}:*"
        }]
    })
}

resource "aws_cloudwatch_log_group" "cloudtrail_cw_log_group" {
    name = var.log_group_name
    retention_in_days = 0
}

data "aws_caller_identity" "current" {}
resource "aws_kms_key" "cloudtrail_key" {
    count = var.encrypt_trail ? 1 : 0
    description = "Key for encrypting CloudTrail logs"
    policy      = data.aws_iam_policy_document.cloudtrail_key_policy.json
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
    count = var.encrypt_trail ? 1 : 0
    name            = var.cloudtrail_key_alias
    target_key_id   = aws_kms_key.cloudtrail_key[0].key_id
}

data "aws_iam_policy_document" "cloudtrail_key_policy" {
    statement {
        sid = "Enable IAM User Permissions"
        actions = [
            "kms:*"
        ]
        effect = "Allow"
        resources = [ "*" ]
        principals {
            type = "AWS"
            identifiers = [
                "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root",
                "${data.aws_caller_identity.current.arn}"
            ]
        }
    }
    statement {
        sid = "Allow CloudTrail to encrypt logs"
        actions = [
            "kms:GenerateDataKey*"
        ]
        effect = "Allow"
        resources = [ "*" ]
        principals {
            type = "Service"
            identifiers = [ "cloudtrail.amazonaws.com" ]
        }
        condition {
            test = "StringLike"
            variable = "kms:EncryptionContext:aws:cloudtrail:arn"
            values = [ "arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*" ]
        }
    }
    statement {
        sid = "AllowS3ToUseKey"
        actions = [
            "kms:GenerateDataKey*",
            "kms:Decrypt"
        ]
        effect = "Allow"
        resources = [ "*" ]
        principals {
            type = "Service"
            identifiers = [ "s3.amazonaws.com" ]
        }
    }
    statement {
        sid = "Allow CloudTrail to describe key"
        actions = [
            "kms:DescribeKey"
        ]
        effect = "Allow"
        resources = [ "*" ]
        principals {
            type = "Service"
            identifiers = [ "cloudtrail.amazonaws.com" ]
        }
    }
    statement {
        sid = "Allow principals in the account to decrypt log files"
        actions = [
            "kms:Decrypt",
            "kms:ReEncryptFrom"
        ]
        effect = "Allow"
        resources = [ "*" ]
        principals {
            type = "AWS"
            identifiers = [ "*" ]
        }
        condition {
            test = "StringEquals"
            variable = "kmsCallerAccount"
            values = [ "${data.aws_caller_identity.current.account_id}" ]
        }
        condition {
            test = "StringLike"
            variable = "kms:EncryptionContext:aws:cloudtrail:arn"
            values = [ "arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*" ]
        }
    }
}

resource "random_string" "random" {
    length  = 12
    lower   = false
    upper   = false
    special = false
    number  = true
} 

resource "aws_s3_bucket" "cloudtrail_bucket" {
    bucket = "cloudtrail-bucket-${random_string.random.result}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket" {
    bucket = aws_s3_bucket.cloudtrail_bucket.id
    rule {
        apply_server_side_encryption_by_default {
            sse_algorithm     = "aws:kms"
            kms_master_key_id = aws_kms_key.cloudtrail_key[0].arn
        }
    }
}

resource "aws_s3_bucket_public_access_block" "block_public_access" {
    bucket = aws_s3_bucket.cloudtrail_bucket.id
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
    depends_on = [ aws_s3_bucket_policy.bucket_policy ]
}

data "aws_iam_policy_document" "bucket_policy_for_cloudtrail_bucket" {
    statement {
        actions = [
            "s3:GetBucketAcl"
        ]
        effect = "Allow"
        resources = [ aws_s3_bucket.cloudtrail_bucket.arn ]
        principals {
            type = "Service"
            identifiers = [ "cloudtrail.amazonaws.com" ]
        }
    }
    statement {
        actions = [
            "s3:PutObject"
        ]
        effect = "Allow"
        resources = [ "${aws_s3_bucket.cloudtrail_bucket.arn}/*" ]
        principals {
            type = "Service"
            identifiers = [ "cloudtrail.amazonaws.com" ]
        }
        condition {
            test = "StringEquals"
            variable = "s3:x-amz-acl"
            values = [ "bucket-owner-full-control" ]
        }
    }
}

resource "aws_s3_bucket_policy" "bucket_policy" {
    bucket = aws_s3_bucket.cloudtrail_bucket.id
    policy = data.aws_iam_policy_document.bucket_policy_for_cloudtrail_bucket.json
}

variable "is_organizational" {
    description = "Set trail to be an organization trail"
    type        = bool
    default     = false
}

variable "trail_name" {
    description = "Name of CloudTrail trail"
    type        = string
    default     = "management_trail"
}

variable "log_group_name" {
    description = "Name for CloudWatch Log Group to which streams new trail"
    type        = string
    default     = "cloudtrail_logs"
}

variable "encrypt_trail" {
    description = "Enable trail encryption"
    type        = bool
    default     = true
}
variable "cloudtrail_key_alias" {
    description = "Alias for key encrypting CloudTrail logs"
    type        = string
    default     = "alias/cloudtrail_key"
}

# default variables

locals {
  default_lifecycle_policy = {
    rules = [{
      rulePriority = 1
      description  = "Only keep 2 images"
      selection = {
        tagStatus   = "any"
        countType   = "imageCountMoreThan"
        countNumber = 2
      }
      action = {
        type = "expire"
      }
    }]
  }
}

