}

## requirements

terraform {
  required_version = ">= 0.13"
}

// File: config.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: data-availability_zones.tf
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  total_subnets  = ((var.enable_public_subnets ? 1 : 0) + (var.enable_nat_subnets ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)) * var.number_of_availability_zones
  subnet_newbits = ceil(log(local.total_subnets, 2))
}

// File: main.tf
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id
}

output "public_sg" {
  value = var.enable_public_subnets ? aws_security_group.public[0].id : ""
  description = "Public Subnet IDs"
}

resource "aws_security_group_rule" "public_egress" {
  count = var.enable_public_subnets ? 1 : 0

  type = "egress"
  cidr_blocks = ["0.0.0.0/0"]
  description = "Allow internet egress"
  from_port = 0
  to_port = 65535
  protocol = "all"
  security_group_id = aws_security_group.public[0].id
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id
}

resource "aws_subnet" "public" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index)
    if var.enable_public_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value

  map_public_ip_on_launch = true
}

output "public_subnet_ids" {
  value = values(aws_subnet.public)[*].id
  description = "Public Subnet IDs"
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  route {
    cidr_block = aws_vpc.main.cidr_block
    gateway_id = "local"
  }
}

resource "aws_route_table_association" "public" {
  for_each = var.enable_public_subnets ? aws_subnet.public : {}

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_subnet" "nat" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index + var.number_of_availability_zones)
    if var.enable_nat_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value
}

resource "aws_subnet" "private" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index + (2 * var.number_of_availability_zones))
    if var.enable_private_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value
}

// File: variables.tf
variable "vpc_cidr" {
  type        = string
  description = "IPv4 CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "number_of_availability_zones" {
  type        = number
  description = "Number of availabilitiy zones to use"
  default     = 2
}

variable "enable_public_subnets" {
  type        = bool
  description = "Whether to create public subnets"
  default     = false
}

variable "enable_nat_subnets" {
  type        = bool
  description = "Whether to create nat subnets"
  default     = false
}

variable "enable_private_subnets" {
  type        = bool
  description = "Whether to create private subnets"
  default     = false
}

output "id" {
  value       = aws_vpc.default.id
  description = "VPC id"
}

output "public_subnet_ids" {
  value       = aws_subnet.public.*.id
  description = "List of public subnet IDs"
}

output "cidr_block" {
  value       = var.cidr_block
  description = "The CIDR block associated with the VPC"
}

variable "project" {
  default     = "demo"
  type        = string
  description = "Name of project this VPC is meant to house"
}

variable "environment" {
  default     = "poc"
  type        = string
  description = "Name of environment this VPC is targeting"
}

variable "name" {
  default     = "demo-dataflow"
  type        = string
  description = "Name of the VPC"
}

variable "region" {
  default     = "us-west-2"
  type        = string
  description = "Region of the VPC"
}

variable "availability_zones" {
  default     = ["us-west-2a", "us-west-2b"]
  type        = list
  description = "List of availability zones"
}

variable "key_name" {
  default     = "kplinuxdemo"
  type        = string
  description = "EC2 Key pair name for the bastion"
}

variable "cidr_block" {
  default     = "10.0.0.0/16"
  type        = string
  description = "CIDR block for the VPC"
}

variable "public_subnet_cidr_blocks" {
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
  type        = list
  description = "List of public subnet CIDR blocks"
}

variable "private_subnet_cidr_blocks" {
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
  type        = list
  description = "List of private subnet CIDR blocks"
}

variable "aws_internet_gateway" {
  default     = "igwdemo"
  type        = string
  description = "Region of the VPC"
}

variable "bastion_ami" {
  default     = " ami-0d6621c01e8c2de2c"
  type        = string
  description = "Bastion Amazon Machine Image (AMI) ID"
}

variable "bastion_ebs_optimized" {
  default     = false
  type        = bool
  description = "If true, the bastion instance will be EBS-optimized"
}

variable "bastion_instance_type" {
  default     = "t3.nano"
  type        = string
  description = "Instance type for bastion instance"
}

variable "tags" {
  default     = {}
  type        = map(string)
  description = "Extra tags to attach to the VPC resources"
}

#
# VPC resources
#

provider "aws" {
  region = var.region
}

resource "aws_vpc" "default" {
  cidr_block           = var.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    {
      Name        = var.name,
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_internet_gateway" "default" {
  vpc_id = aws_vpc.default.id

  tags = merge(
    {
      Name        = "demogwInternet",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidr_blocks)

  vpc_id                  = aws_vpc.default.id
  cidr_block              = var.public_subnet_cidr_blocks[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name        = "demoPublicSubnet",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.default.id

  tags = merge(
    {
      Name        = "demoPublicRouteTable",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.default.id
}

// File: cloud.tf
# ===========================
# KMS keys and backup vaults
# ===========================

resource "aws_backup_vault" "rds_backup_vault" {
  name        = "rds-backup-vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "cross_region_rds_backup_vault" {
  name        = "rds-cross-region-backup-vault-${var.cross_region_destination}"
  kms_key_arn = aws_kms_key.cross_region_rds_backup_key.arn
  region      = var.cross_region_destination
}

resource "aws_kms_key" "backup_key" {
  description             = "KMS key for encrypting RDS backups"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  region                  = "us-east-1"
}

resource "aws_kms_key_policy" "backup_key_external_account" {
  count = var.cross_account_backup ? 1: 0
  key_id = aws_kms_key.backup_key.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "kms:*"
        Effect = "Allow"
        Principal = {
          AWS = [
            "arn:aws:iam::${var.backup_destination_account}:root",
            "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root",
            "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/backup.amazonaws.com/AWSServiceRoleForBackup"
          ]
        }

        Resource = "*"
        Sid      = "Enable cross-account access to copy backups"
      },
    ]
  })
}

resource "aws_kms_key" "cross_region_rds_backup_key" {
  description             = "KMS key for encrypting RDS backups, in ${var.cross_region_destination}"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  region                  = var.cross_region_destination
}

# ==============
# Daily backups
# ==============

resource "aws_backup_plan" "daily" {
  name = "rds-daily-backup-plan"
  count = var.daily_backups_enabled ? 1 : 0

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.rds_backup_vault.name
    schedule          = "cron(0 2 * * ? *)" # Daily at 2 AM UTC
    lifecycle {
      delete_after = 7 # Retain for 7 days
    }

    copy_action {
      lifecycle {
        delete_after = 7 # Retain for 7 days
      }

      destination_vault_arn = aws_backup_vault.cross_region_rds_backup_vault.arn
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup ? [1]: []

      content {
        lifecycle {
          delete_after = 7 # Retain for 7 days
        }

        destination_vault_arn = "arn:aws:backup:us-east-1:${var.backup_destination_account}:backup-vault:rds-central-backup-vault-${data.aws_caller_identity.current.account_id}"
      }
    }
  }
}

resource "aws_backup_selection" "daily" {
  name          = "rds-daily-backup-selection"
  iam_role_arn  = aws_iam_role.backup_role.arn
  plan_id = aws_backup_plan.daily[0].id
  count = var.daily_backups_enabled ? 1 : 0

  resources = [
    "arn:aws:rds:*"
  ]

  not_resources = var.excluded_dbs
}

# ===============
# Weekly backups
# ===============

resource "aws_backup_plan" "weekly" {
  name = "rds-weekly-backup-plan"

  rule {
    rule_name         = "weekly-backup-rule"
    target_vault_name = aws_backup_vault.rds_backup_vault.name
    schedule          = "cron(0 2 ? * 7 *)" # weekly at 2 AM UTC
    lifecycle {
      delete_after = 30 # Retain for 30 days
    }

    copy_action {
      lifecycle {
        delete_after = 30 # Retain for 30 days
      }

      destination_vault_arn = aws_backup_vault.cross_region_rds_backup_vault.arn
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup ? [1]: []

      content {
        lifecycle {
          delete_after = 30 # Retain for 30 days
        }

        destination_vault_arn = "arn:aws:backup:us-east-1:${var.backup_destination_account}:backup-vault:rds-central-backup-vault-${data.aws_caller_identity.current.account_id}"
      }
    }
  }
}

resource "aws_backup_selection" "weekly" {
  name          = "rds-weekly-backup-selection"
  iam_role_arn  = aws_iam_role.backup_role.arn
  plan_id = aws_backup_plan.weekly.id

  resources = [
    "arn:aws:rds:*"
  ]

  not_resources = var.excluded_dbs
}

# ================
# Monthly backups
# ================

resource "aws_backup_plan" "monthly" {
  name = "rds-monthly-backup-plan"

  rule {
    rule_name         = "monthly-backup-rule"
    target_vault_name = aws_backup_vault.rds_backup_vault.name
    schedule          = "cron(0 3 1 * ? *)" # Monthly on the 1st at 3 AM UTC
    lifecycle {
      delete_after = 365 # Retain for 365 days (1 year)
    }

    copy_action {
      lifecycle {
        delete_after = 365 # Retain for 365 days (1 year)
      }

      destination_vault_arn = aws_backup_vault.cross_region_rds_backup_vault.arn
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup ? [1]: []

      content {
        lifecycle {
          delete_after = 365 # Retain for 365 days (1 year)
        }

        destination_vault_arn = "arn:aws:backup:us-east-1:${var.backup_destination_account}:backup-vault:rds-central-backup-vault-${data.aws_caller_identity.current.account_id}"
      }
    }
  }
}

resource "aws_backup_selection" "monthly" {
  name          = "rds-monthly-backup-selection"
  iam_role_arn  = aws_iam_role.backup_role.arn
  plan_id       = aws_backup_plan.monthly.id

  resources = [
    "arn:aws:rds:*"
  ]

  not_resources = var.excluded_dbs
}

# ===============
# Yearly backups
# ===============

resource "aws_backup_plan" "yearly" {
  name = "rds-yearly-backup-plan"

  rule {
    rule_name         = "yearly-backup-rule"
    target_vault_name = aws_backup_vault.rds_backup_vault.name
    schedule          = "cron(0 4 1 1 ? *)" # Yearly on January 1st at 4 AM UTC
    lifecycle {
      delete_after = 2555 # Retain for 2555 days (7 years)
    }

    copy_action {
      lifecycle {
        delete_after = 2555 # Retain for 7 days
      }

      destination_vault_arn = aws_backup_vault.cross_region_rds_backup_vault.arn
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup ? [1]: []

      content {
        lifecycle {
          delete_after = 2555 # Retain for 2555 days (7 years)
        }

        destination_vault_arn = "arn:aws:backup:us-east-1:${var.backup_destination_account}:backup-vault:rds-central-backup-vault-${data.aws_caller_identity.current.account_id}"
      }
    }
  }
}

resource "aws_backup_selection" "yearly" {
  name          = "rds-yearly-backup-selection"
  iam_role_arn  = aws_iam_role.backup_role.arn
  plan_id       = aws_backup_plan.yearly.id

  resources = [
    "arn:aws:rds:*"
  ]

  not_resources = var.excluded_dbs
}

# ==============
# IAM and Auth
# ==============

resource "aws_iam_role" "backup_role" {
  name               = "rds-backup-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_role_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

// File: data.tf
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

// File: variables.tf
variable "retention_period" {
  description = "The number of days to retain the backup"
  type        = number
  default     = 7
}

variable "excluded_dbs" {
  description = "A list of DB ARNs to be EXCLUDED from this backup"
  type        = list
  default     = []
}

variable "daily_backups_enabled" {
  description = "Whether or not the daily backups that are retained for 7 days are preserved"
  type        = bool
  default     = true
}

variable "cross_region_destination" {
  description = "The AWS region in which backups should live"
  type        = string
  default     = "us-west-1"
}

variable cross_account_backup {
  description = "Whether or not to enable cross-account backup. Must specify an account"
  type        = bool
  default     = true
}

variable backup_destination_account {
  description = "The aws account ID for the target backup account"
  type        = string
  default     = "433568766270"
}

// File: data.tf
#############################
# USER POLICIES BEGINNING
#############################

data "aws_iam_policy" "read_only_access" {
  arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}
data "aws_iam_policy" "administrator_access" {
  arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

#############################
# USER POLICIES END
#############################

// File: groups.tf
#############################
# USER GROUPS BEGINNING
#############################

# Administrators
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

# Developpers
resource "aws_iam_group" "developpers" {
  name = "developpers"
}

# Prod users
resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

#############################
# USER GROUP END
#############################


#############################
# USER POLICIES BEGINNING
#############################

data "aws_caller_identity" "current" {
}

# Developpers have access to databases and servers tagged "dev"
resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Policy for developpers"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        "Action"   : "ec2:*",
        "Effect"   : "Allow",
        "Resource" : "*",
        "Condition": {
            "StringEquals": {
               "ec2:ResourceTag/env": "dev"
              }
        }
      },
      {
        "Action"   : "rds:*",
        "Effect"   : "Allow",
        "Resource" : "*",
        "Condition": {
            "StringEquals": {
                "rds:ResourceTag/env": "dev"
              }
        }
      },

    ]
  })
}

# Developpers have access to databases and servers tagged "prod" and "preprod"
resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Policy for prod_users"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        "Action"   : "ec2:*",
        "Effect"   : "Allow",
        "Resource" : "*",
        "Condition": {
            "StringEquals": {
               "ec2:ResourceTag/env": ["preprod","prod"]
              }
        }
      },
      {
        "Action"   : "rds:*",
        "Effect"   : "Allow",
        "Resource" : "*",
        "Condition": {
            "StringEquals": {
                "rds:ResourceTag/env": ["preprod","prod"]
              }
        }
      },

    ]
  })
}

# Administrators
resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Policy for administrators"
  policy = jsonencode({
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "NotAction": [
                "iam:*",
                "organizations:*",
                "account:*"
            ],
            "Resource": "*",
            "Condition": {
                "StringNotEquals": {
                    "aws:ResourceTag/security": "high"
                }
              }
        },
        {
            "Effect": "Allow",
            "Action": [
                "iam:CreateServiceLinkedRole",
                "iam:DeleteServiceLinkedRole",
                "iam:ListRoles",
                "organizations:DescribeOrganization",
                "account:ListRegions"
            ],
            "Resource": "*"
        }
    ]
})
}


resource "aws_iam_group_policy_attachment" "administrators_admin_access" {
  group       = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}


resource "aws_iam_group_policy_attachment" "developpers_access" {
  group       = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_access" {
  group       = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

