  value       = aws_vpc.main.cidr_block
}
output  "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "route_id" {
  value = aws_vpc.main.main_route_table_id
}

output "subnet_ids" {
  value = aws_subnet.private_A.*.id
}

output "route_ids" {
  value = aws_route_table.private_A.*.id
}

output "PrivateSubnet1ACIDR" {
    description = " Private subnet 1A CIDR in Availability Zone 1"
    value = aws_subnet.private_A[0].cidr_block
  }

output "PrivateSubnet1AID" {
    description = " Private subnet 1A ID in Availability Zone 1"
    value =  aws_subnet.private_A[0].id
  }

output "PrivateSubnet2ACIDR" {
    description = " Private subnet 2A CIDR in Availability Zone 2"
    value = aws_subnet.private_A[1].cidr_block
  }

output "PrivateSubnet2AID" {
    description = " Private subnet 2A ID in Availability Zone 2"
    value = aws_subnet.private_A[1].id
  }

output "PrivateSubnet3ACIDR" {
    description = " Private subnet 3A CIDR in Availability Zone 3"
    value = length(aws_subnet.private_A.*.cidr_block) > 2 ? aws_subnet.private_A[2].cidr_block : null
  }

output "PrivateSubnet3AID" {
    description = " Private subnet 3A ID in Availability Zone 3"
    value = length(aws_subnet.private_A.*.id) > 2 ? aws_subnet.private_A[2].id : null
  }

output "PrivateSubnet4ACIDR" {
    description = " Private subnet 4A CIDR in Availability Zone 4"
    value = length(aws_subnet.private_A.*.cidr_block) > 3 ? aws_subnet.private_A[3].cidr_block : null
  }

output "PrivateSubnet4AID" {
    description = " Private subnet 4A ID in Availability Zone 4"
    value = length(aws_subnet.private_A.*.id) > 3 ? aws_subnet.private_A[3].id : null
  }

output "S3VPCEndpoint" {
    description = " Dynamo DB VPC Endpoint"
    value = aws_vpc_endpoint.s3.*.id
  }

output "PrivateSubnet1ARouteTable" {
    description = " Private subnet 1A route table"
    value = aws_route_table.private_A[0].id
  }

output "PrivateSubnet2ARouteTable" {
    description = " Private subnet 2A route table"
    value = aws_route_table.private_A[1].id
  }

output "PrivateSubnet3ARouteTable" {
    description = " Private subnet 3A route table"
    value = length(aws_route_table.private_A.*.id ) > 2 ? aws_route_table.private_A[2].id  : null 
  }

output "PrivateSubnet4ARouteTable" {
    description = " Private subnet 4A route table"
    value = length(aws_route_table.private_A.*.id ) > 3 ? aws_route_table.private_A[3].id  : null 
  }

# ---------------------------------------------------------------------------------------------------------------------
# PARAMETERS
# These parameters have reasonable defaults.
# ---------------------------------------------------------------------------------------------------------------------
variable "region" {
  type        = string
  description = "The name of the region you wish to deploy into"
  default     = "us-east-1"
}

variable "name" {
  description = "Name given resources"
  type        = string
  default     = "tfm-aws"
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "cidr" {
  description = "The CIDR block for the VPC. Default value is a valid CIDR, but not acceptable by AWS and should be overridden"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "A list of private subnets inside the VPC"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Public subnets inbound network ACLs -- scoped to the ephemeral TCP return-traffic range, not a blanket allow-all."
  type        = list(map(string))

  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 1024
      to_port     = 65535
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "public_outbound_acl_rules" {
  description = "Public subnets outbound network ACLs -- scoped to HTTPS, not a blanket allow-all."
  type        = list(map(string))

  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "custom_inbound_acl_rules" {
  description = "Custom subnets inbound network ACLs"
  type        = list(map(string))

  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

variable "custom_outbound_acl_rules" {
  description = "Custom subnets outbound network ACLs"
  type        = list(map(string))

  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_block  = "0.0.0.0/0"
    },
  ]
}

// File: context.tf
#
# ONLY EDIT THIS FILE IN github.com/cloudposse/terraform-null-label
# All other instances of this file should be a copy of that one
#
#
# Copy this file from https://github.com/cloudposse/terraform-null-label/blob/master/exports/context.tf
# and then place it in your Terraform module to automatically get
# Cloud Posse's standard configuration inputs suitable for passing
# to Cloud Posse modules.
#
# curl -sL https://raw.githubusercontent.com/cloudposse/terraform-null-label/master/exports/context.tf -o context.tf
#
# Modules should access the whole context as `module.this.context`
# to get the input variables with nulls for defaults,
# for example `context = module.this.context`,
# and access individual variables as `module.this.<var>`,
# with final values filled in.
#
# For example, when using defaults, `module.this.context.delimiter`
# will be null, and `module.this.delimiter` will be `-` (hyphen).
#

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0" # requires Terraform >= 0.13.0

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

# Copy contents of cloudposse/terraform-null-label/variables.tf here

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = "test-vpc"
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    # Note: we have to use [] instead of null for unset lists due to
    # https://github.com/hashicorp/terraform/issues/28137
    # which was not fixed until Terraform 1.0.0,
    # but we want the default to be all the labels in `label_order`
    # and we want users to be able to prevent all tag generation
    # by setting `labels_as_tags` to `[]`, so we need
    # a different sentinel to indicate "default"
    labels_as_tags = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = "rajesh-vpc"
  description = <<-EOT
    ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'.
    This is the only ID element not also included as a `tag`.
    The "name" tag is set to the full `id` string. There is no tag with the value of the `name` input.
    EOT
}

variable "delimiter" {
  type        = string
  default     = null
  description = <<-EOT
    Delimiter to be used between ID elements.
    Defaults to `-` (hyphen). Set to `""` to use no delimiter at all.
  EOT
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = <<-EOT
    ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`,
    in the order they appear in the list. New attributes are appended to the
    end of the list. The elements of the list are joined by the `delimiter`
    and treated as a single ID element.
    EOT
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = <<-EOT
    Set of labels (ID elements) to include as tags in the `tags` output.
    Default is to include all labels.
    Tags with empty values will not be included in the `tags` output.
    Set to `[]` to suppress all generated tags.
    **Notes:**
      The value of the `name` tag, if included, will be the `id`, not the `name`.
      Unlike other `null-label` inputs, the initial setting of `labels_as_tags` cannot be
      changed in later chained modules. Attempts to change it will be silently ignored.
    EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`).
    Neither the tag keys nor the tag values will be modified by this module.
    EOT
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional key-value pairs to add to each map in `tags_as_list_of_maps`. Not added to `tags` or `id`.
    This is for some rare cases where resources want additional configuration of tags
    and therefore take a list of maps with tag key, value, and additional configuration.
    EOT
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = <<-EOT
    The order in which the labels (ID elements) appear in the `id`.
    Defaults to ["namespace", "environment", "stage", "name", "attributes"].
    You can omit any of the 6 labels ("tenant" is the 6th), but at least one must be present.
    EOT
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = <<-EOT
    Terraform regular expression (regex) string.
    Characters matching the regex will be removed from the ID elements.
    If not set, `"/[^a-zA-Z0-9-]/"` is used to remove all characters other than hyphens, letters and digits.
  EOT
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = <<-EOT
    Limit `id` to this many characters (minimum 6).
    Set to `0` for unlimited length.
    Set to `null` for keep the existing setting, which defaults to `0`.
    Does not affect `id_full`.
  EOT
  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of the `tags` keys (label names) for tags generated by this module.
    Does not affect keys of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper`.
    Default value: `title`.
  EOT

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of ID elements (labels) as included in `id`,
    set as tag values, and output by this module individually.
    Does not affect values of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper` and `none` (no transformation).
    Set this to `title` and set `delimiter` to `""` to yield Pascal Case IDs.
    Default value: `lower`.
  EOT

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = <<-EOT
    Describe additional descriptors to be output in the `descriptors` output map.
    Map of maps. Keys are names of descriptors. Values are maps of the form
    `{
       format = string
       labels = list(string)
    }`
    (Type is `any` so the map values can later be enhanced to provide additional options.)
    `format` is a Terraform format string to be passed to the `format()` function.
    `labels` is a list of labels, in order, to pass to `format()` function.
    Label values will be normalized before being passed to `format()` so they will be
    identical to how they appear in `id`.
    Default is `{}` (`descriptors` output will be empty).
    EOT
}

#### End of copy of cloudposse/terraform-null-label/variables.tf

// File: main.tf
locals {
  enabled = module.this.enabled

  default_adoption_tags = merge(module.label.tags, {
    Name = join(module.label.delimiter, [module.label.id, "default"])
  })

  # Local variables corresponding to v2 module inputs that replace v0 inputs
  ipv4_primary_cidr_block          = var.ipv4_primary_cidr_block
  ipv4_cidr_block_associations     = var.ipv4_additional_cidr_block_associations
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block
  dns_hostnames_enabled            = var.dns_hostnames_enabled
  dns_support_enabled              = var.dns_support_enabled
  default_security_group_deny_all  = local.enabled && var.default_security_group_deny_all
  internet_gateway_enabled         = local.enabled && var.internet_gateway_enabled

  # Local variables that should be false when the module is disabled
  default_route_table_no_routes             = local.enabled && var.default_route_table_no_routes
  default_network_acl_deny_all              = local.enabled && var.default_network_acl_deny_all
  ipv6_egress_only_internet_gateway_enabled = local.enabled && var.ipv6_egress_only_internet_gateway_enabled
}

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context = module.this.context
}

resource "aws_vpc" "default" {
  count = local.enabled ? 1 : 0

  #bridgecrew:skip=BC_AWS_LOGGING_9:VPC Flow Logs are meant to be enabled by terraform-aws-vpc-flow-logs-s3-bucket and/or terraform-aws-cloudwatch-flow-logs
  cidr_block          = local.ipv4_primary_cidr_block
  ipv4_ipam_pool_id   = try(var.ipv4_primary_cidr_block_association.ipv4_ipam_pool_id, null)
  ipv4_netmask_length = try(var.ipv4_primary_cidr_block_association.ipv4_netmask_length, null)
  # Additional IPv4 CIDRs are handled by aws_vpc_ipv4_cidr_block_association below

  ipv6_cidr_block     = try(var.ipv6_primary_cidr_block_association.ipv6_cidr_block, null)
  ipv6_ipam_pool_id   = try(var.ipv6_primary_cidr_block_association.ipv6_ipam_pool_id, null)
  ipv6_netmask_length = try(var.ipv6_primary_cidr_block_association.ipv6_netmask_length, null)
  # Additional IPv6 CIDRs are handled by aws_vpc_ipv6_cidr_block_association below

  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = local.dns_hostnames_enabled
  enable_dns_support               = local.dns_support_enabled
  assign_generated_ipv6_cidr_block = local.assign_generated_ipv6_cidr_block
  tags                             = module.label.tags
}

# If `aws_default_security_group` is not defined, it will be created implicitly with access `0.0.0.0/0`
resource "aws_default_security_group" "default" {
  count = local.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.default[0].id
  tags   = local.default_adoption_tags
}

# If `aws_default_route_table` is not defined, it will be created implicitly with default routes
resource "aws_default_route_table" "default" {
  count = local.default_route_table_no_routes ? 1 : 0

  default_route_table_id = aws_vpc.default[0].default_route_table_id
  tags                   = local.default_adoption_tags
}

# If `aws_default_network_acl` is not defined, it will be created implicitly with access `0.0.0.0/0`
resource "aws_default_network_acl" "default" {
  count = local.default_network_acl_deny_all ? 1 : 0

  default_network_acl_id = aws_vpc.default[0].default_network_acl_id
  tags                   = local.default_adoption_tags
}

resource "aws_internet_gateway" "default" {
  count = local.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default[0].id
  tags   = module.label.tags
}

resource "aws_egress_only_internet_gateway" "default" {
  count = local.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.default[0].id
  tags   = module.label.tags
}

resource "aws_vpc_ipv4_cidr_block_association" "default" {
  for_each = local.enabled ? local.ipv4_cidr_block_associations : {}

  cidr_block          = each.value.ipv4_cidr_block
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  vpc_id = aws_vpc.default[0].id

  dynamic "timeouts" {
    for_each = local.enabled && var.ipv4_cidr_block_association_timeouts != null ? [true] : []
    content {
      create = lookup(var.ipv4_cidr_block_association_timeouts, "create", null)
      delete = lookup(var.ipv4_cidr_block_association_timeouts, "delete", null)
    }
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "default" {
  for_each = local.enabled ? var.ipv6_additional_cidr_block_associations : {}

  ipv6_cidr_block     = each.value.ipv6_cidr_block
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  vpc_id = aws_vpc.default[0].id

  dynamic "timeouts" {
    for_each = local.enabled && var.ipv6_cidr_block_association_timeouts != null ? [true] : []
    content {
      create = lookup(var.ipv6_cidr_block_association_timeouts, "create", null)
      delete = lookup(var.ipv6_cidr_block_association_timeouts, "delete", null)
    }
  }
}

// File: outputs.tf
output "vpc_id" {
  value       = join("", aws_vpc.default.*.id)
  description = "The ID of the VPC"
}

output "vpc_arn" {
  value       = join("", aws_vpc.default.*.arn)
  description = "The ARN of the VPC"
}

output "vpc_cidr_block" {
  value       = join("", aws_vpc.default.*.cidr_block)
  description = "The primary IPv4 CIDR block of the VPC"
}

output "vpc_main_route_table_id" {
  value       = join("", aws_vpc.default.*.main_route_table_id)
  description = "The ID of the main route table associated with this VPC"
}

output "vpc_default_network_acl_id" {
  value       = join("", aws_vpc.default.*.default_network_acl_id)
  description = "The ID of the network ACL created by default on VPC creation"
}

output "vpc_default_security_group_id" {
  value       = join("", aws_vpc.default.*.default_security_group_id)
  description = "The ID of the security group created by default on VPC creation"
}

output "vpc_default_route_table_id" {
  value       = join("", aws_vpc.default.*.default_route_table_id)
  description = "The ID of the route table created by default on VPC creation"
}

output "vpc_ipv6_association_id" {
  value       = join("", aws_vpc.default.*.ipv6_association_id)
  description = "The association ID for the primary IPv6 CIDR block"
}

output "vpc_ipv6_cidr_block" {
  value       = join("", aws_vpc.default.*.ipv6_cidr_block)
  description = "The primary IPv6 CIDR block"
}

output "additional_cidr_blocks" {
  description = "A list of the additional IPv4 CIDR blocks associated with the VPC"
  value = [
    for i in aws_vpc_ipv4_cidr_block_association.default :
    i.cidr_block
  ]
}

output "additional_cidr_blocks_to_association_ids" {
  description = "A map of the additional IPv4 CIDR blocks to VPC CIDR association IDs"
  value = {
    for i in aws_vpc_ipv4_cidr_block_association.default :
    i.cidr_block => i.id
  }
}

output "additional_ipv6_cidr_blocks" {
  description = "A list of the additional IPv6 CIDR blocks associated with the VPC"
  value = [
    for i in aws_vpc_ipv6_cidr_block_association.default :
    i.ipv6_cidr_block
  ]
}

output "additional_ipv6_cidr_blocks_to_association_ids" {
  description = "A map of the additional IPv6 CIDR blocks to VPC CIDR association IDs"
  value = {
    for i in aws_vpc_ipv6_cidr_block_association.default :
    i.ipv6_cidr_block => i.id
  }
}

output "ipv6_cidr_block_network_border_group" {
  value       = join("", aws_vpc.default.*.ipv6_cidr_block_network_border_group)
  description = "The IPv6 Network Border Group Zone name"
}

output "igw_id" {
  value       = join("", aws_internet_gateway.default.*.id)
  description = "The ID of the Internet Gateway"
}

output "ipv6_egress_only_igw_id" {
  value       = join("", aws_egress_only_internet_gateway.default.*.id)
  description = "The ID of the egress-only Internet Gateway"
}

// File: variables.tf
variable "ipv4_primary_cidr_block" {
  type        = string
  description = <<-EOT
    The primary IPv4 CIDR block for the VPC.
    Either `ipv4_primary_cidr_block` or `ipv4_primary_cidr_block_association` must be set, but not both.
    EOT
  default     = "11.0.0.0/16"
}

variable "ipv4_primary_cidr_block_association" {
  type = object({
    ipv4_ipam_pool_id   = string
    ipv4_netmask_length = number
  })
  description = <<-EOT
    Configuration of the VPC's primary IPv4 CIDR block via IPAM. Conflicts with `ipv4_primary_cidr_block`.
    One of `ipv4_primary_cidr_block` or `ipv4_primary_cidr_block_association` must be set.
    Additional CIDR blocks can be set via `ipv4_additional_cidr_block_associations`.
    EOT
  default     = null
}

variable "ipv4_additional_cidr_block_associations" {
  type = map(object({
    ipv4_cidr_block     = string
    ipv4_ipam_pool_id   = string
    ipv4_netmask_length = number
  }))
  description = <<-EOT
    IPv4 CIDR blocks to assign to the VPC.
    `ipv4_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv4_ipam_pool_id` using `ipv4_netmask_length`.
    Map keys must be known at `plan` time, and are only used to track changes.
    EOT
  default     = {}
}

variable "ipv4_cidr_block_association_timeouts" {
  type = object({
    create = string
    delete = string
  })
  description = "Timeouts (in `go` duration format) for creating and destroying IPv4 CIDR block associations"
  default     = null
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  description = "When `true`, assign AWS generated IPv6 CIDR block to the VPC.  Conflicts with `ipv6_ipam_pool_id`."
  default     = true
}

variable "ipv6_primary_cidr_block_association" {
  type = object({
    ipv6_cidr_block     = string
    ipv6_ipam_pool_id   = string
    ipv6_netmask_length = number
  })
  description = <<-EOT
    Primary IPv6 CIDR block to assign to the VPC. Conflicts with `assign_generated_ipv6_cidr_block`.
    `ipv6_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv6_ipam_pool_id` using `ipv6_netmask_length`.
    EOT
  default     = null
}

variable "ipv6_additional_cidr_block_associations" {
  type = map(object({
    ipv6_cidr_block     = string
    ipv6_ipam_pool_id   = string
    ipv6_netmask_length = number
  }))
  description = <<-EOT
    IPv6 CIDR blocks to assign to the VPC (in addition to the autogenerated one).
    `ipv6_cidr_block` can be set explicitly, or set to `null` with the CIDR block derived from `ipv6_ipam_pool_id` using `ipv6_netmask_length`.
    Map keys must be known at `plan` time and are used solely to prevent unnecessary changes.
    EOT
  default     = {}
}

variable "ipv6_cidr_block_association_timeouts" {
  type = object({
    create = string
    delete = string
  })
  description = "Timeouts (in `go` duration format) for creating and destroying IPv6 CIDR block associations"
  default     = null
}

variable "ipv6_cidr_block_network_border_group" {
  type        = string
  description = <<-EOT
    Set this to restrict advertisement of public addresses to a specific Network Border Group such as a LocalZone.
    Requires `assign_generated_ipv6_cidr_block` to be set to `true`.
    EOT
  default     = null
}

variable "instance_tenancy" {
  type        = string
  description = "A tenancy option for instances launched into the VPC"
  default     = "default"
  validation {
    condition     = contains(["default", "dedicated", "host"], var.instance_tenancy)
    error_message = "Instance tenancy must be one of \"default\", \"dedicated\", or \"host\"."
  }
}

variable "dns_hostnames_enabled" {
  type        = bool
  description = "Set `true` to enable [DNS hostnames](https://docs.aws.amazon.com/vpc/latest/userguide/vpc-dns.html#vpc-dns-hostnames) in the VPC"
  default     = true
}

variable "dns_support_enabled" {
  type        = bool
  description = "Set `true` to enable DNS resolution in the VPC through the Amazon provided DNS server"
  default     = true
}

variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = <<-EOT
    When `true`, manage the default security group and remove all rules, disabling all ingress and egress.
    When `false`, do not manage the default security group, allowing it to be managed by another component.
    EOT
}

variable "default_route_table_no_routes" {
  type        = bool
  default     = false
  description = <<-EOT
    When `true`, manage the default route table and remove all routes, disabling all ingress and egress.
    When `false`, do not mange the default route table, allowing it to be managed by another component.
    Conflicts with Terraform resource `aws_main_route_table_association`.
    EOT
}

variable "default_network_acl_deny_all" {
  type        = bool
  default     = false
  description = <<-EOT
    When `true`, manage the default network acl and remove all rules, disabling all ingress and egress.
    When `false`, do not mange the default networking acl, allowing it to be managed by another component.
    EOT
}

variable "internet_gateway_enabled" {
  type        = bool
  description = "Set `true` to create an Internet Gateway for the VPC"
  default     = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  description = "Set `true` to create an IPv6 Egress-Only Internet Gateway for the VPC"
  default     = false
}

// File: versions.tf
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.9.0"
    }
  }
}

// File: main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.10"
    }
  }
}

provider "aws" {
  region     = var.region
}

// Create Terraform user
resource "aws_iam_user" "user" {
  name = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

// Create a Terraform group for managing the infrastructure
resource "aws_iam_group" "group" {
  name = var.group_name
}

// Assign Terraform user to the group
resource "aws_iam_group_membership" "membership" {
  name = var.membership_name

  users = [
    aws_iam_user.user.name,
  ]

  group = aws_iam_group.group.name
}

// Provides an IAM access key for the user
resource "aws_iam_access_key" "terraform_access_key" {
  user = aws_iam_user.user.name
}

// Outputs access key ID
output "AWS_ACCESS_KEY_ID" {
  value = aws_iam_access_key.terraform_access_key.id
}

// Outputs secret access key
output "AWS_SECRET_ACCESS_KEY" {
  # sensitive = true
  value = nonsensitive(aws_iam_access_key.terraform_access_key.secret)
}

// File: policies.tf
resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "sts:GetCallerIdentity"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_basic_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

// Create
resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_create_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

// Read
resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:ImportKeyPair",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeImages",
          "ec2:DescribeVolumes",
          "ec2:DescribeSubnets",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeRouteTables",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeVpcs",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeImportImageTasks",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeTags",
          "ec2:DescribeAddresses"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "read_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

// Update
resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:ModifyVpc*",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyLocalGatewayRoute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifyVolumeAttribute",
          "ec2:ModifyAvailabilityZoneGroup",
          "ec2:ReplaceRouteTableAssociation",
          "ec2:AttachInternetGateway",
          "ec2:AssociateAddress"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "update_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

// Delete
resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:DeleteKeyPair",
          "ec2:DeleteVpc",
          "ec2:DeleteSubnet",
          "ec2:DeleteInternetGateway",
          "ec2:DetachInternetGateway",
          "ec2:DeleteRouteTable",
          "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
          "ec2:DeleteSecurityGroup",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:ReleaseAddress"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_delete_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ],
        "Resource" : "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_instance_policy" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

// Necessary for acessing the terraform backend
resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policies_path

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Effect" : "Allow",
        "Action" : [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
        ]
        "Resource" : [
          "*"
          # // TODO: only allow actions on a specific dynamodb table
          # "arn:aws:dynamodb:*:*:table/*",
        ]
      },
      {
        "Effect" : "Allow",
        "Action" : [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        "Resource" : [
          "*"
          # // TODO: only allow actions on a specific s3 bucket
          # "arn:aws:s3:::*"
        ]
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "attach_terraform_backend_access" {
  group      = aws_iam_group.group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

// File: variables.tf
variable "region" {
  type        = string
  default     = "sa-east-1"
}
variable "project_tag" {
  type        = string
  default     = "my-vpn-tag"
}
variable "username" {
  type        = string
  default     = "my_vpn_infra_user"
}
variable "group_name" {
  type        = string
  default     = "my-vpn-infra-group"
}
variable "membership_name" {
  type        = string
  default     = "my-vpn-infra-manager-group"
}
variable "policies_path" {
  type        = string
  default     = "/my_vpn_infra/"
}

// File: main.tf
# VPC Creation
resource "aws_vpc" "main" {
    cidr_block              = "${var.vpc_cidr_block}"
    enable_dns_hostnames    = true
    tags = {
        Name                = "${var.environment}-vpc"
    }
}

# Public Subnet Creation
resource "aws_subnet" "public-subnet-1a" {
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.public_subnet_1a_cidr_block
    availability_zone   = "us-east-1a"


    tags = {
        Name            = "${var.environment}-public-subnet-1a"
    }
}

resource "aws_subnet" "public-subnet-1b" {
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.public_subnet_1b_cidr_block
    availability_zone   = "us-east-1b"
    tags = {
        Name            = "${var.environment}-public-subnet-1b"
    }
}

# Private Subnet Creation
resource "aws_subnet" "private-subnet-1a" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.private_subnet_1a_cidr_block
    availability_zone   = "us-east-1a"
    tags = {
        Name            = "${var.environment}-private-subnet-1a"
    }
}

resource "aws_subnet" "private-subnet-1b" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id              = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id
    cidr_block          = var.private_subnet_1b_cidr_block
    availability_zone   = "us-east-1b"

    tags = {
        Name            = "${var.environment}-private-subnet-1b"
    }

}

# Route Table Creation - Public 
resource "aws_route_table" "public-route-table" {
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-public-route-table"
    }
}

# Route Table Creation - Private
resource "aws_route_table" "private-route-table" {
    count = var.craete_private_subnet ? 1 : 0
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-private-route-table"
    }
}

# Route Table Association - Public

resource "aws_route_table_association" "public-subnet-1a" {
    subnet_id       = aws_subnet.public-subnet-1a.id
    route_table_id  = aws_route_table.public-route-table.id
}

resource "aws_route_table_association" "public-subnet-1b" {
    subnet_id       = aws_subnet.public-subnet-1b.id
    route_table_id  = aws_route_table.public-route-table.id
}

# Route Table Association - Private

resource "aws_route_table_association" "private-subnet-1a" {
    count = var.craete_private_subnet ? 1 : 0
    subnet_id       = aws_subnet.private-subnet-1a[0].id
    route_table_id  = aws_route_table.private-route-table[0].id
}

resource "aws_route_table_association" "private-subnet-1b" {
    count = var.craete_private_subnet ? 1 : 0
    subnet_id       = aws_subnet.private-subnet-1b[0].id
    route_table_id  = aws_route_table.private-route-table[0].id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "elastic-ip-for-nat-gateway" {
    count = var.craete_private_subnet ? 1 : 0
    domain                         = "vpc"
    associate_with_private_ip   = var.private_ip_for_nat_gateway

    tags = {
      Name = "${var.environment}-EIP-for-NAT-Gateway"
    }
}

# Nat Gateway creation
resource "aws_nat_gateway" "nat-gw" {
    count = var.craete_private_subnet ? 1 : 0
    allocation_id   = aws_eip.elastic-ip-for-nat-gateway[0].id
    subnet_id       = aws_subnet.public-subnet-1a.id

    tags = {
      Name = "${var.environment}-NAT-Gateway"
    }

    depends_on = [ aws_eip.elastic-ip-for-nat-gateway ]
}

# Internet Gateway Creation

resource "aws_internet_gateway" "main-igw" {
    vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main.id

    tags = {
      Name = "${var.environment}-IGW"
    }
}


# Nat Gateway & route table association [ private route]

resource "aws_route" "nat-gw-route" {
    count = var.craete_private_subnet ? 1 : 0
    route_table_id          = aws_route_table.private-route-table[0].id
    nat_gateway_id          = aws_nat_gateway.nat-gw[0].id
    destination_cidr_block  = "0.0.0.0/0"
}

# Public IGW & route table association [ public route]

resource "aws_route" "igw-route" {
    route_table_id          = aws_route_table.public-route-table.id
    gateway_id              = aws_internet_gateway.main-igw.id
    destination_cidr_block  = "0.0.0.0/0"
}

// File: output.tf
output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr_block" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_1a_id" {
  value = aws_subnet.public-subnet-1a.id
}

output "public_subnet_1b_id" {
  value = aws_subnet.public-subnet-1b.id
}

output "private_subnet_1a_id" {
  value = aws_subnet.private-subnet-1a[*].id
}

output "private_subnet_1b_id" {
  value = aws_subnet.private-subnet-1b[*].id
}

output "private_subnets" {
  value = tolist([aws_subnet.private-subnet-1a[*].id, aws_subnet.private-subnet-1b[*].id])
}

output "public_subnets" {
  value = tolist([aws_subnet.public-subnet-1a.id, aws_subnet.public-subnet-1b.id])
}

