  tags = {
    Name = "bjit-public-ssh"
    Project = "BJIT DevOps Task"
    Author = "Ariful Islam" 
  }
}
resource "aws_security_group_rule" "bjit_public_ssh" {
  type        = "ingress"
  from_port   = 22
  to_port     = 22
  protocol    = "tcp"
  cidr_blocks = [aws_vpc.bjit_vpc.cidr_block]
