}

resource "aws_security_group_rule" "bjit_api_server_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = [aws_vpc.bjit_vpc.cidr_block]
  security_group_id = aws_security_group.bjit_api_server_sg.id
}
resource "aws_security_group_rule" "bjit_file_server_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = [aws_vpc.bjit_vpc.cidr_block]
  security_group_id = aws_security_group.bjit_file_server_sg.id
}
resource "aws_security_group_rule" "bjit_public_ssh_outbound" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = [aws_vpc.bjit_vpc.cidr_block]
  security_group_id = aws_security_group.bjit_public_ssh_sg.id
}

resource "aws_eip" "natgw" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)
  domain = "vpc"

  tags = merge(
    {
      "Name" = "${var.base_name}-natgw-eip-${count.index}"
    },
    var.tags
  )
}

data "aws_region" "current" {}

resource "aws_vpc_endpoint" "ecr_api" {
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  vpc_id              = aws_vpc.main.id
//  subnet_ids          = aws_subnet.private.*.id
  subnet_ids          = var.subnet_private_cidrs == null ? aws_subnet.public.*.id : aws_subnet.private.*.id
  security_group_ids  = [aws_security_group.ecr_endpoint.id]
  private_dns_enabled = true

  tags = merge(
    {
      "Name" = "${var.base_name}-ECR-API-Endpoint"
    },
    var.tags
  )
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  vpc_id              = aws_vpc.main.id
//  subnet_ids          = aws_subnet.private.*.id
  subnet_ids          = var.subnet_private_cidrs == null ? aws_subnet.public.*.id : aws_subnet.private.*.id
  security_group_ids  = [aws_security_group.ecr_endpoint.id]
  private_dns_enabled = true

  tags = merge(
    {
      "Name" = "${var.base_name}-ECR-DKR-Endpoint"
    },
    var.tags
  )
}


resource "aws_vpc_endpoint" "s3_public_subnet" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = [aws_route_table.public.id]

  tags = merge(
    {
      "Name" = "${var.base_name}-S3-Endpoint-public-subnet"
    },
    var.tags
  )
}

resource "aws_vpc_endpoint" "s3_private_subnet" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = aws_route_table.private.*.id

  tags = merge(
  {
    "Name" = "${var.base_name}-S3-Endpoint-private-subnet"
  },
  var.tags
  )
}

# com.amazonaws.Region.logs

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-internet-gateway"
    },
    var.tags
  )
}

resource "aws_nat_gateway" "ngw" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  allocation_id = aws_eip.natgw[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    {
      "Name" = "${var.base_name}-nat-gateway-${count.index}"
    },
    var.tags
  )
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "vpc_cidr" {
  value = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  value = [
    for subnet in aws_subnet.public :
    subnet.id
  ]
}

output "private_subnet_ids" {
  value = [
    for subnet in aws_subnet.private :
    subnet.id
  ]
}

resource "aws_route_table" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-private-route-table-${count.index}"
    },
    var.tags
  )
}

resource "aws_route" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.ngw[count.index].id
}

resource "aws_route_table_association" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      "Name" = "${var.base_name}-public-route-table"
    },
    var.tags
  )
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw.id
}

resource "aws_route_table_association" "public" {
  count = length(var.subnet_public_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecr_endpoint" {
  name        = "${var.base_name}-ecr-endpoint-sg"
  vpc_id      = aws_vpc.main.id
  description = "For ECR Endpoint"

  tags = merge(
    {
      "Name" = "${var.base_name}-ecr-endpoint-sg"
    },
    var.tags
  )

  ingress {
    description = "Allow ECR access from subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  egress {
    description = "Allow within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

resource "aws_security_group_rule" "ecr_endpont_private" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  description = "Allow ECR access from subnets"
  from_port   = 443
  to_port     = 443
  protocol    = "tcp"
  cidr_blocks = var.subnet_private_cidrs
  security_group_id = aws_security_group.ecr_endpoint.id
  type = "ingress"
}

data "aws_availability_zones" "available" {}

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-public-subnet-${count.index}"
    },
    var.tags
  )
}

resource "aws_subnet" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-private-subnet-${count.index}",
    },
    var.tags
  )
}

# common parameter
variable "tags" {
  description = "リソース群に付与する共通タグ"
  type        = map(string)
  default     = {}
}

variable "base_name" {
  description = "作成するリソースに付与する接頭語"
  type        = string
  default     = "benchmark"
}

# module parameter
variable "vpc_cidr" {
  description = "VPCのネットワークアドレス帯"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "パブリックサブネットのアドレス帯"
  type        = list(string)
  default     = ["10.0.1.0/24","10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "プライベートサブネットのアドレス帯"
  type        = list(string)
  default     = null
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = merge(
    {
      "Name"                                   = "${var.base_name}-vpc",
      "kubernetes.io/cluster/${var.base_name}" = "shared"
    },
    var.tags
  )
}

#provider
variable "aws_region" {
  type        = string 
  description = "region"
  default     = "eu-central-1"
}
# vpc cidr
variable "cidr_vpc" {
  type        = string 
  description = "cidr"
  default     = "10.0.0.0/16" 
}
# pubsub-1
variable "subpub1" {
  type        = string 
  description = "subnet"
  default     = "10.0.1.0/24" 
}
# pubsub-2
variable "subpub2" {
  type        = string 
  description = "subnet"
  default     = "10.0.2.0/24" 
}
# pvtsub-1
variable "subpvt1" {
  type        = string 
  description = "subnet"
  default     = "10.0.3.0/24" 
}
# pvtsub-2
variable "subpvt2" {
  type        = string 
  description = "subnet"
  default     = "10.0.4.0/24" 
}
# azpub-1
variable "azpub1" {
  type        = string 
  description = "subnet"
  default     = "eu-central-1a" 
}
# azpub-2
variable "az_sub_pub2" {
  type        = string 
  description = "subnet"
  default     = "eu-central-1b" 
}
# azpvt-1
variable "az_sub_pvt1" {
  type        = string 
  description = "subnet"
  default     = "eu-central-1a" 
}
# azpvt-2
variable "az_sub_pvt2" {
  type        = string 
  description = "subnet"
  default     = "eu-central-1b"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = "eu-central-1"
}
# vpc
resource "aws_vpc" "myvpc" {
  cidr_block       = var.cidr_vpc #10.0.0.0/16
  instance_tenancy = "default"

  tags = {
    Name = "project-vpc"
  }
}
# SUBNET
# pub subnet 1
resource "aws_subnet" "pubsub1" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = var.subpub1 #10.0.1.0/16
  availability_zone = var.azpub1

  tags = {
    Name = "pub-sub-1"
  }
}
# pub subnet 2
resource "aws_subnet" "pubsub2" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = var.subpub2 #10.0.2.0/16
  availability_zone = var.az_sub_pub2

  tags = {
    Name = "pub-sub-2"
  }
}
# pvt subnet 1
resource "aws_subnet" "pvtsub1" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = var.subpvt1 #10.0.3.0/16
  availability_zone = var.az_sub_pvt1

  tags = {
    Name = "pvt-sub-1"
  }
}

# pvt subnet 2
resource "aws_subnet" "pvtsub2" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = var.subpvt2 #10.0.4.0/16
  availability_zone = var.az_sub_pvt2

  tags = {
    Name = "pvt-sub-2"
  }
}

# igw
resource "aws_internet_gateway" "tigw" {
  vpc_id = aws_vpc.myvpc.id

  tags = {
    Name = "T-igw"
  }
}

# ROUTE TABLE
# PUB-RT-1
resource "aws_route_table" "pubrt1" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.tigw.id
  }
  tags = {
    Name = "RT_PUBRT-1"
  }
}

# PUB-RT-2
resource "aws_route_table" "pubrt2" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.tigw.id
  }
  tags = {
    Name = "RT_PUBRT-2"
  }
}

# PVT-RT-1
resource "aws_route_table" "pvtrt1" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.pvtnat1.id
  }
  tags = {
    Name = "RT_PVTRT-1"
  }
}
# PVT-RT-2
resource "aws_route_table" "pvtrt2" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.pvtnat1.id
  }
  tags = {
    Name = "RT_PVTRT-2"
  }
}

# ROUTE TABLE ASC
# ASCPUB SUB 1
resource "aws_route_table_association" "pubasc1" {
  subnet_id      = aws_subnet.pubsub1.id
  route_table_id = aws_route_table.pubrt1.id
}

# ASCPUB SUB 2
resource "aws_route_table_association" "pubasc2" {
  subnet_id      = aws_subnet.pubsub2.id
  route_table_id = aws_route_table.pubrt2.id
}
# ASCPVT SUB 1
resource "aws_route_table_association" "pvtasc1" {
  subnet_id      = aws_subnet.pvtsub1.id
  route_table_id = aws_route_table.pvtrt1.id
}

# ASCPVT SUB 2
resource "aws_route_table_association" "pvtasc2" {
  subnet_id      = aws_subnet.pvtsub2.id
  route_table_id = aws_route_table.pvtrt2.id
}

#EIP -1
resource "aws_eip" "eip1" {
  vpc = "true"
}

# EIP-2
resource "aws_eip" "eip2" {
  vpc   = "true"
}

# NAT-1
resource "aws_nat_gateway" "pvtnat1" {
  allocation_id = aws_eip.eip1.id
  subnet_id     = aws_subnet.pubsub1.id

  tags = {
    Name = "T-NAT1"
  }
}

# NAT -2
resource "aws_nat_gateway" "pvtnat2" {
  allocation_id = aws_eip.eip2.id
  subnet_id     = aws_subnet.pubsub2.id

  tags = {
    Name = "T-NAT1"
  }
}

# PUb-SEG
resource "aws_security_group" "pub_sec" {
  name        = "allow_tls"
  description = "Allow TLS inbound traffic"
  vpc_id      = aws_vpc.myvpc.id

  ingress {
    description      = "https"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
  }
  ingress {
    description      = "ssh"
    from_port        = 22
    to_port          = 22
    protocol         = "tcp"
    # Placeholder admin source (RFC 5737 documentation range) -- override with your
    # real source IP/CIDR, not left open to the world.
    cidr_blocks      = ["203.0.113.0/24"]
  }
  ingress {
    description      = "http"
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
  }

  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = [aws_vpc.myvpc.cidr_block]
  }

  tags = {
    Name = "pub-seg"
  }
}

#pvt-seg

resource "aws_security_group" "pvt_sec" {
  name        = "pvt-seg"
  description = "Allow TLS inbound traffic"
  vpc_id      = aws_vpc.myvpc.id

  ingress {
    description      = "https"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    security_groups = [aws_security_group.pub_sec.id]
  }
  ingress {
    description      = "ssh"
    from_port        = 22
    to_port          = 22
    protocol         = "tcp"
    security_groups = [aws_security_group.pub_sec.id]
  }
  ingress {
    description      = "http"
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    security_groups = [aws_security_group.pub_sec.id]
  }
  ingress {
    description      = "postgres"
    from_port        = 5432
    to_port          = 5432
    protocol         = "tcp"
    security_groups = [aws_security_group.pub_sec.id]
  }

  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    security_groups = [aws_security_group.pub_sec.id]

  }

  tags = {
    Name = "pvt-seg"
  }
}

// File: main.tf
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Create an IAM role for API Gateway
resource "aws_iam_role" "APIGWRole" {
  assume_role_policy = <<POLICY1
{
  "Version" : "2012-10-17",
  "Statement" : [
    {
      "Effect" : "Allow",
      "Principal" : {
        "Service" : "apigateway.amazonaws.com"
      },
      "Action" : "sts:AssumeRole"
    }
  ]
}
POLICY1
}

# Create an IAM policy for API Gateway to PutItem & Query DynamoDB
resource "aws_iam_policy" "APIGWPolicy" {
  policy = <<POLICY2
{
  "Version" : "2012-10-17",
  "Statement" : [
    {
      "Effect" : "Allow",
      "Action" : [
        "dynamodb:PutItem",
        "dynamodb:Query"
      ],
      "Resource" : [ "${aws_dynamodb_table.MyDynamoDBTable.arn}",
      "${aws_dynamodb_table.MyDynamoDBTable.arn}/index/*" ]
    }
  ]
}
POLICY2
}

# Attach the IAM policies to the equivalent rule
resource "aws_iam_role_policy_attachment" "APIGWPolicyAttachment" {
  role       = aws_iam_role.APIGWRole.name
  policy_arn = aws_iam_policy.APIGWPolicy.arn
}

# Create a new DynamoDB table with all attributes and Indexes
resource "aws_dynamodb_table" "MyDynamoDBTable" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    write_capacity     = 5
    read_capacity      = 5
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
  }

}

#Create a new API Gateway rest api with DynamoDB Integration that requires an API Key for security
resource "aws_api_gateway_rest_api" "MyApiGatewayRestApi" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
  body = jsonencode({
    "swagger" : "2.0",
    "info" : {
      "version" : "2022-03-21T11:36:12Z",
      "title" : "APIGW DynamoDB Serverless Pattern Demo"
    },
    "basePath" : "/v1",
    "schemes" : ["https"],
    "paths" : {
      "/pets" : {
        "post" : {
          "consumes" : ["application/json"],
          "produces" : ["application/json"],
          "responses" : {
            "200" : {
              "description" : "200 response"
            }
          },
          "security" : [{
            "api_key" : []
          }],
          "x-amazon-apigateway-integration" : {
            "type" : "aws",
            "credentials" : "${aws_iam_role.APIGWRole.arn}",
            "httpMethod" : "POST",
            "uri" : "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem",
            "responses" : {
              "default" : {
                "statusCode" : "200",
                "responseTemplates" : {
                  "application/json" : "{}"
                }
              }
            },
            "requestTemplates" : {
              "application/json" : "{\"TableName\":\"Pets\",\"Item\":{\"id\":{\"S\":\"$context.requestId\"},\"PetType\":{\"S\":\"$input.path('$.PetType')\"},\"PetName\":{\"S\":\"$input.path('$.PetName')\"},\"PetPrice\":{\"N\":\"$input.path('$.PetPrice')\"},\"PetBoolean\":{\"BOOL\":true}}}"
            },
            "passthroughBehavior" : "when_no_templates"
          }
        }
      },
      "/pets/{PetType}" : {
        "get" : {
          "consumes" : ["application/json"],
          "produces" : ["application/json"],
          "parameters" : [{
            "name" : "PetType",
            "in" : "path",
            "required" : true,
            "PetType" : "string"
          }],
          "responses" : {
            "200" : {
              "description" : "200 response"
            }
          },
          "security" : [{
            "api_key" : []
          }],
          "x-amazon-apigateway-integration" : {
            "type" : "aws",
            "credentials" : "${aws_iam_role.APIGWRole.arn}",
            "httpMethod" : "POST",
            "uri" : "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/Query",
            "responses" : {
              "default" : {
                "statusCode" : "200",
                "responseTemplates" : {
                  "application/json" : "#set($inputRoot = $input.path('$'))\n{\n\t\"pets\": [\n\t\t#foreach($field in $inputRoot.Items) {\n\t\t\t\"id\": \"$field.id.S\",\n\t\t\t\"PetType\": \"$field.PetType.S\",\n\t\t\t\"PetName\": \"$field.PetName.S\",\n\t\t\t\"PetPrice\": \"$field.PetPrice.N\"\n\t\t}#if($foreach.hasNext),#end\n\t\t#end\n\t]\n}"
                }
              }
            },
            "requestParameters" : {
              "integration.request.path.PetType" : "method.request.path.PetType"
            },
            "requestTemplates" : {
              "application/json" : "{\"TableName\":\"Pets\",\"IndexName\":\"PetType-index\",\"KeyConditionExpression\":\"PetType=:v1\",\"ExpressionAttributeValues\":{\":v1\":{\"S\":\"$util.urlDecode($input.params('PetType'))\"}}}"
            },
            "passthroughBehavior" : "when_no_templates"
          }
        }
      }
    },
    "securityDefinitions" : {
      "api_key" : {
        "type" : "apiKey",
        "name" : "x-api-key",
        "in" : "header"
      }
    }
  })
}

# Create a new API Gateway deployment for the created rest api
resource "aws_api_gateway_deployment" "MyApiGatewayDeployment" {
  rest_api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
}

# Create a Log Group for API Gateway to push logs to
resource "aws_cloudwatch_log_group" "MyLogGroup" {
  name_prefix = "/aws/APIGW/terraform"
}

# Create a Log Policy to allow Cloudwatch to Create log streams and put logs
resource "aws_cloudwatch_log_resource_policy" "MyCloudWatchLogPolicy" {
  policy_name     = "Terraform-CloudWatchLogPolicy-${data.aws_caller_identity.current.account_id}"
  policy_document = <<POLICY3
{
  "Version": "2012-10-17",
  "Id": "CWLogsPolicy",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": [
          "apigateway.amazonaws.com",
          "delivery.logs.amazonaws.com"
          ]
      },
      "Action": [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
        ],
      "Resource": "${aws_cloudwatch_log_group.MyLogGroup.arn}",
      "Condition": {
        "ArnEquals": {
          "aws:SourceArn": "${aws_api_gateway_rest_api.MyApiGatewayRestApi.arn}"
        }
      }
    }
  ]
}
POLICY3
}

# Create a new API Gateway stage with logging enabled
resource "aws_api_gateway_stage" "MyApiGatewayStage" {
  deployment_id = aws_api_gateway_deployment.MyApiGatewayDeployment.id
  rest_api_id   = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
  stage_name    = "v1"
  depends_on    = [aws_api_gateway_account.ApiGatewayAccountSetting]

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.MyLogGroup.arn
    format          = "{ \"requestId\":\"$context.requestId\", \"ip\": \"$context.identity.sourceIp\", \"requestTime\":\"$context.requestTime\", \"httpMethod\":\"$context.httpMethod\",\"routeKey\":\"$context.routeKey\", \"status\":\"$context.status\",\"protocol\":\"$context.protocol\", \"responseLength\":\"$context.responseLength\" }"
  }
}

# If you are using apigateway and you have an existing cloudwatch role ARN set to your account delete the aws_api_gateway_account block, the aws_iam_role block & the aws_iam_role_policy block.

## delete if you have this configured in your account
resource "aws_api_gateway_account" "ApiGatewayAccountSetting" {
  cloudwatch_role_arn = aws_iam_role.APIGatewayCloudWatchRole.arn
}

## delete if you have this configured in your account
resource "aws_iam_role" "APIGatewayCloudWatchRole" {
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "",
      "Effect": "Allow",
      "Principal": {
        "Service": "apigateway.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

## delete if you have this configured in your account
resource "aws_iam_role_policy" "APIGatewayCloudWatchPolicy" {
  role = aws_iam_role.APIGatewayCloudWatchRole.id

  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": [
                "logs:CreateLogGroup",
                "logs:CreateLogStream",
                "logs:DescribeLogGroups",
                "logs:DescribeLogStreams",
                "logs:PutLogEvents",
                "logs:GetLogEvents",
                "logs:FilterLogEvents"
            ],
            "Resource": "*"
        }
    ]
}
EOF
}

# Configure API Gateway to push all logs to CloudWatch Logs
resource "aws_api_gateway_method_settings" "MyApiGatewaySetting" {
  rest_api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
  stage_name  = aws_api_gateway_stage.MyApiGatewayStage.stage_name
  method_path = "*/*"

  settings {
    # Enable CloudWatch logging and metrics
    metrics_enabled = true
    logging_level   = "INFO"
  }
}

# Create an API Gateway usage plan to use with the created REST API
resource "aws_api_gateway_usage_plan" "MyApiGatewayUsagePlan" {
  name = "apigw-dynamodb-terraform-usage-plan"

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  api_stages {
    api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
    stage  = aws_api_gateway_stage.MyApiGatewayStage.stage_name
  }
}

# Create an API Gateway Key
resource "aws_api_gateway_api_key" "MyAPIKey" {
  name = "apigw-dynamodb-terraform-api-key"
}

# Create an API Gateway Usage Plan key and associate it to the previously created API Key
resource "aws_api_gateway_usage_plan_key" "MyAPIGWUsagePlanKey" {
  key_id        = aws_api_gateway_api_key.MyAPIKey.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.MyApiGatewayUsagePlan.id
}

# Display APIGW invocation URL
output "apigw_endpoint" {
  value       = "${aws_api_gateway_stage.MyApiGatewayStage.invoke_url}/pets"
  description = "The API Gateway Invocation URL"
}

# Display the APIGW Key to use for testing
output "apigw_key" {
  value       = aws_api_gateway_usage_plan_key.MyAPIGWUsagePlanKey.value
  description = "The APIGW Key to use for testing"
}

# Main bucket
resource "aws_s3_bucket" "main" {
  bucket_prefix = var.name
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket     = aws_s3_bucket.main.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_kms_key" "main" {
  description         = "CMK for ${var.name} S3 bucket"
  enable_key_rotation = true
  count               = var.no_default_encryption ? 0 : 1
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main[0].arn
    }
  }

  count = var.no_default_encryption ? 0 : 1
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "main" {
  bucket = aws_s3_bucket.main.id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.name

  count = var.no_logging ? 0 : 1
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = var.no_versioning ? "Disabled" : "Enabled"
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }

  count = var.website_enabled ? 1 : 0
}

# Logging bucket
resource "aws_s3_bucket" "logging" {
  bucket_prefix = "${var.name}-logging"
  force_destroy = true

  count = var.no_logging ? 0 : 1
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  bucket = aws_s3_bucket.logging[0].id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
  count = var.no_logging ? 0 : 1
}

resource "aws_s3_bucket_acl" "logging" {
  bucket     = aws_s3_bucket.logging[0].id
  acl        = var.bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.logging]
  count      = var.no_logging ? 0 : 1
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
  count                   = var.no_logging ? 0 : 1
}

resource "aws_kms_key" "logging" {
  description         = "CMK for ${var.name}-logging S3 bucket"
  enable_key_rotation = true
  count               = var.no_logging ? 0 : 1
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging[0].id
  count  = var.no_logging ? 0 : 1

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logging[0].arn
    }
  }
}

# Force SSL only access policy
resource "aws_s3_bucket_policy" "force_ssl_only_access" {
  bucket = aws_s3_bucket.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ForceSSLOnlyAccess"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  count = var.allow_cleartext ? 1 : 0
}

# Get-only bucket
resource "aws_s3_bucket" "getonly" {
  bucket_prefix = "${var.name}-getonly"
  force_destroy = true

  count = var.s3_getobject_only ? 1 : 0
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false

  count = var.s3_getobject_only ? 1 : 0
}

resource "aws_s3_bucket_policy" "getonly" {
  bucket = aws_s3_bucket.getonly[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource = [
          aws_s3_bucket.getonly[0].arn,
          "${aws_s3_bucket.getonly[0].arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.getonly]
  count      = var.s3_getobject_only ? 1 : 0
}

# Public bucket
resource "aws_s3_bucket" "public" {
  bucket_prefix = "${var.name}-public"
  force_destroy = true

  count = var.s3_public ? 1 : 0
}

resource "aws_s3_bucket_public_access_block" "public" {
  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false

  count = var.s3_public ? 1 : 0
}

resource "aws_s3_bucket_policy" "public" {
  bucket = aws_s3_bucket.public[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWriteObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.public]
  count      = var.s3_public ? 1 : 0
}

output "bucket_id" {
  description = "the bucket id"
  value       = aws_s3_bucket.main.id
}

variable "name" {
  description = "bucket name"
  type        = string
  default     = "sadcloud"
}

variable "logging_bucket" {
  description = "Logging bucket used for this bucket"
  type        = string
  default     = "sadcloud_logs"
}

variable "bucket_acl" {
  description = "Canned acl"
  type        = string
  default     = "log-delivery-write"
}

variable "sse_algorithm" {
  description = "Encryption algorithm to use"
  type        = string
  default     = "AES256"
}

variable "allow_cleartext" {
  description = "should the bucket allow HTTP"
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "should the bucket disable encryption"
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "should the bucket disable logging"
  type        = bool
  default     = false
}

variable "no_versioning" {
  description = "should the bucket disable versioning"
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "should the bucket enable the website"
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "internet accessible s3 bucket (only GetObject)"
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "internet accessible s3 bucket"
  type        = bool
  default     = false
}

// File: main.tf
# Copyright IBM Corp. 2014, 2026
