  name = "AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryAgentRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryAgentRole.name
