// File: outputs.tf
output "codedeploy_app_name" {
  description = "Name of CodeDeploy application"
  value       = local.app_name
}

output "codedeploy_deployment_group_name" {
  description = "CodeDeploy deployment group name"
  value       = local.deployment_group_name
}

output "codedeploy_deployment_group_id" {
  description = "CodeDeploy deployment group id"
  value       = try(aws_codedeploy_deployment_group.this[0].id, "")
}

output "codedeploy_iam_role_name" {
  description = "Name of IAM role used by CodeDeploy"
  value       = try(aws_iam_role.codedeploy[0].name, "")
}

output "appspec" {
  description = "Appspec data as HCL"
  value       = local.appspec
}

output "appspec_content" {
  description = "Appspec data as valid JSON"
  value       = local.appspec_content
}

output "appspec_sha256" {
  description = "SHA256 of Appspec JSON"
  value       = local.appspec_sha256
}

output "script" {
  description = "Deployment script"
  value       = local.script
}

output "deploy_script" {
  description = "Path to a deployment script"
  value       = try(local_file.deploy_script[0].filename, "")
}

// File: variables.tf
variable "create" {
  description = "Controls whether resources should be created"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to resources."
  type        = map(string)
  default     = {}
}

variable "alias_name" {
  description = "Name for the alias"
  type        = string
  default     = ""
}

variable "function_name" {
  description = "The name of the Lambda function to deploy"
  type        = string
  default     = ""
}

variable "current_version" {
  description = "Current version of Lambda function version to deploy (can't be $LATEST)"
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Target version of Lambda function version to deploy"
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute before allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute after allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = ""
}

variable "interpreter" {
  description = "List of interpreter arguments used to execute deploy script, first arg is path"
  type        = list(string)
  default     = ["/bin/bash", "-c"]
}

variable "description" {
  description = "Description to use for the deployment"
  type        = string
  default     = ""
}

#########################
# CodeDeploy Application
#########################

variable "create_app" {
  description = "Whether to create new AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use existing AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of AWS CodeDeploy application"
  type        = string
  default     = ""
}

##############################
# CodeDeploy Deployment Group
##############################

variable "create_deployment_group" {
  description = "Whether to create new AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use existing AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of deployment group to use"
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "Name of deployment config to use"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  description = "Indicates whether a defined automatic rollback configuration is currently enabled for this Deployment Group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "List of event types that trigger a rollback. Supported types are DEPLOYMENT_FAILURE and DEPLOYMENT_STOP_ON_ALARM."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_enabled" {
  description = "Indicates whether the alarm configuration is enabled. This option is useful when you want to temporarily deactivate alarm monitoring for a deployment group without having to add the same alarms again later."
  type        = bool
  default     = false
}

variable "alarms" {
  description = "A list of alarms configured for the deployment group. A maximum of 10 alarms can be added to a deployment group."
  type        = list(string)
  default     = []
}

variable "alarm_ignore_poll_alarm_failure" {
  description = "Indicates whether a deployment should continue if information about the current state of alarms cannot be retrieved from CloudWatch."
  type        = bool
  default     = false
}

variable "triggers" {
  description = "Map of triggers which will be notified when event happens. Valid options for event types are DeploymentStart, DeploymentSuccess, DeploymentFailure, DeploymentStop, DeploymentRollback, DeploymentReady (Applies only to replacement instances in a blue/green deployment), InstanceStart, InstanceSuccess, InstanceFailure, InstanceReady. Note that not all are applicable for Lambda deployments."
  type        = map(any)
  default     = {}
}

########################
# CodeDeploy Deployment
########################

variable "aws_cli_command" {
  description = "Command to run as AWS CLI. May include extra arguments like region and profile."
  type        = string
  default     = "aws"
}

variable "save_deploy_script" {
  description = "Save deploy script locally"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Create the AWS resources and script for CodeDeploy"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Run AWS CLI command to start the deployment"
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Force deployment every time (even when nothing changes)"
  type        = bool
  default     = false
}

variable "wait_deployment_completion" {
  description = "Wait until deployment completes. It can take a lot of time and your terraform process may lock execution for long time."
  type        = bool
  default     = false
}

######################
# CodeDeploy IAM role
######################

variable "create_codedeploy_role" {
  description = "Whether to create new AWS CodeDeploy IAM role"
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "IAM role name to create or use by CodeDeploy"
  type        = string
  default     = ""
}

variable "codedeploy_principals" {
  description = "List of CodeDeploy service principals to allow. The list can include global or regional endpoints."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach Invoke policy to CodeDeploy role when before allow traffic or after allow traffic hooks are defined."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach SNS policy to CodeDeploy role when triggers are defined"
  type        = bool
  default     = false
}

variable "get_deployment_sleep_timer" {
  description = "Adds additional sleep time to get-deployment command to avoid the service throttling"
  type        = number
  default     = 5
}

// File: versions.tf
terraform {
  required_version = ">= 0.13.1"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.35"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 1.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 2.0"
    }
  }
}

// File: main.tf
data "aws_availability_zones" "availaibility-zones" {
}

data "aws_subnets" "app_subnets" {
  filter {
    name   = "tag:Name"
    values = ["app-*"]
  }
  filter {
    name   = "availabilityZone"
    values = var.availability_zone
  }
}

data "aws_subnets" "web_subnets" {
  filter {
    name   = "tag:Name"
    values = ["web-*"]
  }
  filter {
    name   = "availabilityZone"
    values = var.availability_zone
  }
}

resource "random_shuffle" "shuffle-az" {
  input        = data.aws_availability_zones.availaibility-zones.names
  result_count = var.max_subnetcount
}

resource "random_integer" "random" {
  min = 1
  max = 100
}

resource "aws_vpc" "tf-project-vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames
  tags = {
    Name = "${var.vpc_name}-${random_integer.random.id}"
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_subnet" "web-subnet" {
  count                   = var.web_subnet_count
  vpc_id                  = aws_vpc.tf-project-vpc.id
  cidr_block              = var.web_cidr_blocks[count.index]
  map_public_ip_on_launch = true
  availability_zone       = random_shuffle.shuffle-az.result[count.index]
  tags = {
    Name = "web-${count.index + 1}"
  }
}

resource "aws_route_table" "public-rt" {
  count  = var.web_subnet_count > 0 ? 1 : 0
  vpc_id = aws_vpc.tf-project-vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }
  tags = {
    Name = "publicRT"
  }
}

resource "aws_route_table_association" "public-rt-association" {
  count          = var.web_subnet_count
  subnet_id      = aws_subnet.web-subnet[count.index].id
  route_table_id = aws_route_table.public-rt[0].id
}

resource "aws_route_table" "private-rt" {
  count  = (var.app_subnet_count > 0 || var.db_subnet_count > 0 || var.reserved_subnet_count > 0) ? 1 : 0
  vpc_id = aws_vpc.tf-project-vpc.id
  tags = {
    Name = "privateRT"
  }
}

resource "aws_subnet" "app-subnet" {
  count             = var.app_subnet_count
  vpc_id            = aws_vpc.tf-project-vpc.id
  cidr_block        = var.app_cidr_blocks[count.index]
  availability_zone = random_shuffle.shuffle-az.result[count.index]
  tags = {
    Name = "app-${count.index + 1}"
  }
}

resource "aws_route_table_association" "app-rt-association" {
  count          = var.app_subnet_count
  subnet_id      = aws_subnet.app-subnet[count.index].id
  route_table_id = aws_route_table.private-rt[0].id
}


resource "aws_subnet" "db-subnet" {
  count             = var.db_subnet_count
  vpc_id            = aws_vpc.tf-project-vpc.id
  cidr_block        = var.db_cidr_blocks[count.index]
  availability_zone = random_shuffle.shuffle-az.result[count.index]
  tags = {
    Name = "db-${count.index + 1}"
  }
}

resource "aws_route_table_association" "db-rt-association" {
  count          = var.db_subnet_count
  subnet_id      = aws_subnet.db-subnet[count.index].id
  route_table_id = aws_route_table.private-rt[0].id
}

resource "aws_subnet" "reserved-subnet" {
  count             = var.reserved_subnet_count
  vpc_id            = aws_vpc.tf-project-vpc.id
  cidr_block        = var.reserved_cidr_blocks[count.index]
  availability_zone = random_shuffle.shuffle-az.result[count.index]
  tags = {
    Name = "reserved-${count.index + 1}"
  }
}

resource "aws_route_table_association" "reserved-rt-association" {
  count          = var.reserved_subnet_count
  subnet_id      = aws_subnet.reserved-subnet[count.index].id
  route_table_id = aws_route_table.private-rt[0].id
}

resource "aws_internet_gateway" "igw" {
  count  = var.web_subnet_count > 0 ? 1 : 0
  vpc_id = aws_vpc.tf-project-vpc.id
  tags = {
    Name = "IGW"
  }
}

resource "aws_vpc_endpoint" "interface_endpoints" {
  for_each = { for endpointtype, endpointconfig in var.vpc_endpoints : endpointtype => endpointconfig
    if endpointconfig.service_name != "" && endpointconfig.vpc_endpoint_type != ""
  }
  vpc_id              = aws_vpc.tf-project-vpc.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = each.value.vpc_endpoint_type
  subnet_ids          = var.subnet_ids
  security_group_ids  = var.security_group_ids
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "gateway_endpoint" {
  count             = length(var.service_name) > 0 && length(var.vpc_endpoint_type) > 0 ? 1 : 0
  vpc_id            = aws_vpc.tf-project-vpc.id
  service_name      = var.service_name
  vpc_endpoint_type = var.vpc_endpoint_type
}

resource "aws_vpc_endpoint_route_table_association" "gateway_endpoint_rt_association" {
  count           = length(var.service_name) > 0 ? 1 : 0
  route_table_id  = aws_route_table.private-rt[0].id
  vpc_endpoint_id = aws_vpc_endpoint.gateway_endpoint[0].id
}

// File: outputs.tf
output "vpc_id" {
  value = aws_vpc.tf-project-vpc.id
}

output "app-subnet" {
  value = aws_subnet.app-subnet
}

output "app-subnet-availability_zone_names" {
  value = random_shuffle.shuffle-az.result
}

output "web_subnet_ids" {
  value = data.aws_subnets.web_subnets.ids
}

output "db_subnet_ids" {
  value = aws_subnet.db-subnet.*.id
}

output "gateway_endpoint_rt_association_id" {
  value = try(aws_vpc_endpoint_route_table_association.gateway_endpoint_rt_association[0].id, "")
}

// File: variables.tf
variable "vpc_cidr" {
  description = "CIDR for the VPC."
  default = "10.16.0.0/16"
}
variable "enable_dns_support" {
  description = "Flag to enable or disable DNS support in the VPC."
  default = true
}
variable "enable_dns_hostnames" {
  description = "Flag to enable or disable DNS hostnames in the VPC."
  default = true
}
variable "web_subnet_count" {
  description = "Number of web (public) subnets required."
  default = 0
}
variable "app_subnet_count" {
  description = "Number of app (private) subnets required."
  default = 0
}
variable "db_subnet_count" {
  description = "Number of DB (private) subnets required."
  default = 0
}
variable "reserved_subnet_count" {
  description = "Number of reserved (for future use) subnets required."
  default = 0
}
variable "web_cidr_blocks" {
  description = "CIDR blocks for the web subnets. Example [for i in range(0, 4, 1) : cidrsubnet(\"10.16.0.0/16\", 4, i)]"
  default = []
}
variable "app_cidr_blocks" {
  description = "CIDR blocks for the app subnets. Example [for i in range(4, 8, 1) : cidrsubnet(\"10.16.0.0/16\", 4, i)]"
  default = []
}
variable "db_cidr_blocks" {
  description = "CIDR blocks for the DB subnets. Example [for i in range(8, 12, 1) : cidrsubnet(\"10.16.0.0/16\", 4, i)]"
  default = []
}
variable "reserved_cidr_blocks" {
  description = "CIDR blocks for the reserved subnets. Example [for i in range(12, 16, 1) : cidrsubnet(\"10.16.0.0/16\", 4, i)]"
  default = []
}
variable "max_subnetcount" {
  description = "Maximum number of subnets in the VPC."
  default = 20
}
variable "vpc_endpoints" {
  description = "Map for building Interface endpoints."
  default = {}
}
variable "security_group_ids" {
  description = "Security group IDs for the Interface endpoints."
  default = []
}
variable "availability_zone" {
  description = "AZs where the Subnets are created."
  default = []
}
variable "service_name" {
  description = "Service name for the Gateway endpoint. Example com.amazonaws.us-east-1.s3"
  default = ""
}
variable "vpc_endpoint_type" {
  description = "Endpoint type for the Gateway endpoint."
  default = "Gateway"
}
variable "subnet_ids" {
  description = "Subnets IDS where the Interface endpoints should be provisioned."
  default = []
}
variable "vpc_name" {
  description = "Name prefix for the VPC."
  default = "tf-project"
}

resource "aws_route53_zone" "private" {
    name = var.internal_domain

    vpc {
        vpc_id = aws_vpc.main.id
    }
}

resource "aws_vpc_dhcp_options" "domains" {
    domain_name = var.internal_domain
    domain_name_servers = var.dns_resolvers
}

resource "aws_vpc_dhcp_options_association" "domains" {
    vpc_id = aws_vpc.main.id
    dhcp_options_id = aws_vpc_dhcp_options.domains.id
}

resource "aws_network_acl" "sandbox" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.sandbox.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
    ingress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "web" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.web.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 22
        to_port = 22
    }
    ingress {
        protocol = "tcp"
        rule_no = 102
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 80
        to_port = 80
    }
    ingress {
        protocol = "tcp"
        rule_no = 103
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 443
        to_port = 443
    }
    ingress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "database" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.database.id]

    ingress {
        protocol = "tcp"
        rule_no = 100
        action = "allow"
        cidr_block = var.web_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = var.web_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    ingress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = var.gameserver_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = var.gameserver_subnet_cidr
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "gameserver" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.gameserver.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 22
        to_port = 22
    }
    ingress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27015
        to_port = 27015
    }
    ingress {
        protocol = "tcp"
        rule_no = 201
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27020
        to_port = 27020
    }
    ingress {
        protocol = "udp"
        rule_no = 202
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27015
        to_port = 27015
    }
    ingress {
        protocol = "udp"
        rule_no = 203
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27020
        to_port = 27020
    }
    ingress {
        protocol = "tcp"
        rule_no = 998
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    ingress {
        protocol = "udp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }

    egress {
        protocol = "tcp"
        rule_no = 998
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "udp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

output "vpc_id" {
    value = aws_vpc.main.id
}

output "reserved_subnet_id" {
    value = aws_subnet.reserved.id
}

output "sandbox_subnet_id" {
    value = aws_subnet.sandbox.id
}

output "web_subnet_id" {
    value = aws_subnet.web.id
}

output "database_subnet_id" {
    value = aws_subnet.database.id
}

output "gameserver_subnet_id" {
    value = aws_subnet.gameserver.id
}

output "ssh_securitygroup_id" {
    value = aws_security_group.home_ssh.id
}

output "internal_dns_zone_id" {
    value = aws_route53_zone.private.id
}

resource "aws_security_group" "home_ssh" {
    name = "Home SSH"
    description = "SSH from home"
    vpc_id = aws_vpc.main.id

    ingress {
        from_port = 22
        to_port = 22
        protocol = "tcp"
        cidr_blocks =  var.ssh_ip_addrs
        self = true
    }

    egress {
        from_port   = 0
        to_port     = 0
        protocol    = "-1"
        cidr_blocks = [aws_vpc.main.cidr_block]
    }

    tags = {
        Name = "Home SSH"
    }
}

resource "aws_security_group" "packer_ssh" {
    name = "Packer SSH"
    description = "SSH for Packer"
    vpc_id = aws_vpc.main.id

    ingress {
        from_port = 22
        to_port = 22
        protocol = "tcp"
        cidr_blocks = [aws_vpc.main.cidr_block]
        self = true
    }

    egress {
        from_port   = 0
        to_port     = 0
        protocol    = "-1"
        cidr_blocks = [aws_vpc.main.cidr_block]
    }

    tags = {
        Name = "Packer SSH"
    }
}

# Reserved for use by NAT's and other appliances
resource "aws_subnet" "reserved" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.reserved_subnet_cidr
    map_public_ip_on_launch  = false

    tags = {
        Name = "reserved"
    }
}
resource "aws_route_table" "reserved" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "reserved" {
    subnet_id = aws_subnet.reserved.id
    route_table_id = aws_route_table.reserved.id
}

# Used for builds or otherwise unimportant things
# Not able to access other subnets
resource "aws_subnet" "sandbox" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.sandbox_subnet_cidr
    map_public_ip_on_launch = false

    tags = {
        Name = "sandbox"
    }
}
resource "aws_route_table" "sandbox" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "sandbox" {
    subnet_id = aws_subnet.sandbox.id
    route_table_id = aws_route_table.sandbox.id
}

# Used for web applications
# Bot software
# Frontends
resource "aws_subnet" "web" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.web_subnet_cidr
    map_public_ip_on_launch = false

    tags = {
        Name = "web"
    }
}
resource "aws_route_table" "web" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "web" {
    subnet_id = aws_subnet.web.id
    route_table_id = aws_route_table.web.id
}

# Used to back web and gameserver resources
# Not accessiable from the internet
resource "aws_subnet" "database" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.database_subnet_cidr
    map_public_ip_on_launch = false

    tags = {
        Name = "database"
    }
}
resource "aws_route_table" "database" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "database" {
    subnet_id = aws_subnet.database.id
    route_table_id = aws_route_table.database.id
}

# Used to house all the gameservers
resource "aws_subnet" "gameserver" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.gameserver_subnet_cidr
    map_public_ip_on_launch = false

    tags = {
        Name = "gameserver"
    }
}
resource "aws_route_table" "gameserver" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "gameserver" {
    subnet_id = aws_subnet.gameserver.id
    route_table_id = aws_route_table.gameserver.id
}

variable "vpc_cidr" {
    type = string
    default = "10.0.0.0/16"
}

variable "internal_domain" {
    type = string
    default = "internal"
}

variable "dns_resolvers" {
    type = list
    default = ["10.0.0.2", "8.8.8.8"]
}

variable "ssh_ip_addrs" {
    type = list
    default = ["203.0.113.0/24"] # placeholder (RFC 5737 documentation range) -- override with your real source IP/CIDR
}

variable "reserved_subnet_cidr" {
    type = string
    default = "10.0.0.0/24"
}

variable "sandbox_subnet_cidr" {
    type = string
    default = "10.0.1.0/24"
}

variable "web_subnet_cidr" {
    type = string
    default = "10.0.2.0/24"
}

variable "database_subnet_cidr" {
    type = string
    default = "10.0.3.0/24"
}

variable "gameserver_subnet_cidr" {
    type = string
    default = "10.0.4.0/22"
}

resource "aws_vpc" "main" {
    cidr_block = var.vpc_cidr

    enable_dns_support = true
    enable_dns_hostnames = true

    tags = {
        Name = "main"
    }
}

resource "aws_internet_gateway" "main" {
    vpc_id = aws_vpc.main.id

    tags = {
        Name = "ig"
    }
}

