# environment variables
variable "env" {
  default = ""
}

# vpc variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_route_table_cidr" {
  description = "CIDR block for the public route table"
  type        = string
  default     = "0.0.0.0/0"
}

variable "private_route_table_az1_cidr" {
  description = "CIDR block for the private route table in Availability Zone 1"
  type        = string
  default     = "0.0.0.0/0"
}

variable "private_route_table_az2_cidr" {
  description = "CIDR block for the private route table in Availability Zone 2"
  type        = string
  default     = "0.0.0.0/0"
}

variable "private_route_table_az3_cidr" {
  description = "CIDR block for the private route table in Availability Zone 3"
  type        = string
  default     = "0.0.0.0/0"
}

variable "database_route_table_cidr" {
  description = "CIDR block for the database route table"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_az1_cidr" {
  description = "CIDR block for the public subnet in Availability Zone 1"
  type        = string
  default     = "10.0.1.0/24"
}
variable "public_subnet_az2_cidr" {
  description = "CIDR block for the public subnet in Availability Zone 2"
  type        = string
  default     = "10.0.2.0/24"
}
variable "public_subnet_az3_cidr" {
  description = "CIDR block for the public subnet in Availability Zone 3"
  type        = string
  default     = "10.0.3.0/24"
}
variable "private_app_subnet_az1_cidr" {
  description = "CIDR block for the private application subnet in Availability Zone 1"
  type        = string
  default     = "10.0.10.0/24"
}
variable "private_app_subnet_az2_cidr" {
  description = "CIDR block for the private application subnet in Availability Zone 2"
  type        = string
  default     = "10.0.20.0/24"
}
variable "private_app_subnet_az3_cidr" {
  description = "CIDR block for the private application subnet in Availability Zone 3"
  type        = string
  default     = "10.0.30.0/24"
}
variable "private_database_subnet_az1_cidr" {
  description = "CIDR block for the private database subnet in Availability Zone 1"
  type        = string
  default     = "10.0.100.0/24"
}
variable "private_database_subnet_az2_cidr" {
  description = "CIDR block for the private database subnet in Availability Zone 2"
  type        = string
  default     = "10.0.110.0/24"
}
variable "private_database_subnet_az3_cidr" {
  description = "CIDR block for the private database subnet in Availability Zone 3"
  type        = string
  default     = "10.0.120.0/24"
}

# use data source to get all avalablility zones in region
data "aws_availability_zones" "available_zones" {}

# create vpc
resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_hostnames = true

  tags = {
    Name = "${var.env}-vpc"
  }
}

# create internet gateway and attach it to vpc
resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "${var.env}-igw"
  }

  depends_on = [aws_vpc.vpc]

}

# allocate elastic ip address az1
resource "aws_eip" "eip-for-nat-gateway-az1" {
  domain   = "vpc"

  tags   = {
    Name = "${var.env}-eip-az1-ngw-az1"
  }
}

# allocate elastic ip address az2
resource "aws_eip" "eip-for-nat-gateway-az2" {
  domain   = "vpc"

  tags   = {
    Name = "${var.env}-eip-az2-ngw-az2"
  }
}

# allocate elastic ip address az3
resource "aws_eip" "eip-for-nat-gateway-az3" {
  domain   = "vpc"

  tags   = {
    Name = "${var.env}-eip-az3-ngw-az3"
  }
}

# create nat gateway az1 in public subnet az1
resource "aws_nat_gateway" "nat-gateway-az1" {
  allocation_id = aws_eip.eip-for-nat-gateway-az1.id
  subnet_id     = aws_subnet.public_subnet_az1.id

  tags   = {
    Name = "${var.env}-ngw-az1-pub-sbnt-az1"
  }

  depends_on = [aws_route_table.public_route_table]

}

# create nat gateway az2 in public subnet az2
resource "aws_nat_gateway" "nat-gateway-az2" {
  allocation_id = aws_eip.eip-for-nat-gateway-az2.id
  subnet_id     = aws_subnet.public_subnet_az2.id

  tags   = {
    Name = "${var.env}-ngw-az2-pub-sbnt-az2"
  }

  depends_on = [aws_nat_gateway.nat-gateway-az1]

}

# create nat gateway az3 in public subnet az3
resource "aws_nat_gateway" "nat-gateway-az3" {
  allocation_id = aws_eip.eip-for-nat-gateway-az3.id
  subnet_id     = aws_subnet.public_subnet_az3.id

  tags   = {
    Name = "${var.env}-ngw-az3-pub-sbnt-az3"
  }

  depends_on = [aws_nat_gateway.nat-gateway-az2]

}

# create route table and add public route
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.vpc.id

  route {
