// File: main.tf
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  bucket_prefix         = var.use_account_alias_prefix ? format("%s-", data.aws_iam_account_alias.current[0].account_alias) : ""
  bucket_id             = "${local.bucket_prefix}${var.bucket}"
  enable_bucket_logging = var.logging_bucket != ""

  # Detect aspects of default lifecycle rules
  aiu_has_expiration = var.lifecycle_abort_incomplete_upload.expiration != null ? true : false
  aiu_has_transition = var.lifecycle_abort_incomplete_upload.transition != null ? true : false
  aiu_has_nvt        = var.lifecycle_abort_incomplete_upload.nvt != null ? true : false
  aiu_has_nve        = var.lifecycle_abort_incomplete_upload.nve != null ? true : false

}

data "aws_iam_policy_document" "supplemental_policy" {
  source_policy_documents = [var.custom_bucket_policy]

  # Enforce SSL/TLS on all transmitted objects
  # We do this by extending the custom_bucket_policy
  statement {
    sid = "enforce-tls-requests-only"

    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_id}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid = "inventory-and-analytics"

    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_id}/*"
    ]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:s3:::${local.bucket_id}"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket" "private_bucket" {
  bucket        = var.use_random_suffix ? null : local.bucket_id
  bucket_prefix = var.use_random_suffix ? local.bucket_id : null
  tags          = var.tags
  force_destroy = var.enable_bucket_force_destroy

  lifecycle {
    # These lifecycle ignore_changes rules exist to permit a smooth upgrade
    # path from version 3.x of the AWS provider to version 4.x
    ignore_changes = [
      # While no special usage instructions are documented for needing this
      # ignore_changes rule, this should avoid drift detection if conflicts
      # with the aws_s3_bucket_versioning exist.
      versioning,

      # https://registry.terraform.io/providers/hashicorp%20%20/aws/3.75.2/docs/resources/s3_bucket_acl#usage-notes
      grant,

      # https://registry.terraform.io/providers/hashicorp%20%20/aws/3.75.2/docs/resources/s3_bucket_cors_configuration#usage-notes
      cors_rule,

      # https://registry.terraform.io/providers/hashicorp%20%20/aws/3.75.2/docs/resources/s3_bucket_lifecycle_configuration#usage-notes
      lifecycle_rule,

      # https://registry.terraform.io/providers/hashicorp%20%20/aws/3.75.2/docs/resources/s3_bucket_logging#usage-notes
      logging,

      # https://registry.terraform.io/providers/hashicorp%20%20/aws/3.75.2/docs/resources/s3_bucket_server_side_encryption_configuration#usage-notes
      server_side_encryption_configuration,
    ]
  }
}

resource "aws_s3_bucket_policy" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id
  policy = data.aws_iam_policy_document.supplemental_policy.json
}

resource "aws_s3_bucket_accelerate_configuration" "private_bucket" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id
  status = var.transfer_acceleration ? "Enabled" : "Suspended"
}

resource "aws_s3_bucket_acl" "private_bucket" {
  count      = var.s3_bucket_acl != null ? 1 : 0
  bucket     = aws_s3_bucket.private_bucket.id
  acl        = var.s3_bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.private_bucket]
}

resource "aws_s3_bucket_ownership_controls" "private_bucket" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [
    aws_s3_bucket_policy.private_bucket,
    aws_s3_bucket_public_access_block.public_access_block,
    aws_s3_bucket.private_bucket
  ]
}

resource "aws_s3_bucket_versioning" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "private_bucket" {
  bucket                                 = aws_s3_bucket.private_bucket.id
  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  rule {
    id = "abort-incomplete-multipart-upload"

    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = var.abort_incomplete_multipart_upload_days
    }

    dynamic "expiration" {
      for_each = local.aiu_has_expiration == true ? [var.lifecycle_abort_incomplete_upload.expiration] : []
      content {
        date                         = expiration.value.date
        days                         = expiration.value.days
        expired_object_delete_marker = expiration.value.expired_object_delete_marker
      }
    }

    dynamic "transition" {
      for_each = local.aiu_has_transition == true ? [var.lifecycle_abort_incomplete_upload.transition] : []
      content {
        days          = transition.value.days
        storage_class = transition.value.storage_class
      }
    }

    dynamic "noncurrent_version_transition" {
      for_each = local.aiu_has_nvt == true ? [var.lifecycle_abort_incomplete_upload.nvt] : []
      content {
        newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
        noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
        storage_class             = noncurrent_version_transition.value.storage_class
      }
    }

    dynamic "noncurrent_version_expiration" {
      for_each = local.aiu_has_nve == true ? [var.lifecycle_abort_incomplete_upload.nve] : []
      content {
        newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
        noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
      }
    }
  }

  rule {
    id = "aws-bucket-inventory"

    status = var.enable_bucket_inventory ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = var.lifecycle_aws_bucket_inventory_expiration
    }
  }

  rule {
    id = "aws-bucket-analytics"

    status = var.enable_analytics ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = var.lifecycle_aws_bucket_analytics_expiration
    }
  }

  dynamic "rule" {
    for_each = var.additional_lifecycle_rules
    content {
      id     = rule.value["id"]
      status = rule.value["status"]
      dynamic "filter" {
        for_each = rule.value.filter
        content {
          prefix = filter.value["prefix"]
        }
      }
      dynamic "expiration" {
        for_each = rule.value.expiration
        content {
          days = expiration.value["days"]
        }
      }
    }
  }
}

resource "aws_s3_bucket_logging" "private_bucket" {
  count = local.enable_bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${local.bucket_id}/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = length(var.kms_master_key_id) > 0 ? "aws:kms" : "AES256"
      kms_master_key_id = length(var.kms_master_key_id) > 0 ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_cors_configuration" "private_bucket" {
  count = length(var.cors_rules)

  bucket = aws_s3_bucket.private_bucket.id

  cors_rule {
    allowed_methods = var.cors_rules[count.index].allowed_methods
    allowed_origins = var.cors_rules[count.index].allowed_origins
    allowed_headers = lookup(var.cors_rules[count.index], "allowed_headers", null)
    expose_headers  = lookup(var.cors_rules[count.index], "expose_headers", null)
    max_age_seconds = lookup(var.cors_rules[count.index], "max_age_seconds", null)
  }
}

resource "aws_s3_bucket_analytics_configuration" "private_analytics_config" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id
  name   = "Analytics"

  storage_class_analysis {
    data_export {
      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.private_bucket.arn
          prefix     = "_AWSBucketAnalytics"
        }
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "public_access_block" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id

  # Block new public ACLs and uploading public objects
  block_public_acls = true

  # Retroactively remove public access granted through public ACLs
  ignore_public_acls = true

  # Block new public bucket policies
  block_public_policy = true

  # Retroactivley block public and cross-account access if bucket has public policies
  restrict_public_buckets = true
}

resource "aws_s3_bucket_inventory" "inventory" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.private_bucket.id
  name   = "BucketInventory"

  included_object_versions = "All"

  schedule {
    frequency = var.schedule_frequency
  }

  destination {
    bucket {
      format     = var.inventory_bucket_format
      bucket_arn = aws_s3_bucket.private_bucket.arn
      prefix     = "_AWSBucketInventory/"
    }
  }

  optional_fields = ["Size", "LastModifiedDate", "StorageClass", "ETag", "IsMultipartUploaded", "ReplicationStatus", "EncryptionStatus",
  "ObjectLockRetainUntilDate", "ObjectLockMode", "ObjectLockLegalHoldStatus", "IntelligentTieringAccessTier"]
}

// File: outputs.tf
output "id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.private_bucket.id
}

output "arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = aws_s3_bucket.private_bucket.arn
}

output "name" {
  description = "The Name of the bucket. Will be of format bucketprefix-bucketname."
  value       = "${local.bucket_prefix}${var.bucket}"
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.private_bucket.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.private_bucket.bucket_regional_domain_name
}

output "bucket_logging_prefix" {
  description = "Prefix defined for logging to an S3 bucket."
  value       = aws_s3_bucket_logging.private_bucket[*].target_prefix
}

// File: variables.tf
variable "abort_incomplete_multipart_upload_days" {
  description = "Number of days until aborting incomplete multipart uploads"
  type        = number
  default     = 14
}

variable "additional_lifecycle_rules" {
  description = "List of additional lifecycle rules to specify"
  type        = list(any)
  default     = []
}

variable "bucket" {
  description = "The name of the bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "bucket_key_enabled" {
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = true
}

variable "cors_rules" {
  description = "List of maps containing rules for Cross-Origin Resource Sharing."
  type        = list(any)
  default     = []
}

variable "custom_bucket_policy" {
  description = "JSON formatted bucket policy to attach to the bucket."
  type        = string
  default     = ""
}

variable "enable_analytics" {
  description = "Enables storage class analytics on the bucket."
  default     = true
  type        = bool
}

variable "enable_bucket_force_destroy" {
  type        = bool
  default     = false
  description = "If set to true, Bucket will be emptied and destroyed when terraform destroy is run."
}

variable "enable_bucket_inventory" {
  type        = bool
  default     = false
  description = "If set to true, Bucket Inventory will be enabled."
}

variable "enable_s3_public_access_block" {
  description = "Bool for toggling whether the s3 public access block resource should be enabled."
  type        = bool
  default     = true
}

variable "inventory_bucket_format" {
  type        = string
  default     = "ORC"
  description = "The format for the inventory file. Default is ORC. Options are ORC or CSV."
}

variable "kms_master_key_id" {
  description = "The AWS KMS master key ID used for the SSE-KMS encryption. If blank, bucket encryption configuration defaults to AES256."
  type        = string
  default     = ""
}

variable "lifecycle_abort_incomplete_upload" {
  description = "Default values for the abort incomplete mutlipart uploads lifecycle rule"
  default = {
    expiration = {
      expired_object_delete_marker = true
      days                         = null
      date                         = null
    }
    # No transition block necessary by default
    transition = null

    # noncurrent_version_transition (nvt) block attributes
    nvt = {
      newer_noncurrent_versions = null
      noncurrent_days           = 30
      storage_class             = "STANDARD_IA"
    }

    # noncurrent_version_expiration (nve) block attributes
    # Number of days until non-current version of object expires
    nve = {
      newer_noncurrent_versions = null,
      noncurrent_days           = 365
    }
  }
}

variable "lifecycle_aws_bucket_analytics_expiration" {
  description = "Number of days to keep aws bucket analytics objects"
  type        = number
  default     = 30
}

variable "lifecycle_aws_bucket_inventory_expiration" {
  description = "Number of days unused items expire from AWS Inventory"
  type        = number
  default     = 14
}

variable "logging_bucket" {
  description = "The S3 bucket to send S3 access logs."
  type        = string
  default     = ""
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "s3_bucket_acl" {
  description = "Set bucket ACL per [AWS S3 Canned ACL](<https://docs.aws.amazon.com/AmazonS3/latest/dev/acl-overview.html#canned-acl>) list."
  default     = null
  type        = string
}

variable "schedule_frequency" {
  type        = string
  default     = "Weekly"
  description = "The S3 bucket inventory frequency. Defaults to Weekly. Options are 'Weekly' or 'Daily'."
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket."
  default     = {}
  type        = map(string)
}

variable "transfer_acceleration" {
  description = "Whether or not to enable bucket acceleration."
  type        = bool
  default     = null
}

variable "transition_default_minimum_object_size" {
  description = "Minimum object size to transition for lifecycle rule"
  type        = string
  default     = "all_storage_classes_128K"
}

variable "use_account_alias_prefix" {
  description = "Whether to prefix the bucket name with the AWS account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to add a random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "A string that indicates the versioning status for the log bucket."
  default     = "Enabled"
  type        = string
  validation {
    condition     = contains(["Enabled", "Disabled", "Suspended"], var.versioning_status)
    error_message = "Valid values for versioning_status are Enabled, Disabled, or Suspended."
  }
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = ">= 5.89.0"
  }
}

// File: main.tf
/**
 * # aws-terraform-s3
 *
 * This module builds a s3 bucket with varying options.
 * It will not do s3 origin, which is in another module.
 *
 * ## Basic Usage
 *
 * ```HCL
 * module "s3_basic" {
 *   source = "git@github.com:rackspace-infrastructure-automation/aws-terraform-s3//?ref=v0.12.12"
 *
 *   bucket_logging    = false
 *   environment       = "Development"
 *   name              = "${random_string.s3_rstring.result}-example-s3-bucket"
 *   versioning        = true
 *   lifecycle_enabled = true
 *   lifecycle_rule = [
 *     {
 *       id                                     = "Default MPU Cleanup Rule."
 *       enabled                                = true
 *       abort_incomplete_multipart_upload_days = 7
 *     }
 *   ]
 *
 *   tags = {
 *     RightSaid = "Fred"
 *     LeftSaid  = "George"
 *   }
 * }
 * ```
 *
 * Full working references are available at [examples](examples)
 *
 * ## Terraform 0.12 upgrade
 *
 * Several changes were required while adding terraform 0.12 compatibility.  The following changes should be
 * made when upgrading from a previous release to version 0.12.0 or higher.
 *
 * ### Module variables
 *
 * The following module variables were updated to better meet current Rackspace style guides:
 *
 * - `bucket_name` -> `name`
 * - `kms_master_key_id` -> `kms_key_id`
 * - `bucket_tags` -> `tags`
 *
 */

data "aws_canonical_user_id" "this" {}

terraform {
  required_version = ">= 0.13"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {

  ##############################################################
  # Bucket local variables
  ##############################################################

  acl_list = ["authenticated-read", "aws-exec-read", "log-delivery-write", "private", "public-read", "public-read-write"]

  default_tags = {
    ServiceProvider = "Rackspace"
    Environment     = var.environment
  }

  grants               = try(jsondecode(var.grant), var.grant)
  cors_rules           = try(jsondecode(var.cors_rule), var.cors_rule)
  lifecycle_rules      = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)
  intelligent_tiering  = try(jsondecode(var.intelligent_tiering), var.intelligent_tiering)
  metric_configuration = try(jsondecode(var.metric_configuration), var.metric_configuration)

}

resource "aws_s3_bucket" "s3_bucket" {

  bucket = var.name

  force_destroy       = var.force_destroy_bucket
  object_lock_enabled = var.object_lock_enabled
  tags                = merge(var.tags, local.default_tags)
}

##############################################################
# Public Access Block Settings
##############################################################

resource "aws_s3_bucket_public_access_block" "block_public_access_settings" {
  count = var.block_public_access ? 1 : 0

  bucket = aws_s3_bucket.s3_bucket.id

  block_public_acls       = var.block_public_access_acl
  block_public_policy     = var.block_public_access_policy
  ignore_public_acls      = var.block_public_access_ignore_acl
  restrict_public_buckets = var.block_public_access_restrict_bucket
}

##############################################################
# S3 Access Control List
##############################################################
resource "aws_s3_bucket_acl" "s3_acl" {
  count = (var.acl != null && var.acl != "null") || length(local.grants) > 0 ? 1 : 0

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner

  # hack when `null` value can't be used (eg, from terragrunt, https://github.com/gruntwork-io/terragrunt/pull/1367)
  acl = var.acl == "null" ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(local.grants) > 0 ? [true] : []

    content {
      dynamic "grant" {
        for_each = local.grants

        content {
          permission = grant.value.permission

          grantee {
            type          = grant.value.type
            id            = try(grant.value.id, null)
            uri           = try(grant.value.uri, null)
            email_address = try(grant.value.email, null)
          }
        }
      }

      owner {
        id           = try(var.owner["id"], data.aws_canonical_user_id.this.id)
        display_name = try(var.owner["display_name"], null)
      }
    }
  }

  # This `depends_on` is to prevent "AccessControlListNotSupported: The bucket does not allow ACLs."
  depends_on = [aws_s3_bucket_ownership_controls.this]
}


##############################################################
# S3 Versioning Configuration
##############################################################
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.s3_bucket.id
  versioning_configuration {
    # Valid values: "Enabled" or "Suspended"
    status = var.versioning ? "Enabled" : "Suspended"
    # Valid values: "Enabled" or "Disabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

##############################################################
# S3 Logging Configuration
##############################################################
resource "aws_s3_bucket_logging" "s3_logging" {
  count = var.bucket_logging ? 1 : 0

  bucket        = aws_s3_bucket.s3_bucket.id
  target_bucket = var.logging_bucket_name
  target_prefix = var.logging_bucket_prefix
}

##############################################################
# S3 Server Side Encryption (SSE) Configuration
##############################################################
resource "aws_s3_bucket_server_side_encryption_configuration" "s3_sse" {
  count = var.sse_algorithm == "none" ? 0 : 1

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = try(var.sse_algorithm, "AES256")
      kms_master_key_id = try(var.kms_key_id, null)
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

##############################################################
# S3 CORS Configuration
##############################################################
resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.cors ? 1 : 0

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "cors_rule" {
    for_each = local.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

##############################################################
# S3 Object Lock Configuration
##############################################################
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner
  token                 = try(var.object_lock_token, null)

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = try(var.object_lock_retention_days, null)
      years = try(var.object_lock_retention_years, null)
    }
  }
}

##############################################################
# S3 Website Configuration
##############################################################
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website ? 1 : 0

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "index_document" {
    for_each = try([var.website_config["index_document"]], [])

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website_config["error_document"]], [])

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try([var.website_config["redirect_all_requests_to"]], [])

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(flatten([var.website_config["routing_rules"]]), [])

    content {
      dynamic "condition" {
        for_each = [try([routing_rule.value.condition], [])]

        content {
          http_error_code_returned_equals = try(routing_rule.value.condition["http_error_code_returned_equals"], null)
          key_prefix_equals               = try(routing_rule.value.condition["key_prefix_equals"], null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect["host_name"], null)
        http_redirect_code      = try(routing_rule.value.redirect["http_redirect_code"], null)
        protocol                = try(routing_rule.value.redirect["protocol"], null)
        replace_key_prefix_with = try(routing_rule.value.redirect["replace_key_prefix_with"], null)
        replace_key_with        = try(routing_rule.value.redirect["replace_key_with"], null)
      }
    }
  }
}

##############################################################
# S3 Lifecycle Configuration
##############################################################
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.lifecycle_enabled ? 1 : 0

  bucket                = aws_s3_bucket.s3_bucket.id
  expected_bucket_owner = var.expected_bucket_owner

  dynamic "rule" {
    for_each = local.lifecycle_rules

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.enabled ? "Enabled" : "Disabled", tobool(rule.value.status) ? "Enabled" : "Disabled", title(lower(rule.value.status)))

      # Only one rule allowed - abort_incomplete_multipart_upload
      dynamic "abort_incomplete_multipart_upload" {
        for_each = try([rule.value.abort_incomplete_multipart_upload_days], [])

        content {
          days_after_initiation = try(rule.value.abort_incomplete_multipart_upload_days, null)
        }
      }


      # Only one rule allowed - expiration
      dynamic "expiration" {
        for_each = try(flatten([rule.value.expiration]), [])

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      # Multiple rules allowed - transition
      dynamic "transition" {
        for_each = try(flatten([rule.value.transition]), [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      # Only one rule allowed - noncurrent_version_expiration
      dynamic "noncurrent_version_expiration" {
        for_each = try(flatten([rule.value.noncurrent_version_expiration]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.days, noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      # Multiple rules allowed - noncurrent_version_transition
      dynamic "noncurrent_version_transition" {
        for_each = try(flatten([rule.value.noncurrent_version_transition]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.days, noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      # Only one rule allowed - filter - without any key arguments or tags
      dynamic "filter" {
        for_each = length(try(flatten([rule.value.filter]), [])) == 0 ? [true] : []

        content {

        }
      }

      # Only one rule allowed - filter - with one key argument or a single tag
      dynamic "filter" {
        for_each = [for v in try(flatten([rule.value.filter]), []) : v if max(length(keys(v)), length(try(rule.value.filter.tags, rule.value.filter.tag, []))) == 1]

        content {
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)
          prefix                   = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, filter.value.tag, [])

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      # Only one rule allowed - filter - with more than one key arguments or multiple tags
      dynamic "filter" {
        for_each = [for v in try(flatten([rule.value.filter]), []) : v if max(length(keys(v)), length(try(rule.value.filter.tags, rule.value.filter.tag, []))) > 1]

        content {
          and {
            object_size_greater_than = try(filter.value.object_size_greater_than, null)
            object_size_less_than    = try(filter.value.object_size_less_than, null)
            prefix                   = try(filter.value.prefix, null)
            tags                     = try(filter.value.tags, filter.value.tag, null)
          }
        }
      }
    }
  }

  # Requires versioning enabled to build
  depends_on = [aws_s3_bucket_versioning.this]
}

##############################################################
# S3 Intelligent Tiering Configuration
##############################################################
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = { for k, v in local.intelligent_tiering : k => v if var.enable_intelligent_tiering }

  name   = each.key
  bucket = aws_s3_bucket.s3_bucket.id
  status = try(tobool(each.value.status) ? "Enabled" : "Disabled", title(lower(each.value.status)), null)

  # Max 1 block - filter
  dynamic "filter" {
    for_each = length(try(flatten([each.value.filter]), [])) == 0 ? [] : [true]

    content {
      prefix = try(each.value.filter.prefix, null)
      tags   = try(each.value.filter.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering

    content {
      access_tier = tiering.key
      days        = tiering.value.days
    }
  }

}

##############################################################
# S3 Metrics Configuration
##############################################################
resource "aws_s3_bucket_metric" "this" {
  for_each = { for k, v in local.metric_configuration : k => v if var.enable_bucket_metrics }

  name   = each.value.name
  bucket = aws_s3_bucket.s3_bucket.id

  dynamic "filter" {
    for_each = length(try(flatten([each.value.filter]), [])) == 0 ? [] : [true]
    content {
      prefix = try(each.value.filter.prefix, null)
      tags   = try(each.value.filter.tags, null)
    }
  }
}

##############################################################
# S3 Bucket Ownership Control
##############################################################
resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.s3_bucket.id

  rule {
    object_ownership = var.object_ownership
  }

  # This `depends_on` is to prevent "A conflicting conditional operation is currently in progress against this resource."
  depends_on = [
    aws_s3_bucket_public_access_block.block_public_access_settings,
    aws_s3_bucket.s3_bucket
  ]
}

// File: outputs.tf
output "bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = aws_s3_bucket.s3_bucket.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name. Will be of format bucketname.s3.amazonaws.com."
  value       = aws_s3_bucket.s3_bucket.bucket_domain_name
}

output "bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = aws_s3_bucket.s3_bucket.hosted_zone_id
}

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.s3_bucket.id
}

output "bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = aws_s3_bucket.s3_bucket.region
}

output "bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website. If not, this will be an empty string. This is used to create Route 53 alias records."
  value       = var.website ? aws_s3_bucket.s3_bucket.website_domain : ""
}

output "bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website. If not, this will be an empty string."
  value       = var.website ? aws_s3_bucket.s3_bucket.website_endpoint : ""
}

// File: variables.tf
variable "bucket_logging" {
  description = "Enable bucket logging. Will store logs in another existing bucket. You must give the log-delivery group WRITE and READ_ACP permissions to the target bucket. i.e. true | false"
  type        = bool
  default     = false
}

variable "block_public_access" {
  description = "Block various forms of public access on a per bucket level"
  type        = bool
  default     = false
}

variable "block_public_access_acl" {
  description = "Related to block_public_access. PUT Bucket acl and PUT Object acl calls will fail if the specified ACL allows public access. PUT Object calls will fail if the request includes an object ACL."
  type        = bool
  default     = true
}

variable "block_public_access_ignore_acl" {
  description = "Related to block_public_access. Ignore public ACLs on this bucket and any objects that it contains."
  type        = bool
  default     = true
}

variable "block_public_access_policy" {
  description = "Related to block_public_access. Reject calls to PUT Bucket policy if the specified bucket policy allows public access."
  type        = bool
  default     = true
}

variable "block_public_access_restrict_bucket" {
  description = "Related to block_public_access. Only the bucket owner and AWS Services can access this buckets if it has a public policy."
  type        = bool
  default     = true
}

variable "environment" {
  description = "Application environment for which this network is being created. must be one of ['Development', 'Integration', 'PreProduction', 'Production', 'QA', 'Staging', 'Test']"
  type        = string
  default     = "Development"
}

variable "force_destroy_bucket" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error. These objects are not recoverable."
  type        = bool
  default     = false
}

variable "lifecycle_enabled" {
  description = "Enable object lifecycle management. i.e. true | false"
  type        = bool
  default     = false
}

variable "lifecycle_rule" {
  description = "List of maps containing configuration of object lifecycle management."
  type        = any
  default     = []
}

variable "intelligent_tiering" {
  description = "Map containing intelligent tiering configuration."
  type        = any
  default     = {}
}

variable "metric_configuration" {
  description = "Map containing bucket metric configuration."
  type        = any
  default     = []
}

variable "logging_bucket_name" {
  description = "Name of the existing bucket where the logs will be stored."
  type        = string
  default     = ""
}

variable "logging_bucket_prefix" {
  description = "Prefix for all log object keys. i.e. logs/"
  type        = string
  default     = ""
}

variable "name" {
  description = "The name of the S3 bucket for the access logs. The bucket name can contain only lowercase letters, numbers, periods (.), and dashes (-). Must be globally unique. If changed, forces a new resource."
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "object_expiration_days" {
  description = "Indicates after how many days we are deleting current version of objects. Set to 0 to disable or at least 365 days longer than TransitionInDaysGlacier. i.e. 0 to disable, otherwise 1-999"
  type        = number
  default     = 0
}

variable "object_lock_enabled" {
  description = "Indicates whether this bucket has an Object Lock configuration enabled. Disabled by default. You can only enable S3 Object Lock for new buckets. If you need to turn on S3 Object Lock for an existing bucket, please contact AWS Support."
  type        = bool
  default     = false
}

variable "object_lock_token" {
  description = "A token to allow Object Lock to be enabled for an existing bucket. You must contact AWS support for the bucket's 'Object Lock token'. The token is generated in the back-end when versioning is enabled on a bucket."
  type        = string
  default     = null
}

variable "object_lock_mode" {
  description = "The default Object Lock retention mode you want to apply to new objects placed in this bucket. Valid values are GOVERNANCE and COMPLIANCE. Default is GOVERNANCE (allows administrative override)."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_retention_days" {
  description = "The retention of the object lock in days. Either days or years must be specified, but not both."
  type        = number
  default     = null
}

variable "object_lock_retention_years" {
  description = "The retention of the object lock in years. Either days or years must be specified, but not both."
  type        = number
  default     = null
}

variable "sse_algorithm" {
  description = "The server-side encryption algorithm to use. Valid values are AES256, aws:kms, and none"
  type        = string
  default     = "AES256"
}

variable "kms_key_id" {
  description = "The AWS KMS master key ID used for the SSE-KMS encryption. This can only be used when you set the value of sse_algorithm as aws:kms."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to be applied to the Bucket. i.e {Environment='Development'}"
  type        = map(string)
  default     = {}
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Specifies whether MFA delete is enabled in the bucket versioning configuration"
  type        = bool
  default     = false
}

variable "website" {
  description = "Use bucket as a static website. i.e. true | false"
  type        = bool
  default     = false
}

variable "website_config" {
  description = "Map containing static web-site hosting or redirect configuration."
  type        = any # map(string)
  default     = {}
}

variable "cors" {
  description = "Enable CORS Rules. Rules must be defined in the variable cors_rules"
  type        = bool
  default     = false
}

variable "cors_rule" {
  description = "List of maps containing rules for Cross-Origin Resource Sharing."
  type        = any
  default     = []
}

variable "expected_bucket_owner" {
  description = "The account ID of the expected bucket owner"
  type        = string
  default     = null
}

variable "enable_intelligent_tiering" {
  description = "Enable intelligent tiering"
  type        = bool
  default     = false
}

variable "enable_bucket_metrics" {
  description = "Enable bucket metrics"
  type        = bool
  default     = false
}

variable "owner" {
  description = "Bucket owner's display name and ID. Conflicts with `acl`"
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "(Optional) The canned ACL to apply. Conflicts with `grant`"
  type        = string
  default     = null
}

variable "grant" {
  description = "An ACL policy grant. Conflicts with `acl`"
  type        = any
  default     = []
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter. 'BucketOwnerEnforced': ACLs are disabled, and the bucket owner automatically owns and has full control over every object in the bucket. 'BucketOwnerPreferred': Objects uploaded to the bucket change ownership to the bucket owner if the objects are uploaded with the bucket-owner-full-control canned ACL. 'ObjectWriter': The uploading account will own the object if the object is uploaded with the bucket-owner-full-control canned ACL."
  type        = string
  default     = "ObjectWriter"
}

// File: main.tf
locals {
  bucket_key_enabled        = var.kms_key_arn != null ? true : false
  cors_rule                 = var.cors_rule != null ? { create = true } : {}
  lifecycle_rules           = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)
  logging_permissions       = length(var.logging_source_bucket_arns) > 0 ? { create = true } : {}
  object_lock_configuration = var.object_lock_mode != null ? { create : true } : {}
  policy                    = var.policy != null ? var.policy : null
  replication_configuration = var.replication_configuration != null ? { create = true } : {}
}

data "aws_iam_policy_document" "ssl_policy" {
  statement {
    sid     = "AllowSSLRequestsOnly"
    actions = ["s3:*"]
    effect  = "Deny"
    resources = [
      aws_s3_bucket.default.arn,
      "${aws_s3_bucket.default.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }
}

data "aws_iam_policy_document" "logging_policy" {
  dynamic "statement" {
    for_each = local.logging_permissions

    content {
      sid     = "S3AccessLog"
      actions = ["s3:PutObject"]
      effect  = "Allow"
      resources = [
        "${aws_s3_bucket.default.arn}/*"
      ]
      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }
      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

data "aws_iam_policy_document" "combined" {
  source_policy_documents = compact([
    local.policy,
    data.aws_iam_policy_document.ssl_policy.json,
    data.aws_iam_policy_document.logging_policy.json
  ])
}

resource "aws_s3_bucket" "default" {
  bucket              = var.name
  bucket_prefix       = var.name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_mode != null ? true : false
  tags                = var.tags
}

resource "aws_s3_bucket_acl" "default" {
  count  = var.object_ownership_type == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.default.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.default]
}

resource "aws_s3_bucket_ownership_controls" "default" {
  bucket = aws_s3_bucket.default.id
  rule {
    object_ownership = var.object_ownership_type
  }
}

resource "aws_s3_bucket_cors_configuration" "default" {
  for_each = local.cors_rule
  bucket   = aws_s3_bucket.default.bucket

  cors_rule {
    allowed_headers = var.cors_rule.allowed_headers
    allowed_methods = var.cors_rule.allowed_methods
    allowed_origins = var.cors_rule.allowed_origins
    expose_headers  = var.cors_rule.expose_headers
    max_age_seconds = var.cors_rule.max_age_seconds
  }
}

resource "aws_s3_bucket_inventory" "default" {
  for_each = var.inventory_configuration

  bucket                   = aws_s3_bucket.default.id
  enabled                  = each.value.enabled
  included_object_versions = each.value.included_object_versions
  name                     = each.key
  optional_fields          = each.value.optional_fields

  destination {
    bucket {
      account_id = each.value.destination.account_id
      bucket_arn = each.value.destination.bucket_arn
      format     = each.value.destination.format
      prefix     = each.value.destination.prefix

      encryption {
        dynamic "sse_kms" {
          for_each = each.value.destination.encryption.encryption_type == "sse_kms" ? { create = true } : {}

          content {
            key_id = each.value.destination.encryption.kms_key_id
          }
        }

        dynamic "sse_s3" {
          for_each = each.value.destination.encryption.encryption_type == "sse_s3" ? { create = true } : {}

          content {
          }
        }
      }
    }
  }

  schedule {
    frequency = each.value.frequency
  }

  dynamic "filter" {
    for_each = each.value.filter_prefix != null ? { create = true } : {}

    content {
      prefix = each.value.filter_prefix
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "default" {
  count = length(local.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.default.bucket

  dynamic "rule" {
    for_each = local.lifecycle_rules

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = try([rule.value.prefix], [])

        content {
          prefix = try(filter.value, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(flatten([rule.value.abort_incomplete_multipart_upload]), [])

        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }

      dynamic "expiration" {
        for_each = try(flatten([rule.value.expiration]), [])

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(flatten([rule.value.noncurrent_version_expiration]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(flatten([rule.value.noncurrent_version_transition]), [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "transition" {
        for_each = try(flatten([rule.value.transition]), [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }
    }
  }
}

resource "aws_s3_bucket_logging" "default" {
  count         = var.logging != null ? 1 : 0
  bucket        = aws_s3_bucket.default.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix

  lifecycle {
    precondition {
      condition     = var.logging.target_bucket != aws_s3_bucket.default.id || var.object_lock_mode == null
      error_message = "You're trying to enable server access logging and object locking on the same bucket! Object lock will prevent server access logs from written to the bucket. Either log to a different bucket or remove the object lock configuration."
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "default" {
  for_each = local.object_lock_configuration
  bucket   = aws_s3_bucket.default.bucket

  rule {
    default_retention {
      mode  = var.object_lock_mode
      years = var.object_lock_years
      days  = var.object_lock_days
    }
  }

  lifecycle {
    precondition {
      condition     = var.object_lock_mode == null || length(var.logging_source_bucket_arns) == 0
      error_message = "You're trying to allow (other buckets) logging to this bucket and enable object locking on the same bucket! Object lock will prevent server access logs from written to the bucket. Either remove the logging source buckets configuration or remove the object lock configuration."
    }
  }
}

resource "aws_s3_bucket_notification" "eventbridge" {
  count = var.eventbridge_enabled ? 1 : 0

  bucket      = aws_s3_bucket.default.id
  eventbridge = var.eventbridge_enabled
}

resource "aws_s3_bucket_replication_configuration" "default" {
  for_each = local.replication_configuration

  role   = var.replication_configuration.iam_role_arn
  bucket = aws_s3_bucket.default.id

  dynamic "rule" {
    for_each = var.replication_configuration.rules

    content {
      id       = rule.value["id"]
      priority = rule.key
      status   = "Enabled"

      delete_marker_replication {
        status = "Disabled"
      }

      destination {
        bucket        = rule.value["dest_bucket"]
        storage_class = rule.value["dest_storage_class"]

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_arn != null ? { create = true } : {}

          content {
            replica_kms_key_id = rule.value.replica_kms_key_arn
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? { create = true } : {}

        content {
          replica_modifications {
            status = rule.value.source_selection_criteria.replica_modifications ? "Enabled" : "Disabled"
          }
          sse_kms_encrypted_objects {
            status = rule.value.source_selection_criteria.sse_kms_encrypted_objects ? "Enabled" : "Disabled"
          }
        }
      }

      filter {}
    }
  }

  depends_on = [aws_s3_bucket_versioning.default]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  bucket = aws_s3_bucket.default.bucket

  rule {
    bucket_key_enabled = local.bucket_key_enabled

    apply_server_side_encryption_by_default {
      kms_master_key_id = var.kms_key_arn
      sse_algorithm     = var.kms_key_arn != null ? "aws:kms" : "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "default" {
  bucket = aws_s3_bucket.default.id
  policy = data.aws_iam_policy_document.combined.json
}

resource "aws_s3_bucket_public_access_block" "default" {
  bucket                  = aws_s3_bucket.default.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

// tfsec:ignore:aws-s3-enable-versioning
resource "aws_s3_bucket_versioning" "default" {
  #checkov:skip=CKV_AWS_21: Ensure all data stored in the S3 bucket have versioning enabled - consumer of the module should decide
  bucket = aws_s3_bucket.default.id

  versioning_configuration {
    status = var.versioning ? "Enabled" : "Suspended"
  }
}

// File: outputs.tf
output "arn" {
  value       = aws_s3_bucket.default.arn
  description = "ARN of the bucket"
}

output "id" {
  value       = aws_s3_bucket.default.id
  description = "Name of the bucket"
}

output "name" {
  value       = aws_s3_bucket.default.id
  description = "Name of the bucket"
}

// File: variables.tf
variable "name" {
  type        = string
  default     = null
  description = "The Name of the bucket. If omitted, Terraform will assign a random, unique name. Conflicts with `name_prefix`."

  validation {
    condition     = var.name != null ? length(var.name) <= 63 : true
    error_message = "The name must be less than or equal to 63 characters in length"
  }
}

variable "name_prefix" {
  type        = string
  default     = null
  description = "Creates a unique bucket name beginning with the specified prefix. Conflicts with `name`."

  validation {
    condition     = var.name_prefix != null ? length(var.name_prefix) <= 37 : true
    error_message = "The name prefix must be less than or equal to 37 characters in length"
  }
}

variable "acl" {
  type        = string
  default     = "private"
  description = "The canned ACL to apply, defaults to `private`."
}

variable "block_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public ACLs for this bucket."
}

variable "block_public_policy" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
}

variable "cors_rule" {
  type = object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  })
  default     = null
  description = "The CORS rule for the S3 bucket"
}

variable "eventbridge_enabled" {
  type        = bool
  default     = false
  description = "Whether to enable Amazon EventBridge notifications."
}

variable "force_destroy" {
  type        = bool
  default     = false
  description = "A boolean that indicates all objects should be deleted when deleting the bucket."
}

variable "ignore_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
}

variable "inventory_configuration" {
  type = map(object({
    enabled                  = optional(bool, true)
    filter_prefix            = optional(string, null)
    frequency                = optional(string, "Weekly")
    included_object_versions = optional(string, "Current")
    optional_fields          = optional(list(string), null)

    destination = object({
      account_id = string
      bucket_arn = string
      format     = optional(string, "Parquet")
      prefix     = optional(string, null)

      encryption = optional(object({
        encryption_type = string
        kms_key_id      = optional(string, null)
        }), {
        encryption_type = "sse_s3"
      })
    })
  }))
  default     = {}
  description = "Bucket inventory configuration settings"
}

variable "kms_key_arn" {
  type        = string
  default     = null
  description = "The KMS key ARN used for the bucket encryption."
}

variable "lifecycle_rule" {
  type        = any
  default     = []
  description = "List of maps containing lifecycle management configuration settings."
}

variable "logging" {
  type = object({
    target_bucket = string
    target_prefix = string
  })
  default     = null
  description = "Logging configuration, logging is disabled by default."
}

variable "logging_source_bucket_arns" {
  type        = list(string)
  default     = []
  description = "Configures which source buckets are allowed to log to this bucket."
}

variable "object_lock_mode" {
  type        = string
  default     = null
  description = "The default object Lock retention mode to apply to new objects."
}

variable "object_lock_years" {
  type        = number
  default     = null
  description = "The number of years that you want to specify for the default retention period."
}

variable "object_lock_days" {
  type        = number
  default     = null
  description = "The number of days that you want to specify for the default retention period."
}

variable "object_ownership_type" {
  type        = string
  default     = "BucketOwnerEnforced"
  description = "The object ownership type for the objects in S3 Bucket, defaults to BucketOwnerEnforced."
}

variable "replication_configuration" {
  type = object({
    iam_role_arn = string
    rules = map(object({
      id                  = string
      dest_bucket         = string
      dest_storage_class  = optional(string, null)
      replica_kms_key_arn = optional(string, null)

      source_selection_criteria = optional(object({
        replica_modifications     = optional(bool, false)
        sse_kms_encrypted_objects = optional(bool, false)
      }))
    }))
  })
  default     = null
  description = "Bucket replication configuration settings, specify the rules map keys as integers as these are used to determine the priority of the rules in case of conflict."
}

variable "restrict_public_buckets" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
}

variable "policy" {
  type        = string
  default     = null
  description = "A valid bucket policy JSON document."
}

variable "versioning" {
  type        = bool
  default     = false
  description = "Versioning is a means of keeping multiple variants of an object in the same bucket."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "A mapping of tags to assign to the bucket."
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.9.0"
    }
  }

  required_version = ">= 1.2.0"
}

// File: main.tf
//password-policy
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_numbers                = true
  require_uppercase_characters   = true
  require_symbols                = true
  allow_users_to_change_password = true
}

//s3 public acess
resource "aws_s3_account_public_access_block" "secure_s3_public_acls" {
  block_public_acls       = true
  block_public_policy     = true
  restrict_public_buckets = true
  ignore_public_acls      = true
}

variable "group_name_prefix" {
  default     = "app"

  type = string
}

# groups
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name =  "${var.group_name_prefix}_admin"
}

# conditions
locals {
  condition_if_multi_factor_auth_enabled = {
    test     = "Bool"
    variable = "aws:MultiFactorAuthPresent"

    values = [
      "true",
    ]
  }

  condition_restrict_region = {
    test     = "StringEquals"
    variable = "aws:RequestedRegion"

    values = [
      "eu-west-2",
    ]
  }
}

# get the curerent account arns ids and username for later
data "aws_caller_identity" "current" {}

# developer policys

data "aws_iam_policy_document" "manage_personal_mfa" {
  # based off https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_mfa_configure-api-require.html#MFAProtectedAPI-user-mfa
  statement {
    actions = [
      "iam:ListMFADevices",
    ]

    resources = [
      "arn:aws:iam::*:mfa/*",
      "arn:aws:iam::*:user/$${aws:username}", ## $$ is used here to escape terrfarom parsing this aws var
    ]
  }

  statement {
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:aws:iam::*:mfa/*",
      "arn:aws:iam::*:user/$${aws:username}", ## $$ is used here to escape terrfarom parsing this aws var
    ]
  }

  statement {
    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:aws:iam::*:mfa/*",
      "arn:aws:iam::*:user/$${aws:username}", ## $$ is used here to escape terrfarom parsing this aws var
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }
  }
}

resource "aws_iam_policy" "manage_personal_mfa" {
  name   = "manage_personal_mfa"
  path   = "/"
  policy = data.aws_iam_policy_document.manage_personal_mfa.json
}

data "aws_iam_policy_document" "developers_manage_personal_keys" {
  statement {
    sid = "ManageSSHKeys"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:UpdateAccessKey",
    ]

    resources = [
      "arn:aws:iam::*:user/$${aws:username}", ## $$ is used here to escape terrfarom parsing this aws var
    ]
  }
}

resource "aws_iam_policy" "developers_manage_personal_keys" {
  name   = "developers_manage_personal_keys"
  path   = "/"
  policy = data.aws_iam_policy_document.developers_manage_personal_keys.json
}

data "aws_iam_policy_document" "allow_S3_mfa" {
  statement {
    sid = "allowS3Mfa"

    actions = [
      "s3:*",
    ]

    resources = [
      "*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }
  }

  statement {
    sid    = "ForceS3Region"
    effect = "Deny"

    actions = [
      "s3:CreateBucket",
    ]

    resources = [
      "*",
    ]

    condition  {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"

      values = [
        "eu-west-2",
      ]
    }
  }

  statement {
    sid    = "DenyStateBucket" ## comment this statement out if not using state bucket
    effect = "Deny"

    actions = [
      "s3:*",
    ]

    resources = [
      "arn:aws:s3:::ceb-terraform-remote-state-storage-s3/*",
      "arn:aws:s3:::ceb-terraform-remote-state-storage-s3",
    ]
  }
}

resource "aws_iam_policy" "allow_S3_mfa" {
  name   = "allow_S3_mfa"
  path   = "/"
  policy = data.aws_iam_policy_document.allow_S3_mfa.json
}

data "aws_iam_policy_document" "allow_ec2_if_mfa_enabled" {
  statement {
    sid = "AllowEC2General"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]

    resources = [
      "*",
    ]


    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }

  }

  statement {
    sid = "AllowEC2GeneralLinkedRoles"

    actions = [
      "iam:CreateServiceLinkedRole",
    ]

    resources = [
      "*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }

    condition {
        test     = "StringEquals"
        variable = "iam:AWSServiceName"

        values = [
          "autoscaling.amazonaws.com",
          "ec2scheduled.amazonaws.com",
          "elasticloadbalancing.amazonaws.com",
          "spot.amazonaws.com",
          "spotfleet.amazonaws.com",
          "transitgateway.amazonaws.com",
        ]
    }
  }
}

resource "aws_iam_policy" "allow_ec2_if_mfa_enabled" {
  name   = "allow_ec2_if_mfa_enabled"
  path   = "/"
  policy = data.aws_iam_policy_document.allow_ec2_if_mfa_enabled.json
}

# admin policys

data "aws_iam_policy_document" "allow_admin_if_mfa" {
  statement {
    sid = "RequireAdminMFA"

    actions = [
      "*",
    ]

    resources = [
      "*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }
  }
}

resource "aws_iam_policy" "allow_admin_if_mfa" {
  name   = "allow_admin_if_mfa"
  path   = "/"
  policy = data.aws_iam_policy_document.allow_admin_if_mfa.json
}

data "aws_iam_policy_document" "assume_role_to_admin" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/admin",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"

      values = [
        "true",
      ]
    }
  }
}

resource "aws_iam_policy" "assume_role_to_admin" {
  name   = "assume_role_to_admin"
  path   = "/"
  policy = data.aws_iam_policy_document.assume_role_to_admin.json
}

# admin assume role
data "aws_iam_policy_document" "admin_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin_assume_role" {
  name               = "admin"
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role_policy.json
}

resource "aws_iam_policy_attachment" "admin_assume_role_policy" {
  name       = "admin_assume_role_policy"
  roles      = [aws_iam_role.admin_assume_role.name]
  policy_arn = aws_iam_policy.allow_admin_if_mfa.arn
}

# developer group policy-attachments
resource "aws_iam_group_policy_attachment" "developers_iam_read_only_access" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# only neded for codeDeploy
# resource "aws_iam_group_policy_attachment" "IAMSelfManageServiceSpecificCredentials" { 
#   group      = "${aws_iam_group.developer.name}"
#   policy_arn = "arn:aws:iam::aws:policy/IAMSelfManageServiceSpecificCredentials"
# }

resource "aws_iam_group_policy_attachment" "developers_iam_User_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developers_iam_user_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

resource "aws_iam_group_policy_attachment" "developers_manage_personal_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developers_manage_personal_keys.arn
}

resource "aws_iam_group_policy_attachment" "developers_manage_personal_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_personal_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developers_allow_s3_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.allow_S3_mfa.arn
}

resource "aws_iam_group_policy_attachment" "developers_allow_ec2_if_mfa_enabled" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.allow_ec2_if_mfa_enabled.arn
}

# admin group policy-attachments

resource "aws_iam_group_policy_attachment" "assume_role_to_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_role_to_admin.arn
}

provider "aws" {
  region  = "us-west-2"
}

variable "cidr_block_prefix" {
  description = "cidr block for the vpc"
  default     = "10.0.0.0/16"
}

variable "subnet_prefix" {
  description = "cidr block for the subnets"
  default = [
    { cidr_block = "10.0.0.0/24", az = "us-west-2a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24", az = "us-west-2b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24", az = "us-west-2c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24", az = "us-west-2a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24", az = "us-west-2b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24", az = "us-west-2c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24", az = "us-west-2a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24", az = "us-west-2b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24", az = "us-west-2c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24", az = "us-west-2a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", az = "us-west-2b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", az = "us-west-2c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", az = "us-west-2a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", az = "us-west-2b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", az = "us-west-2c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", az = "us-west-2a", name = "subnet-15" },
  ]
}

#Create AWS VPC
resource "aws_vpc" "vpc-deploy-me" {
  cidr_block       = var.cidr_block_prefix
  instance_tenancy = "default"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

#Create AWS VPC Internet gateway
resource "aws_internet_gateway" "igw-deploy-me" {
  vpc_id = aws_vpc.vpc-deploy-me.id

  tags = {
    Name = "igw-deploy-me"
  }
}

#AWS Elastic IP
resource "aws_eip" "eip-deploy-me-for-nat" {
  domain                    = "vpc"
  depends_on                = [aws_internet_gateway.igw-deploy-me]
}

#Printig Outputs 
output "server_public_ip" {
  value = aws_eip.eip-deploy-me-for-nat.public_ip
}

#NAT Gateway
resource "aws_nat_gateway" "deployme-natgw" {
  allocation_id = aws_eip.eip-deploy-me-for-nat.id
  subnet_id     = aws_subnet.sn-deployme-private-1a.id
  depends_on = [aws_internet_gateway.igw-deploy-me]

  tags = {
    Name = "deployme-natgw"
  }
}

#Subnet Group 1
#Create AWS VPC Private Subnet A us-west-2a
resource "aws_subnet" "sn-deployme-private-1a" {
  vpc_id            = aws_vpc.vpc-deploy-me.id
  cidr_block        = var.subnet_prefix[0].cidr_block
  availability_zone = var.subnet_prefix[0].az

  tags = {
    Name = var.subnet_prefix[0].name
  }
}

#Create AWS VPC Private Subnet A us-west-2b
resource "aws_subnet" "sn-deployme-private-2a" {
