resource "aws_route_table" "rt-private-deploy-me" {

  vpc_id = aws_vpc.vpc-deploy-me.id

  route {
      cidr_block = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.deployme-natgw.id
  }

  tags = {
