// File: outputs.tf
output "prefix_list_id" {
  value       = var.prefix_list_enabled && length(var.prefix_list_ids) < 1 ? aws_ec2_managed_prefix_list.prefix_list[0].id : null
  description = "The ID of the prefix list."
}

output "security_group_id" {
  value       = var.new_sg ? aws_security_group.default[0].id : null
  description = "IDs on the AWS Security Groups associated with the instance."
}

output "security_group_arn" {
  value       = var.new_sg ? aws_security_group.default[0].arn : null
  description = "IDs on the AWS Security Groups associated with the instance."
}

output "security_group_tags" {
  value       = var.new_sg ? aws_security_group.default[0].tags : null
  description = "A mapping of public tags to assign to the resource."
}

// File: variables.tf
variable "name" {
  type        = string
  default     = ""
  description = "Name  (e.g. `app` or `cluster`)."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "label_order" {
  type        = list(any)
  default     = ["name", "environment"]
  description = "Label order, e.g. `name`,`application`."
}

variable "repository" {
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
  description = "Terraform current module repo"
}

variable "managedby" {
  type        = string
  default     = "opsstation"
  description = "ManagedBy, eg 'cypik'."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "The ID of the VPC that the instance security group belongs to."
  sensitive   = true
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "The ID of the prefix list."
}

variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Enable prefix_list."
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "The maximum number of entries that this prefix list can contain."
}

variable "entry" {
  type        = list(any)
  default     = []
  description = "Can be specified multiple times for each prefix list entry."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "Provide existing security group id for updating existing rule"
}

variable "new_sg_ingress_rules_with_cidr_blocks" {
  type        = any
  default     = {}
  description = "Ingress rules with only cidr blocks. Should be used when new security group is been deployed."
}

variable "new_sg_ingress_rules_with_self" {
  type        = any
  default     = {}
  description = "Ingress rules with only self. Should be used when new security group is been deployed."
}

variable "new_sg_ingress_rules_with_source_sg_id" {
  type        = any
  default     = {}
  description = "Ingress rules with only source security group id. Should be used when new security group is been deployed."
}

variable "new_sg_ingress_rules_with_prefix_list" {
  type        = any
  default     = {}
  description = "Ingress rules with only prefix list ids. Should be used when new security group is been deployed."
}

variable "existing_sg_ingress_rules_with_cidr_blocks" {
  type        = any
  default     = {}
  description = "Ingress rules with only cidr blocks. Should be used when there is existing security group."
}

variable "existing_sg_ingress_rules_with_self" {
  type        = any
  default     = {}
  description = "Ingress rules with only source security group id. Should be used when new security group is been deployed."
}

variable "existing_sg_ingress_rules_with_source_sg_id" {
  type        = any
  default     = {}
  description = "Ingress rules with only prefix list ids. Should be used when there is existing security group."
}

variable "existing_sg_ingress_rules_with_prefix_list" {
  type        = any
  default     = {}
  description = "Ingress rules with only prefix_list. Should be used when new security group is been deployed."
}

variable "new_sg_egress_rules_with_cidr_blocks" {
  type        = any
  default     = {}
  description = "Egress rules with only cidr_blockd. Should be used when new security group is been deployed."
}

variable "new_sg_egress_rules_with_self" {
  type        = any
  default     = {}
  description = "Egress rules with only self. Should be used when new security group is been deployed."
}

variable "new_sg_egress_rules_with_source_sg_id" {
  type        = any
  default     = {}
  description = "Egress rules with only source security group id. Should be used when new security group is been deployed."
}

variable "new_sg_egress_rules_with_prefix_list" {
  type        = any
  default     = {}
  description = "Egress rules with only prefix list ids. Should be used when new security group is been deployed."
}

variable "existing_sg_egress_rules_with_cidr_blocks" {
  type        = any
  default     = {}
  description = "Ingress rules with only cidr block. Should be used when there is existing security group."
}

variable "existing_sg_egress_rules_with_self" {
  type        = any
  default     = {}
  description = "Egress rules with only self. Should be used when there is existing security group."
}

variable "existing_sg_egress_rules_with_source_sg_id" {
  type        = any
  default     = {}
  description = "Egress rules with only source security group id. Should be used when there is existing security group."
}

variable "existing_sg_egress_rules_with_prefix_list" {
  type        = any
  default     = {}
  description = "Egress rules with only prefic ist ids. Should be used when there is existing security group."
}

variable "new_sg" {
  type        = bool
  default     = true
  description = "Flag to control creation of new security group."
}

variable "sg_description" {
  type        = string
  default     = null
  description = "Security group description. Defaults to Managed by Terraform. Cannot be empty string. NOTE: This field maps to the AWS GroupDescription attribute, for which there is no Update API. If you'd like to classify your security groups in a way that can be updated, use tags."
}

variable "enable" {
  type        = bool
  default     = true
  description = "Flag to control module creation."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "(Required, Forces new resource) The address family (IPv4 or IPv6) of prefix list."
}

// File: versions.tf
# Terraform version
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.1.0"
    }
  }
}

data "aws_iam_policy" "secrets-manager" {
  name = "SecretsManagerReadWrite"
}

data "aws_iam_policy" "s3-full-access" {
  name = "AmazonS3FullAccess"
}

resource "aws_iam_policy" "access-secrets-from-ecs" {
  name = "access-secrets-from-ecs"
  policy = jsonencode({
    Version : "2012-10-17",
    Statement : [
      {
        Effect : "Allow",
        Action : [
          "secretsmanager:GetSecretValue",
          "kms:Decrypt"
        ],
        Resource : [
          "arn:aws:secretsmanager:*:*:*:*",
          "arn:aws:kms:*:*:*"
        ]
      }
    ]
  })

}

resource "aws_iam_policy" "allow_ecs_command_execution" {
  name = "allow_ecs_command_execution"
  policy = jsonencode({
    Version : "2012-10-17",
    Statement : [
      {
        Effect : "Allow",
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource : [
          "*"
        ]
      }
    ]
  })

}

resource "aws_iam_role" "ecs-task-role" {
  name = "ecs-task-role-for-${var.env_name}"

  managed_policy_arns = [data.aws_iam_policy.secrets-manager.arn, data.aws_iam_policy.s3-full-access.arn, aws_iam_policy.allow_ecs_command_execution.arn]
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      },
    ]
  })

}


data "aws_iam_policy" "ecs-task-exec" {
  name = "AmazonECSTaskExecutionRolePolicy"
}

data "aws_iam_policy" "ec2-service-role" {
  name = "AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role" "ecs-execution-role" {
  name = "ecs-execution-role-for-${var.env_name}"

  managed_policy_arns = [
    data.aws_iam_policy.ecs-task-exec.arn, data.aws_iam_policy.ec2-service-role.arn,
    aws_iam_policy.access-secrets-from-ecs.arn
  ]

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      },
    ]
  })

}

data "aws_iam_policy_document" "assume_role_events" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "ecs_events" {
  name = "ecs_events_role-for-${var.env_name}"

  managed_policy_arns = [
    data.aws_iam_policy.ecs-task-exec.arn, data.aws_iam_policy.ec2-service-role.arn,
    aws_iam_policy.access-secrets-from-ecs.arn
  ]

  assume_role_policy = data.aws_iam_policy_document.assume_role_events.json
}

resource "aws_iam_policy" "developers_policy" {
  name        = "developers-policy-limited-mfa"
  description = "Developer accesspolicy"

  policy = jsonencode(
    {
      "Statement" : [
        {
          "Action" : [
            "s3:GetObject",
            "s3:PutObject",
            "s3:DeleteObject",
            "s3:ListBucket",
            "s3:GetBucketLocation",
            "s3:ListAllMyBuckets"
          ],
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "s3fullAccess"
        },
        {
          "Action" : [
            "secretsmanager:Get*",
            "secretsmanager:List*",
            "secretsmanager:Describe*"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "SecretManagerViewOnly"
        },
        {
          "Action" : [
            "logs:GetLogEvents",
            "logs:DescribeLogGroups",
            "logs:DescribeLogStreams",
            "logs:TestMetricFilter",
            "logs:DescribeMetricFilters",
            "logs:ListTagsForResource",
            "logs:ListAnomalies",
            "logs:Filter*",
            "logs:StartQuery",
            "logs:StopQuery",
            "logs:DescribeQueries",
            "logs:GetLogGroupFields",
            "logs:GetLogRecord",
            "logs:GetQueryResults",
            "logs:PutMetricFilter",
            "cloudwatch:Describe*",
            "cloudwatch:Get*",
            "cloudwatch:List*"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "CloudwatchReadOnly"
        },
        {
          "Action" : [
            "ecs:Get*",
            "ecs:Describe*",
            "ecs:List*"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "EcsReadOnly"
        },
        {
          "Action" : [
            "iam:ChangePassword"
          ],
          "Effect" : "Allow",
          "Resource" : [
            "arn:aws:iam::*:user/$${aws:username}"
          ],
          "Sid" : "IAMChangePassword"
        },
        {
          "Action" : [
            "iam:GetAccountPasswordPolicy"
          ],
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "GetPasswordPolicy"
        },
        {
          "Action" : [
            "iam:ListUsers",
            "iam:ListVirtualMFADevices"
          ],
          "Effect" : "Allow",
          "Resource" : "*",
          "Sid" : "AllowListActions"
        },
        {
          "Action" : [
            "iam:CreateAccessKey",
            "iam:DeleteAccessKey",
            "iam:ListAccessKeys",
            "iam:UpdateAccessKey"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : "arn:aws:iam::*:user/$${aws:username}",
          "Sid" : "AllowManageOwnAccessKeys"
        },
        {
          "Action" : [
            "iam:DeleteSSHPublicKey",
            "iam:GetSSHPublicKey",
            "iam:ListSSHPublicKeys",
            "iam:UpdateSSHPublicKey",
            "iam:UploadSSHPublicKey"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : "arn:aws:iam::*:user/$${aws:username}",
          "Sid" : "AllowManageOwnSSHPublicKeys"
        },
        {
          "Action" : [
            "iam:ListMFADevices"
          ],
          "Effect" : "Allow",
          "Resource" : [
            "arn:aws:iam::*:mfa/*",
            "arn:aws:iam::*:user/$${aws:username}"
          ],
          "Sid" : "AllowIndividualUserToListOnlyTheirOwnMFA"
        },
        {
          "Action" : [
            "iam:CreateVirtualMFADevice",
            "iam:DeleteVirtualMFADevice",
            "iam:EnableMFADevice",
            "iam:ResyncMFADevice"
          ],
          "Effect" : "Allow",
          "Resource" : [
            "arn:aws:iam::*:mfa/*",
            "arn:aws:iam::*:user/$${aws:username}"
          ],
          "Sid" : "AllowIndividualUserToManageTheirOwnMFA"
        },
        {
          "Action" : [
            "iam:DeactivateMFADevice"
          ],
          "Condition" : {
            "Bool" : {
              "aws:MultiFactorAuthPresent" : "true"
            }
          },
          "Effect" : "Allow",
          "Resource" : [
            "arn:aws:iam::*:mfa/*",
            "arn:aws:iam::*:user/$${aws:username}"
          ],
          "Sid" : "AllowIndividualUserToDeactivateOnlyTheirOwnMFAOnlyWhenUsingMFA"
        },
        {
          "Condition" : {
            "BoolIfExists" : {
              "aws:MultiFactorAuthPresent" : "false"
            }
          },
          "Effect" : "Deny",
          "NotAction" : [
            "iam:CreateVirtualMFADevice",
            "iam:EnableMFADevice",
            "iam:ListMFADevices",
            "iam:ListUsers",
            "iam:ListVirtualMFADevices",
            "iam:ResyncMFADevice",
            "iam:ChangePassword",
            "s3:*"
          ],
          "Resource" : "*",
          "Sid" : "BlockMostAccessUnlessSignedInWithMFA"
        }
      ],
      "Version" : "2012-10-17"
    }
  )
}

resource "aws_iam_policy" "billing_mfa_policy" {
  name        = "billing-policy-limited-mfa"
  description = "Billing job function plus MFA policy"

  policy = jsonencode(
    {
      "Statement" : [
        {
          "Action" : [
            "account:GetAccountInformation",
            "aws-portal:*Billing",
            "aws-portal:*PaymentMethods",
            "aws-portal:*Usage",
            "billing:GetBillingData",
            "billing:GetBillingDetails",
            "billing:GetBillingNotifications",
            "billing:GetBillingPreferences",
            "billing:GetContractInformation",
            "billing:GetCredits",
            "billing:GetIAMAccessPreference",
            "billing:GetSellerOfRecord",
            "billing:ListBillingViews",
