    for user, access_point in aws_efs_access_point.user_access_point : user => {
      id             = access_point.id
      arn            = access_point.arn
      file_system_id = access_point.file_system_id
    }
  }
  sensitive = false
}

output "additional_access_points" {
  description = "Information about the general-use EFS access points"
  value = {
    for name, access_point in aws_efs_access_point.additional_access_point : name => {
      id             = access_point.id
      arn            = access_point.arn
      file_system_id = access_point.file_system_id
    }
  }
  sensitive = false
}

// File: security_group_efs.tf
resource "aws_security_group" "efs" {
  count = var.create_efs_security_group ? 1 : 0

  name        = var.efs_security_group_name
  description = "Security Group for EFS Mount"
  vpc_id      = var.vpc_id
  tags        = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "efs" {
  for_each = { for k, v in var.efs_security_group_rules : k => v if var.create_efs_security_group }

  # Required
  security_group_id = aws_security_group.efs[0].id
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  type              = each.value.type

  # Optional
  description              = try(each.value.description, null)
  cidr_blocks              = try(each.value.cidr_blocks, null)
  ipv6_cidr_blocks         = try(each.value.ipv6_cidr_blocks, null)
  prefix_list_ids          = try(each.value.prefix_list_ids, [])
  self                     = try(each.value.self, null)
  source_security_group_id = try(each.value.source_security_group_id, null)
}

