// File: main.tf
# Managed By : CloudDrove
# Copyright @ CloudDrove. All Right Reserved.

module "labels" {
  source      = "clouddrove/labels/aws"
  version     = "1.3.1"
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
  extra_tags  = var.tags
}

##-----------------------------------------------------------------------------
## Security group — inline ingress/egress blocks intentionally omitted.
## All rules managed via aws_vpc_security_group_*_rule resources below.
##-----------------------------------------------------------------------------
resource "aws_security_group" "default" {
  count                  = var.enable && var.new_sg ? 1 : 0
  name_prefix            = format("%s-sg-", module.labels.id)
  vpc_id                 = var.vpc_id
  description            = var.sg_description
  revoke_rules_on_delete = var.revoke_rules_on_delete
  tags                   = module.labels.tags
  lifecycle {
    create_before_destroy = true
  }
  timeouts {
    delete = "60m"
  }
}

data "aws_security_group" "existing" {
  count  = var.enable && var.existing_sg_id != null ? 1 : 0
  id     = var.existing_sg_id
  vpc_id = var.vpc_id
}

resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count          = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) < 1 ? 1 : 0
  address_family = var.prefix_list_address_family
  max_entries    = var.max_entries
  name           = format("%s-prefix-list", module.labels.id)
  dynamic "entry" {
    for_each = var.entry
    content {
      cidr        = lookup(entry.value, "cidr", null)
      description = lookup(entry.value, "description", null)
    }
  }
}

locals {
  new_sg_id      = var.enable && var.new_sg ? aws_security_group.default[0].id : null
  existing_sg_id = var.enable && var.existing_sg_id != null ? data.aws_security_group.existing[0].id : null
}

##-----------------------------------------------------------------------------
## Ingress rules — new SG. Uses aws_vpc_security_group_ingress_rule (provider
## 5.x), replacing the deprecated aws_security_group_rule. One resource per
## source. key field must be unique and stable across rule list changes.
##-----------------------------------------------------------------------------
resource "aws_vpc_security_group_ingress_rule" "new_sg_cidr" {
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_ingress_rules : rule.key => rule
    if rule.cidr_ipv4 != null || rule.cidr_ipv6 != null
  } : {}
  security_group_id = local.new_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_ingress_rule" "new_sg_source_sg" {
  # Filter on absence of CIDR/prefix fields (always static config values) rather than
  # presence of referenced_security_group_id (may be unknown at plan time, causing
  # Terraform to error with "for_each map includes keys derived from resource attributes
  # that cannot be determined until apply").
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_ingress_rules : rule.key => rule
    if rule.cidr_ipv4 == null && rule.cidr_ipv6 == null && rule.prefix_list_id == null
  } : {}
  security_group_id            = local.new_sg_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? null : each.value.to_port
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = each.value.description
  tags                         = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_ingress_rule" "new_sg_prefix" {
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_ingress_rules : rule.key => rule
    if rule.prefix_list_id != null
  } : {}
  security_group_id = local.new_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

##-----------------------------------------------------------------------------
## Egress rules — new SG.
##-----------------------------------------------------------------------------
resource "aws_vpc_security_group_egress_rule" "new_sg_cidr" {
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_egress_rules : rule.key => rule
    if rule.cidr_ipv4 != null || rule.cidr_ipv6 != null
  } : {}
  security_group_id = local.new_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_egress_rule" "new_sg_source_sg" {
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_egress_rules : rule.key => rule
    if rule.cidr_ipv4 == null && rule.cidr_ipv6 == null && rule.prefix_list_id == null
  } : {}
  security_group_id            = local.new_sg_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? null : each.value.to_port
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = each.value.description
  tags                         = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_egress_rule" "new_sg_prefix" {
  for_each = var.enable && var.new_sg ? {
    for rule in var.new_sg_egress_rules : rule.key => rule
    if rule.prefix_list_id != null
  } : {}
  security_group_id = local.new_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  prefix_list_id    = each.value.prefix_list_id
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

##-----------------------------------------------------------------------------
## Ingress/egress rules for an existing security group.
##-----------------------------------------------------------------------------
resource "aws_vpc_security_group_ingress_rule" "existing_sg_cidr" {
  for_each = var.enable && var.existing_sg_id != null ? {
    for rule in var.existing_sg_ingress_rules : rule.key => rule
    if rule.cidr_ipv4 != null || rule.cidr_ipv6 != null
  } : {}
  security_group_id = local.existing_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_ingress_rule" "existing_sg_source_sg" {
  for_each = var.enable && var.existing_sg_id != null ? {
    for rule in var.existing_sg_ingress_rules : rule.key => rule
    if rule.cidr_ipv4 == null && rule.cidr_ipv6 == null && rule.prefix_list_id == null
  } : {}
  security_group_id            = local.existing_sg_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? null : each.value.to_port
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = each.value.description
  tags                         = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_egress_rule" "existing_sg_cidr" {
  for_each = var.enable && var.existing_sg_id != null ? {
    for rule in var.existing_sg_egress_rules : rule.key => rule
    if rule.cidr_ipv4 != null || rule.cidr_ipv6 != null
  } : {}
  security_group_id = local.existing_sg_id
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6
  description       = each.value.description
  tags              = merge(module.labels.tags, each.value.tags)
}

resource "aws_vpc_security_group_egress_rule" "existing_sg_source_sg" {
  for_each = var.enable && var.existing_sg_id != null ? {
    for rule in var.existing_sg_egress_rules : rule.key => rule
    if rule.cidr_ipv4 == null && rule.cidr_ipv6 == null && rule.prefix_list_id == null
  } : {}
  security_group_id            = local.existing_sg_id
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port                      = each.value.ip_protocol == "-1" ? null : each.value.to_port
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = each.value.description
  tags                         = merge(module.labels.tags, each.value.tags)
}

// File: outputs.tf
output "security_group_id" {
  value       = var.enable && var.new_sg ? aws_security_group.default[0].id : null
  description = "ID of the created security group."
}

output "security_group_arn" {
  value       = var.enable && var.new_sg ? aws_security_group.default[0].arn : null
  description = "ARN of the created security group."
}

output "security_group_name" {
  value       = var.enable && var.new_sg ? aws_security_group.default[0].name : null
  description = "Name of the created security group."
}

output "security_group_tags" {
  value       = var.enable && var.new_sg ? aws_security_group.default[0].tags : null
  description = "Tags applied to the security group."
}

output "prefix_list_id" {
  value       = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) < 1 ? aws_ec2_managed_prefix_list.prefix_list[0].id : null
  description = "ID of the managed prefix list, if created."
}

// File: variables.tf
variable "name" {
  type        = string
  default     = ""
  description = "Name (e.g. app or cluster)."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. prod, dev, staging)."
}

variable "label_order" {
  type        = list(any)
  default     = ["name", "environment"]
  description = "Label order."
}

variable "repository" {
  type        = string
  default     = "https://github.com/clouddrove/terraform-aws-security-group"
  description = "Terraform current module repo."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags."
}

variable "managedby" {
  type        = string
  default     = "hello@clouddrove.com"
  description = "ManagedBy, eg 'CloudDrove'."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "VPC ID the security group belongs to."
  sensitive   = true
}

variable "enable" {
  type        = bool
  default     = true
  description = "Flag to control module creation."
}

variable "new_sg" {
  type        = bool
  default     = true
  description = "Create a new security group. Set false to manage rules on an existing SG via existing_sg_id."
}

variable "sg_description" {
  type        = string
  default     = "Managed by Terraform"
  description = "Security group description. Cannot be updated in-place — forces replacement."
}

variable "revoke_rules_on_delete" {
  type        = bool
  default     = false
  description = "Revoke all rules before deleting the SG. Required for EMR and similar services that inject their own rules."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "ID of a pre-existing security group to add rules to."
}

##-----------------------------------------------------------------------------
## Rule object type used for all ingress/egress rule variables.
## Exactly one of cidr_ipv4, cidr_ipv6, prefix_list_id, or
## referenced_security_group_id must be set per rule.
## key must be unique and stable — it is used as the for_each map key.
##-----------------------------------------------------------------------------
variable "new_sg_ingress_rules" {
  description = "Ingress rules for the newly created security group."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    prefix_list_id               = optional(string)
    referenced_security_group_id = optional(string)
    description                  = optional(string, "Managed by Terraform")
    tags                         = optional(map(string), {})
  }))
  default = []
}

variable "new_sg_egress_rules" {
  description = "Egress rules for the newly created security group. Default allows all IPv4 egress."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    prefix_list_id               = optional(string)
    referenced_security_group_id = optional(string)
    description                  = optional(string, "Managed by Terraform")
    tags                         = optional(map(string), {})
  }))
  default = [
    {
      key         = "allow-all-ipv4-egress"
      ip_protocol = "-1"
      cidr_ipv4   = "0.0.0.0/0"
      description = "Allow all IPv4 egress"
    }
  ]
}

variable "existing_sg_ingress_rules" {
  description = "Ingress rules to add to an existing security group (requires existing_sg_id)."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    prefix_list_id               = optional(string)
    referenced_security_group_id = optional(string)
    description                  = optional(string, "Managed by Terraform")
    tags                         = optional(map(string), {})
  }))
  default = []
}

variable "existing_sg_egress_rules" {
  description = "Egress rules to add to an existing security group (requires existing_sg_id)."
  type = list(object({
    key                          = string
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    prefix_list_id               = optional(string)
    referenced_security_group_id = optional(string)
    description                  = optional(string, "Managed by Terraform")
    tags                         = optional(map(string), {})
  }))
  default = []
}

##-----------------------------------------------------------------------------
## Prefix list
##-----------------------------------------------------------------------------
variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Create a managed prefix list."
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "Existing prefix list IDs to reference in rules. If empty and prefix_list_enabled=true, a new one is created."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "Address family for the managed prefix list: IPv4 or IPv6."
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "Maximum entries in the managed prefix list."
}

variable "entry" {
  type        = list(any)
  default     = []
  description = "Entries for the managed prefix list."
}

// File: versions.tf
# Terraform version
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.80.0"
    }
  }

  provider_meta "aws" {
    user_agent = ["github.com/clouddrove/terraform-aws-security-group"]
  }
}

data "aws_caller_identity" "default" {}

#EC2 Code deploy service role
resource "aws_iam_role" "ec2codedeploy_role" {
  name = "${var.project}_ec2_codedeploy_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF

  tags = {
    Name = "${var.project}-role-ManagedBy-Terraform"
  }

}

resource "aws_iam_role_policy_attachment" "AnazonEc2RoleforAWSCodeDeploy_attach" {
  role       = aws_iam_role.ec2codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_fullaccess_attach" {
  role       = aws_iam_role.ec2codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_s3_fullaccess_attach" {
  role       = aws_iam_role.ec2codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_code_deploy_instance_profile" {
  name = "${var.project}_code_deploy_instance_profile"
  role = aws_iam_role.ec2codedeploy_role.name
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

#AWS Code Deploy Service Role
resource "aws_iam_role" "codedeploy_role" {
  name               = "${var.project}_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
  tags = {
    Name = "${var.project}-role-ManagedBy-Terraform"
  }

}

resource "aws_iam_role_policy_attachment" "codedeploy_attachment_policy" {
  role       = aws_iam_role.codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_s3_fullaccess_attach" {
  role       = aws_iam_role.codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}


#EC2 service role for cloud watch agent
resource "aws_iam_role" "ec2_cw_agent_role" {
  name = "${var.project}_ec2_cw_agent_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF

  tags = {
    Name = "${var.project}-role-ManagedBy-Terraform"
  }

}


resource "aws_iam_role_policy_attachment" "CW_Agent_attach" {
  role       = aws_iam_role.ec2_cw_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}
resource "aws_iam_role_policy_attachment" "asg_ec2_s3_fullaccess_attach" {
  role       = aws_iam_role.ec2_cw_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}
resource "aws_iam_instance_profile" "ec2_cw_instance_profile" {
  name = "${var.project}_cw_agent_instance_profile"
  role = aws_iam_role.ec2_cw_agent_role.name
}

# CodeBuild Role
resource "aws_iam_role" "codebuildrole" {
  assume_role_policy = jsonencode(
    {
      Statement = [
        {
          Action = "sts:AssumeRole"
          Effect = "Allow"
          Principal = {
            Service = "codebuild.amazonaws.com"
          }
        },
      ]
      Version = "2012-10-17"
    }
  )
  description           = "Allows CodeBuild to call AWS services on your behalf."
  force_detach_policies = false
  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
  ]
  max_session_duration = 3600
  name                 = "CodeBuildRole"

  inline_policy {
    name = "CodeBuild"
    policy = jsonencode(
      {
        Statement = [
          {
            Action = [
              "logs:CreateLogGroup",
              "logs:CreateLogStream",
              "logs:PutLogEvents",
            ]
            Effect = "Allow"
            Resource = [
              "*",
            ]
          },
          {
            Action = [
              "s3:PutObject",
              "s3:GetObject",
              "s3:GetObjectVersion",
              "s3:GetBucketAcl",
              "s3:GetBucketLocation",
            ]
            Effect = "Allow"
            Resource = [
              "arn:aws:s3:::codepipeline-us-east-1-*",
            ]
          },

          {
            Action = [
              "codebuild:CreateReportGroup",
              "codebuild:CreateReport",
              "codebuild:UpdateReport",
              "codebuild:BatchPutTestCases",
              "codebuild:BatchPutCodeCoverages",
            ]
            Effect = "Allow"
            Resource = [
              "*",
            ]
          },
          # Uncomment this block to allow CodeBuild to create and manage VPC resources
          # {
          #   "Effect" : "Allow",
          #   "Action" : [
          #     "ec2:CreateNetworkInterface",
          #     "ec2:DescribeDhcpOptions",
          #     "ec2:DescribeNetworkInterfaces",
          #     "ec2:DeleteNetworkInterface",
          #     "ec2:DescribeSubnets",
          #     "ec2:DescribeSecurityGroups",
          #     "ec2:DescribeVpcs"
          #   ],
          #   "Resource" : "*"
          # },
          # {
          #   "Effect" : "Allow",
          #   "Action" : [
          #     "ec2:CreateNetworkInterfacePermission"
          #   ],
          #   "Resource" : "*",
          # },
        ]
        Version = "2012-10-17"
      }
    )
  }
  tags = { Name = "${var.project}-role-ManagedBy-Terraform" }
}


# CodePipeline Role
resource "aws_iam_role" "codepipeline" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.cp_assume_role_policy.json
}

data "aws_iam_policy_document" "cp_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com", "codebuild.amazonaws.com", "codedeploy.amazonaws.com", "ec2.amazonaws.com", "ecs-tasks.amazonaws.com"]
    }
  }

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.default.account_id}:root"]
    }
  }
}


resource "aws_iam_role_policy" "codepipelinerole_policy" {
  name = "CodepipelineRole-Policy"
  role = aws_iam_role.codepipeline.id

  policy = <<EOF
{
    "Statement": [
        {
            "Action": [
                "codestar-connections:*"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "s3:GetObject",
                "s3:GetObjectVersion",
                "s3:GetBucketVersioning"
            ],
            "Resource": [
                "arn:aws:s3:::codepipeline-us-east-1-*"
            ],
            "Effect": "Allow"
        },
        {
            "Action": [
                "s3:PutObject",
                "s3:GetObject",
                "s3:DeleteObject"
            ],
            "Resource": [
                "arn:aws:s3:::codepipeline-us-east-1-*",
                "arn:aws:s3:::codepipeline-us-east-1-*/*"
            ],
            "Effect": "Allow"
        },
        {
            "Action": [
                "codecommit:CancelUploadArchive",
                "codecommit:GetBranch",
                "codecommit:GetCommit",
                "codecommit:GetUploadArchiveStatus",
                "codecommit:UploadArchive"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "codedeploy:CreateDeployment",
                "codedeploy:GetApplicationRevision",
                "codedeploy:GetDeployment",
                "codedeploy:GetDeploymentConfig",
                "codedeploy:RegisterApplicationRevision"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "elasticbeanstalk:*",
                "ec2:*",
                "elasticloadbalancing:*",
                "autoscaling:*",
                "cloudwatch:*",
                "sns:*",
                "cloudformation:*",
                "rds:*",
                "sqs:*",
                "ecs:*",
                "iam:PassRole"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "lambda:*"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "opsworks:CreateDeployment",
                "opsworks:DescribeApps",
                "opsworks:DescribeCommands",
                "opsworks:DescribeDeployments",
                "opsworks:DescribeInstances",
                "opsworks:DescribeStacks",
                "opsworks:UpdateApp",
                "opsworks:UpdateStack"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "cloudformation:CreateStack",
                "cloudformation:DeleteStack",
                "cloudformation:DescribeStacks",
                "cloudformation:UpdateStack",
                "cloudformation:CreateChangeSet",
                "cloudformation:DeleteChangeSet",
                "cloudformation:DescribeChangeSet",
                "cloudformation:ExecuteChangeSet",
                "cloudformation:SetStackPolicy",
                "cloudformation:ValidateTemplate",
                "iam:PassRole"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "codebuild:BatchGetBuilds",
                "codebuild:StartBuild"
            ],
            "Resource": "*",
            "Effect": "Allow"
        }
    ],
    "Version": "2012-10-17"
}
EOF
}

output "codedeploy_role_arn" {
  description = "ARN of CodeDeploy role"
  value       = aws_iam_role.codedeploy_role.arn
}

output "codedeploy_instance_profile" {
  description = "Name of CodeDeploy instance profile"
