}

output "cw_agent_instance_profile" {
  description = "Name of CloudWatch instance profile"
  value       = aws_iam_instance_profile.ec2_cw_instance_profile.name
}

output "codebuild_role_arn" {
  description = "ARN of CodeBuild role"
  value       = aws_iam_role.codebuildrole.arn
}

output "codepipeline_role_arn" {
  description = "ARN of CodePipeline role"
  value       = aws_iam_role.codepipeline.arn
}

variable "project" {
  description = "The name of the project"
  default     = "Cv-React-App"
  type        = string
}

// File: near-app-actions-mapping.tf
######## AppActionsMapping Table (name=near-app-actions-mapping)
resource "aws_dynamodb_table" "near-app-actions-mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-mapping"
    Environment = var.environment
  }
    lifecycle {
    prevent_destroy = true
    }  
}

// File: near-app-actions-master.tf
######## AppActionsMaster Table (name=near-app-actions-master)
resource "aws_dynamodb_table" "near-app-actions-master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-master"
    Environment = var.environment
  }

    lifecycle {
    prevent_destroy = true
    }
}

// File: near-app-categories.tf
######## AppCategories Table (name=near-app-categories)
resource "aws_dynamodb_table" "near-app-categories" {
  name         = "near-app-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = {
    Name        = "near-app-categories"
    Environment = var.environment
  }
   lifecycle {
    prevent_destroy = true
    } 
}

// File: near-apps.tf
######## Apps Table (name=near-apps)
resource "aws_dynamodb_table" "near-apps" {
  name         = "near-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  attribute {
    name = "categoryId"
    type = "S"
  }

    global_secondary_index {
    name               = "categoryId-Index"
    hash_key           = "categoryId"
    projection_type    = "ALL"
  }

  tags = {
    Name        = "near-apps"
    Environment = var.environment
  }
    lifecycle {
    prevent_destroy = true
    }  
}

// File: near-connected-apps.tf
######## ConnectedApps Table (name=near-connected-apps)
resource "aws_dynamodb_table" "near-connected-apps" {
  name         = "near-connected-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "connectionId"

  attribute {
    name = "connectionId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "appId"
    type = "S"
  }

  global_secondary_index {
    name               = "userId-Index"
    hash_key           = "userId"
    projection_type    = "ALL"
  }

  global_secondary_index {
    name               = "appId-Index"
    hash_key           = "appId"
    projection_type    = "ALL"
  }

  tags = {
    Name        = "near-connected-apps"
    Environment = var.environment
  }
 lifecycle {
    prevent_destroy = true
    }
}

// File: near-contacts.tf
######## Contacts Table (name=near-contacts)
resource "aws_dynamodb_table" "near-contacts" {
  name         = "near-contacts"
