## CLUSTER CREATION

resource "aws_kms_key" "eks_cluster_secrets" {
  description             = "CMK for EKS cluster secrets envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.MD_CLUSTER_NAME
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.pub_subnet.*.id, aws_subnet.priv_subnet.*.id)
    security_group_ids      = [aws_security_group.ControlPlaneSecurityGroup.id]
    endpoint_public_access  = false
    endpoint_private_access = true
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks_cluster_secrets.arn
    }
  }

  tags = {
    Name = "terraform-${var.MD_CLUSTER_NAME}-cluster/ControlPlane"
  }

  depends_on = [
    aws_iam_role_policy_attachment.AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.AmazonEKSVPCResourceController,
    aws_iam_role_policy_attachment.PolicyELBPermissions,
    aws_iam_role_policy_attachment.PolicyCloudWatchMetrics
  ]
}

resource "aws_eks_fargate_profile" "fargate_profile" {
  count = var.DEPLOY_FARGATE_NODES ? 1 : 0

  cluster_name           = aws_eks_cluster.eks_cluster.name
  fargate_profile_name   = var.PERSISTENT_DEPLOYMENT ? "fp-${var.MD_CLUSTER_NAME}" : "fp-default"
  pod_execution_role_arn = aws_iam_role.fargate_pod_execution_role[0].arn
  subnet_ids             = aws_subnet.priv_subnet.*.id

  selector {
    namespace = "default"
    labels = {
      aws-type = "fargate"
    }
  }

  dynamic "selector" {
    for_each = var.PERSISTENT_DEPLOYMENT ? [] : [{}]
    content {
      namespace = "kube-system"
    }
  }

  depends_on = [
    aws_eks_cluster.eks_cluster
  ]
}

data "aws_eks_cluster_auth" "eks_cluster_auth" {
  count = var.PERSISTENT_DEPLOYMENT || !var.DEPLOY_FARGATE_NODES ? 0 : 1

  name = aws_eks_cluster.eks_cluster.name
}

locals {
  kubeconfig = var.PERSISTENT_DEPLOYMENT || !var.DEPLOY_FARGATE_NODES ? "" : <<-EOF
    apiVersion: v1
    kind: Config
    current-context: terraform
    clusters:
    - name: ${aws_eks_cluster.eks_cluster.name}
      cluster:
        certificate-authority-data: ${aws_eks_cluster.eks_cluster.certificate_authority.0.data}
        server: ${aws_eks_cluster.eks_cluster.endpoint}
    contexts:
    - name: terraform
      context:
        cluster: ${aws_eks_cluster.eks_cluster.name}
        user: terraform
    users:
    - name: terraform
      user:
        token: ${data.aws_eks_cluster_auth.eks_cluster_auth[0].token}
  EOF
}

resource "local_file" "kubeconfig" {
  count = var.PERSISTENT_DEPLOYMENT || !var.DEPLOY_FARGATE_NODES ? 0 : 1

  filename = "${path.module}/.kubeconfig"
  content  = local.kubeconfig
}

// Hack to make CoreDNS run on Fargate nodes
resource "null_resource" "update_coredns_annotations" {
  count = var.PERSISTENT_DEPLOYMENT || !var.DEPLOY_FARGATE_NODES ? 0 : 1

  provisioner "local-exec" {
    interpreter = ["${local.os == "Linux" ? "/bin/bash" : "PowerShell"}", "${local.os == "Linux" ? "-c" : "-Command"}"]
    environment = {
      KUBECONFIG = base64encode(local_file.kubeconfig[0].content)
    }
    command = <<-EOF
      kubectl \
        -n kube-system \
        --kubeconfig <(echo $KUBECONFIG | base64 --decode) \
        patch deployment coredns \
        --type json \
        -p='[{"op": "remove", "path": "/spec/template/metadata/annotations/eks.amazonaws.com~1compute-type"}]'
    EOF
  }

  depends_on = [
    aws_eks_cluster.eks_cluster,
    aws_eks_fargate_profile.fargate_profile
  ]
}

resource "aws_launch_template" "launch_template" {
  count = var.PERSISTENT_DEPLOYMENT ? 1 : 0

  name = "terraform-${var.MD_CLUSTER_NAME}-nodegroup"

  vpc_security_group_ids = [data.aws_security_groups.eks_security_group.ids[0], aws_security_group.NodeGroupRemoteAccessSecurityGroup[0].id]
  key_name               = aws_key_pair.key_pair[0].key_name

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 80
      volume_type = "gp3"
      throughput  = 125
      iops        = 3000
    }
  }
}

resource "aws_eks_node_group" "node_group" {
  count = var.PERSISTENT_DEPLOYMENT ? 1 : 0

  cluster_name    = var.MD_CLUSTER_NAME
  node_group_name = "terraform-${var.MD_CLUSTER_NAME}-nodegroup"
  node_role_arn   = aws_iam_role.eks_nodes_role[0].arn
  subnet_ids      = aws_subnet.pub_subnet.*.id
  instance_types  = ["c5.2xlarge"]
  labels = {
    type = "ec2-db-node"
  }

  scaling_config {
    desired_size = 2
    max_size     = 2
    min_size     = 2
  }

  launch_template {
    id      = aws_launch_template.launch_template[0].id
    version = aws_launch_template.launch_template[0].latest_version
  }

  depends_on = [
    aws_iam_role_policy_attachment.AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.AmazonEC2ContainerRegistryReadOnly,
    aws_iam_role_policy_attachment.AmazonSSMManagedInstanceCore,
    aws_iam_role_policy_attachment.PolicyAWSLoadBalancerController,
    aws_iam_role_policy_attachment.AmazonEKS_CNI_Policy,
    aws_eks_cluster.eks_cluster
  ]
}


### Group Subnet for other resources

resource "aws_db_subnet_group" "private_subnet_group" {
  name       = "${var.MD_CLUSTER_NAME}-private-subnet-group"
  subnet_ids = [for subnet in aws_subnet.priv_subnet : subnet.id]
}

output "vpc_id" {
  value = aws_vpc.vpc.id
}

output "vpc_cidr" {
  value = aws_vpc.vpc.cidr_block
}

output "public_subnets" {
  value = [for subnet in aws_subnet.pub_subnet : subnet.id]
}

output "private_subnets" {
  value = [for subnet in aws_subnet.priv_subnet : subnet.id]
}

output "subnet_group_id" {
  value = aws_db_subnet_group.private_subnet_group.id
}

output "eks_cluster_oicd_url" {
  value = aws_eks_cluster.eks_cluster.identity.0.oidc.0.issuer
}

variable "MD_CLUSTER_NAME" {
  type    = string
  default = "md-k8s"
}

variable "MD_CLUSTER_REGION" {
  type    = string
  default = "eu-central-1"
}

variable "ACCESS_KEY_ID" {
  type    = string
  default = ""
}

variable "SECRET_ACCESS_KEY" {
  type    = string
  default = ""
}

variable "PERSISTENT_DEPLOYMENT" {
  type    = bool
  default = false
}

variable "DEPLOY_FARGATE_NODES" {
  type    = bool
  default = false
}

## Managed By : CloudDrove
# Description : This Script is used to create S3.
## Copyright @ CloudDrove. All Right Reserved.

#Module      : label
#Description : This terraform module is designed to generate consistent label names and
#              tags for resources. You can use terraform-labels to implement a strict
#              naming convention..
module "labels" {
  source  = "clouddrove/labels/aws"
  version = "0.15.0"

  name        = var.name
  repository  = var.repository
  environment = var.environment
  managedby   = var.managedby
  attributes  = var.attributes
  label_order = var.label_order
}

# Module      : S3 BUCKET
# Description : Terraform module to create S3 bucket with different combination . 
#               type specific features.
resource "aws_s3_bucket" "s3_default" {
  count = var.create_bucket == true ? 1 : 0

  bucket        = module.labels.id
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy

  dynamic "object_lock_configuration" {
    for_each = var.object_lock_configuration != null ? [1] : []

    content {
      object_lock_enabled = "Enabled"

    }
  }
}

# Module      : S3 BUCKET POLICY
# Description : Terraform module which creates policy for S3 bucket on AWS
resource "aws_s3_bucket_policy" "s3_default" {
  # count = var.create_bucket && var.bucket_policy && var.bucket_enabled == true ? 1 : 0
  count  = var.bucket_policy == true ? 1 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)
  policy = var.aws_iam_policy_document
}

resource "aws_s3_bucket_accelerate_configuration" "example" {
  count = var.create_bucket && var.acceleration_status == true ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)
  status = "Enabled"
}

resource "aws_s3_bucket_request_payment_configuration" "example" {
  count = var.create_bucket && var.request_payer == true ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)
  payer  = "Requester"
}

resource "aws_s3_bucket_versioning" "example" {
  count = var.create_bucket && var.versioning == true ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "example" {
  count  = var.create_bucket && var.logging == true ? 1 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)

  target_bucket = var.target_bucket
  target_prefix = var.target_prefix
}

resource "aws_s3_bucket_public_access_block" "s3_default" {
  count  = var.create_bucket ? 1 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3_default" {
  count = var.create_bucket && var.enable_server_side_encryption && var.enable_kms && var.kms_master_key_id == "" ? 1 : 0

  description             = "CMK for the S3 bucket managed by this module"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "example" {
  count  = var.create_bucket && var.enable_server_side_encryption == true ? 1 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms == true ? "aws:kms" : var.sse_algorithm
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : join("", aws_kms_key.s3_default.*.arn)
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "example" {
  count = var.create_bucket && var.object_lock_configuration != null ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)

  object_lock_enabled = "Enabled"

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "example" {
  count = var.create_bucket && var.cors_rule != null ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)

  dynamic "cors_rule" {
    for_each = var.cors_rule == null ? [] : var.cors_rule

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_website_configuration" "example" {
  count = var.create_bucket && var.website_config_enable == true ? 1 : 0

  bucket = join("", aws_s3_bucket.s3_default.*.id)

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "error.html"
  }

  routing_rule {
    condition {
      key_prefix_equals = "docs/"
    }
    redirect {
      replace_key_prefix_with = "documents/"
    }
  }
}

locals {
  acl_grants = var.grants == null ? var.acl_grants : flatten(
    [
      for g in var.grants : [
        for p in g.permissions : {
          id         = g.id
          type       = g.type
          permission = p
          uri        = g.uri
        }
      ]
  ])
}


resource "aws_s3_bucket_acl" "default" {

  count  = var.create_bucket ? var.grants != null ? var.acl != null ? 1 : 0 : 0 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)


  acl = try(length(local.acl_grants), 0) == 0 ? var.acl : null

  dynamic "access_control_policy" {
    for_each = try(length(local.acl_grants), 0) == 0 || try(length(var.acl), 0) > 0 ? [] : [1]

    content {
      dynamic "grant" {
        for_each = local.acl_grants

        content {
          grantee {
            id   = grant.value.id
            type = grant.value.type
            uri  = grant.value.uri
          }
          permission = grant.value.permission
        }
      }

      owner {
        id = var.owner_id
      }
    }
  }
}


resource "aws_s3_bucket_lifecycle_configuration" "default" {
  count  = var.create_bucket && var.enable_lifecycle_configuration_rules == true ? 1 : 0
  bucket = join("", aws_s3_bucket.s3_default.*.id)

  dynamic "rule" {
    for_each = var.lifecycle_configuration_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled == true ? "Enabled" : "Disabled"

      # Filter is always required due to https://github.com/hashicorp/terraform-provider-aws/issues/23299
      filter {
        dynamic "and" {
          for_each = (try(length(rule.value.prefix), 0) + try(length(rule.value.tags), 0)) > 0 ? [1] : []
          content {
            prefix = rule.value.prefix == null ? "" : rule.value.prefix
            tags   = try(length(rule.value.tags), 0) > 0 ? rule.value.tags : {}
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(tonumber(rule.value.abort_incomplete_multipart_upload_days), null) != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.enable_noncurrent_version_expiration ? [1] : []

        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.enable_glacier_transition ? [1] : []

        content {
          noncurrent_days = rule.value.noncurrent_version_glacier_transition_days
          storage_class   = "GLACIER"
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.enable_deeparchive_transition ? [1] : []

        content {
          noncurrent_days = rule.value.noncurrent_version_deeparchive_transition_days
          storage_class   = "DEEP_ARCHIVE"
        }
      }

      dynamic "transition" {
        for_each = rule.value.enable_glacier_transition ? [1] : []

        content {
          days          = rule.value.glacier_transition_days
          storage_class = "GLACIER"
        }
      }

      dynamic "transition" {
        for_each = rule.value.enable_deeparchive_transition ? [1] : []

        content {
          days          = rule.value.deeparchive_transition_days
          storage_class = "DEEP_ARCHIVE"
        }
      }

      dynamic "transition" {
        for_each = rule.value.enable_standard_ia_transition ? [1] : []

        content {
          days          = rule.value.standard_transition_days
          storage_class = "STANDARD_IA"
        }
      }

      dynamic "expiration" {
        for_each = rule.value.enable_current_object_expiration ? [1] : []

        content {
          days = rule.value.expiration_days
        }
      }
    }
  }

  depends_on = [
    # versioning must be set before lifecycle configuration
    aws_s3_bucket_versioning.example
  ]
}

# Module      : S3 BUCKET.
# Description : Terraform module to create default S3 bucket with logging and encryption..
#               type specific features.
output "id" {
  value       = join("", aws_s3_bucket.s3_default.*.id)
  description = "The ID of the s3 bucket."
}

output "arn" {
  value       = join("", aws_s3_bucket.s3_default.*.arn)
  description = "The ARN of the s3 bucket."
}


output "bucket_domain_name" {
  value       = join("", aws_s3_bucket.s3_default.*.bucket_domain_name)
  description = "The Domain of the s3 bucket."
}

output "tags" {
  value       = module.labels.tags
  description = "A mapping of tags to assign to the resource."
}

#Module      : LABEL
#Description : Terraform label module variables.
variable "name" {
  type        = string
  default     = ""
  description = "Name  (e.g. `app` or `cluster`)."
}

variable "repository" {
  type        = string
  default     = "https://github.com/clouddrove/terraform-aws-s3"
  description = "Terraform current module repo"
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "label_order" {
  type        = list(any)
  default     = []
  description = "Label order, e.g. `name`,`application`."
}

variable "managedby" {
  type        = string
  default     = "hello@clouddrove.com"
  description = "ManagedBy, eg 'CloudDrove'."
}

variable "attributes" {
  type        = list(any)
  default     = []
  description = "Additional attributes (e.g. `1`)."
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter to be used between `organization`, `environment`, `name` and `attributes`."
}

variable "tags" {
  type        = map(any)
  default     = {}
  description = "Additional tags (e.g. map(`BusinessUnit`,`XYZ`)."
}

# Module      : S3 BUCKET
# Description : Terraform S3 Bucket module variables.
variable "create_bucket" {
  type        = bool
  default     = true
  description = "Conditionally create S3 bucket."
}

variable "versioning" {
  type        = bool
  default     = true
  description = "Enable Versioning of S3."
}

variable "acl" {
  type        = string
  default     = null
  description = "Canned ACL to apply to the S3 bucket."
}

variable "mfa_delete" {
  type        = bool
  default     = false
  description = "Enable MFA delete for either Change the versioning state of your bucket or Permanently delete an object version."
}

variable "enable_server_side_encryption" {
  type        = bool
  default     = true
  description = "Enable enable_server_side_encryption"
}

variable "sse_algorithm" {
  type        = string
  default     = "AES256"
  description = "The server-side encryption algorithm to use. Valid values are AES256 and aws:kms."
}

variable "enable_kms" {
  type        = bool
  default     = true
  description = "Enable enable_server_side_encryption"
}

variable "kms_master_key_id" {
  type        = string
  default     = ""
  description = "The AWS KMS master key ID used for the SSE-KMS encryption. This can only be used when you set the value of sse_algorithm as aws:kms. The default aws/s3 AWS KMS master key is used if this element is absent while the sse_algorithm is aws:kms."
}

variable "enable_lifecycle_configuration_rules" {
  type        = bool
  default     = false
  description = "enable or disable lifecycle_configuration_rules"
}

variable "lifecycle_configuration_rules" {
  type = list(object({
    id      = string
    prefix  = string
    enabled = bool
    tags    = map(string)

    enable_glacier_transition            = bool
    enable_deeparchive_transition        = bool
    enable_standard_ia_transition        = bool
    enable_current_object_expiration     = bool
    enable_noncurrent_version_expiration = bool

    abort_incomplete_multipart_upload_days         = number
    noncurrent_version_glacier_transition_days     = number
    noncurrent_version_deeparchive_transition_days = number
    noncurrent_version_expiration_days             = number

    standard_transition_days    = number
    glacier_transition_days     = number
    deeparchive_transition_days = number
    expiration_days             = number
  }))
  default     = null
  description = "A list of lifecycle rules"
}

variable "lifecycle_infrequent_storage_transition_enabled" {
  type        = bool
  default     = false
  description = "Specifies infrequent storage transition lifecycle rule status."
}

variable "lifecycle_infrequent_storage_object_prefix" {
  type        = string
  default     = ""
  sensitive   = true
  description = "Object key prefix identifying one or more objects to which the lifecycle rule applies."
}

variable "lifecycle_days_to_infrequent_storage_transition" {
  type        = number
  default     = 60
  description = "Specifies the number of days after object creation when it will be moved to standard infrequent access storage."
}

variable "lifecycle_glacier_transition_enabled" {
  type        = bool
  default     = false
  description = "Specifies Glacier transition lifecycle rule status."
}

variable "lifecycle_glacier_object_prefix" {
  type        = string
  default     = ""
  sensitive   = true
  description = "Object key prefix identifying one or more objects to which the lifecycle rule applies."
}

variable "lifecycle_days_to_deep_archive_transition" {
  type        = number
  default     = 180
  description = "Specifies the number of days after object creation when it will be moved to DEEP ARCHIVE ."
}

variable "lifecycle_deep_archive_transition_enabled" {
  type        = bool
  default     = false
  description = "Specifies DEEP ARCHIVE transition lifecycle rule status."
}

variable "lifecycle_deep_archive_object_prefix" {
  type        = string
  default     = ""
  sensitive   = true
  description = "Object key prefix identifying one or more objects to which the lifecycle rule applies."
}

variable "lifecycle_days_to_glacier_transition" {
  type        = number
  default     = 180
  description = "Specifies the number of days after object creation when it will be moved to Glacier storage."
}

variable "lifecycle_expiration_enabled" {
  type        = bool
  default     = false
  description = "Specifies expiration lifecycle rule status."
}

variable "lifecycle_expiration_object_prefix" {
  type        = string
  default     = ""
  description = "Object key prefix identifying one or more objects to which the lifecycle rule applies."
}

variable "lifecycle_days_to_expiration" {
  type        = number
  default     = 365
  description = "Specifies the number of days after object creation when the object expires."
}

