#You may obtain a copy of the License at
#
#    http://www.apache.org/licenses/LICENSE-2.0
#
#Unless required by applicable law or agreed to in writing, software
#distributed under the License is distributed on an “AS IS” BASIS,
#WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
#See the License for the specific language governing permissions and
#limitations under the License.

variable "aws_region" {
  default = "us-east-1"
}

variable "aws_vpc_name" {
  default = "vpc"
}

variable "aws_azs" {
  description = "comma separated string of availability zones in order of precedence"
  default     = "us-east-1a, us-east-1d, us-east-1e, us-east-1c"
}

variable "az_count" {
  description = "number of active availability zones in VPC"
  default     = "3"
}

variable "vpc_cidr_base" {
  default = "10.20"
}

variable "vpc_instance_tenancy" {
  default = "default"
}

variable "vpc_enable_dns_support" {
  default = "true"
}

variable "vpc_enable_dns_hostnames" {
  default = "true"
}

variable "admin_subnet_parent_cidr" {
  description = "parent CIDR for the administrative subnets"
  default     = ".0.0/19"
}

variable "admin_subnet_cidrs" {
  description = "CIDRs for the adminsitrative subnets"
  default = {
    zone0 = ".0.0/21"
    zone1 = ".8.0/21"
    zone2 = ".16.0/21"
    zone3 = ".24.0/21"
  }
}

variable "admin_subnet_tags" {
  description = "Tags to apply to the admin subnet"
  default     = {}
}

variable "public_subnet_parent_cidr" {
  description = "parent CIDR for the public subnets"
  default     = ".32.0/19"
}

variable "public_subnet_cidrs" {
  description = "CIDRs for the public subnets"
  default = {
    zone0 = ".32.0/21"
    zone1 = ".40.0/21"
    zone2 = ".48.0/21"
    zone3 = ".56.0/21"
  }
}

variable "public_subnet_tags" {
  description = "Tags to apply to the public subnets"
  default     = {}
}

variable "private_prod_subnet_parent_cidr" {
  description = "parent CIDR for the private production subnets"
  default     = ".64.0/19"
}

variable "private_prod_subnet_cidrs" {
  description = "CIDRs for the private production subnets"
  default = {
    zone0 = ".64.0/21"
    zone1 = ".72.0/21"
    zone2 = ".80.0/21"
    zone3 = ".88.0/21"
  }
}

variable "private_prod_subnet_tags" {
  description = "Tags to apply to the private production subnets"
  default     = {}
}

variable "private_working_subnet_parent_cidr" {
  description = "parent CIDR for the private working subnets"
  default     = ".96.0/19"
}

variable "private_working_subnet_cidrs" {
  description = "CIDRs for the private working subnets"
  default = {
    zone0 = ".96.0/21"
    zone1 = ".104.0/21"
    zone2 = ".112.0/21"
    zone3 = ".120.0/21"
  }
}

variable "private_working_subnet_tags" {
  description = "Tags to apply to the private working subnets"
  default     = {}
}

variable "multi_az_nat_gateway" {
  description = "place a NAT gateway in each AZ"
  default     = 1
}

variable "single_nat_gateway" {
  description = "use a single NAT gateway to serve outbound traffic for all AZs"
  default     = 0
}

variable "enable_s3_vpc_endpoint" {
  description = "Create a VPC S3 gateway endpoint and private subnet route entries. This will route S3 traffic over private network rather than over NAT gateways."
  default     = "false"
}

variable "s3_vpc_endpoint_policy" {
  description = "S3 VPC endpoint gateway policy document. Bucket and IAM policies still apply."
  default     = <<POLICY
{
    "Statement": [
        {
            "Sid": "FullAccess",
            "Action": "*",
            "Effect": "Allow",
            "Resource": "*",
            "Principal": "*"
        }
    ],
    "Version": "2008-10-17"
}
POLICY

}

variable "s3_vpc_endpoint_route_table_ids" {
  description = "By default routes to the s3 endpoint are added for private subnet route tables. Pass additional route table ids that require routes."
  type        = list(string)
  default     = []
}

variable "internet_gateway_tags" {
  description = "Tags to apply to the internet gateway"
  default     = {}
}

variable "public_route_table_tags" {
  description = "Tags to apply to the public route table"
  default     = {}
}

variable "private_route_table_tags" {
  description = "Tags to apply to the private route table"
  default     = {}
}

variable "global_tags" {
  description = "AWS tags that will be added to all resources managed herein"
  type        = map(string)
  default = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }
}

// File: versions.tf
terraform {
  required_version = ">= 0.12"
  required_providers {
    aws = ">=2.30.0"
  }
}

// File: vpc-endpoint.tf
#Copyright 2019 Fairwinds Inc.
#
#Licensed under the Apache License, Version 2.0 (the “License”);
#you may not use this file except in compliance with the License.
#You may obtain a copy of the License at
#
#    http://www.apache.org/licenses/LICENSE-2.0
#
#Unless required by applicable law or agreed to in writing, software
#distributed under the License is distributed on an “AS IS” BASIS,
#WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
#See the License for the specific language governing permissions and
#limitations under the License.

resource "aws_vpc_endpoint" "s3_endpoint" {
  count        = var.enable_s3_vpc_endpoint ? 1 : 0
  vpc_id       = aws_vpc.default.id
  service_name = "com.amazonaws.${var.aws_region}.s3"
  route_table_ids = concat(
    aws_route_table.private.*.id,
    var.s3_vpc_endpoint_route_table_ids,
  )
  policy = var.s3_vpc_endpoint_policy
}

// File: vpc.tf
#Copyright 2019 Fairwinds Inc.
#
#Licensed under the Apache License, Version 2.0 (the “License”);
#you may not use this file except in compliance with the License.
#You may obtain a copy of the License at
#
#    http://www.apache.org/licenses/LICENSE-2.0
#
#Unless required by applicable law or agreed to in writing, software
#distributed under the License is distributed on an “AS IS” BASIS,
#WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
#See the License for the specific language governing permissions and
#limitations under the License.

resource "aws_vpc" "default" {
  cidr_block           = "${var.vpc_cidr_base}.0.0/16"
  instance_tenancy     = var.vpc_instance_tenancy
  enable_dns_support   = var.vpc_enable_dns_support
  enable_dns_hostnames = var.vpc_enable_dns_hostnames
  tags = merge(
    var.global_tags,
    {
      "Name" = var.aws_vpc_name
    },
  )
  lifecycle {
    ignore_changes = [tags]
  }
}

output "aws_vpc_id" {
  value = aws_vpc.default.id
}

output "aws_vpc_cidr" {
  value = aws_vpc.default.cidr_block
}

resource "aws_lb" "main" {
  name                       = "alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.listener.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_target_group" "main" {
  name_prefix = "alb-tg"
  vpc_id      = aws_vpc.main.id
  protocol    = "HTTP"
  port        = var.application_port
  target_type = "ip"

  health_check {
    enabled = true
    path    = var.application_health_check_path
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "tls_private_key" "listener" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "listener" {
  private_key_pem       = tls_private_key.listener.private_key_pem
  dns_names             = ["app.example.internal"]
  validity_period_hours = 8760
  allowed_uses          = ["key_encipherment", "digital_signature", "server_auth"]

  subject {
    common_name = "app.example.internal"
  }
}

# Self-signed certificate imported into ACM so the listener can serve HTTPS without a domain.
resource "aws_acm_certificate" "listener" {
  private_key      = tls_private_key.listener.private_key_pem
  certificate_body = tls_self_signed_cert.listener.cert_pem
}

resource "aws_ecr_repository" "web_backend" {
  name                 = var.application_name
  image_tag_mutability = "IMMUTABLE"
  force_delete         = true

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_ecr_lifecycle_policy" "web_backend" {
  repository = aws_ecr_repository.web_backend.name
  policy     = <<EOF
{
  "rules": [
    {
      "rulePriority": 1,
      "description": "Expire images older than 14 days",
      "selection": {
        "tagStatus": "untagged",
        "countType": "sinceImagePushed",
        "countUnit": "days",
        "countNumber": 14
      },
      "action": {
          "type": "expire"
      }
    }
  ]
}
EOF
}

################### IAM for ECS ###################
resource "aws_iam_role" "ecs_task_execution" {
  name = "ecs-task-execution"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": ["ecs-tasks.amazonaws.com" ]
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

resource "aws_iam_role" "ecs_task" {
  name               = "ecs-task"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": ["ecs-tasks.amazonaws.com"]
      },
      "Effect": "Allow"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "ecs_task_policy" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}


################### ECS ###################
resource "aws_ecs_cluster" "main" {
  name = "my-ecs-cluster"
}

resource "aws_ecs_service" "web_backend" {
  name            = var.application_name
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.web_backend.arn
  desired_count   = 2 # only works initially

  # 20% FARGATE, 80% FARGATE_SPOT
  capacity_provider_strategy {
    base              = 1
    capacity_provider = "FARGATE"
    weight            = 20
  }

  capacity_provider_strategy {
    base              = 0
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  network_configuration {
    subnets         = aws_subnet.public[*].id
    security_groups = [aws_security_group.ecs_task.id]
    assign_public_ip = true
  }

  deployment_controller {
    type = "ECS"
  }

  load_balancer {
    container_name   = var.application_name
    container_port   = var.application_port
    target_group_arn = aws_lb_target_group.main.arn
  }

  lifecycle {
    ignore_changes = [
      # let auto-scaling manage
      # source: https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecs_service#ignoring-changes-to-desired-count
      desired_count,
      # task_definition is only for initial apply
      task_definition
    ]
  }

  # source: https://github.com/hashicorp/terraform/issues/12634#issuecomment-313215022
  depends_on = [aws_lb_listener.http, aws_lb_listener.https]
}


################### ECS Task: How to launch new containers ###################
resource "aws_ecs_task_definition" "web_backend" {
  family                   = var.application_name
  task_role_arn            = aws_iam_role.ecs_task.arn
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 256
  memory                   = 512

  # Image: We use dummy nginx to pass health check at the first launch. Image is controlled by CI/CD in the future
  # Env: We can even use "environmentFiles" to pass env files on S3
  container_definitions = <<TASK_DEFINITION
[
  {
    "name": "${var.application_name}",
    "image": "nginx:1.23.1",
    "essential": true,
    "portMappings": [
      {
        "containerPort": ${var.application_port},
        "hostPort": ${var.application_port}
      }
    ],
    "healthCheck": {
      "retries": 3,
      "command": [
          "CMD-SHELL",
          "curl -f http://localhost:${var.application_port}/ || exit 1"
      ],
      "timeout": 5,
      "interval": 30,
      "startPeriod": null
    },
    "environment": [
      {
        "name": "DATABASE_URL",
        "value": "postgresql://${aws_db_instance.main.username}:${aws_db_instance.main.password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}"
      },
      {
        "name": "DATABASE_NAME",
        "value": "mydb"
      }
    ]
  }
]
TASK_DEFINITION

  depends_on = [aws_db_instance.main]

  lifecycle {
    ignore_changes = all
  }
}


################### ECS Auto-Scaling ###################
resource "aws_appautoscaling_target" "web_backend" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.web_backend.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "ecs_policy_memory" {
  name               = "scale-by-memory"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.web_backend.resource_id
  scalable_dimension = aws_appautoscaling_target.web_backend.scalable_dimension
  service_namespace  = aws_appautoscaling_target.web_backend.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value = 80

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "ecs_policy_cpu" {
  name               = "scale-by-cpu"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.web_backend.resource_id
  scalable_dimension = aws_appautoscaling_target.web_backend.scalable_dimension
  service_namespace  = aws_appautoscaling_target.web_backend.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value = 80

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

# Source: https://docs.github.com/en/actions/deployment/security-hardening-your-deployments/configuring-openid-connect-in-amazon-web-services
resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

resource "aws_iam_role" "github_actions" {
  name                 = "github_actions"
  max_session_duration = 3600

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Federated": "${aws_iam_openid_connect_provider.github.arn}"
      },
      "Action": "sts:AssumeRoleWithWebIdentity",
      "Condition": {
        "StringEquals": {
          "token.actions.githubusercontent.com:aud": "sts.amazonaws.com"
        },
        "StringLike": {
          "token.actions.githubusercontent.com:sub": "repo:${var.github_account}/*"
        }
      }
    }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "github_actions_ecr_policy" {
  role       = aws_iam_role.github_actions.id
  policy_arn = "arn:aws:iam::aws:policy/EC2InstanceProfileForImageBuilderECRContainerBuilds"
}

resource "aws_iam_role_policy" "github_actions_ecs_deploy_policy" {
  name   = "github-actions-ecs-policy"
  role   = aws_iam_role.github_actions.id
  policy = <<EOF
{
  "Version":"2012-10-17",
  "Statement":[
    {
      "Sid":"RegisterTaskDefinition",
      "Effect":"Allow",
      "Action":[
        "ecs:RegisterTaskDefinition",
        "ecs:DescribeTaskDefinition"
      ],
      "Resource":"*"
    },
    {
      "Sid":"PassRolesInTaskDefinition",
      "Effect":"Allow",
      "Action":[
        "iam:PassRole"
      ],
      "Resource":[
        "${aws_iam_role.ecs_task.arn}",
        "${aws_iam_role.ecs_task_execution.arn}"
      ]
    },
    {
      "Sid":"DeployService",
      "Effect":"Allow",
      "Action":[
        "ecs:UpdateService",
        "ecs:DescribeServices"
      ],
      "Resource": "*"
    },
    {
      "Sid":"CleanUpService",
      "Effect":"Allow",
      "Action":[
        "ecs:DescribeServices",
        "ecs:ListServices",
        "ecs:ListTaskDefinitions",
        "ecs:DeregisterTaskDefinition",
        "ecs:DeleteTaskDefinitions"
      ],
      "Resource": "*"
    }
  ]
}
  EOF
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region

  # Default tags for all resources
  default_tags {
    tags = {
      Owner = "terraform"
    }
  }
}

locals {
  vpc_cidr_block      = "10.0.0.0/16"
  private_cidr_blocks = ["10.0.1.0/24", "10.0.2.0/24"]
  public_cidr_blocks  = ["10.0.101.0/24", "10.0.102.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr_block
}

# from outside to inside: Internet Gateway --> Route Table --> Subnet  --> Security Group

################### Internet Gateway ###################
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}


################### Route Table ###################
# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.public_cidr_blocks)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private" {
  count          = length(local.private_cidr_blocks)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}


################### Subnet ###################
# Public Subnet
resource "aws_subnet" "public" {
  count             = length(local.public_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidr_blocks[count.index]
  availability_zone = var.aws_availability_zones[count.index]
}

# Private Subnet
resource "aws_subnet" "private" {
  count             = length(local.private_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidr_blocks[count.index]
  availability_zone = var.aws_availability_zones[count.index]
}


################### Security Group ###################
# Public Security Group (ALB)
resource "aws_security_group" "alb" {
  name        = "public-sg-alb"
  description = "Allow HTTP inbound traffic and all outbound traffic"
  vpc_id      = aws_vpc.main.id
}

resource "aws_vpc_security_group_ingress_rule" "alb_ingress_https" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 443
  ip_protocol       = "tcp"
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "alb_ingress_http" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  ip_protocol       = "tcp"
  to_port           = 80
}

resource "aws_vpc_security_group_egress_rule" "alb_egress_all" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1" # all protocols, all ports
}

# ECS Security Group
resource "aws_security_group" "ecs_task" {
  name        = "ecs-task-sg"
  description = "Allow inbound traffic from ALB to ECS"
  vpc_id      = aws_vpc.main.id
}

resource "aws_vpc_security_group_ingress_rule" "ecs_task_ingress_alb" {
  security_group_id            = aws_security_group.ecs_task.id
  referenced_security_group_id = aws_security_group.alb.id
  ip_protocol                  = "-1" # all protocols, all ports
}

resource "aws_vpc_security_group_egress_rule" "ecs_task_egress" {
  security_group_id = aws_security_group.ecs_task.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1" # all protocols, all ports
}

# Private Security Group
resource "aws_security_group" "private" {
  name   = "private-sg"
  vpc_id = aws_vpc.main.id
}

resource "aws_vpc_security_group_ingress_rule" "private_ingress_from_public" {
  security_group_id            = aws_security_group.private.id
  referenced_security_group_id = aws_security_group.ecs_task.id
  description                  = "Allow ECS to access PostgresSQL"
  from_port                    = 5432
  ip_protocol                  = "tcp"
  to_port                      = 5432
}

resource "aws_vpc_security_group_egress_rule" "private_egress_all" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1" # all ports
}

output "alb_dns_name" {
  description = "ALB public dns name"
  value       = aws_lb.main.dns_name
}

output "aws_region" {
  description = "AWS region"
  value       = var.aws_region
}

output "github_actions_role_arn" {
  description = "Role ARN for GitHub Actions"
  value       = aws_iam_role.github_actions.arn
}

output "ecs_cluster_name" {
  description = "ECS clusster name"
  value       = aws_ecs_cluster.main.name
}

resource "aws_db_instance" "main" {
  allocated_storage      = 5
  identifier             = "my-postgres"
  engine                 = "postgres"
  engine_version         = "15"
  instance_class         = "db.t3.micro"
  username               = "postgres"
  password               = "postgres"
  skip_final_snapshot    = true
  storage_type           = "gp2"
  storage_encrypted      = true
  multi_az               = false
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.private.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  port                   = 5432
}

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_db_parameter_group" "main" {
  name   = "main-pg"
  family = "postgres15"

  lifecycle {
    create_before_destroy = true
  }
}

variable "application_name" {
  description = "Application Service Name"
  type        = string
  default     = "web_backend"
}

variable "application_port" {
  description = "Application Port"
  type        = number
  default     = 80
}

variable "application_health_check_path" {
  description = "Application Health Check Path"
  type        = string
  default     = "/"
}

variable "aws_region" {
  description = "AWS Region"
  type        = string
  default     = "us-west-1"

}

variable "aws_availability_zones" {
  description = "AWS Availability Zones"
  type        = list(string)
  default     = ["us-west-1a", "us-west-1c"]
}

variable "github_account" {
  description = "GitHub Account to setup IAM role for GitHub Actions"
  type        = string
  default     = "benchmark-org"
}

// File: inputs.tf
variable "enable_key_rotation" {
  type        = bool
  description = "Enable annual key rotation for KMS keys"
  default     = false
}

variable "cluster_tag" {
  type        = string
  description = "Tag to be used across all resources to namespace clusters."
  default     = "default"
}

variable "machine_roles" {
  type        = map(set(string))
  description = "Map of role name to role policy identifiers"
  default     = {}
}

// File: kms.tf
resource "aws_kms_key" "vault_key" {
  description         = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation = var.enable_key_rotation

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

data "aws_iam_policy_document" "vault_kms_unseal" {
  statement {
    sid       = "VaultKMSUnseal"
    effect    = "Allow"
    resources = [aws_kms_key.vault_key.arn]

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
  }
}

resource "aws_iam_policy" "vault_kms_unseal" {
  name        = "ResinStackKMSUnseal-${var.cluster_tag}"
  description = "Allow unsealing a vault with a KMS key"

  policy = data.aws_iam_policy_document.vault_kms_unseal.json
}

// File: outputs.tf
output "vault_key_id" {
  value       = aws_kms_key.vault_key.id
  description = "ID of the Vault KMS key"
}

output "secretmanager_names" {
  value       = { for key, value in aws_secretsmanager_secret.hashistack_minimal : key => value.name }
  description = "AWS-SM secret names for key resinstack secrets"
}

output "machine_role" {
  value       = { for name, role in aws_iam_role.resinstack_machine_role : name => role.name }
  description = "Map of name to role name for machine roles"
}

output "machine_profile" {
  value       = { for name, profile in aws_iam_instance_profile.machine_profile : name => profile.name }
  description = "Map of name to role ARN for machine profiles"
}

// File: roles.tf
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "resinstack_machine_role" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600 * 12

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_role_policy_attachment" "read_tags" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "read-tags") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.read_tags.arn
}

resource "aws_iam_role_policy_attachment" "vault_kms_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "vault-kms") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.vault_kms_unseal.arn
}

resource "aws_iam_role_policy_attachment" "nomad_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "nomad-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.nomad_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "consul_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "consul-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.consul_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "vault_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "vault-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.vault_server_key_access.arn
}

resource "aws_iam_role_policy_attachment" "client_key_access" {
  for_each = { for i, p in var.machine_roles : i => p if contains(p, "client-keys") }

  role       = aws_iam_role.resinstack_machine_role[each.key].name
  policy_arn = aws_iam_policy.client_key_access.arn
}

resource "aws_iam_instance_profile" "machine_profile" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.resinstack_machine_role[each.key].name
}

// File: secrets.tf
resource "aws_secretsmanager_secret" "hashistack_minimal" {
  for_each = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ])

  name = "resinstack-${each.value}-${var.cluster_tag}"

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }

}

data "aws_iam_policy_document" "client_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-client-consul-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "client_key_access" {
  name        = "ResinStackClientKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to clients"

  policy = data.aws_iam_policy_document.client_keys.json
}

data "aws_iam_policy_document" "nomad_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-server-consul-token"].arn,
      aws_secretsmanager_secret.hashistack_minimal["nomad-vault-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "nomad_server_key_access" {
  name        = "ResinStackNomadServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Nomad servers"

  policy = data.aws_iam_policy_document.nomad_server_keys.json
}

data "aws_iam_policy_document" "consul_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
    ]
  }
}

resource "aws_iam_policy" "consul_server_key_access" {
  name        = "ResinStackConsulServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Consul servers"

  policy = data.aws_iam_policy_document.consul_server_keys.json
}

data "aws_iam_policy_document" "vault_server_keys" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    effect  = "Allow"
    resources = [
      aws_secretsmanager_secret.hashistack_minimal["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack_minimal["vault-consul-token"].arn,
    ]
  }
}

resource "aws_iam_policy" "vault_server_key_access" {
  name        = "ResinStackVaultServerKeyAccess-${var.cluster_tag}"
  description = "Allow access to secret keys related to Vault servers"

  policy = data.aws_iam_policy_document.vault_server_keys.json
}

// File: tags.tf
data "aws_iam_policy_document" "read_tags" {
  statement {
    actions   = ["ec2:DescribeInstances"]
    effect    = "Allow"
    resources = ["*"]
  }
}

resource "aws_iam_policy" "read_tags" {
  name   = "ResinStackReadTags"
  policy = data.aws_iam_policy_document.read_tags.json
}

/*
this is a learning project for me

after learning terraform for 2 days - second attempt at building my infrastructure

##################################################### a few notes ######################################################
if you see an empty comment space ie.
# it is usually because the function/resource/variable/etc explains itself
# there is quite a few topics

########################################################################################################################
***************** there are some pretty specific explanations regarding a few of the trickier aspects ******************
#   having said that - there will be a few conventions that carry on throughout the code explanations for these will   #
#                                            declared in this block                                                    #
                                    :: topics are in order of construction ::

_one_ ::  explanation of tagging system can be found in _3_vpc_structure.tf
          tags are used to implement the following properties during terraform construction:
              vpc name
              create one private && public subnet in each available availability zone according to selected region
              name each subnet as follows: (vpc), (region+availability zone), (tag designating public or private subnet)
              dynamically assign ip address ranges to given subnets
              create one private and public route table in vpc
              name each route table following explained conventions






_!_twenty_!_ :: construction zone located in :: _private_route_tables.tf (developer setup enabling)
                                                _vpc_structures.tf
             :: developer setup enabled
************************************************************************************************************************
########################################################################################################################
# portfolio project // blog infrastructure
# @author luis_cortez elluis.codes@gmail.com
# @version 0.02
*/
terraform {
  required_providers {
    aws           = {
      source      = "hashicorp/aws"
      version     = "~> 2.70"
    }
  }
}

# provide default aws cli and region information
provider "aws" {
  region          = var.aws_region
}

data "aws_region" "us-east-2" {}

locals {
  route_out_cidr = "0.0.0.0/0"
  region_name = "us-east-2"
  region_short_name = lookup(var.region_az_short_names, local.region_name)

  # this carries the local environment variables through the tag system
  default_tags = {
    Environment = lower(var.env_prefix)
  }

  # notice that the last field in the format string is "default" the tag we
  # be using to number our infrastructure names
  vpc_name_tag        = format("%s-%s-%s", upper(var.env_prefix), local.region_short_name, "default")
  public_label        = "elluis_public"
  private_label       = "elluis_private"
  nat_gw_label        = "elluis_nat_gateway"
}

# vpc construction
resource "aws_vpc" "elluis_vpc" {
  cidr_block                    = var.elluis_vpc_cidr_block
  instance_tenancy              = var.instance_tenancy
  enable_dns_hostnames          = var.enable_dns_hostnames
  enable_dns_support            = var.enable_dns_support
  enable_classiclink            = var.enable_classiclink
}

# internet gateway construction attached to vpc
resource "aws_internet_gateway" "elluis_internet_gateway" {
  # attach to elluis_vpc
  vpc_id                        = aws_vpc.elluis_vpc.id
  # begin collecting naming and counting data for cidr and az assignments
  # by using tag created in _2_local_var_creator.tf
  tags                          = local.default_tags
}
# developer mode switch
# I will only be creating one nat-gateway instead of all nat-gateways
# this nat-gateway will be attached to us-east-2c private subnet
# creates a nat-gateway named after the resource it is attached to
resource "aws_nat_gateway" "elluis_nat_gateway" {
  for_each = var.azs

  allocation_id = lookup(aws_eip.nat_ips, each.key).id
  subnet_id = lookup(aws_subnet.public, each.key).id
  tags = merge(
  local.default_tags,
  {
    Name = format(
    "%s-%s-%s",
    upper(var.env_prefix),
    lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
    local.nat_gw_label
    )
  },
  )
}

# assigns elastic (eip) ip to every nat-gateway to keep db ip address constant
  resource "aws_eip" "nat_ips" {
    for_each = var.azs

    vpc = true
    tags = merge(
    local.default_tags,
    {
      Name = format(
      "%s-%s-%s",
      upper(var.env_prefix),
      lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
      local.nat_gw_label
      )
    }
    )
  }

  # create public subnets in each az
  resource "aws_subnet" "public" {
    #_1_ for every availability zone
    for_each = var.azs
    #_2_ create a new subnet adding 32 to the value
    cidr_block = cidrsubnet(var.elluis_vpc_cidr_block, 8, each.value + 32)
    # assign availability zone        #us-east-2          # a , b, c :: as mapped in our variables
    # following values are assigned to the public az's
    availability_zone = format("%s%s", local.region_name, each.key)
    # us_east_2*
    map_public_ip_on_launch = false
    vpc_id = aws_vpc.elluis_vpc.id

    # name resource according to project name, az, and region
    # merging the tag allows us to carry this information to the next resource
    tags = merge(
    local.default_tags,
    {
      # tags our subnets with the appropriate 'Name'
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2a-elluis_public
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2b-elluis_public
      # ELLUIS_CODES_LIMITED_NETWORK-us_east_2c-elluis_public

      # creates our format template - be careful pay attention to commas!
      Name = format("%s-%s-%s", upper(var.env_prefix),
      lookup(var.region_az_short_names,
      # this puts together our us-east2 with a/b/c
      format("%s%s", local.region_name, each.key)),
      # finally attaching our elluis_public tag at the end
      local.public_label)
    }
    )
  }

# create public subnets in each az
resource "aws_subnet" "private" {
  for_each = var.azs
  # ensure that the final value entered in our cidrsubnet does not match our public subnets
  cidr_block                    = cidrsubnet(var.elluis_vpc_cidr_block, 8, each.value)
  availability_zone             = format("%s%s", local.region_name, each.key)
  map_public_ip_on_launch       = false
  vpc_id                        = aws_vpc.elluis_vpc.id

  tags                          = merge(
  local.default_tags,
  {
                                # following values are assigned to the public az's
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2a-elluis_private
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2b-elluis_private
                                # ELLUIS_CODES_LIMITED_NETWORK-us_east_2c-elluis_private
    Name                        = format("%s-%s-%s", upper(var.env_prefix),   # ELLUIS_CODES_LIMITED_NETWORK
                                lookup(var.region_az_short_names,             # us_east_2
                                format("%s%s", local.region_name, each.key)), # a - b -c
                                local.private_label)                          # elluis_private
  }
  )
}

# create public route table
resource "aws_route_table" "public" {
  vpc_id                    = aws_vpc.elluis_vpc.id
  tags                      = merge(
  local.default_tags,
  {
                # it is important to note that this name will not dynamically - we are only spinning up one igw
                # since we will be attaching the internet gateway will be attached to all public subnets located
                # in the region
    Name                    =  format("%s-%s-%s",
                            upper(var.env_prefix),
                            local.region_short_name,
                            local.public_label
    )
  }
  )
}
# create aws public out route from all ports
resource "aws_route" "public_route_out_all" {
  # connect to public route table
  route_table_id = aws_route_table.public.id
  # create out all 0.0.0.0/0 ( passed from _2_ )
  destination_cidr_block    = local.route_out_cidr
  # connect to internet gateway ( created in _3_ )
  gateway_id                = aws_internet_gateway.elluis_internet_gateway.id
}

# create aws public route table association
resource "aws_route_table_association" "public" {
  # for availability availability zone
  for_each                  = var.azs
  # the following two lines associate the subnet with the route table and vice versa
  subnet_id                 = lookup(aws_subnet.public, each.key).id
  route_table_id            = aws_route_table.public.id
}

# keeping both the public and private route tables separate is intentional
# keep them separate ! for heavens sake !


# 1_ create public route table
resource "aws_route_table" "private" {
  for_each = var.azs
  vpc_id = aws_vpc.elluis_vpc.id
  tags = merge(
  local.default_tags,
  {
    Name = format(
    "%s-%s-%s",
    upper(var.env_prefix),
    lookup(var.region_az_short_names, format("%s%s", local.region_name, each.key)),
    local.private_label
    )
  }
  )
}
# 2_ creates route for private subnets
resource "aws_route" "private_subnet_route" {
  for_each = var.azs

  destination_cidr_block = local.route_out_cidr
  route_table_id = lookup(aws_route_table.private, each.key).id
  # connecting the nat gateway to the subnet
  # at the moment I am commenting out this call - due to the fact that I do not want to pay nat gateway prices for 3
  # running nat gateways at this stage of development
  # just in-case of uncomment !!!... will still stop you from trying to connect all the nats!
//!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
  nat_gateway_id = lookup(aws_nat_gateway.elluis_nat_gateway, each.key).id

  lifecycle {
    ignore_changes = [
      route_table_id,
      nat_gateway_id]
  }
}


# create aws public route table association
resource "aws_route_table_association" "private" {
  # for availability availability zone
  for_each                = var.azs
  # the following two lines associate the subnet with the route table and vice versa
  subnet_id               = lookup(aws_subnet.public, each.key).id
  route_table_id          = aws_route_table.public.id
}

# define main cidr_block
variable "elluis_vpc_cidr_block" {
  description   = "main vpc cidr block"
  type          = string
  default       = "64.0.0.0/16"
}
# warning this can greatly influence your weight loss diet - set to "default"
# in our use case is going to be false
variable "instance_tenancy" {
  description   = "!!!!!!!! this can cost you mucho dinero !!!!!!!!!!!!"
