}

output "aggregator_name" {
  description = "The name of the AWS Config aggregator"
  value       = aws_config_configuration_aggregator.this.name
}

// File: variables.tf
variable "tags" {
  description = "Tags to apply to module resources"
  type        = map(string)
  default = {
    Terraform = true
  }
}

