// File: db_disaster_recovery.tf
resource "aws_iam_user" "db_disaster_recovery" {
  count = var.create_db_disaster_user ? 1 : 0

  name = "mattermost-cloud-${var.environment}-db-disaster-recovery"
  path = "/"
}

resource "aws_iam_policy" "db_disaster_recovery" {
  count = var.create_db_disaster_user ? 1 : 0

  name        = "mattermost-cloud-${var.environment}-db-disaster-recovery-policy"
  description = "A policy attached to DB Disaster Recovery IAM user"
  path        = "/"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "kms:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ],
        Effect   = "Allow",
        Resource = local.secret_manager_rds
      },
    ]
  })
}

resource "aws_iam_user_policy_attachment" "db_disaster_recovery" {
  count = var.create_db_disaster_user ? 1 : 0

  user       = aws_iam_user.db_disaster_recovery[0].name
  policy_arn = aws_iam_policy.db_disaster_recovery[0].arn
}

// File: exports.tf
resource "aws_iam_user" "exports" {
  count = var.create_exports_user ? 1 : 0

  name = "mattermost-cloud-${var.environment}-exports"
  path = "/"
}

resource "aws_iam_policy" "exports" {
  count = var.create_exports_user ? 1 : 0

  name        = "mattermost-cloud-${var.environment}-exports-policy"
  description = "A policy attached to exports IAM user"
  path        = "/"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetBucketTagging"
        ]
        Effect   = "Allow"
        Resource = var.exports_bucket_arn
      },
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:DeleteObject",
          "s3:GetObjectVersionAcl"
        ],
        Effect   = "Allow",
        Resource = "${var.exports_bucket_arn}/*"
      },
    ]
  })
}

resource "aws_iam_user_policy_attachment" "exports" {
  count = var.create_exports_user ? 1 : 0

  user       = aws_iam_user.exports[0].name
  policy_arn = aws_iam_policy.exports[0].arn
}

// File: local.tf
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {

  secret_manager_rds = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"

}

// File: packer.tf
resource "aws_iam_user" "packer" {
  count = var.create_packer_user ? 1 : 0

  name = "mattermost-cloud-${var.environment}-packer"
  path = "/"
}

resource "aws_iam_policy" "packer" {
  count = var.create_packer_user ? 1 : 0

  name        = "mattermost-cloud-${var.environment}-packer-policy"
  description = "A policy attached to packer IAM user"
  path        = "/"
  policy      = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "LambdaPolicyAllResources",
            "Effect": "Allow",
            "Action": [
                "lambda:ListCodeSigningConfigs",
                "lambda:ListEventSourceMappings",
                "lambda:ListVersionsByFunction",
                "lambda:ListFunctionsByCodeSigningConfig",
                "lambda:ListTags",
                "lambda:GetPolicy"
            ],
            "Resource": "*"
        },
        {
            "Sid": "LambdaPolicySpecificResource",
            "Effect": "Allow",
            "Action": [
                "lambda:GetFunction",
                "lambda:GetFunctionConfiguration",
                "lambda:GetFunctionCodeSigningConfig",
                "lambda:GetFunctionEventInvokeConfig",
                "lambda:GetCodeSigningConfig"
            ],
            "Resource": [
                "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
            ]
        },
        {
            "Sid": "S3Policy",
            "Effect": "Allow",
            "Action": [
                "s3:GetObjectAttributes",
                "s3:ListBucket",
                "s3:GetObjectLegalHold",
                "s3:GetObjectVersionAttributes",
                "s3:GetObjectVersionTorrent",
                "s3:GetObject",
                "s3:GetObjectTorrent",
                "s3:GetObjectVersionAcl",
                "s3:GetObjectTagging",
                "s3:PutObject"
            ],
            "Resource": [
                "arn:aws:s3:::terraform-cloud-monitoring-state-bucket-${var.environment}/*",
                "arn:aws:s3:::terraform-cloud-monitoring-state-bucket-${var.environment}"
            ]
        },
        {
            "Sid": "AllOtherServicesPolicy",
            "Effect": "Allow",
            "Action": [
              "autoscaling:DescribeAutoScalingGroups",
              "autoscaling:DescribeLifecycleHooks",
              "autoscaling:DescribeInstanceRefreshes",
              "autoscaling:UpdateAutoScalingGroup",
              "autoscaling:PutLifecycleHook",
              "autoscaling:StartInstanceRefresh",
              "ec2:AttachVolume",
              "ec2:AuthorizeSecurityGroupIngress",
              "ec2:CopyImage",
              "ec2:CreateImage",
              "ec2:CreateKeypair",
              "ec2:CreateLaunchTemplateVersion",
              "ec2:CreateSecurityGroup",
              "ec2:CreateSnapshot",
              "ec2:CreateTags",
              "ec2:CreateVolume",
              "ec2:DeleteKeyPair",
              "ec2:DeleteSecurityGroup",
              "ec2:DeleteSnapshot",
              "ec2:DeleteVolume",
              "ec2:DeregisterImage",
              "ec2:DescribeImageAttribute",
              "ec2:DescribeImages",
              "ec2:DescribeInstanceStatus",
              "ec2:DescribeInstances",
              "ec2:DescribeKeyPairs",
              "ec2:DescribeLaunchTemplateVersions",
              "ec2:DescribeLaunchTemplates",
              "ec2:DescribeNetworkInterfaces",
              "ec2:DescribeRegions",
              "ec2:DescribeSecurityGroups",
              "ec2:DescribeSnapshots",
              "ec2:DescribeSubnets",
              "ec2:DescribeTags",
              "ec2:DescribeVolumes",
              "ec2:DescribeVpcAttribute",
              "ec2:DescribeVpcs",
              "ec2:DetachVolume",
              "ec2:GetPasswordData",
              "ec2:ModifyImageAttribute",
              "ec2:ModifyInstanceAttribute",
              "ec2:ModifyLaunchTemplate",
              "ec2:ModifySnapshotAttribute",
              "ec2:RegisterImage",
              "ec2:RunInstances",
              "ec2:StopInstances",
              "ec2:TerminateInstances",
              "events:DescribeRule",
              "events:ListTagsForResource",
              "events:ListTargetsByRule",
              "iam:GetInstanceProfile",
              "iam:GetRole",
              "iam:GetRolePolicy",
              "iam:ListAttachedRolePolicies",
              "iam:ListRolePolicies",
              "ssm:GetParameter",
              "ssm:GetParameters"
            ],
            "Resource": "*"
        },
        {
          "Effect": "Allow",
          "Action": "iam:PassRole",
          "Resource": [
            "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.environment}-bind-server-role"
          ]
        }
    ]
}
EOF
}

resource "aws_iam_user_policy_attachment" "packer" {
  count = var.create_packer_user ? 1 : 0

  user       = aws_iam_user.packer[0].name
  policy_arn = aws_iam_policy.packer[0].arn
}

// File: providers.tf
terraform {
  required_version = ">= 1.6.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.41.0"
    }
  }
}

// File: variables.tf
variable "environment" {
  description = "The environment"
  type        = string
  default     = "dev"
}

variable "create_packer_user" {
  description = "Whether to create the packer user"
  type        = bool
  default     = false
}

variable "create_db_disaster_user" {
  description = "Whether to create the DB disaster recovery user"
  type        = bool
  default     = false
}

variable "create_exports_user" {
  description = "Whether to create the exports user"
  type        = bool
  default     = false
}

variable "exports_bucket_arn" {
  description = "The bucket that will be used for data exports. Needed only when create_exports_users is set to true"
  type        = string
  default     = ""
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {

}

locals {
  health_omics_arn   = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.health_omics_role_name}"
  additional_buckets = var.additional_buckets != null ? var.additional_buckets : []
  buckets            = concat([aws_s3_bucket.output_bucket.arn, "${aws_s3_bucket.output_bucket.arn}/*"], local.additional_buckets)
  ecr_resources = concat(["arn:aws:ecr:${var.region}:${data.aws_caller_identity.current.account_id}:*"], [for account in var.external_ecr_accounts: "arn:aws:ecr:${var.region}:${account}:*"]) 
}


data "aws_iam_policy_document" "health_omics_user_policy" {
  statement {
    sid = "AllowPassRole"
    actions = [
      "iam:PassRole"
    ]

    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["omics.amazonaws.com"]
    }
  }

  statement {
    sid = "AllowOmicsActions"
    actions = [
      "omics:*"
    ]
    resources = ["*"]
  }

  statement {
    sid = "AllowS3ReadOnlyAccess"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = local.buckets
  }

  statement {
    sid = "AllowReadLogs"
    actions = [
      "logs:DescribeLogStreams",
      "logs:GetLogEvents",
    ]

    resources = [
      "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*"
    ]
  }
}

data "aws_iam_policy_document" "health_omics_trust_policy" {
  statement {
    sid = "AllowHealthOmicsService"
    actions = [
      "sts:AssumeRole"
    ]

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
  }
}


data "aws_iam_policy_document" "health_omics_service_policy" {
  statement {
    sid = "AllowS3ReadOnlyAccess"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = local.buckets
  }
  statement {
    sid = "UploadFilesToS3"
    actions = [
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  statement {
    sid = "AllowECRActions"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
    resources = local.ecr_resources

  }

  statement {
    sid = "AllowLogs"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:CreateLogGroup",
      "logs:DescribeLogStreams",
    ]

    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*"
    ]
  }
}

data "aws_iam_policy_document" "health_omics_ecr_policy" {
  statement {
    sid       = "OmicsWorkflow Access"
    effect    = "Allow"

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
  }
}

provider "aws" {
  region = var.region
}

resource "aws_s3_bucket" "output_bucket" {
  bucket = var.output_bucket_name
  tags = {
    created_by = "terraform"
  }
}

resource "aws_s3_bucket_public_access_block" "output_bucket" {
  bucket                  = aws_s3_bucket.output_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "output_bucket" {
  description         = "CMK for the HealthOmics output bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.output_bucket.arn
    }
  }
}

resource "aws_iam_user" "workbench_service_account" {
  name = var.workbench_service_account_name
  tags = {
    created_by = "terraform"
  }
}

resource "aws_iam_user_policy_attachment" "workbench_service_account_policy" {
  user       = aws_iam_user.workbench_service_account.name
  policy_arn = aws_iam_policy.health_omics_user_policy.arn
}

resource "aws_iam_access_key" "workbench_service_account_secret_key" {
  user = aws_iam_user.workbench_service_account.name
}

resource "aws_iam_policy" "health_omics_user_policy" {
  name        = var.health_omics_user_policy_name
  description = "Policy for health omics service"
  policy      = data.aws_iam_policy_document.health_omics_user_policy.json
  tags = {
    created_by = "terraform"
  }

}

resource "aws_iam_policy" "health_omics_service_policy" {
  name        = var.health_omics_service_policy_name
  description = "Policy for health omics service"
  policy      = data.aws_iam_policy_document.health_omics_service_policy.json
  tags = {
    created_by = "terraform"
  }

}

resource "aws_iam_role" "health_omics_role" {
  name               = var.health_omics_role_name
  assume_role_policy = data.aws_iam_policy_document.health_omics_trust_policy.json
  managed_policy_arns = [
    aws_iam_policy.health_omics_service_policy.arn
  ]
  tags = {
    created_by = "terraform"
  }

}

resource "aws_ecr_repository" "ecr_repositories" {
  for_each = var.ecr_repositories
  name     = each.value
}

resource "aws_ecr_repository_policy" "docker_repository_policy" {
  for_each = var.ecr_repositories
  repository = aws_ecr_repository.ecr_repositories[each.key].name
  policy = data.aws_iam_policy_document.health_omics_ecr_policy.json
}

output "access_key_id" {
  description = "Access key ID for Workbench to use"
  value       = aws_iam_access_key.workbench_service_account_secret_key.id
}

output "secret_access_key" {
  description = "Secret access key for Workbench to use"
  sensitive   = true
  value       = aws_iam_access_key.workbench_service_account_secret_key.secret
}

output "role_arn" {
    description = "ARN of the role used by HealthOmics"
    value       = aws_iam_role.health_omics_role.arn

}

output "output_bucket" {
    description = "The name of the output bucket"
    value       = aws_s3_bucket.output_bucket.bucket
}

output "docker_repositories" {
    description = "The name of the docker repositories"
    value       = [for repo in aws_ecr_repository.ecr_repositories: repo.repository_url]

}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.35"
    }
  }
  required_version = "~> 1.3"
}

variable "output_bucket_name" {
  description = "The name of the output bucket"
  type        = string
  nullable    = false
  default     = "tf-benchmark-omics-output-bucket"
}

variable "workbench_service_account_name" {
  description = "The name of the workbench service account"
  type        = string
  default     = "workbench-health-omics"
  nullable    = false

}

variable "force_destroy" {
  description = "Applying the module with this value true allows you to run terraform destroy"
  type        = bool
  default     = false
}

variable "health_omics_role_name" {
  description = "The name of the health omics role"
  type        = string
  default     = "HealthOmicsRole"
  nullable    = false
}

variable "region" {
  description = "The region in which the resources will be created"
  type        = string
  default     = "us-east-1"
  nullable    = false
  validation {
    condition     = contains(["us-east-1", "us-west-2", "ap-southeast-1", "eu-central-1", "eu-west-1", "eu-west-2", "il-central-1"], var.region)
    error_message = "Invalid region"
  }
}
variable "additional_buckets" {
  description = "Additional buckets to add to the policy"
  type        = list(string)
  default     = []
  nullable    = true

}
variable "health_omics_service_policy_name" {
  description = "The name of the health omics service policy"
  type        = string
  default     = "HealthOmicsServicePolicy"
  nullable    = false

}
variable "health_omics_user_policy_name" {
  description = "The name of the health omics user policy"
  type        = string
  default     = "HealthOmicsUserPolicy"
  nullable    = false

}

variable "ecr_repositories" {
  description = "The ecr of docker images to create"
  type        = set(string)
  default     = []
  nullable    = true
}

variable "external_ecr_accounts" {
  description = "The list of external ECR accounts to allow access to the repositories"
  type        = list(string)
  default     = []
  nullable    = true

}

// File: main.tf
resource "aws_ecs_cluster" "dit_paas_cluster" {
  name               = "dit-paas-${var.cluster_name}-cluster"
  tags = {
    Name    = "dit-paas-${var.cluster_name}-cluster"
    Cluster = var.cluster_name
  }
}

// File: variables.tf
variable "aws_region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "The name of the cluster"
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type        = string
  description = "CIDR network range for the VPC"
  default     = "10.0"
}

variable "default_tags" {
  type        = map(string)
  default     = {}
  description = "Standard tags to add to deployed resources"
}

// File: vpc.tf
locals {
  vpc_tags = {
  }
}

# VPC

resource "aws_vpc" "dit_paas_cluster" {
  cidr_block = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  tags = {"Name" = "dit-paas-${var.cluster_name}-cluster-vpc"} 
}


# Private Subnets

resource "aws_subnet" "dit_paas_cluster_private_a" {
  vpc_id = aws_vpc.dit_paas_cluster.id
  cidr_block = "${var.vpc_cidr_network_octets}.0.0/22"
  availability_zone = "${var.aws_region}a"
  tags = merge(
    {
      "Name" = "dit-paas-${var.cluster_name}-private-a",
      "Subnet" = "dit-paas-${var.cluster_name}-private",
      "Subnet_class" = "private",
      "Availability_zone" = "${var.aws_region}a"
      "Cluster" = "dit-paas-${var.cluster_name}"
      "Cluster_name" = var.cluster_name
    },
    var.default_tags,
    local.vpc_tags
  )
}

resource "aws_subnet" "dit_paas_cluster_private_b" {
  vpc_id = aws_vpc.dit_paas_cluster.id
  cidr_block = "${var.vpc_cidr_network_octets}.4.0/22"
  availability_zone = "${var.aws_region}b"
  tags = merge(
    {
      "Name" = "dit-paas-${var.cluster_name}-private-b",
      "Subnet" = "dit-paas-${var.cluster_name}-private",
      "Subnet_class" = "private",
      "Availability_zone" = "${var.aws_region}b"
      "Cluster" = "dit-paas-${var.cluster_name}"
      "Cluster_name" = var.cluster_name
    },
    var.default_tags,
    local.vpc_tags
  )
}

resource "aws_subnet" "dit_paas_cluster_private_c" {
  vpc_id = aws_vpc.dit_paas_cluster.id
  cidr_block = "${var.vpc_cidr_network_octets}.8.0/22"
  availability_zone = "${var.aws_region}c"
  tags = merge(
    {
      "Name" = "dit-paas-${var.cluster_name}-private-c",
      "Subnet" = "dit-paas-${var.cluster_name}-private",
      "Subnet_class" = "private",
      "Availability_zone" = "${var.aws_region}c"
      "Cluster" = "dit-paas-${var.cluster_name}"
      "Cluster_name" = var.cluster_name
    },
    var.default_tags,
    local.vpc_tags
  )
}

# Private Routing

resource "aws_route" "private_route_a" {
  route_table_id         = aws_route_table.private_a.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.public_a.id
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.dit_paas_cluster.id
  tags = merge(
    {"Name" = "${var.cluster_name}-private-a"},
    var.default_tags,
    local.vpc_tags
  )
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.dit_paas_cluster_private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route" "private_route_b" {
  route_table_id         = aws_route_table.private_b.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.public_b.id
}

resource "aws_route_table" "private_b" {
