resource "aws_nat_gateway" "public_b" {
  allocation_id = aws_eip.public_b.id
  subnet_id     = aws_subnet.dit_paas_cluster_public_b.id
  tags = merge(
    {"Name" = "${var.cluster_name}-nat-gateway-b"},
