// File: variables.tf
variable "vpc_cidr_block" {
  type        = string
  description = "Cidr block to use for the VPC."
  default     = "172.16.0.0/16"
}

variable "region" {
  type        = string
  description = "AWS Region to deploy in"
  default     = "us-east-1"
}

variable "availability_zones" {
  type        = list(string)
  description = "Availability Zones for the VPC"
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "vpc_name" {
  type        = string
  description = "Name for the VPC"
  default     = "benchmark-vpc"
}

// File: locals.tf
locals {
  gateway_services = ["dynamodb", "s3"]

  # This essentially implements the 'setsubtract' function available in Terraform v.0.12.21 and later
  interface_endpoints_to_create = toset([
    for service in var.aws_vpce_services :
    service if !contains(local.gateway_services, service)
  ])

  gateway_endpoints_to_create = setintersection(var.aws_vpce_services, local.gateway_services)

  # Creates an exhaustive list of tuples of the form [<security_group_id>, <port>]
  # where each <security_group_id> is one of the externally provided Security Group IDs
  # and <port> is one of the custom vpce services ports
  sg_id_to_port_mapping = tolist(setproduct(var.interface_vpce_source_security_group_ids, var.custom_vpce_services[*].port))

  service_names_with_dns      = setunion(local.interface_endpoints_to_create, var.custom_vpce_services[*].key)
  endpoint_resources_with_dns = merge(aws_vpc_endpoint.custom_vpc_endpoints, aws_vpc_endpoint.aws_interface_vpc_endpoints)


}

// File: outputs.tf
output "vpc" {
  value       = aws_vpc.vpc
  description = "VPC Details"
}

output "interface_vpce_sg_id" {
  value       = aws_security_group.vpc_endpoints.id
  description = "VPCE SG endpoint ID"
}

output "custom_vpce_sg_id" {
  value       = aws_security_group.custom_vpc_endpoints.id
  description = "Custom VPCE SG endpoint ID"
}

output "custom_vpce_dns_names" {
  value = {
    for key in var.custom_vpce_services[*].key :
    key => aws_vpc_endpoint.custom_vpc_endpoints[key].dns_entry[*].dns_name
  }
  description = "Custom VPCE DNS Names"
}

output "prefix_list_ids" {
  value = {
    for service in setintersection(local.gateway_services, var.aws_vpce_services) :
    service => aws_vpc_endpoint.aws_gateway_vpc_endpoints[service].prefix_list_id
  }
  description = "Prefix List ID's"
}

output "ecr_dkr_domain_name" {
  value       = "dkr.ecr.${var.region}.amazonaws.com"
  description = "ECR dkr domain name"
}
locals {
  s3_no_proxy                   = contains(var.aws_vpce_services, "s3") ? [".s3.${var.region}.amazonaws.com"] : []
  s3_path_no_proxy              = contains(var.aws_vpce_services, "s3") ? ["*.s3.${var.region}.amazonaws.com"] : []
  s3_path_non_regional_no_proxy = contains(var.aws_vpce_services, "s3") ? ["*.s3.amazonaws.com"] : []
  ecr_api_no_proxy              = contains(var.aws_vpce_services, "ecr.api") ? ["api.ecr.${var.region}.amazonaws.com"] : []
  ecr_dkr_no_proxy              = contains(var.aws_vpce_services, "ecr.dkr") ? [".dkr.ecr.${var.region}.amazonaws.com"] : []
  emr_no_proxy                  = contains(var.aws_vpce_services, "elasticmapreduce") ? ["${var.region}.elasticmapreduce.amazonaws.com"] : []
  sqs_no_proxy                  = contains(var.aws_vpce_services, "sqs") ? ["${var.region}.queue.amazonaws.com"] : []
}

output "no_proxy_list" {
  value       = concat(["169.254.169.254", "127.0.0.1", "localhost"], formatlist("%s.%s.amazonaws.com", var.aws_vpce_services, var.region), local.s3_no_proxy, local.ecr_api_no_proxy, local.ecr_dkr_no_proxy, local.emr_no_proxy, local.sqs_no_proxy, local.s3_path_no_proxy, local.s3_path_non_regional_no_proxy)
  description = "No_proxy List"
}


# Note that all of the outputs below are conditional, based on their respective
# endpoints having been requested. Naively, you'd think the following would work:
# value = "${var.s3_endpoint ? aws_vpc_endpoint.s3.0.prefix_list_id : ""}"
# but you end up running into https://github.com/hashicorp/hil/issues/50 so we
# use the workaround from that issue to achieve the same goal

# To understand how this works
# 1. list() converts the boolean flag into a list, so that...
# 2. concat() joins the 2 lists (the potentially empty list of the resource in
#    question, and the list from step 1)
# 3. element() returns the first element of that newly combined list; it'll
#    either be the resource's attribute, or an empty string


output "ssm_iam_role_name" {
  value       = concat(aws_iam_role.ssm.*.name, tolist([""]))[0]
  description = "SSM IAM Role Name"
}

output "ssm_instance_profile_name" {
  value       = concat(aws_iam_instance_profile.ssm.*.name, tolist([""]))[0]
  description = "SSM IAM instance profile Name"
}

// File: ssm_role.tf
resource "aws_iam_role" "ssm" {
  count              = contains(var.aws_vpce_services, "ssm") ? 1 : 0
  name               = "ssm_${var.vpc_name}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.common_tags
}

resource "aws_iam_role_policy_attachment" "ec2_for_ssm_attachment" {
  count      = contains(var.aws_vpce_services, "ssm") ? 1 : 0
  role       = aws_iam_role.ssm[count.index].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_instance_profile" "ssm" {
  count = contains(var.aws_vpce_services, "ssm") ? 1 : 0
  name  = "ssm_${var.vpc_name}"
  role  = aws_iam_role.ssm[count.index].name
}

// File: variables.tf
variable "vpc_name" {
  type        = string
  description = "The name of the VPC."
  default     = "benchmark-vpc"
}

variable "vpc_cidr_block" {
  type        = string
  description = "The CIDR block of the VPC."
  default     = "10.0.0.0/16"
}

variable "vpc_instance_tenancy" {
  type        = string
  default     = "default"
  description = "Tenancy of instances spun up within the VPC (`default`, `dedicated`).)"
}

variable "region" {
  type        = string
  description = "The region in which to deploy the VPC."
  default     = "us-east-1"
}

variable "interface_vpce_source_security_group_ids" {
  type        = list(string)
  description = "A list of security group IDs that will be allowed to reach the Interface VPCs."
  default     = []
}

variable "interface_vpce_subnet_ids" {
  type        = list(string)
  description = "A list of subnet IDs that all Interface VPC endpoints will be attached to"
  default     = []
}

variable "vpc_enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "A boolean flag to enable/disable DNS hostnames in the VPC. Defaults to true."
}

variable "vpc_flow_log_retention_days" {
  type        = string
  default     = 180
  description = "The number of days to retain VPC flow logs in CloudWatch for. Defaults to 180."
}

variable "vpc_flow_log_traffic_type" {
  type        = string
  default     = "ALL"
  description = "The type of traffic ('ACCEPT', 'REJECT', or 'ALL') to log. Defaults to 'ALL'."
}

variable "aws_vpce_services" {
  type        = set(string)
  description = "Set of AWS Service names to create VPC Endpoints for. By default only the 'logs' service endpoint is provided"
  default     = ["logs"]
}

variable "custom_vpce_services" {
  type = set(object({
    key          = string
    service_name = string
    port         = number
  }))

  description = "Set of objects mapping service names to ports for custom VPC Endpoint services. The key is used to provide a friendly name when accessing outputs."
  default     = []
}

variable "gateway_vpce_route_table_ids" {
  type        = list(string)
  default     = []
  description = "A list of one or more route table IDs for Gateway VPC Endpoint rules to be added to."
}

variable "common_tags" {
  type        = map(string)
  description = "Common Tags"
  default     = {}
}

variable "hcs_tags" {
  type        = map(string)
  description = "Common Tags"
  default     = {}
}

// File: vpc.tf
resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr_block
  instance_tenancy     = var.vpc_instance_tenancy
  enable_dns_hostnames = var.vpc_enable_dns_hostnames

  tags = merge(
    var.common_tags,
    var.hcs_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.vpc.id
}

resource "aws_flow_log" "flow_log" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn
  log_destination = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type    = var.vpc_flow_log_traffic_type
  vpc_id          = aws_vpc.vpc.id
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = var.vpc_flow_log_retention_days

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}

data "aws_iam_policy_document" "vpc_flow_logs_assume_role" {
  statement {
    sid    = "VpcFlowLogsAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "vpc_flow_logs" {
  statement {
    sid       = "VpcFlowLogs${replace(var.vpc_name, "-", "")}"
    effect    = "Allow"
    resources = [format("%s:*", aws_cloudwatch_log_group.vpc_flow_logs.arn)]

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
    ]
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name               = "vpc_flow_logs_${var.vpc_name}"
  assume_role_policy = data.aws_iam_policy_document.vpc_flow_logs_assume_role.json

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name   = "vpc_flow_logs_${var.vpc_name}"
  role   = aws_iam_role.vpc_flow_logs.id
  policy = data.aws_iam_policy_document.vpc_flow_logs.json
}

// File: vpc_endpoints.tf
resource "aws_vpc_endpoint" "aws_interface_vpc_endpoints" {
  for_each = local.interface_endpoints_to_create

  service_name        = "com.amazonaws.${var.region}.${each.value}"
  vpc_id              = aws_vpc.vpc.id
  vpc_endpoint_type   = "Interface"
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = var.interface_vpce_subnet_ids
  private_dns_enabled = true

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_vpc_endpoint" "aws_gateway_vpc_endpoints" {
  for_each = local.gateway_endpoints_to_create

  service_name      = "com.amazonaws.${var.region}.${each.value}"
  vpc_id            = aws_vpc.vpc.id
  vpc_endpoint_type = "Gateway"
  route_table_ids   = var.gateway_vpce_route_table_ids

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_vpc_endpoint" "custom_vpc_endpoints" {
  for_each = {
    for service in var.custom_vpce_services :
    service["key"] => service["service_name"]
  }

  service_name        = each.value
  vpc_id              = aws_vpc.vpc.id
  vpc_endpoint_type   = "Interface"
  security_group_ids  = [aws_security_group.custom_vpc_endpoints.id]
  subnet_ids          = var.interface_vpce_subnet_ids
  private_dns_enabled = false

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}


resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Allows instances to reach Interface VPC endpoints"
  vpc_id      = aws_vpc.vpc.id

  tags = merge(
    var.common_tags,
    { Name = var.vpc_name }
  )
}

resource "aws_security_group_rule" "vpce_source_https_ingress" {
  count                    = length(var.interface_vpce_source_security_group_ids)
  description              = "Accept VPCE traffic"
  type                     = "ingress"
  protocol                 = "tcp"
  from_port                = 443
  to_port                  = 443
  source_security_group_id = var.interface_vpce_source_security_group_ids[count.index]
  security_group_id        = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "source_vpce_https_egress" {
  count                    = length(var.interface_vpce_source_security_group_ids)
  description              = "Allow outbound requests to VPC endpoints"
  type                     = "egress"
  protocol                 = "tcp"
  from_port                = 443
  to_port                  = 443
  source_security_group_id = aws_security_group.vpc_endpoints.id
  security_group_id        = var.interface_vpce_source_security_group_ids[count.index]
}

resource "aws_security_group" "custom_vpc_endpoints" {
  description = "Allows instances to reach Custom VPC endpoints"
  vpc_id      = aws_vpc.vpc.id
  tags        = var.common_tags
}

resource "aws_security_group_rule" "custom_vpce_source_ingress" {
  count = length(local.sg_id_to_port_mapping)

  description              = "Allow instance traffic to Custom VPCE"
  type                     = "ingress"
  protocol                 = "tcp"
  from_port                = local.sg_id_to_port_mapping[count.index][1]
  to_port                  = local.sg_id_to_port_mapping[count.index][1]
  source_security_group_id = local.sg_id_to_port_mapping[count.index][0]
  security_group_id        = aws_security_group.custom_vpc_endpoints.id
}

resource "aws_security_group_rule" "source_custom_vpce_egress" {
  count = length(local.sg_id_to_port_mapping)

  description              = "Accept Custom VPCE traffic"
  type                     = "egress"
  protocol                 = "tcp"
  from_port                = local.sg_id_to_port_mapping[count.index][1]
  to_port                  = local.sg_id_to_port_mapping[count.index][1]
  source_security_group_id = aws_security_group.custom_vpc_endpoints.id
  security_group_id        = local.sg_id_to_port_mapping[count.index][0]
}

// File: main.tf
# Encryption & Data Protection - KMS keys per layer, account-level defaults

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

# EBS encryption by default
resource "aws_ebs_encryption_by_default" "enabled" {
  enabled = true
}

# KMS Key - Compute Layer (EBS, Auto Scaling)
resource "aws_kms_key" "compute" {
  description             = "KMS key for ${var.project_name} compute layer - EBS and Auto Scaling"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEC2ToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowAutoScalingToUseTheKey"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAutoScalingToCreateGrants"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"
        }
        Action   = "kms:CreateGrant"
        Resource = "*"
        Condition = {
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
        }
      }
    ]
  })

  tags = {
    Name     = "${var.project_name}-kms-compute"
    Purpose  = "Encryption for EBS volumes and Auto Scaling"
    Security = "encryption-at-rest"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

# Account-level EBS default key - external ARN overrides if provided
resource "aws_ebs_default_kms_key" "ebs" {
  key_arn = var.ebs_default_kms_key_arn != "" ? var.ebs_default_kms_key_arn : aws_kms_key.compute.arn
}

# KMS Key - Observability Layer (CloudTrail, CloudWatch Logs, SNS)
resource "aws_kms_key" "observability" {
  description             = "KMS key for ${var.project_name} observability layer - CloudTrail, CloudWatch, SNS"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${local.region}:${local.account_id}:*"
          }
        }
      },
      {
        Sid    = "AllowCloudTrailToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:aws:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchAlarmsToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowSNSToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowSQSToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowEventBridgeToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name     = "${var.project_name}-kms-observability"
    Purpose  = "Encryption for CloudTrail CloudWatch Logs and SNS"
    Security = "encryption-at-rest"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

# KMS Key - Storage Layer (S3 Log Buckets)
resource "aws_kms_key" "storage" {
  description             = "KMS key for ${var.project_name} storage layer - S3 log buckets"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowConfigToDeliverEncryptedSnapshots"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowCloudTrailToEncryptLogs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:aws:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      }
    ]
  })

  tags = {
    Name     = "${var.project_name}-kms-storage"
    Purpose  = "Encryption for S3 audit log buckets and Config snapshots"
    Security = "encryption-at-rest"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# Block public AMI sharing
resource "aws_ec2_image_block_public_access" "enabled" {
  state = "block-new-sharing"
}

# Block public EBS snapshot sharing
resource "aws_ebs_snapshot_block_public_access" "enabled" {
  state = "block-all-sharing"
}

# IMDSv2 by default - prevents SSRF-based credential theft from metadata endpoint
resource "aws_ec2_instance_metadata_defaults" "imdsv2" {
  count = var.enable_imdsv2_default ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.imdsv2_hop_limit
  http_endpoint               = "enabled"
  instance_metadata_tags      = "disabled"
}

# Disable EC2 Serial Console - eliminates out-of-band access path
resource "aws_ec2_serial_console_access" "disabled" {
  count = var.disable_ec2_serial_console ? 1 : 0

  enabled = false
}

# Block public access for EMR - prevents clusters with public security groups
resource "aws_emr_block_public_access_configuration" "enabled" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

// File: outputs.tf
output "ebs_encryption_enabled" {
  description = "Whether EBS encryption by default is enabled"
  value       = aws_ebs_encryption_by_default.enabled.enabled
}

# Compute Layer KMS Key (EBS, Auto Scaling)

output "kms_compute_key_arn" {
  description = "ARN of the compute layer KMS key (EBS, Auto Scaling)"
  value       = aws_kms_key.compute.arn
}

output "kms_compute_key_id" {
  description = "ID of the compute layer KMS key"
  value       = aws_kms_key.compute.key_id
}

# Observability Layer KMS Key (CloudTrail, CloudWatch, SNS)

output "kms_observability_key_arn" {
  description = "ARN of the observability layer KMS key (CloudTrail, CloudWatch, SNS)"
  value       = aws_kms_key.observability.arn
}

output "kms_observability_key_id" {
  description = "ID of the observability layer KMS key"
  value       = aws_kms_key.observability.key_id
}

# Storage Layer KMS Key (S3 Log Buckets)

output "kms_storage_key_arn" {
  description = "ARN of the storage layer KMS key (S3 log buckets)"
  value       = aws_kms_key.storage.arn
}

output "kms_storage_key_id" {
  description = "ID of the storage layer KMS key"
  value       = aws_kms_key.storage.key_id
}

# Public Access Blocks

output "ami_block_public_access_state" {
  description = "State of AMI public access blocking"
  value       = aws_ec2_image_block_public_access.enabled.state
}

output "ebs_snapshot_block_public_access_state" {
  description = "State of EBS snapshot public access blocking"
  value       = aws_ebs_snapshot_block_public_access.enabled.state
}

# EC2 Instance Defaults

output "imdsv2_default_enabled" {
  description = "Whether IMDSv2 is enforced as the account default for new instances"
  value       = var.enable_imdsv2_default
}

output "ec2_serial_console_disabled" {
  description = "Whether EC2 Serial Console access is disabled"
  value       = var.disable_ec2_serial_console
}

output "emr_block_public_access_enabled" {
  description = "Whether EMR block public access is enabled"
  value       = var.enable_emr_block_public_access
}

// File: variables.tf
variable "project_name" {
  description = "Project name used for resource naming"
  type        = string
  default     = "benchmark"
}

variable "kms_rotation_period_days" {
  description = "KMS key rotation period in days. Minimum 90, maximum 2560. CIS requires at least annual (365)."
  type        = number
  default     = 90

  validation {
    condition     = var.kms_rotation_period_days >= 90 && var.kms_rotation_period_days <= 2560
    error_message = "KMS rotation period must be between 90 and 2560 days."
  }
}

variable "ebs_default_kms_key_arn" {
  description = "ARN of an existing customer-managed KMS key for default EBS encryption. Used only when an externally managed key is preferred over the internally created one. Leave empty to use the internally created compute key."
  type        = string
  default     = ""

  validation {
    condition     = var.ebs_default_kms_key_arn == "" || can(regex("^arn:aws(-[a-z]+)?:kms:[a-z0-9-]+:[0-9]{12}:key/", var.ebs_default_kms_key_arn))
    error_message = "ebs_default_kms_key_arn must be a valid KMS key ARN (arn:aws:kms:REGION:ACCOUNT:key/KEY-ID) or empty."
  }
}

# IMDSv2

variable "enable_imdsv2_default" {
  description = "Enforce IMDSv2 as the account-level default for all new EC2 instances. Does not affect existing instances."
  type        = bool
  default     = true
}

variable "imdsv2_hop_limit" {
  description = "HTTP PUT response hop limit for IMDSv2. Default is 1. In a container environment, set the hop limit to 2 (recommended)."
  type        = number
  default     = 1

  validation {
    condition     = var.imdsv2_hop_limit >= 1 && var.imdsv2_hop_limit <= 64
    error_message = "Hop limit must be between 1 and 64."
  }
}

# EC2 Serial Console

variable "disable_ec2_serial_console" {
  description = "Disable EC2 Serial Console access for the account. Eliminates out-of-band access path."
  type        = bool
  default     = true
}

# EMR

variable "enable_emr_block_public_access" {
  description = "Block public access on Amazon EMR on EC2. Prevents EMR clusters from launching with public security group rules."
  type        = bool
  default     = true
}

variable "ssh_keypair_name" {
  type = string
  description = "AWS SSH key pair name"
  default = "benchmark-keypair"
  validation {
    condition     = length(var.ssh_keypair_name) > 4
    error_message = "The SSH key pair name must be greater than 4 characters."
  }
}

variable "ssh_keypair_public_key_text" {
  type = string
  description = "AWS SSH key pair public key text"
  default = "ssh-rsa  benchmark-generated"
  validation {
    condition     = length(var.ssh_keypair_public_key_text) > 0
    error_message = "The SSH key pair public key text must not be empty."
  }
}

resource "aws_key_pair" "deployment_keypair" {
  key_name   = var.ssh_keypair_name
  public_key = var.ssh_keypair_public_key_text
}

output "ssh_keypair" {
  value = {
    name = aws_key_pair.deployment_keypair.key_name
    public_key = var.ssh_keypair_public_key_text
    fingerprint = aws_key_pair.deployment_keypair.fingerprint
  }
  description = "Deployment SSH keypair"
}

variable "cluster_prefix" {
  type = string
  description = "Deployment cluster prefix"
  default = "bench"
  validation {
    condition     = length(var.cluster_prefix) < 9 && length(var.cluster_prefix) > 4
    error_message = "The deployment cluster prefix must be between 5-8 characters."
  }
}

variable "vpc_name" {
  type        = string
  description = "VPC name"
  default     = null
}

variable "vpc_cidr" {
  type        = string
  description = "VPC CIDR block"
  default     = "172.16.0.0/16"
}

variable "vpc_enable_dns_support" {
  type        = bool
  description = "VPC DNS Support"
  default     = true
}

variable "vpc_enable_dns_hostnames" {
  type        = bool
  description = "VPC DNS Hostnames"
  default     = true
}

variable "igw_name" {
  type        = string
  description = "Internet Gateway name"
  default     = null
}

variable "public_subnets" {
  type       = list(object({
    az          = string
    name        = optional(string)
    cidr        = optional(string)
    cidr_range  = optional(number, 4) 
    tags        = optional(map(string), {})
  }))

  description = "List of public subnets"
  default    = []
}

variable "public_route_table_name" {
  type        = string
  description = "Public route table name"
  default     = null
}

variable "private_subnets" {
  type       = list(object({
    az          = string
    name        = optional(string)
    cidr        = optional(string)
    cidr_range  = optional(number, 4) 
    tags        = optional(map(string), {})
  }))

  description = "List of private subnets"
  default    = []
}

variable "nat_gateway_name" {
  type        = string
  description = "NAT gateway name"
  default     = null
}

variable "private_route_table_name" {
  type        = string
  description = "Private route table name"
  default     = null
}

# Security Groups
variable "security_group_default_name" {
  type        = string
  description = "Default Security Group name"
  default     = null
}

variable "security_group_default_desc" {
  type        = string
  description = "Default Security Group description"
  default     = null
}

variable "security_group_rules_ingress" {
  type       = list(object({
    cidr       = list(string)
    from_port  = string
    to_port    = string
    protocol   = string
  }))

  description = "Ingress rules for default Security Group"
  default    = []
}

# ------- Virtual Network ------- 
resource "aws_vpc" "cluster" {
  cidr_block            = var.vpc_cidr
  tags                  = { Name = var.vpc_name != null ? var.vpc_name : var.cluster_prefix }
  instance_tenancy      = "default"
  enable_dns_support    = var.vpc_enable_dns_support
  enable_dns_hostnames  = var.vpc_enable_dns_hostnames
}

# ------- Public Network infrastructure -------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.cluster.id
  tags   = { Name = var.igw_name != null ? var.igw_name : var.cluster_prefix }
}

locals {
  public_subnets = [
    for idx, subnet in var.public_subnets : 
      merge(subnet, { name = subnet.name != null ? subnet.name : "${var.cluster_prefix}-public-${format("%02d", idx+1)}" })
  ]

  private_subnets = [
    for idx, subnet in var.private_subnets : 
      merge(subnet, { name = subnet.name != null ? subnet.name : "${var.cluster_prefix}-private-${format("%02d", idx+1)}" })
  ]

  cidr_allocation = zipmap(
    [for subnet in concat(local.public_subnets, local.private_subnets) : subnet.name if subnet.cidr == null],
    cidrsubnets(var.vpc_cidr, [for subnet in concat(local.public_subnets, local.private_subnets) : subnet.cidr_range if subnet.cidr == null]...)
  )
}

resource "aws_subnet" "public_subnets" {
  for_each                = {for idx, subnet in local.public_subnets: idx => subnet}

  vpc_id                  = aws_vpc.cluster.id
  cidr_block              = each.value.cidr != null ? each.value.cidr : local.cidr_allocation[each.value.name]
  map_public_ip_on_launch = true
  availability_zone       = each.value.az
  tags                    = merge(each.value.tags, { Name = each.value.name })
}

resource "aws_default_route_table" "public_route_table" {
  default_route_table_id = aws_vpc.cluster.default_route_table_id

  route {
    cidr_block           = "0.0.0.0/0"
    gateway_id           = aws_internet_gateway.igw.id
  }

  tags                   = { Name = var.public_route_table_name != null ? var.public_route_table_name : "${var.cluster_prefix}-public" }
}

resource "aws_route_table_association" "public_subnets" {
  for_each        = aws_subnet.public_subnets

  subnet_id       = each.value.id
  route_table_id  = aws_vpc.cluster.default_route_table_id
}

# ------- Private Network infrastructure -------
resource "aws_subnet" "private_subnets" {
  for_each                = {for idx, subnet in local.private_subnets: idx => subnet}

  vpc_id                  = aws_vpc.cluster.id
  cidr_block              = each.value.cidr != null ? each.value.cidr : local.cidr_allocation[each.value.name]
  map_public_ip_on_launch = false
  availability_zone       = each.value.az
  tags                    = merge(each.value.tags, { Name = each.value.name })
}

resource "aws_eip" "nat_gateway_eip" {
  for_each  = aws_subnet.private_subnets

  vpc       = true
  tags      = merge(each.value.tags, { Name = "${var.cluster_prefix}-${each.value.tags_all["Name"]}-nat" })
}

resource "aws_nat_gateway" "private_subnets" {
  for_each          = aws_subnet.private_subnets

  subnet_id         = aws_subnet.public_subnets[each.key % length(aws_subnet.public_subnets)].id
  allocation_id     = aws_eip.nat_gateway_eip[each.key].id
  connectivity_type = "public"

  tags              = { Name = each.value.tags_all["Name"] != null ? each.value.tags_all["Name"] : "${var.cluster_prefix}-nat-${format("%02d", each.key+1)}" }
}

resource "aws_route_table" "private_route_table" {
  for_each          = aws_nat_gateway.private_subnets

  vpc_id            = aws_vpc.cluster.id

  route {
    cidr_block      = "0.0.0.0/0"
    nat_gateway_id  = each.value.id
  }

  tags = { Name = each.value.tags_all["Name"] }
}

resource "aws_route_table_association" "private_subnets" {
  for_each        = aws_subnet.private_subnets

  subnet_id       = each.value.id
  route_table_id  = aws_route_table.private_route_table[each.key].id
}

# ------- Security Groups -------
locals {
  default_sg_name = var.security_group_default_name != null ? var.security_group_default_name : "${var.cluster_prefix}-default"
}

resource "aws_security_group" "default_sg" {
  vpc_id       = aws_vpc.cluster.id
  name         = local.default_sg_name
  description  = var.security_group_default_desc != null ? var.security_group_default_desc : local.default_sg_name

  tags         = { Name = local.default_sg_name }

  # Intra-SG communication
  ingress {
      from_port = 0
      to_port   = 0
      protocol  = "all"
      self      = true
  }
  dynamic "ingress" {
    for_each = var.security_group_rules_ingress

    content {
      cidr_blocks = ingress.value.cidr
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
    }

  }

  egress {
    cidr_blocks = [aws_vpc.cluster.cidr_block]
    from_port   = 0
    to_port     = 0
    protocol    = "all"
  }
}

output "vpc" {
  value = {
    cidr = aws_vpc.cluster.cidr_block
  }
}

output "subnets" {
  value = {
    public = ["TBD"]
    private = ["TBD"]
  }

  description = "Network infrastructure"
}

variable "nodes" {
  type                      = list(object({
    name                    = string
    ami_filters             = optional(map(list(string)), {
      name                  = [ "RHEL-8.6*" ]
      architecture          = [ "x86_64" ]
    })
    ami_owners              = optional(list(string),[ 309956199498 ])
    ami_user                = optional(string, "ec2-user")
    instance_type           = optional(string, "m5.xlarge")
    subnet_index            = optional(number, 0)
    elastic_ip              = optional(bool, false)
    private_ip              = optional(string, null)
    tags                    = optional(map(string))
    root_volume             = optional(object({
      delete_on_termination = optional(bool, true)
      volume_size           = optional(number, 30)
      volume_type           = optional(string, "gp2")
    }), {})
    volumes                 = optional(list(object({
      device_name           = string
      mount                 = string
      volume_size           = optional(number, 100)
      volume_type           = optional(string, "gp2")
      tags                  = optional(map(string), {})
    })), [])
  }))

  description = "List of infrastructure nodes"
  default     = []
}

# ------- Inventory Nodes -------
data "aws_ami" "images" {
  for_each = { for idx, node in var.nodes : idx => node }

  most_recent = true

  owners = each.value.ami_owners
  dynamic filter {
    for_each = each.value.ami_filters

    content {
      name   = filter.key
      values = filter.value
    }
  }
}

locals {
  existing_subnets = concat(values(aws_subnet.public_subnets), values(aws_subnet.private_subnets))

  volumes = flatten([
    for idx, node in var.nodes:
    [ 
      for node_vol in node.volumes:
        {
          node_index    = idx
          name          = node.name
          device        = node_vol.device_name
          mount         = node_vol.mount
          size          = node_vol.volume_size
          type          = node_vol.volume_type
          subnet_index  = node.subnet_index
        }
    ] 
  ])
}

resource "aws_instance" "inventory" {
  for_each                = {for idx, node in var.nodes: idx => node}

  # TODO Find security group(s) by name
  vpc_security_group_ids  = [aws_security_group.default_sg.id]
  key_name                = aws_key_pair.deployment_keypair.key_name
  instance_type           = each.value.instance_type
  ami                     = data.aws_ami.images[each.key].id
  ebs_optimized           = true

  # TODO Alternatively, render by looking up the subnet name
  subnet_id               = local.existing_subnets[each.value.subnet_index].id
  private_ip              = each.value.private_ip  

  root_block_device {
    delete_on_termination = each.value.root_volume.delete_on_termination
    volume_size           = each.value.root_volume.volume_size
    volume_type           = each.value.root_volume.volume_type
  }

  associate_public_ip_address = local.existing_subnets[each.value.subnet_index].map_public_ip_on_launch

  tags                     = merge(each.value.tags, { Name = each.value.name }) 

  lifecycle {
    precondition {
      condition     = length(var.public_subnets) > 0 || length(var.private_subnets) > 0
      error_message = "Unable to provision, no subnets available. You must define at least one subnet, public or private."
    } 
  }
}

resource "aws_eip" "inventory" {
  for_each = {for idx, node in var.nodes: idx => node if node.elastic_ip}

  instance = aws_instance.inventory[each.key].id
  vpc      = true
  tags     = {
    Name     = each.value.name
  }

  depends_on = [
    aws_internet_gateway.igw
  ]
}

resource "aws_ebs_volume" "inventory" {
  for_each    = {for idx, volume in local.volumes: idx => volume}

  availability_zone = local.existing_subnets[each.value.subnet_index].availability_zone
  size              = each.value.size
  type              = each.value.type
  tags              = {
    Name        = "${each.value.name}: ${each.value.device}"
    mount       = each.value.mount
  }
  #encrypted ...
}

resource "aws_volume_attachment" "inventory" {
  for_each    = {for idx, volume in local.volumes: idx => volume}

  device_name = each.value.device
  volume_id   = aws_ebs_volume.inventory[index(local.volumes, each.value)].id
  instance_id = aws_instance.inventory[each.value.node_index].id
}

# ------- Construct outputs for details of node and storage volumes -------
locals {
  # Details for all attached volumes
  attached_volumes = [
      for idx, volume in local.volumes: 
        {
            "vol_name" = aws_ebs_volume.inventory[index(local.volumes, volume)].tags["Name"]
            "vol_id"   = aws_volume_attachment.inventory[index(local.volumes, volume)].volume_id
            "instance" = aws_volume_attachment.inventory[index(local.volumes, volume)].instance_id
            "device"   = aws_volume_attachment.inventory[index(local.volumes, volume)].device_name
            "mount"    = aws_ebs_volume.inventory[index(local.volumes, volume)].tags["mount"]
        }
        if length(aws_ebs_volume.inventory) > 0
    ]

  # Attached volume details grouped by instance
  attached_volumes_by_instance = {
    for vol in local.attached_volumes :
      vol.instance => 
      {
        vol_name = vol.vol_name
        vol_id   = vol.vol_id
        device   = vol.device
        mount    = vol.mount
      }...
  }
}

output "nodes" {
  value = [
    for idx, v in aws_instance.inventory : 
      {
        # The top-level keys are used by 'add_host' within the provision role; 
        # use the nested 'metadata' tags within a 'module_defaults' declaration 
        # to add additional, ad-hoc 'add_host' variables
        "id"  = v.id
        "label" = v.tags["Name"]
        "hostname" = v.tags["hostname"]
        "instance_user" = var.nodes[idx].ami_user
        "ipv4" = lookup(aws_eip.inventory, idx, "") != "" ? aws_eip.inventory[idx].public_ip : v.public_ip != "" ? v.public_ip : v.private_ip
        "groups" = [ for g in coalesce(split(",", v.tags["groups"]), []) : trimspace(g) ]
        "metadata" = { for m, t in v.tags_all : m => t if !contains(["groups", "Name", "hostname"], m) }
        "storage_volumes" = lookup(local.attached_volumes_by_instance, v.id, [])
      }
  ]

  description = "Details of the provisioned inventory nodes."
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  type        = string
  description = "AWS Region"
  default     = "us-east-1"
}

variable "env_tags" {
  type        = map(string)
  description = "Tags applied to provisioned resources"

  default     = {
    comment = "Created with Terraform via cloudera.exe.provision"
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = var.env_tags
  }
}

provider "aws" {
  profile    = "default"
  region     = var.region
}

output "vpc_main" {
  value       = aws_vpc.main.id
  description = "VPC id"
}

output "subnet_public_A" {
  value       = aws_subnet.public_a.id
  description = "Subnet public A"
}

output "subnet_public_B" {
  value       = aws_subnet.public_b.id
  description = "Subnet public B"
}

output "subnet_private_A" {
  value       = aws_subnet.private_a[0].id
  description = "Subnet private A"
}

output "subnet_private_B" {
  value       = aws_subnet.private_b[0].id
  description = "Subnet private B"
}

output "subnet_public_C" {
  value       = try(aws_subnet.public_c[0].id, null)
  description = "Subnet public C"
}

output "subnet_public_D" {
  value       = try(aws_subnet.public_d[0].id, null)
  description = "Subnet public D"
}

output "default_security_group"{
  value = aws_default_security_group.default.id
  description = "Default SG for VPC"
}

output "security_group_allow_tls"{
  value = aws_security_group.allow_tls.id
  description = "Default SG for VPC"
}

// Only with has_egress_only_internet_gateway = true
// Egress only internet gateway
resource "aws_egress_only_internet_gateway" "egress_only_ig" {
  vpc_id = "${aws_vpc.main.id}"
  count = "${var.has_egress_only_internet_gateway?1:0}"
}

// Route Tables
resource "aws_route_table" "private_egress_only_ig" {
  vpc_id = "${aws_vpc.main.id}"
  tags = merge ({
    Name = "${var.name}_private_route_table"
    type = "private"
  },var.tags)
  count = "${var.has_egress_only_internet_gateway?1:0}"
}

// Routes
resource "aws_route" "egress_only_ig_route" {
  route_table_id = "${aws_route_table.private_egress_only_ig[0].id}"
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id = "${aws_egress_only_internet_gateway.egress_only_ig[0].id}"
  count = "${var.has_egress_only_internet_gateway?1:0}"
}

// Association
resource "aws_route_table_association" "egress_only_ig_route_route_a" {
  subnet_id      = aws_subnet.private_a[0].id
  route_table_id = aws_route_table.private_egress_only_ig[0].id
  count = "${var.has_egress_only_internet_gateway?1:0}"
}

resource "aws_route_table_association" "egress_only_ig_route_route_b" {
  subnet_id      = aws_subnet.private_b[0].id
  route_table_id = aws_route_table.private_egress_only_ig[0].id
  count = "${var.has_egress_only_internet_gateway?1:0}"
}

// Only with has_nat_gateway = true
// Elastic IPs
resource "aws_eip" "nat_ig_elastic_ip" {
  domain   = "vpc"
  count = "${var.has_nat_gateway?2:0}"
  tags = merge ({
    Name = "${var.name}_route_table_elastic_ip_${count.index==0?"a":"b"}"
  },var.tags)
}

// Nat Gateways
resource "aws_nat_gateway" "nat_gateway_public_a" {
  allocation_id = "${aws_eip.nat_ig_elastic_ip[0].id}"
  subnet_id = "${aws_subnet.public_a.id}"
  count = "${var.has_nat_gateway?1:0}"
  tags = merge ({
    Name = "${var.name}_nat_gateway_a"
  },var.tags)
}

resource "aws_nat_gateway" "nat_gateway_public_b" {
  allocation_id = "${aws_eip.nat_ig_elastic_ip[1].id}"
  subnet_id = "${aws_subnet.public_b.id}"
  count = "${var.has_nat_gateway?1:0}"
  tags = merge ({
    Name = "${var.name}_nat_gateway_b"
  },var.tags)
}

// Route Tables
resource "aws_route_table" "nat_gateway_private_table_a" {
  vpc_id = "${aws_vpc.main.id}"
  route {
        cidr_block = "0.0.0.0/0"
        nat_gateway_id = "${aws_nat_gateway.nat_gateway_public_a[0].id}"
    }
  tags = merge ({
    Name = "${var.name}_private_table_a"
    type = "private"
  },var.tags)
  count = "${var.has_nat_gateway?1:0}"
}

resource "aws_route_table" "nat_gateway_private_table_b" {
  vpc_id = "${aws_vpc.main.id}"
  route {
        cidr_block = "0.0.0.0/0"
        nat_gateway_id = "${aws_nat_gateway.nat_gateway_public_b[0].id}"
    }
  tags = merge ({
    Name = "${var.name}_private_table_b"
    type = "private"
  },var.tags)
  count = "${var.has_nat_gateway?1:0}"
}

// Association

resource "aws_route_table_association" "nat_gateway_route_route_a" {
  subnet_id      = aws_subnet.private_a[0].id
  route_table_id = aws_route_table.nat_gateway_private_table_a[0].id
  count = "${var.has_nat_gateway?1:0}"
}

resource "aws_route_table_association" "nat_gateway_route_route_b" {
  subnet_id      = aws_subnet.private_b[0].id
  route_table_id = aws_route_table.nat_gateway_private_table_b[0].id
  count = "${var.has_nat_gateway?1:0}"
}

// Only with has_nat_instance = true

// Nat AMI

data "aws_ami" "nat_instance" {
  count       = var.has_nat_instance ? 1 : 0
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["137112412989"] # Amazon
}


// Nat Instance

resource "aws_instance" "nat_a" {
    ami = "${ data.aws_ami.nat_instance[0].id}"
    availability_zone = "${var.region_az[0]}"
    instance_type = "m1.small"
    // key_name = "${var.aws_key_name}"
    vpc_security_group_ids = ["${aws_security_group.nat[0].id}"]
    subnet_id = "${aws_subnet.public_a.id}"
    associate_public_ip_address = true
    source_dest_check = false
    tags = merge ({
        Name = "${var.name}_nat_instance_${var.region_az[0]}"
    },var.tags)
    count = "${var.has_nat_instance?1:0}"
}

resource "aws_instance" "nat_b" {
    ami = "${ data.aws_ami.nat_instance[0].id}"
    availability_zone = "${var.region_az[1]}"
    instance_type = "m1.small"
    // key_name = "${var.aws_key_name}"
    vpc_security_group_ids = ["${aws_security_group.nat[0].id}"]
    subnet_id = "${aws_subnet.public_b.id}"
    associate_public_ip_address = true
    source_dest_check = false
    tags = merge ({
        Name = "${var.name}_nat_instance_${var.region_az[1]}"
    },var.tags)
    count = "${var.has_nat_instance?1:0}"
}

// Route Tables
resource "aws_route_table" "nat_instance_private_table_a" {
  vpc_id = "${aws_vpc.main.id}"
  route {
        cidr_block = "0.0.0.0/0"
        network_interface_id = "${aws_instance.nat_a[0].primary_network_interface_id}"
  }
  tags = merge ({
    Name = "${var.name}_private_table_a"
    type = "private"
  },var.tags)
  count = "${var.has_nat_instance?1:0}"
}

resource "aws_route_table" "nat_instance_private_table_b" {
  vpc_id = "${aws_vpc.main.id}"
  route {
        cidr_block = "0.0.0.0/0"
        network_interface_id = "${aws_instance.nat_b[0].primary_network_interface_id}"
  }
  tags = merge ({
    Name = "${var.name}_private_table_b"
    type = "private"
  },var.tags)

  count = "${var.has_nat_instance?1:0}"
}

// Association

resource "aws_route_table_association" "nat_instance_route_route_a" {
  subnet_id      = aws_subnet.private_a[0].id
  route_table_id = aws_route_table.nat_instance_private_table_a[0].id
  count = "${var.has_nat_instance?1:0}"
}

resource "aws_route_table_association" "nat_instance_route_route_b" {
  subnet_id      = aws_subnet.private_b[0].id
  route_table_id = aws_route_table.nat_instance_private_table_b[0].id
  count = "${var.has_nat_instance?1:0}"
}

// Security Group

resource "aws_security_group" "nat" {
	name = "nat"
	description = "Allow services from the private subnet through NAT"
	vpc_id = "${aws_vpc.main.id}"
	ingress {
		from_port = 80
		to_port = 80
		protocol = "tcp"
		cidr_blocks = ["0.0.0.0/0"]
	}
	ingress {
		from_port = 443
		to_port = 443
		protocol = "tcp"
		cidr_blocks = ["0.0.0.0/0"]
	}
	ingress {
		from_port = 0
		to_port = 65535
		protocol = "tcp"
		security_groups = ["${aws_default_security_group.default.id}"]
	}
	ingress {
		from_port = 0
		to_port = 65535
		protocol = "udp"
		security_groups = ["${aws_default_security_group.default.id}"]
	}
	egress {
		from_port = 0
		to_port = 0
		protocol = "-1"
		cidr_blocks = ["0.0.0.0/0"]
	}
  tags = merge ({
    Name = "${var.name}_sg_nat"
    type = "private"
  },var.tags)
  count = "${var.has_nat_instance?1:0}"
}

resource "aws_route_table" "public_main" {
  vpc_id = "${aws_vpc.main.id}"
  // internet
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = "${aws_internet_gateway.main.id}"
  }
  tags = merge ({
    Name = "${var.name}_public_route_table"
    type = "public"
  },var.tags)
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public_main.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public_main.id
}

// Optional
resource "aws_route_table_association" "public_c" {
  subnet_id      = aws_subnet.public_c[0].id
  route_table_id = aws_route_table.public_main.id
  count = "${!var.has_private_subnet ? 1 : 0}"

}

resource "aws_route_table_association" "public_d" {
  subnet_id      = aws_subnet.public_d[0].id
  route_table_id = aws_route_table.public_main.id
  count = "${!var.has_private_subnet ? 1 : 0}"
}

resource "aws_default_security_group" "default" {
  vpc_id = "${aws_vpc.main.id}"
  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }
  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }
  tags = merge ({
    Name = "${var.name}_default"
    type = "private"
  },var.tags)
}


resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Allow TLS inbound traffic"
  vpc_id      = "${aws_vpc.main.id}"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    cidr_blocks     = [data.aws_vpc.trivy_scope_1.cidr_block]
  }

  tags = merge ({
    Name = "${var.name}_allow_tls"
    type = "private"
  },var.tags)
}

// Public Subnet
resource "aws_subnet" "public_a" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[0]}"
  availability_zone = "${var.region_az[0]}"
  map_public_ip_on_launch = "${var.public_subnet_map_public_ip_on_launch}"
  tags = merge({
    Name = "${var.name}_public_${var.region_az[0]}"
    Type = "public"
    },var.tags)
}

resource "aws_subnet" "public_b" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[1]}"
  availability_zone = "${var.region_az[1]}"
  map_public_ip_on_launch = "${var.public_subnet_map_public_ip_on_launch}"
  tags = merge({
    Name = "${var.name}_public_${var.region_az[1]}"
    Type = "public"
  },var.tags)
}

// Public Subnet Optional

resource "aws_subnet" "public_c" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[2]}"
  availability_zone = "${var.region_az[2]}"
  tags = merge({
    Name = "${var.name}_public_${var.region_az[2]}"
    Type = "public"
  },var.tags)
  count = "${!var.has_private_subnet ? 1 : 0}"
}

resource "aws_subnet" "public_d" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[3]}"
  availability_zone = "${var.region_az[3]}"
  tags = merge({
    Name = "${var.name}_public_${var.region_az[3]}"
    type = "public"
  },var.tags)
  count = "${!var.has_private_subnet ? 1 : 0}"
}

// Private Subnet
resource "aws_subnet" "private_a" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[2]}"
  availability_zone = "${var.region_az[0]}"
  tags = merge({
    Name = "${var.name}_private_${var.region_az[0]}"
    Type = "private"
  },var.tags)
  count = "${var.has_private_subnet ? 1 : 0}"
}

resource "aws_subnet" "private_b" {
  vpc_id     = "${aws_vpc.main.id}"
  cidr_block = "${var.cidr_subnets[3]}"
  availability_zone = "${var.region_az[1]}"
  tags = merge({
    Name = "${var.name}_private_${var.region_az[1]}"
    type = "private"
  },var.tags)
  count = "${var.has_private_subnet ? 1 : 0}"
}

# VPC CIDRs used to scope security-group rules that previously allowed 0.0.0.0/0
# (Trivy AWS-0104 unrestricted egress / AWS-0107 admin ports open to the internet).

data "aws_vpc" "trivy_scope_1" {
  id = "${aws_vpc.main.id}"
}

// configuration
variable has_private_subnet {default = true}
variable has_nat_gateway {default = false}
variable has_nat_instance {default = false}
variable has_egress_only_internet_gateway {default = false}

// tags
variable name {default = "benchmark-vpc"}
//VPC
variable region {default = "us-east-1"}
variable cidr_block {default = "10.0.0.0/16"}
variable assign_generated_ipv6  { default = false}
variable tenancy  { default = "default"} // default | dedicated
variable tags {
  default = {
    Created = "terraform"
  }
}

//subnets
variable cidr_subnets {default = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]} // list with only 4 subnets
variable region_az {default = ["us-east-1a", "us-east-1b", "us-east-1c", "us-east-1d"]} // list with only two AZ
variable enable_dns_support {default = false}
variable enable_dns_hostnames {default = false}
variable public_subnet_map_public_ip_on_launch {default = false} // Only for public subnets

resource "aws_vpc" "main" {
  cidr_block = var.cidr_block
  instance_tenancy = var.tenancy
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6
  enable_dns_support = "${ var.enable_dns_support}"
  enable_dns_hostnames  = "${ var.enable_dns_hostnames}"
  tags = merge({
    Name = "${var.name}"
    },var.tags)
}


resource "aws_internet_gateway" "main" {
  vpc_id = "${aws_vpc.main.id}"
  tags = merge({
    Name = "${var.name}_internet_gateway"
    },var.tags)
}

locals {
  accesslogs_bucket_name = "govwifi-${var.env_name}-accesslogs-${data.aws_region.main.name}"
}

resource "aws_iam_role" "accesslogs_replication" {
  name = "govwifi-${var.env_name}-accesslogs-replication-role"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "s3.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY

}

resource "aws_iam_policy" "accesslogs_replication" {
  name = "govwifi-${var.env_name}-accesslogs-replication-policy"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "s3:GetReplicationConfiguration",
        "s3:ListBucket"
      ],
      "Effect": "Allow",
      "Resource": [
        "${aws_s3_bucket.accesslogs_bucket.arn}"
      ]
    },
    {
      "Action": [
        "s3:GetObjectVersion",
        "s3:GetObjectVersionAcl"
      ],
      "Effect": "Allow",
      "Resource": [
        "${aws_s3_bucket.accesslogs_bucket.arn}/*"
      ]
    },
    {
      "Action": [
         "s3:ReplicateObject",
         "s3:ReplicateDelete"
      ],
      "Effect": "Allow",
      "Resource": "${aws_s3_bucket.replication_accesslogs_bucket.arn}/*"
    }
  ]
}
EOF

}

resource "aws_iam_policy_attachment" "accesslogs_replication" {
  name       = "govwifi-${var.env_name}-accesslogs-replication"
  roles      = [aws_iam_role.accesslogs_replication.name]
  policy_arn = aws_iam_policy.accesslogs_replication.arn
}

resource "aws_s3_bucket" "accesslogs_bucket" {
  bucket = local.accesslogs_bucket_name

  tags = {
    Region   = data.aws_region.main.name
    Category = "Accesslogs"
  }
}

resource "aws_s3_bucket_public_access_block" "accesslogs_bucket" {
  bucket = aws_s3_bucket.accesslogs_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}


resource "aws_s3_bucket_replication_configuration" "accesslogs_replication" {
  depends_on = [
    aws_s3_bucket_versioning.accesslogs_bucket,
    aws_s3_bucket_versioning.replication_accesslogs_bucket
  ]

  bucket = aws_s3_bucket.accesslogs_bucket.id
  role   = aws_iam_role.accesslogs_replication.arn

  rule {
    id = "${data.aws_region.main.name}-to-${data.aws_region.replication.name}-accesslogs-backup"

    filter {
      prefix = "${var.env_name}-accesslogs-backup"
    }

    destination {
      bucket        = aws_s3_bucket.replication_accesslogs_bucket.arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }

    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "accesslogs_bucket" {
  bucket = aws_s3_bucket.accesslogs_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}


resource "aws_s3_bucket_acl" "accesslogs_bucket" {
  bucket = aws_s3_bucket.accesslogs_bucket.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.accesslogs_bucket]
}

resource "aws_s3_bucket_versioning" "accesslogs_bucket" {
  bucket = aws_s3_bucket.accesslogs_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "accesslogs_bucket" {
  depends_on = [aws_s3_bucket_versioning.accesslogs_bucket]

  bucket = aws_s3_bucket.accesslogs_bucket.id

  rule {
    id = "accesslogs-lifecycle"

    transition {
      days          = var.accesslogs_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.accesslogs_expiration_days
    }

    status = "Enabled"
  }
}

locals {
  bucket_name = "govwifi-${var.env_name}-tfstate-${data.aws_region.main.name}"
}

resource "aws_iam_role" "tfstate_replication" {
  name = "tfstate-replication"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "s3.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY

}

resource "aws_iam_policy" "tfstate_replication" {
  name = "tfstate-replication"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "s3:GetReplicationConfiguration",
        "s3:ListBucket"
      ],
      "Effect": "Allow",
      "Resource": [
        "${aws_s3_bucket.state_bucket.arn}"
      ]
    },
    {
      "Action": [
        "s3:GetObjectVersion",
        "s3:GetObjectVersionAcl"
      ],
      "Effect": "Allow",
      "Resource": [
        "${aws_s3_bucket.state_bucket.arn}/*"
      ]
    },
    {
      "Action": [
        "s3:ReplicateObject",
        "s3:ReplicateDelete"
      ],
      "Effect": "Allow",
      "Resource": "arn:aws:s3:::${local.replication_bucket_name}/*"
    }
  ]
}
EOF

}

resource "aws_iam_policy_attachment" "tfstate_replication" {
  name       = "tfstate-replication"
  roles      = [aws_iam_role.tfstate_replication.name]
  policy_arn = aws_iam_policy.tfstate_replication.arn
}

resource "aws_s3_bucket" "state_bucket" {
  bucket = local.bucket_name

  tags = {
    Region   = data.aws_region.main.name
    Category = "TFstate"
  }
}

resource "aws_s3_bucket_public_access_block" "state_bucket" {
  bucket = aws_s3_bucket.state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "state_bucket" {
  bucket = aws_s3_bucket.state_bucket.id

  policy = <<EOF
{
  "Version": "2008-10-17",
  "Statement": [{
    "Sid": "S3PolicyStmt-allow-all-s3-for-owner",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:*",
    "Resource": "arn:aws:s3:::${local.bucket_name}/*",
    "Condition": {
      "StringEquals": {
        "aws:SourceAccount": "${data.aws_caller_identity.current.account_id}",
        "s3:x-amz-acl": "bucket-owner-full-control"
      }
    }
  }]
}
EOF
}

resource "aws_s3_bucket_replication_configuration" "state_bucket" {
  depends_on = [
    aws_s3_bucket_versioning.state_bucket,
    aws_s3_bucket_versioning.replication_state_bucket
  ]

  bucket = aws_s3_bucket.state_bucket.id
  role   = aws_iam_role.tfstate_replication.arn

  rule {
    id = "${lower(data.aws_region.main.name)}-to-${lower(data.aws_region.replication.name)}-tfstate-backup"

    filter {
      prefix = "${lower(data.aws_region.main.name)}-tfstate"
    }

    destination {
      bucket        = aws_s3_bucket.replication_state_bucket.arn
      storage_class = "STANDARD_IA"
    }

    delete_marker_replication {
      status = "Enabled"
    }

    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "state_bucket" {
  bucket = aws_s3_bucket.state_bucket.id

  target_bucket = aws_s3_bucket.accesslogs_bucket.id
  target_prefix = "${var.env_name}-tfstate"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_bucket" {
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "state_bucket" {
  bucket = aws_s3_bucket.state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
    }
  }
}

provider "aws" {
  alias  = "replication"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_region" "main" {}

data "aws_region" "replication" {
  provider = aws.replication
}

resource "aws_s3_bucket" "replication_accesslogs_bucket" {
  bucket = "govwifi-${var.env_name}-accesslogs-${data.aws_region.replication.name}"

  tags = {
    Region   = data.aws_region.replication.name
    Category = "Accesslogs"
  }
}

resource "aws_s3_bucket_public_access_block" "replication_accesslogs_bucket" {
  bucket = aws_s3_bucket.replication_accesslogs_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replication_accesslogs_bucket" {
  bucket = aws_s3_bucket.replication_accesslogs_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "replication_accesslogs_bucket" {
  depends_on = [aws_s3_bucket_versioning.replication_accesslogs_bucket]

  bucket = aws_s3_bucket.replication_accesslogs_bucket.id

  rule {
    id = "accesslogs-lifecycle"

    transition {
      days          = var.accesslogs_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.accesslogs_expiration_days
    }

    status = "Enabled"
  }
}

locals {
  replication_bucket_name = "govwifi-${var.env_name}-tfstate-${data.aws_region.replication.name}"
}

resource "aws_s3_bucket" "replication_state_bucket" {
  provider = aws.replication

  bucket = local.replication_bucket_name

  tags = {
    Region   = data.aws_region.replication.name
    Category = "TFstate"
  }
}

resource "aws_s3_bucket_public_access_block" "replication_state_bucket" {
  provider = aws.replication
  bucket   = aws_s3_bucket.replication_state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "replication_state_bucket" {
  provider = aws.replication

  bucket = aws_s3_bucket.replication_state_bucket.id

  policy = <<EOF
{
  "Version": "2008-10-17",
  "Statement": [{
    "Sid": "S3PolicyStmt-allow-all-s3-for-owner",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:*",
    "Resource": "arn:aws:s3:::${local.replication_bucket_name}/*",
    "Condition": {
      "StringEquals": {
        "aws:SourceAccount": "${data.aws_caller_identity.current.account_id}",
        "s3:x-amz-acl": "bucket-owner-full-control"
      }
    }
  }]
}
EOF
}

resource "aws_kms_key" "replication_state_bucket" {
  provider            = aws.replication
  description         = "CMK for the replicated Terraform state bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_state_bucket" {
  provider = aws.replication

  bucket = aws_s3_bucket.replication_state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replication_state_bucket.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "replication_state_bucket" {
  provider = aws.replication

  bucket = aws_s3_bucket.replication_state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

variable "env_name" {
  default = "benchmark"
}

variable "accesslogs_glacier_transition_days" {
  default = 7
}

variable "accesslogs_expiration_days" {
  default = 30
}

# This is customized based on - https://github.com/terraform-aws-modules/terraform-aws-vpc

locals {
  vpc_id           = var.vpc_id == null ? aws_vpc.vpc[0].id : data.aws_vpc.vpc[0].id
  existing_subnets = length(var.existing_subnet_ids) > 0 ? true : false

  existing_public_subnets = local.existing_subnets && contains(keys(var.existing_subnet_ids), "public") ? (length(var.existing_subnet_ids["public"]) > 0 ? true : false) : false
  existing_private_subnets = local.existing_subnets && contains(keys(var.existing_subnet_ids), "private") ? (length(var.existing_subnet_ids["private"]) > 0 ? true : false) : false
  existing_database_subnets = local.existing_subnets && contains(keys(var.existing_subnet_ids), "database") ? (length(var.existing_subnet_ids["database"]) > 0 ? true : false) : false

  public_subnets  = local.existing_public_subnets ? data.aws_subnet.public : aws_subnet.public
  private_subnets = local.existing_private_subnets ? data.aws_subnet.private : aws_subnet.private

}

data "aws_vpc" "vpc" {
  count = var.vpc_id == null ? 0 : 1
  id    = var.vpc_id
}

######
# VPC
######
resource "aws_vpc" "vpc" {
  count                = var.vpc_id == null ? 1 : 0
  cidr_block           = var.cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support
  tags = merge(
    {
      "Name" = format("%s", "${var.name}-vpc")
    },
    var.tags,
  )
}

resource "aws_security_group" "vpc_endpoints" {
  count       = var.security_group_id == "" ? 1 : 0
  name        = "${var.name}-vpc-endpoints"
  description = "Allow HTTPS from within the VPC to interface endpoints"
  vpc_id      = local.vpc_id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.cidr]
  }
}

resource "aws_vpc_endpoint" "private_endpoints" {
  count              = length(var.vpc_private_endpoints)
  vpc_id             = local.vpc_id
  service_name       = "com.amazonaws.${var.region}.${var.vpc_private_endpoints[count.index]}"
  vpc_endpoint_type  = "Interface"
  security_group_ids = [var.security_group_id != "" ? var.security_group_id : aws_security_group.vpc_endpoints[0].id]

  tags = merge(
    {
      "Name" = format("%s", "${var.name}-private-endpoint-${var.vpc_private_endpoints[count.index]}")
    },
    var.tags,
  )

  subnet_ids = [ 
    for subnet in local.private_subnets : subnet.id
  ]
}

data "aws_subnet" "public" {
  count = local.existing_public_subnets ? length(var.subnets["public"]) : 0
  id    = element(var.existing_subnet_ids["public"], count.index)
}

data "aws_subnet" "private" {
  count = local.existing_private_subnets ? length(var.subnets["private"]) : 0
  id    = element(var.existing_subnet_ids["private"], count.index)
}

data "aws_subnet" "database" {
  count = local.existing_database_subnets ? length(var.subnets["database"]) : 0
  id    = element(var.existing_subnet_ids["database"], count.index)
}

################
# Public subnet
################
resource "aws_subnet" "public" {
  count                   = local.existing_public_subnets ? 0 : length(var.subnets["public"])
  vpc_id                  = local.vpc_id
  cidr_block              = element(var.subnets["public"], count.index)
  availability_zone       = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    {
      "Name" = format(
        "%s-${var.public_subnet_suffix}-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
    var.public_subnet_tags,
  )
}

###################
# Internet Gateway
###################
resource "aws_internet_gateway" "this" {
  count =  var.existing_nat_id == null ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    {
      "Name" = format("%s", var.name)
    },
    var.tags,
  )
}

################
# Publiс routes
################
resource "aws_route_table" "public" {
  count = local.existing_public_subnets ? 0 : 1
  vpc_id = local.vpc_id

  tags = merge(
    {
      "Name" = format(
        "%s-${var.public_subnet_suffix}-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
  )
}

resource "aws_route" "public_internet_gateway" {
  count = var.existing_nat_id == null ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id

  timeouts {
    create = "5m"
  }
}

##########################
# Route table association
##########################
resource "aws_route_table_association" "private" {
  count = local.existing_private_subnets ? 0 : length(var.subnets["private"])

  subnet_id      = element(aws_subnet.private.*.id, count.index)
  route_table_id = element(aws_route_table.private.*.id, 0)
}

resource "aws_route_table_association" "public" {
  count = local.existing_public_subnets ? 0 :length(var.subnets["public"])

  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = element(aws_route_table.public.*.id, 0)
}

resource "aws_route_table_association" "database" {
  count = local.existing_database_subnets ? 0 : length(var.subnets["database"])

  subnet_id      = element(aws_subnet.database.*.id, count.index)
  route_table_id = element(aws_route_table.private.*.id, 0)
}

#################
# Private subnet
#################
resource "aws_subnet" "private" {
  count                = local.existing_private_subnets ? 0 : length(var.subnets["private"])
  vpc_id               = local.vpc_id
  cidr_block           = element(var.subnets["private"], count.index)
  availability_zone    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null

  tags = merge(
    {
      "Name" = format(
        "%s-${var.private_subnet_suffix}-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
    var.private_subnet_tags,
  )
}

#################
# Private routes
# There are as many routing tables as the number of NAT gateways
#################
resource "aws_route_table" "private" {
  count = local.existing_private_subnets ? 0 : 1

  vpc_id = local.vpc_id

  tags = merge(
    {
      "Name" = format(
        "%s-${var.private_subnet_suffix}-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
  )
}

##################
# Database subnet
##################
resource "aws_subnet" "database" {
  count                = local.existing_database_subnets ? 0 : length(var.subnets["database"])
  vpc_id               = local.vpc_id
  cidr_block           = element(var.subnets["database"], count.index)
  availability_zone    = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) > 0 ? element(var.azs, count.index) : null
  availability_zone_id = length(regexall("^[a-z]{2}-", element(var.azs, count.index))) == 0 ? element(var.azs, count.index) : null

  tags = merge(
    {
      "Name" = format(
        "%s-${var.database_subnet_suffix}-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
  )
}

resource "aws_db_subnet_group" "database" {
  count = local.existing_database_subnets == false && length(var.subnets["database"]) > 0 ? 1 : 0

  name        = lower(var.name)
  description = "Database subnet group for ${var.name}"
  subnet_ids  = aws_subnet.database.*.id

  tags = merge(
    {
      "Name" = format("%s", var.name)
    },
    var.tags,
  )
}

resource "aws_eip" "nat" {
  count = var.existing_nat_id == null ? 1 : 0

  domain = "vpc"

  tags = merge(
    {
      "Name" = format(
        "%s-%s",
        var.name,
        element(var.azs, count.index),
      )
    },
    var.tags,
  )
}

data "aws_nat_gateway" "nat_gateway" {
  count = var.existing_nat_id != null ? 1 : 0
  id = var.existing_nat_id # alt. support vpc_id or subnet_id where NAT 
}

resource "aws_nat_gateway" "nat_gateway" {
  count = var.existing_nat_id == null ? 1 : 0

  allocation_id = element(aws_eip.nat.*.id, 0)
  subnet_id = local.existing_public_subnets ? element(data.aws_subnet.public.*.id, 0) : element(aws_subnet.public.*.id,0)

  tags = merge(
    {
      "Name" = format(
        "%s-%s",
        var.name,
        element(var.azs, 0),
      )
    },
    var.tags,
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route" "private_nat_gateway" {
  count = var.existing_nat_id == null ? 1 : 0

  route_table_id         = element(aws_route_table.private.*.id, count.index)
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.nat_gateway.*.id, count.index)

  timeouts {
    create = "5m"
  }
}

#vpc_id
output "vpc_id" {
  description = "VPC id"
  value       = local.vpc_id
}

#subnet_ids
output "public_subnets" {
  description = "List of IDs of public subnets"
  value       = local.existing_public_subnets ? data.aws_subnet.public.*.id : aws_subnet.public.*.id
}

output "public_subnet_azs" {
  description = "List of public subnet AZs"
  value       = local.existing_public_subnets ? data.aws_subnet.public.*.availability_zone : aws_subnet.public.*.availability_zone
}

output "public_subnet_cidrs" {
  description = "CIDR blocks of public subnets"
  value       = local.existing_public_subnets ? data.aws_subnet.public.*.cidr_block : aws_subnet.public.*.cidr_block
}


output "private_subnets" {
  description = "List of IDs of private subnets"
  value       = local.existing_private_subnets ? data.aws_subnet.private.*.id : aws_subnet.private.*.id
}

output "private_subnet_azs" {
  description = "List of private subnet AZs"
  value       = local.existing_private_subnets ? data.aws_subnet.private.*.availability_zone : aws_subnet.private.*.availability_zone
}

output "private_subnet_cidrs" {
  description = "CIDR blocks of private subnets"
  value       = local.existing_private_subnets ? data.aws_subnet.private.*.cidr_block : aws_subnet.private.*.cidr_block
}


output "database_subnets" {
  description = "List of IDs of database subnets"
  value       = local.existing_database_subnets ? data.aws_subnet.database.*.id : aws_subnet.database.*.id
}

output "nat_public_ips" {
  description = "List of public Elastic IPs created for AWS NAT Gateway"
  value       = var.existing_nat_id == null ? aws_eip.nat.*.public_ip : data.aws_nat_gateway.nat_gateway.*.public_ip
}

output "public_route_table_ids" {
  description = "List of IDs of public route tables"
  value       = local.existing_public_subnets ? null : aws_route_table.public.*.id
}

output "private_route_table_ids" {
  description = "List of IDs of private route tables"
  value       = local.existing_private_subnets ? null : aws_route_table.private.*.id
}

output "vpc_cidr" {
  description = "CIDR block of VPC"
  value       = var.vpc_id == null ? var.cidr : data.aws_vpc.vpc[0].cidr_block
}

variable "azs" {
  description = "A list of availability zones names or ids in the region"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

variable vpc_id {
  description = "Existing vpc id"
  default     = null
}

variable "name" {
  type    = string
  default = "benchmark-vpc"
}

variable "cidr" {
  type        = string
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnets" {
  type        = map
  description = "Map of list of subnet cidr_blocks"
  default = {
    public   = ["10.0.1.0/24", "10.0.2.0/24"]
    private  = ["10.0.11.0/24", "10.0.12.0/24"]
    database = ["10.0.21.0/24", "10.0.22.0/24"]
  }
}

variable "existing_subnet_ids" {
  type        = map(list(string))
  default     = {}
  description = "Map subnet usage roles to existing list of subnet ids"
}

variable "existing_nat_id" {
  type = string
  default = null
  description = "Pre-existing VPC NAT Gateway id"
}

variable "enable_nat_gateway" {
  description = "Should be true if you want to provision NAT Gateways for each of your private networks"
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = "Should be true if you want to provision a single shared NAT Gateway across all of your private networks"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}


variable "tags" {
  description = "The tags to associate with your network and subnets."
  type        = map(string)
  default     = {}
}

variable "public_subnet_tags" {
  description = "Additional tags for the public subnets"
  type        = map(string)
  default     = {}
}

variable "private_subnet_tags" {
  description = "Additional tags for the private subnets"
  type        = map(string)
  default     = {}
}

variable "public_subnet_suffix" {
  description = "Suffix to append to public subnets name"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix to append to private subnets name"
  type        = string
  default     = "private"
}

variable "database_subnet_suffix" {
  description = "Suffix to append to database subnets name"
  type        = string
  default     = "db"
}

variable "map_public_ip_on_launch" {
  description = "Should be false if you do not want to auto-assign public IP on launch"
  type        = bool
  default     = false
}

variable "vpc_private_endpoints" {
   description = "Endpoints needed for private cluster"
   type        = list(string)
   default     = [ "ec2", "ecr.api", "ecr.dkr", "s3", "logs", "sts", "elasticloadbalancing", "autoscaling" ]
}

variable "region" {
  description = "Region"
  type        = string
  default     = "us-east-1"
}

variable "security_group_id" {
  description = "Security Group ID"
  type        = string
  default     = ""
}

## Main ##

terraform {
  required_version      = ">= 0.13"
  required_providers {
    aws                 = ">= 3.37.0"
  }
}

provider "aws" {
  profile               = var.aws_profile
  region                = var.aws_region
}

locals {
  # Common tags to be assigned to resources
  common_tags           = {
    Application         = var.app_name
    Environment         = var.aws_env
  }

}

output "ec2_private_dns" {
  value                 = aws_instance.test_instance.private_dns
}

output "ec2_instance_id" {
  value                 = aws_instance.test_instance.id
}

output "ec2_sg_id" {
  value                 = aws_security_group.ec2_sg.id
}

output "ec2_instance_profile_name" {
  value                 = aws_iam_instance_profile.ec2_instance_profile.name
}

output "vpc_id" {
  value                 = aws_vpc.vpc.id
}

output "subnet_id" {
  value                 = aws_subnet.priv_subnet.id
}

## Security Group attached to EC2 instance ##

resource "aws_security_group" "ec2_sg" {
  name                  = "ec2_sg"
  vpc_id                = aws_vpc.vpc.id

  # no ingress is needed to enble SSM session manager access

  egress {
    from_port           = 443
    to_port             = 443
    protocol            = "tcp"
    cidr_blocks         = [ aws_vpc.vpc.cidr_block ]
  }

  tags                  = local.common_tags
}

## Common Security Group for all VPC Endpoints to AWS services ##

resource "aws_security_group" "svc_vpce_sg" {
  name                  = "svc_vpce_sg"
  vpc_id                = aws_vpc.vpc.id

  ingress {
    cidr_blocks         = [ aws_vpc.vpc.cidr_block ]
    from_port           = 443
    to_port             = 443
    protocol            = "tcp"
  }

  # no egress port access is needed to enable SSM through VPC endpoints

  tags                  = local.common_tags
}

## EC2 Instance Profile and Execution Role ## 

resource "aws_iam_role" "ec2_ssm_exec_role" {
  name_prefix           = "${var.app_shortcode}-ec2-ssm-exec-role-"
  assume_role_policy    = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": [
          "ec2.amazonaws.com"
        ]
      },
      "Effect": "Allow",
      "Sid": "EC2ExecRole"
    }
  ]
}
EOF

  depends_on            = [ aws_iam_policy.ec2_ssm_exec_role_permissions ]
  tags                  = local.common_tags
}

# this custom policy is a replacement for AWS managed AmazonSSMManagedInstanceCore policy
# TODO: limit s3 access to specific bucket: arn:aws:s3:::DOC-EXAMPLE-BUCKET/s3-bucket-prefix/*
resource "aws_iam_policy" "ec2_ssm_exec_role_permissions" {
  name_prefix           = "${var.app_shortcode}-ec2-ssm-exec-role-permissions-"
  description           = "Provides EC2 instance access to SSM, S3 and CW Logs services"

  policy                = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "SSMPermissions"
        Action = [
          "ssm:UpdateInstanceInformation",
          "ssm:ListInstanceAssociations", 
          "ssm:DescribeInstanceProperties", 
          "ssm:DescribeDocumentParameters", 
          "ssm:StartSession",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Sid = "SSMMessagesPermissions"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel",
          "ssm:UpdateInstanceInformation"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Sid = "EC2MessagesPermissions"
        Action = [
          "ec2messages:AcknowledgeMessage",
          "ec2messages:DeleteMessage",
          "ec2messages:FailMessage",
          "ec2messages:GetEndpoint",
          "ec2messages:GetMessages",
          "ec2messages:SendReply",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Sid = "CWLogsPermissions"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Sid = "KMSPermissions"
        Action = [
          "kms:GenerateDataKey",
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Sid = "S3Permissions"
        Action = [
          "s3:GetEncryptionConfiguration",
          "s3:PutObject", 
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]        
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ssm_exec_role_policy" {
  role                  = aws_iam_role.ec2_ssm_exec_role.name
  policy_arn            = aws_iam_policy.ec2_ssm_exec_role_permissions.arn
}

resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name_prefix           = "${var.app_shortcode}-ec2-instance-profile-"
  role                  = aws_iam_role.ec2_ssm_exec_role.name
}

# get the most recent Amazon Linux 2 AMI
data "aws_ami" "ec2_ami" {
  most_recent           = true
  owners                = ["amazon"]

  filter {
    name                = "name"
    values              = ["amzn2-ami-hvm-2*"]
  }

  filter {
    name                = "architecture"
    values              = ["x86_64"]
  }

  filter {
    name                = "root-device-type"
    values              = ["ebs"]
  }

  filter {
    name                = "virtualization-type"
    values              = ["hvm"]
  }
}

# create a test ec2 instance to validate SSM session manager access and permissions
resource "aws_instance" "test_instance" {
  ami                   = data.aws_ami.ec2_ami.id
  instance_type         = "t3.small"

  subnet_id             = aws_subnet.priv_subnet.id
  source_dest_check     = false

  vpc_security_group_ids  = [ aws_security_group.ec2_sg.id ]
  iam_instance_profile    = aws_iam_instance_profile.ec2_instance_profile.name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}-test" }
  )
}

variable "aws_profile" {
  type                  = string
  default               = "default"
  description           = "Specify an aws profile name to use for access credentials"
}

variable "aws_env" {
  type                  = string
  default               = "dev"
  description           = "Specify a value for the Environment tag"
}

variable "aws_region" {
  type                  = string
  default               = "us-east-2"
  description           = "Specify the AWS region to be used for resource creations"
}

variable "app_name" {
  type                  = string
  description           = "Specify an application or project name, used primarily for tagging"
  default               = "benchmark-app"
}

variable "app_shortcode" {
  type                  = string
  description           = "Specify a short-code or pneumonic for this application or project"
  default               = "bmk"
}

## VPC ##

# use an RFC 1918 reserved IP range
variable "vpc_cidr" {
  type                  = string
  default               = "10.8.0.0/16"
  description           = "Specify CIDR range for VPC"
}

variable "vpc_name" {
  type                  = string
  default               = "packer_vpc"
  description           = "Specify a name for VPC for labeling purposes"
}

variable "priv_subnet_cidr" {
  type                  = string
  default               = "10.8.1.0/24"
  description           = "Specify a CIDR range for private subnet within VPC"
}

variable "priv_subnet_name" {
  type                  = string
  default               = "packer_subnet"
  description           = "Specify a name for private subnet for labeling purposes"
}

# -----
# Pulls data for AZs in the region

data "aws_availability_zones" "available_azs" {}

## VPC and Subnet ##

resource "aws_vpc" "vpc" {
  cidr_block            = var.vpc_cidr
  assign_generated_ipv6_cidr_block  = false
  enable_dns_support    = true
  enable_dns_hostnames  = true
  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}_${var.vpc_name}" }
  )
}

resource "aws_subnet" "priv_subnet" {
  vpc_id                = aws_vpc.vpc.id
  availability_zone     = data.aws_availability_zones.available_azs.names[0]
  cidr_block            = var.priv_subnet_cidr
  map_public_ip_on_launch = false
  tags                  = merge(
    local.common_tags, 
    { Name = var.priv_subnet_name }
  )
}

## VPC Endpoint to AWS Services required by SSM Session Manager ##

# com.amazonaws.region.ssm: The endpoint for the Systems Manager service
resource "aws_vpc_endpoint" "vpce_ssm" {
  service_name          = "com.amazonaws.${var.aws_region}.ssm"
  vpc_id                = aws_vpc.vpc.id
  subnet_ids            = [ aws_subnet.priv_subnet.id ]
  private_dns_enabled   = true

  auto_accept           = true
  vpc_endpoint_type     = "Interface"

  security_group_ids    = [ aws_security_group.svc_vpce_sg.id ]

  policy                = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "SSMRequiredPermissions"
        Principal = "*"
        Action = [
          "ssm:UpdateInstanceInformation",
          "ssm:ListInstanceAssociations", 
          "ssm:DescribeInstanceProperties", 
          "ssm:DescribeDocumentParameters", 
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]        
  })

  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}_ssm" }
  )
}

# com.amazonaws.region.ec2messages: Systems Manager uses this endpoint to make calls from SSM Agent to the Systems Manager service
resource "aws_vpc_endpoint" "vpce_ec2_messages" {
  service_name          = "com.amazonaws.${var.aws_region}.ec2messages"
  vpc_id                = aws_vpc.vpc.id
  subnet_ids            = [ aws_subnet.priv_subnet.id ]
  private_dns_enabled   = true

  auto_accept           = true
  vpc_endpoint_type     = "Interface"

  security_group_ids    = [ aws_security_group.svc_vpce_sg.id ]

  policy                = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "SSMRequiredPermissions"
        Principal = "*"
        Action = [
          "ec2messages:AcknowledgeMessage",
          "ec2messages:DeleteMessage",
          "ec2messages:FailMessage",
          "ec2messages:GetEndpoint",
          "ec2messages:GetMessages",
          "ec2messages:SendReply",
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]        
  })

  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}_ec2_messages" }
  )
}

# com.amazonaws.region.ssmmessages: This endpoint is required to connect to your instances through a secure data channel using Session Manager 
resource "aws_vpc_endpoint" "vpce_ssm_messages" {
  service_name          = "com.amazonaws.${var.aws_region}.ssmmessages"
  vpc_id                = aws_vpc.vpc.id
  subnet_ids            = [ aws_subnet.priv_subnet.id ]
  private_dns_enabled   = true

  auto_accept           = true
  vpc_endpoint_type     = "Interface"

  security_group_ids    = [ aws_security_group.svc_vpce_sg.id ]

  policy                = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "SSMRequiredPermissions"
        Principal = "*"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel",
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]        
  })

  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}_ssm_messages" }
  )
}

resource "aws_vpc_endpoint" "vpce_cw_logs" {
  service_name          = "com.amazonaws.${var.aws_region}.logs"
  vpc_id                = aws_vpc.vpc.id
  subnet_ids            = [ aws_subnet.priv_subnet.id ]
  private_dns_enabled   = true

  auto_accept           = true
  vpc_endpoint_type     = "Interface"

  security_group_ids    = [ aws_security_group.svc_vpce_sg.id ]

  policy                = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "SSMRequiredPermissions"
        Principal = "*"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]        
  })

  tags                  = merge(
    local.common_tags, 
    { Name = "${var.app_shortcode}_cw_logs" }
  )
}

resource "aws_ecr_repository" "foo" {
  name                 = "${local.prefix}-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-fargate-cluster"
  tags = merge(
    local.common_tags,
    {
      Name = "${local.prefix}-fargate-cluster"
    }
  )
}

locals {
  aws_account_id = data.aws_caller_identity.current.account_id
  service_name = "nginx"
  task_image = "${local.aws_account_id}.dkr.ecr.${local.aws_region}.amazonaws.com/${local.prefix}-${local.service_name}:latest"
  service_port = 80
  service_namespace_id = aws_service_discovery_private_dns_namespace.app.id
  container_definition = [{
    cpu         = 512
    image       = local.task_image
    memory      = 1024
    name        = local.service_name
    networkMode = "awsvpc"
    environment = [
      {
        "name": "SERVICE_DISCOVERY_NAMESPACE_ID", "value": local.service_namespace_id
      }
    ]
    portMappings = [
      {
        protocol      = "tcp"
        containerPort = local.service_port
        hostPort      = local.service_port
      }
    ]
    logConfiguration = {
      logdriver = "awslogs"
      options = {
        "awslogs-group"         = local.cw_log_group
        "awslogs-region"        = data.aws_region.current.name
        "awslogs-stream-prefix" = "stdout"
      }
    }
  }]
  cw_log_group = "/ecs/${local.service_name}"
}

# Fargate service

resource "aws_security_group" "fargate_task" {
  name   = "${local.service_name}-fargate-task"
  vpc_id = module.vpc.vpc_id

  ingress {
    from_port   = local.service_port
    to_port     = local.service_port
    protocol    = "tcp"
    cidr_blocks = [module.vpc.vpc_cidr_block]
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.trivy_scope_1.cidr_block]
  }

  tags = merge(
  local.common_tags,
  {
    Name = local.service_name
  }
  )
}

data "aws_iam_policy_document" "fargate-role-policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com", "ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "fargate_execution" {
  name   = "fargate_execution_policy"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
        "Effect": "Allow",
        "Action": [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetAuthorizationToken",
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
        ],
        "Resource": "*"
    },
    {
        "Effect": "Allow",
        "Action": [
            "ssm:GetParameters",
            "secretsmanager:GetSecretValue",
            "kms:Decrypt"
        ],
        "Resource": [
            "*"
        ]
    }
  ]
}
EOF
}

resource "aws_iam_policy" "fargate_task" {
  name   = "fargate_task_policy"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
        "Effect": "Allow",
        "Action": [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
        ],
        "Resource": "*"
    },
    {
        "Effect": "Allow",
        "Action": [
            "servicediscovery:ListServices",
            "servicediscovery:ListInstances"
        ],
        "Resource": "*"
    }
  ]
}
EOF
}

resource "aws_iam_role" "fargate_execution" {
  name               = "${local.service_name}-fargate-execution-role"
  assume_role_policy = data.aws_iam_policy_document.fargate-role-policy.json
}

resource "aws_iam_role" "fargate_task" {
  name               = "${local.service_name}-fargate-task-role"
  assume_role_policy = data.aws_iam_policy_document.fargate-role-policy.json
}
resource "aws_iam_role_policy_attachment" "fargate-execution" {
  role       = aws_iam_role.fargate_execution.name
  policy_arn = aws_iam_policy.fargate_execution.arn
}
resource "aws_iam_role_policy_attachment" "fargate-task" {
  role       = aws_iam_role.fargate_task.name
  policy_arn = aws_iam_policy.fargate_task.arn
}

# Fargate Container
resource "aws_cloudwatch_log_group" "app" {
  name = local.cw_log_group
  tags = merge(
    local.common_tags,
    {
      Name = local.service_name
    }
  )
}

resource "aws_ecs_task_definition" "app" {
  family                   = local.service_name
  network_mode             = "awsvpc"
  cpu                      = local.container_definition.0.cpu
  memory                   = local.container_definition.0.memory
  requires_compatibilities = ["FARGATE"]
  container_definitions    = jsonencode(local.container_definition)
  execution_role_arn       = aws_iam_role.fargate_execution.arn
  task_role_arn            = aws_iam_role.fargate_task.arn
  tags = merge(
    local.common_tags,
    {
      Name = local.service_name
    }
  )
}

resource "aws_ecs_service" "app" {
  name            = local.service_name
  cluster         = aws_ecs_cluster.main.name
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = "1"
  launch_type     = "FARGATE"

  service_registries {
    registry_arn = aws_service_discovery_service.app_service.arn
    container_name = local.service_name
    container_port = local.service_port
  }

  network_configuration {
    security_groups = [aws_security_group.fargate_task.id]
    subnets         = module.vpc.private_subnets
  }
}

resource "aws_service_discovery_service" "app_service" {
  name = local.service_name

  dns_config {
    namespace_id = local.service_namespace_id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

locals {
  demo_ec2_instance_type = "t3.micro"
}

# Latest Amazon Linux 2 AMI

data "aws_ami" "amazon_linux_2" {
  most_recent = true

  filter {
    name   = "owner-alias"
    values = ["amazon"]
  }

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  owners = ["amazon"]
}

# EC2 client Instance Profile

resource "aws_iam_instance_profile" "ec2_client" {
  name = "${local.prefix}-ec2-client"
  role = aws_iam_role.ec2_client.name
}

resource "aws_iam_role" "ec2_client" {
  name = "${local.prefix}-ec2-client"
  path = "/"

  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Action": "sts:AssumeRole",
            "Principal": {
               "Service": "ec2.amazonaws.com"
            },
            "Effect": "Allow",
            "Sid": ""
        }
    ]
}
EOF
}

# EC2 client Security Group

resource "aws_security_group" "ec2_client" {
  name   = "${local.prefix}-ec2-client"
  vpc_id = module.vpc.vpc_id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [module.vpc.vpc_cidr_block]
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.trivy_scope_1.cidr_block]
  }

  tags = merge(
  local.common_tags,
  {
    Name = "${local.prefix}-ec2-client"
  }
  )
}

# EC2 client instance

resource "aws_iam_policy_attachment" "ec2_client" {
  name       = "${local.prefix}-ec2-client-role-attachment"
  roles      = [aws_iam_role.ec2_client.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_network_interface" "ec2_client" {
  subnet_id   = module.vpc.public_subnets[0]
  private_ips = ["10.0.100.101"]
  security_groups = [aws_security_group.ec2_client.id]
}

resource "aws_instance" "ec2_client" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = local.demo_ec2_instance_type
  availability_zone    = "${local.aws_region}a"
  iam_instance_profile = aws_iam_instance_profile.ec2_client.name

  network_interface {
    network_interface_id = aws_network_interface.ec2_client.id
    device_index         = 0
  }

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.prefix}-ec2-client"
    }
  )
}

locals {
  aws_region  = "us-east-1"
  prefix      = "private-fargate-crowdnews"
  common_tags = {
    Project         = local.prefix
    ManagedBy       = "Terraform"
  }
  vpc_cidr = "10.0.0.0/16"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

output "nginx_test" {
  value = "curl http://${aws_ecs_service.app.name}.${aws_service_discovery_private_dns_namespace.app.name}"
}

# VPC CIDRs used to scope security-group rules that previously allowed 0.0.0.0/0
# (Trivy AWS-0104 unrestricted egress / AWS-0107 admin ports open to the internet).

data "aws_vpc" "trivy_scope_1" {
  id = module.vpc.vpc_id
}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = "${local.prefix}-vpc"
  cidr = local.vpc_cidr

  azs             = ["${local.aws_region}a", "${local.aws_region}b", "${local.aws_region}c"]
  private_subnets = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.100.0/24", "10.0.101.0/24", "10.0.102.0/24"]

  enable_nat_gateway      = true
  single_nat_gateway      = false
  one_nat_gateway_per_az  = true
  enable_vpn_gateway      = false
  enable_dns_hostnames    = true
  enable_dns_support      = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.prefix}-vpc"
    }
  )
}

resource "aws_service_discovery_private_dns_namespace" "app" {
  name        = "${local.prefix}.hands-on.cloud.local"
  description = "${local.prefix}.hands-on.cloud.local zone"
  vpc         = module.vpc.vpc_id
}

# VPC Endpoint Security Group

resource "aws_security_group" "vpc_endpoint" {
  name   = "${local.prefix}-vpce-sg"
  vpc_id = module.vpc.vpc_id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [module.vpc.vpc_cidr_block]
  }
  tags = local.common_tags
}

# VPC Endpoints

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = module.vpc.private_route_table_ids

  tags = {
    Name        = "s3-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "dkr" {
  vpc_id              = module.vpc.vpc_id
  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "dkr-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "dkr_api" {
  vpc_id              = module.vpc.vpc_id
  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "dkr-api-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = module.vpc.vpc_id

  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "logs-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = module.vpc.vpc_id

  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "secretsmanager-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = module.vpc.vpc_id

  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "ssm-endpoint"
    Environment = "dev"
  }
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = module.vpc.vpc_id

  private_dns_enabled = true
  service_name        = "com.amazonaws.${data.aws_region.current.name}.kms"
  vpc_endpoint_type   = "Interface"
  security_group_ids = [
    aws_security_group.vpc_endpoint.id,
  ]
  subnet_ids = module.vpc.private_subnets

  tags = {
    Name        = "kms-endpoint"
    Environment = "dev"
  }
}

