#--------------------------------------------------------------
# Locals
#--------------------------------------------------------------
locals {
  tags = {
    for k, v in(var.tags == null ? {} : var.tags) : k => v if lookup(data.aws_default_tags.provider.tags, k, null) == null || lookup(data.aws_default_tags.provider.tags, k, null) != v
  }
}
#--------------------------------------------------------------
# Use this data source to get the default tags configured on the provider.
#--------------------------------------------------------------
data "aws_default_tags" "provider" {}

#--------------------------------------------------------------
# role: ecs.amazonaws.com
#--------------------------------------------------------------
resource "aws_iam_role" "ecs" {
  description           = lookup(var.aws_iam_role.ecs, "description", null)
  name                  = lookup(var.aws_iam_role.ecs, "name")
  assume_role_policy    = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ecs.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY
  force_detach_policies = true
  path                  = lookup(var.aws_iam_role.ecs, "path", "/")
  tags                  = local.tags
}

#--------------------------------------------------------------
# Attaches a Managed IAM Policy to an IAM role
# policy attach: AmazonEC2ContainerServiceRole
#--------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "ecs" {
  role       = aws_iam_role.ecs.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

#--------------------------------------------------------------
# role: ecs-tasks.amazonaws.com
# https://docs.aws.amazon.com/ja_jp/AmazonECS/latest/developerguide/task_execution_IAM_role.html
#--------------------------------------------------------------
resource "aws_iam_role" "ecs_tasks" {
  description           = lookup(var.aws_iam_role.ecs_tasks, "description", null)
  name                  = lookup(var.aws_iam_role.ecs_tasks, "name")
  assume_role_policy    = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ecs-tasks.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY
  force_detach_policies = true
  path                  = lookup(var.aws_iam_role.ecs_tasks, "path", "/")
  tags                  = local.tags
}

#--------------------------------------------------------------
# Attaches a Managed IAM Policy to an IAM role
# policy attach: AmazonECSTaskExecutionRolePolicy
#--------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "ecs_tasks" {
  role       = aws_iam_role.ecs_tasks.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

#--------------------------------------------------------------
# events.amazonaws.com
#--------------------------------------------------------------
resource "aws_iam_role" "events" {
  description           = lookup(var.aws_iam_role.events, "description", null)
  name                  = lookup(var.aws_iam_role.events, "name")
  assume_role_policy    = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "events.amazonaws.com"
      },
      "Effect": "Allow"
    }
  ]
}
POLICY
  force_detach_policies = true
  path                  = lookup(var.aws_iam_role.events, "path", "/")
  tags                  = local.tags
}
#--------------------------------------------------------------
# Generates an IAM policy document in JSON format for use with resources that expect policy documents such as aws_iam_policy.
#--------------------------------------------------------------
#tfsec:ignore:aws-iam-no-policy-wildcards
data "aws_iam_policy_document" "this" {
  statement {
    effect = "Allow"
    actions = [
      "ecs:RunTask"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.ecs_tasks.arn,
    ]
  }
}

#--------------------------------------------------------------
# Provides an IAM policy.
#--------------------------------------------------------------
#tfsec:ignore:AWS099
resource "aws_iam_policy" "events" {
  description = lookup(var.aws_iam_policy.events, "description", null)
  name        = lookup(var.aws_iam_policy.events, "name")
  path        = lookup(var.aws_iam_policy.events, "path", "/")
  policy      = data.aws_iam_policy_document.this.json
}
#--------------------------------------------------------------
# Attaches a Managed IAM Policy to an IAM role
# policy attach: ECS runtask
#--------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "events" {
  role       = aws_iam_role.events.name
  policy_arn = aws_iam_policy.events.arn
}
#--------------------------------------------------------------
# Attaches a Managed IAM Policy to an IAM role
# events.amazonaws.com role adds CloudWatchLogsFullAccess policy
#--------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "cloudwatch_logs" {
  role       = aws_iam_role.events.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

output "ecs_arn" {
  description = "Amazon Resource Name (ARN) specifying the role."
  value       = aws_iam_role.ecs.arn
}
output "ecs_name" {
  description = "Name of the role."
  value       = aws_iam_role.ecs.name
}
output "ecs_tasks_arn" {
  description = "Amazon Resource Name (ARN) specifying the role."
  value       = aws_iam_role.ecs_tasks.arn
}
output "ecs_tasks_name" {
  description = "Name of the role."
  value       = aws_iam_role.ecs_tasks.name
}
output "events_arn" {
  description = "Amazon Resource Name (ARN) specifying the role."
  value       = aws_iam_role.events.arn
}
output "events_name" {
  description = "Name of the role."
  value       = aws_iam_role.events.name
}

#--------------------------------------------------------------
# module variables
#--------------------------------------------------------------
variable "aws_iam_role" {
  type = object(
    {
      ecs = object({
        # Description of the role.
        description = string
        # Friendly name of the role. If omitted, Terraform will assign a random, unique name. See IAM Identifiers for more information.
        name = string
        # Path to the role. See IAM Identifiers for more information.
        path = string
        }
      )
      ecs_tasks = object({
        # Description of the role.
        description = string
        # Friendly name of the role. If omitted, Terraform will assign a random, unique name. See IAM Identifiers for more information.
        name = string
        # Path to the role. See IAM Identifiers for more information.
        path = string
        }
      )
      events = object({
        # Description of the role.
        description = string
        # Friendly name of the role. If omitted, Terraform will assign a random, unique name. See IAM Identifiers for more information.
        name = string
        # Path to the role. See IAM Identifiers for more information.
        path = string
        }
      )
    }
  )
  description = "(Optional) Provides an IAM role."
  default = {
    ecs = {
      description = "Role for ECS."
      name        = "ecs-role"
      path        = "/"
    }
    ecs_tasks = {
      description = "Role for ECS Task."
      name        = "ecs-tasks-role"
      path        = "/"
    }
    events = {
      description = "Role for Events."
      name        = "events-role"
      path        = "/"
    }
  }

}
variable "aws_iam_policy" {
  type = object(
    {
      events = object({
        # Description of the IAM policy.
        description = string
        # The name of the policy. If omitted, Terraform will assign a random, unique name.
        name = string
        # Path in which to create the policy. See IAM Identifiers for more information.
        path = string
        }
      )
    }
  )
  description = "(Optional) Provides an IAM policy."
  default = {
    events = {
      description = "Policy for ECS."
      name        = "ecs-policy"
      path        = "/"
    }
  }

}
variable "tags" {
  type        = map(any)
  description = "(Optional) Key-value mapping of tags for the IAM role"
  default     = null
}

#--------------------------------------------------------------
# Terraform Provider
#--------------------------------------------------------------
terraform {
  required_version = "~>1.4"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~>4.67.0"
    }
  }
}

data "aws_caller_identity" "current" {
  provider = aws.primary_region
}
data "aws_partition" "current" {
  provider = aws.primary_region
}
data "aws_iam_policy_document" "assume_role" {
  provider = aws.primary_region
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

output "multi_access_point_status" {
  value = aws_s3control_multi_region_access_point.example.status
  description = "Status of multi_region_access_point"
}
output "multi_access_point_alias" {
  value = aws_s3control_multi_region_access_point.example.alias
  description = "alias of multi_region_access_point"
}
output "multi_access_point_domain_name" {
  value = aws_s3control_multi_region_access_point.example.domain_name
  description = "domain_name of multi_region_access_point"
}

output "multi_access_point_arn" {
  value = aws_s3control_multi_region_access_point.example.arn
  description = "arn of multi_region_access_point"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  alias  = "primary_region"
  default_tags {
    tags = {
      Environment = "Primary-Region"
      Name        = "Devopscaptain"
    }
  }
}

provider "aws" {
  region = "us-west-2"
  alias  = "secondary_region"
  default_tags {
    tags = {
      Environment = "Secondary-Region"
      Name        = "Devopscaptain"
    }
  }
}

resource "aws_iam_role" "replication" {
  provider           = aws.primary_region
  name               = "devopscaptain-tf-iam-role-replication"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "aws_iam_policy_document" "replication" {
  provider = aws.primary_region
  statement {
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.primary.arn]
  }

  statement {
    effect    = "Allow"
    actions   = ["kms:Encrypt"]
    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_policy" "replication" {
  provider = aws.primary_region
  name     = "devopscaptain-iam-role-policy-replication"
  policy   = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  provider   = aws.primary_region
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

resource "aws_s3_bucket_replication_configuration" "replication" {
  provider   = aws.primary_region
  depends_on = [aws_s3_bucket_versioning.primary]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "rule-1"
    status = "Enabled"

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

###### Create S3 Bucket in primary region ####

resource "aws_s3_bucket" "primary" {
  provider = aws.primary_region
  bucket   = "${var.primary_bucket_name}-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket   = aws_s3_bucket.primary.id
  provider = aws.primary_region
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  depends_on = [aws_s3_bucket_ownership_controls.primary]
  bucket     = aws_s3_bucket.primary.id
  provider   = aws.primary_region
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
  provider = aws.primary_region
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  provider                = aws.primary_region
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "primary" {
  provider            = aws.primary_region
  description         = "CMK for ${var.primary_bucket_name}"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket   = aws_s3_bucket.primary.id
  provider = aws.primary_region
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
  }
}




###### Create S3 Bucket in  secondary region ####
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary_region
  bucket   = "${var.secondary_bucket_name}-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  bucket   = aws_s3_bucket.secondary.id
  provider = aws.secondary_region
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
  bucket     = aws_s3_bucket.secondary.id
  provider   = aws.secondary_region
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "secondary" {
  bucket = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
  provider = aws.secondary_region
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  bucket                  = aws_s3_bucket.secondary.id
  provider                = aws.secondary_region
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "secondary" {
  provider            = aws.secondary_region
  description         = "CMK for ${var.secondary_bucket_name}"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  bucket   = aws_s3_bucket.secondary.id
  provider = aws.secondary_region
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
  }
}

resource "aws_s3control_multi_region_access_point" "example" {
  # S3 Control's Multi-Region Access Point API must be called against
  # us-west-2 regardless of where the underlying buckets live (a documented
  # AWS requirement) -- secondary_region is us-west-2 in provider.tf.
  provider = aws.secondary_region
  details {
    name = var.access_point_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "example" {
  provider = aws.secondary_region
  details {
    name = element(split(":", aws_s3control_multi_region_access_point.example.id), 1)
    policy = jsonencode({
      "Version" : "2012-10-17",
      "Statement" : [
        {
          "Sid" : "Example",
          "Effect" : "Allow",
          "Principal" : {
            "AWS" : data.aws_caller_identity.current.account_id
          },
          "Action" : ["s3:GetObject", "s3:PutObject"],
          "Resource" : "arn:${data.aws_partition.current.partition}:s3::${data.aws_caller_identity.current.account_id}:accesspoint/${aws_s3control_multi_region_access_point.example.alias}/object/*"
        }
      ]
    })
  }
}

variable "primary_bucket_name" {
  type        = string
  default = "example1"
  description = "primary bucket name to be created for multi_region_access_point"
}

variable "secondary_bucket_name" {
  type        = string
  default = "example2"
  description = "secondary bucket name to be created for multi_region_access_point"
}

variable "access_point_name" {
  type    = string
  default = "example-mrap"
  description = "Name for multi_region_access_point"
}

#
# ONLY EDIT THIS FILE IN github.com/cloudposse/terraform-null-label
# All other instances of this file should be a copy of that one
#
#
# Copy this file from https://github.com/cloudposse/terraform-null-label/blob/master/exports/context.tf
# and then place it in your Terraform module to automatically get
# Cloud Posse's standard configuration inputs suitable for passing
# to Cloud Posse modules.
#
# curl -sL https://raw.githubusercontent.com/cloudposse/terraform-null-label/master/exports/context.tf -o context.tf
#
# Modules should access the whole context as `module.this.context`
# to get the input variables with nulls for defaults,
# for example `context = module.this.context`,
# and access individual variables as `module.this.<var>`,
# with final values filled in.
#
# For example, when using defaults, `module.this.context.delimiter`
# will be null, and `module.this.delimiter` will be `-` (hyphen).
#

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0" # requires Terraform >= 0.13.0

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

# Copy contents of cloudposse/terraform-null-label/variables.tf here

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = null
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    # Note: we have to use [] instead of null for unset lists due to
    # https://github.com/hashicorp/terraform/issues/28137
    # which was not fixed until Terraform 1.0.0,
    # but we want the default to be all the labels in `label_order`
    # and we want users to be able to prevent all tag generation
    # by setting `labels_as_tags` to `[]`, so we need
    # a different sentinel to indicate "default"
    labels_as_tags = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = null
  description = <<-EOT
    ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'.
    This is the only ID element not also included as a `tag`.
    The "name" tag is set to the full `id` string. There is no tag with the value of the `name` input.
    EOT
}

variable "delimiter" {
  type        = string
  default     = null
  description = <<-EOT
    Delimiter to be used between ID elements.
    Defaults to `-` (hyphen). Set to `""` to use no delimiter at all.
  EOT
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = <<-EOT
    ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`,
    in the order they appear in the list. New attributes are appended to the
    end of the list. The elements of the list are joined by the `delimiter`
    and treated as a single ID element.
    EOT
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = <<-EOT
    Set of labels (ID elements) to include as tags in the `tags` output.
    Default is to include all labels.
    Tags with empty values will not be included in the `tags` output.
    Set to `[]` to suppress all generated tags.
    **Notes:**
      The value of the `name` tag, if included, will be the `id`, not the `name`.
      Unlike other `null-label` inputs, the initial setting of `labels_as_tags` cannot be
      changed in later chained modules. Attempts to change it will be silently ignored.
    EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`).
    Neither the tag keys nor the tag values will be modified by this module.
    EOT
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional key-value pairs to add to each map in `tags_as_list_of_maps`. Not added to `tags` or `id`.
    This is for some rare cases where resources want additional configuration of tags
    and therefore take a list of maps with tag key, value, and additional configuration.
    EOT
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = <<-EOT
    The order in which the labels (ID elements) appear in the `id`.
    Defaults to ["namespace", "environment", "stage", "name", "attributes"].
    You can omit any of the 6 labels ("tenant" is the 6th), but at least one must be present.
    EOT
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = <<-EOT
    Terraform regular expression (regex) string.
    Characters matching the regex will be removed from the ID elements.
    If not set, `"/[^a-zA-Z0-9-]/"` is used to remove all characters other than hyphens, letters and digits.
  EOT
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = <<-EOT
    Limit `id` to this many characters (minimum 6).
    Set to `0` for unlimited length.
    Set to `null` for keep the existing setting, which defaults to `0`.
    Does not affect `id_full`.
  EOT
  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of the `tags` keys (label names) for tags generated by this module.
    Does not affect keys of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper`.
    Default value: `title`.
  EOT

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of ID elements (labels) as included in `id`,
    set as tag values, and output by this module individually.
    Does not affect values of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper` and `none` (no transformation).
    Set this to `title` and set `delimiter` to `""` to yield Pascal Case IDs.
    Default value: `lower`.
  EOT

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = <<-EOT
    Describe additional descriptors to be output in the `descriptors` output map.
    Map of maps. Keys are names of descriptors. Values are maps of the form
    `{
       format = string
       labels = list(string)
    }`
    (Type is `any` so the map values can later be enhanced to provide additional options.)
    `format` is a Terraform format string to be passed to the `format()` function.
    `labels` is a list of labels, in order, to pass to `format()` function.
    Label values will be normalized before being passed to `format()` so they will be
    identical to how they appear in `id`.
    Default is `{}` (`descriptors` output will be empty).
    EOT
}

#### End of copy of cloudposse/terraform-null-label/variables.tf

locals {
  enabled = module.this.enabled
}

data "aws_caller_identity" "current" {
  count = local.enabled ? 1 : 0
}

data "aws_partition" "current" {
  count = local.enabled ? 1 : 0
}

module "scan_window_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled    = local.enabled
  attributes = ["scan-window"]
  context    = module.this.context
}

resource "aws_ssm_maintenance_window" "scan_window" {
  count    = local.enabled ? 1 : 0
  name     = module.scan_window_label.id
  schedule = var.scan_maintenance_window_schedule
  duration = var.scan_maintenance_window_duration
  cutoff   = var.scan_maintenance_window_cutoff
}

resource "aws_ssm_maintenance_window_task" "task_scan_patches" {
  count            = local.enabled ? 1 : 0
  window_id        = aws_ssm_maintenance_window.scan_window[0].id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = var.task_scan_priority
  service_role_arn = var.service_role_arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = aws_ssm_maintenance_window_target.target_scan[*].id
  }

  task_invocation_parameters {
    run_command_parameters {
      parameter {
        name   = "Operation"
        values = ["Scan"]
      }
      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
      output_s3_bucket     = var.s3_log_output_enabled ? local.bucket_id : null
      output_s3_key_prefix = var.s3_log_output_enabled ? var.s3_bucket_prefix_scan_logs : null
      service_role_arn     = var.sns_notification_role_arn

      dynamic "notification_config" {
        for_each = var.scan_sns_notification_enabled ? [1] : []
        content {
          notification_arn    = var.notification_arn
          notification_events = var.notification_events
          notification_type   = var.notification_type
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_log_output_enabled ? [1] : []
        content {
          cloudwatch_output_enabled = var.cloudwatch_log_output_enabled
          cloudwatch_log_group_name = var.cloudwatch_log_group_name
        }
      }
    }
  }
}

resource "aws_ssm_maintenance_window_target" "target_scan" {
  count         = local.enabled ? 1 : 0
  window_id     = aws_ssm_maintenance_window.scan_window[0].id
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = toset(var.scan_maintenance_windows_targets)
    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }

  dynamic "targets" {
    for_each = length(var.scan_maintenance_windows_targets) == 0 ? [1] : []
    content {
      key    = "tag:Patch Group"
      values = var.scan_patch_groups
    }
  }
}

# Maintenance Windows for patching

module "install_window_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled    = local.enabled
  attributes = ["install-window"]
  context    = module.this.context
}

resource "aws_ssm_maintenance_window" "install_window" {
  count    = local.enabled ? 1 : 0
  name     = module.install_window_label.id
  schedule = var.install_maintenance_window_schedule
  duration = var.install_maintenance_window_duration
  cutoff   = var.install_maintenance_window_cutoff
}

resource "aws_ssm_maintenance_window_task" "task_install_patches" {
  count            = local.enabled ? 1 : 0
  window_id        = aws_ssm_maintenance_window.install_window[0].id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = var.task_install_priority
  service_role_arn = var.service_role_arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = aws_ssm_maintenance_window_target.target_install[*].id
  }

  task_invocation_parameters {
    run_command_parameters {
      parameter {
        name   = "Operation"
        values = ["Install"]
      }
      parameter {
        name   = "RebootOption"
        values = [var.reboot_option]
      }
      output_s3_bucket     = var.s3_log_output_enabled ? local.bucket_id : null
      output_s3_key_prefix = var.s3_log_output_enabled ? var.s3_bucket_prefix_scan_logs : null
      service_role_arn     = var.sns_notification_role_arn

      dynamic "notification_config" {
        for_each = var.install_sns_notification_enabled ? [1] : []
        content {
          notification_arn    = var.notification_arn
          notification_events = var.notification_events
          notification_type   = var.notification_type
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_log_output_enabled ? [1] : []
        content {
          cloudwatch_output_enabled = var.cloudwatch_log_output_enabled
          cloudwatch_log_group_name = var.cloudwatch_log_group_name
        }
      }
    }
  }
}

resource "aws_ssm_maintenance_window_target" "target_install" {
  count         = local.enabled ? 1 : 0
  window_id     = aws_ssm_maintenance_window.install_window[0].id
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = toset(var.install_maintenance_windows_targets)
    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }

  dynamic "targets" {
    for_each = length(var.install_maintenance_windows_targets) == 0 ? [1] : []
    content {
      key    = "tag:Patch Group"
      values = var.install_patch_groups
    }
  }
}

# Patch Baselines
resource "aws_ssm_patch_baseline" "baseline" {
  count            = local.enabled ? 1 : 0
  name             = "${module.this.id}-${var.operating_system}"
  description      = "${var.operating_system} baseline"
  operating_system = var.operating_system

  approved_patches                  = var.approved_patches
  rejected_patches                  = var.rejected_patches
  approved_patches_compliance_level = var.approved_patches_compliance_level

  dynamic "approval_rule" {
    for_each = toset(var.patch_baseline_approval_rules)
    content {

      approve_after_days  = approval_rule.value.approve_after_days
      approve_until_date  = approval_rule.value.approve_until_date
      compliance_level    = approval_rule.value.compliance_level
      enable_non_security = approval_rule.value.enable_non_security

      # https://docs.aws.amazon.com/cli/latest/reference/ssm/describe-patch-properties.html
      dynamic "patch_filter" {
        for_each = approval_rule.value.patch_baseline_filters

        content {
          key    = patch_filter.value.name
          values = patch_filter.value.values
        }
      }
    }
  }

  tags = module.this.tags
}

resource "aws_ssm_patch_group" "install_patchgroup" {
  count       = (local.enabled ? 1 : 0) * length(var.install_patch_groups)
  baseline_id = aws_ssm_patch_baseline.baseline[0].id
  patch_group = element(var.install_patch_groups, count.index)
}

resource "aws_ssm_patch_group" "scan_patchgroup" {
  count       = (local.enabled ? 1 : 0) * length(var.scan_patch_groups)
  baseline_id = aws_ssm_patch_baseline.baseline[0].id
  patch_group = element(var.scan_patch_groups, count.index)
}

output "ssm_patch_log_s3_bucket_id" {
  description = "SSM Patch Manager s3 log bucket ID"
  value       = local.create_log_bucket ? join("", module.ssm_patch_log_s3_bucket[*].bucket_id) : ""
}

output "ssm_patch_log_s3_bucket_arn" {
  description = "SSM Patch Manager s3 log bucket ARN"
  value       = local.create_log_bucket ? join("", module.ssm_patch_log_s3_bucket[*].bucket_arn) : ""
}

output "scan_maintenance_window_task_id" {
  description = "SSM Patch Manager scan maintenance windows task ID"
  value       = try(aws_ssm_maintenance_window_task.task_scan_patches[0].id, "")
}

output "install_maintenance_window_task_id" {
  description = "SSM Patch Manager install maintenance windows task ID"
  value       = try(aws_ssm_maintenance_window_task.task_install_patches[0].id, "")
}

output "scan_maintenance_window_target_id" {
  description = "SSM Patch Manager scan maintenance window target ID"
  value       = try(aws_ssm_maintenance_window_target.target_scan[0].id, "")
}

output "install_maintenance_window_target_id" {
  description = "SSM Patch Manager install maintenance window target ID"
  value       = try(aws_ssm_maintenance_window_target.target_install[0].id, "")
}

output "install_maintenance_window_id" {
  description = "SSM Patch Manager install maintenance window ID"
  value       = try(aws_ssm_maintenance_window.install_window[0].id, "")
}

output "patch_baseline_arn" {
  description = "SSM Patch Manager patch baseline ARN"
  value       = try(aws_ssm_patch_baseline.baseline[0].arn, "")
}

output "install_patch_group_id" {
  description = "SSM Patch Manager install patch group ID"
  value       = try(aws_ssm_patch_group.install_patchgroup[0].id, "")
}

output "scan_patch_group_id" {
  description = "SSM Patch Manager scan patch group ID"
  value       = try(aws_ssm_patch_group.scan_patchgroup[0].id, "")
}

locals {
  account_id        = join("", data.aws_caller_identity.current[*].account_id)
  aws_partition     = join("", data.aws_partition.current[*].partition)
  create_log_bucket = local.enabled && length(var.bucket_id) > 0
  bucket_id         = local.create_log_bucket ? var.bucket_id[0] : module.this.id
  bucket_policy     = var.ssm_bucket_policy != null ? var.ssm_bucket_policy : try(data.aws_iam_policy_document.bucket_policy[0].json, "")
}

data "aws_iam_policy_document" "bucket_policy" {
  count = local.create_log_bucket ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:GetEncryptionConfiguration",
    ]

    resources = [
      format("arn:%s:s3:::%s", local.aws_partition, module.this.id),
      format("arn:%s:s3:::%s/*", local.aws_partition, module.this.id)
    ]

    principals {
      identifiers = [format("arn:%s:iam::%s:root", local.aws_partition, local.account_id)]
      type        = "AWS"
    }
  }
}

module "ssm_patch_log_s3_bucket" {
  count   = local.create_log_bucket ? 1 : 0
  source  = "cloudposse/s3-bucket/aws"
  version = "4.0.1"

  acl                     = "private"
  versioning_enabled      = var.ssm_bucket_versioning_enable
  source_policy_documents = [local.bucket_policy]
  context                 = module.this.context
}

variable "scan_maintenance_window_duration" {
  description = "The duration of the maintenence windows (hours)"
  type        = number
  default     = 3
}

variable "scan_maintenance_window_cutoff" {
  description = "The number of hours before the end of the Maintenance Window that Systems Manager stops scheduling new tasks for execution"
  type        = number
  default     = 1
}

variable "install_maintenance_window_duration" {
  description = "The duration of the maintenence windows (hours)"
  type        = number
  default     = 3
}

variable "install_maintenance_window_cutoff" {
  description = "The number of hours before the end of the Maintenance Window that Systems Manager stops scheduling new tasks for execution"
  type        = number
  default     = 1
}

variable "max_concurrency" {
  description = "The maximum number of targets this task can be run for in parallel"
  type        = number
  default     = 20
}

variable "max_errors" {
  description = "The maximum number of errors allowed before this task stops being scheduled"
  type        = number
  default     = 50
}

variable "service_role_arn" {
  description = "The role that should be assumed when executing the task. If a role is not provided, Systems Manager uses your account's service-linked role. If no service-linked role for Systems Manager exists in your account, it is created for you"
  type        = string
  default     = null
}

variable "reboot_option" {
  description = "When you choose the RebootIfNeeded option, the instance is rebooted if Patch Manager installed new patches, or if it detected any patches with a status of INSTALLED_PENDING_REBOOT during the Install operation. Possible values : RebootIfNeeded, NoReboot"
  type        = string
  default     = "RebootIfNeeded"
}

variable "notification_events" {
  description = "The different events for which you can receive notifications. Valid values: All, InProgress, Success, TimedOut, Cancelled, and Failed"
  type        = list(string)
  default     = ["All"]
}

variable "notification_type" {
  description = "When specified with Command, receive notification when the status of a command changes. When specified with Invocation, for commands sent to multiple instances, receive notification on a per-instance basis when the status of a command changes. Valid values: Command and Invocation"
  type        = string
  default     = "Command"
}

variable "notification_arn" {
  description = "An Amazon Resource Name (ARN) for a Simple Notification Service (SNS) topic. Run Command pushes notifications about command status changes to this topic."
  type        = string
  default     = ""
}

variable "sns_notification_role_arn" {
  description = "An Amazon Resource Name (ARN) for a Simple Notification Service (SNS) topic. Run Command pushes notifications about command status changes to this topic."
  type        = string
  default     = ""
}
variable "scan_patch_groups" {
  description = "The targets to register with the maintenance window. In other words, the instances to run commands on when the maintenance window runs. You can specify targets using instance IDs, resource group names, or tags that have been applied to instances. For more information about these examples formats see (https://docs.aws.amazon.com/systems-manager/latest/userguide/mw-cli-tutorial-targets-examples.html)"
  type        = list(string)
  default     = ["TOSCAN"]
}

variable "scan_maintenance_window_schedule" {
  description = "The schedule of the Maintenance Window in the form of a cron or rate expression."
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
}

variable "task_scan_priority" {
  description = "The priority of the task in the Maintenance Window, the lower the number the higher the priority. Tasks in a Maintenance Window are scheduled in priority order with tasks that have the same priority scheduled in parallel. Default 1"
  type        = number
  default     = 1
}

variable "scan_sns_notification_enabled" {
  description = "Enable/Disable the SNS notification for scans"
  type        = bool
  default     = false
}

variable "scan_maintenance_windows_targets" {
  description = "The map of tags for targetting which EC2 instances will be scaned"
  type = list(object({
    key : string
    values : list(string)
    }
    )
  )
  default = []
}

variable "install_patch_groups" {
  description = "The targets to register with the maintenance window. In other words, the instances to run commands on when the maintenance window runs. You can specify targets using instance IDs, resource group names, or tags that have been applied to instances. For more information about these examples formats see (https://docs.aws.amazon.com/systems-manager/latest/userguide/mw-cli-tutorial-targets-examples.html)"
  type        = list(string)
  default     = ["TOPATCH"]
}

variable "install_maintenance_window_schedule" {
  description = "The schedule of the Maintenance Window in the form of a cron or rate expression"
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
}

variable "s3_bucket_prefix_install_logs" {
  description = "The Amazon S3 bucket subfolder for install logs"
  type        = string
  default     = "install"
}

variable "s3_bucket_prefix_scan_logs" {
  description = "The Amazon S3 bucket subfolder for scan logs"
  type        = string
  default     = "scanning"
}

variable "task_install_priority" {
  description = "The priority of the task in the Maintenance Window, the lower the number the higher the priority. Tasks in a Maintenance Window are scheduled in priority order with tasks that have the same priority scheduled in parallel."
  type        = number
  default     = 1
}

variable "install_sns_notification_enabled" {
  description = "Enable/disable the SNS notification for install patches"
  type        = bool
  default     = false
}

variable "install_maintenance_windows_targets" {
  description = "The targets to register with the maintenance window. In other words, the instances to run commands on when the maintenance window runs. You can specify targets using instance IDs, resource group names, or tags that have been applied to instances. For more information about these examples formats see (https://docs.aws.amazon.com/systems-manager/latest/userguide/mw-cli-tutorial-targets-examples.html)"
  type = list(object({
    key : string
    values : list(string)
    }
    )
  )
  default = []
}

variable "operating_system" {
  description = "Defines the operating system the patch baseline applies to. Supported operating systems include WINDOWS, AMAZON_LINUX, AMAZON_LINUX_2, SUSE, UBUNTU, CENTOS, and REDHAT_ENTERPRISE_LINUX. The Default value is WINDOWS."
  type        = string
  default     = "AMAZON_LINUX_2"
}

variable "approved_patches" {
  description = "A list of explicitly approved patches for the baseline"
  type        = list(string)
  default     = []
}

variable "rejected_patches" {
  description = "A list of rejected patches"
  type        = list(string)
  default     = []
}

variable "patch_baseline_approval_rules" {
  description = <<EOT
    A set of rules used to include patches in the baseline. Up to 10 approval rules can be specified.
    Each `approval_rule` block requires the fields documented below (unless marked optional).
    `approve_after_days` and `approve_until_date` conflict, do not set both in the same `approval_rule`.

    See https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ssm_patch_baseline#approval_rule-block for full details.
  EOT
  type = list(object({
    approve_after_days : optional(number)
    approve_until_date : optional(string)
    compliance_level : string
    enable_non_security : bool
    patch_baseline_filters : list(object({
      name : string
      values : list(string)
    }))
  }))

  default = [
    {
      approve_after_days  = 7
      compliance_level    = "HIGH"
      enable_non_security = true
      patch_baseline_filters = [
        {
          name   = "PRODUCT"
          values = ["AmazonLinux2", "AmazonLinux2.0"]
        },
        {
          name   = "CLASSIFICATION"
          values = ["Security", "Bugfix", "Recommended"]
        },
        {
          name   = "SEVERITY"
          values = ["Critical", "Important", "Medium"]
        }
      ]
    }
  ]

}
variable "approved_patches_compliance_level" {
  type        = string
  description = "Defines the compliance level for approved patches. This means that if an approved patch is reported as missing, this is the severity of the compliance violation. Valid compliance levels include the following: CRITICAL, HIGH, MEDIUM, LOW, INFORMATIONAL, UNSPECIFIED. The default value is UNSPECIFIED."
  default     = "HIGH"
}

variable "ssm_bucket_policy" {
  type        = string
  description = "Custom bucket policy for the SSM log bucket"
  default     = null
}

variable "bucket_id" {
  type        = list(string)
  description = "The bucket ID to use for the patch log. If no bucket ID is provided, the module will create a new one. This is of type `list(string)` to work around #41 / https://github.com/hashicorp/terraform/issues/28962."
  default     = []
}

variable "ssm_bucket_versioning_enable" {
  type        = string
  description = "To enable or disable S3 bucket versioning for the log bucket."
  default     = true
}

variable "s3_log_output_enabled" {
  type        = bool
  description = "To enable or disable s3 bucket output for the runCommand logs"
  default     = true
}

variable "cloudwatch_log_output_enabled" {
  type        = bool
  description = "Enables Systems Manager to send command output to CloudWatch Logs."
  default     = false
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "The name of the CloudWatch log group where you want to send command output. If you don't specify a group name, Systems Manager automatically creates a log group for you. The log group uses the following naming format: aws/ssm/SystemsManagerDocumentName."
  default     = null
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  filter_metrics_type = {
    "security_group_change" = {
      metric_description         = "Secuity group update alert",
      pattern                    = "{($.eventName=AuthorizeSecurityGroupIngress)||($.eventName=AuthorizeSecurityGroupEgress)||($.eventName=RevokeSecurityGroupIngress)||($.eventName=RevokeSecurityGroupEgress)||($.eventName=CreateSecurityGroup)||($.eventName=DeleteSecurityGroup)}",
      metric_transformation_name = "SecurityGroupEventCount"
    },
    "user_creation_or_deletion" = {
      metric_description         = "User creation or deletion alert",
      pattern                    = "{($.eventName=CreateUser)||($.eventName=DeleteUser)}",
      metric_transformation_name = "UserCreationOrDeletionEvent"
    },
    "console_login_failed" = {
      metric_description         = "Console login failed alert",
      pattern                    = "{($.eventName=ConsoleLogin)&&($.errorMessage=\"Failed authentication\")}",
      metric_transformation_name = "ConsoleLoginFailedEvent"
    },
    "iam_group_policy_change" = {
      metric_description         = "IAM Group policy update alert",
      pattern                    = "{ ($.eventName=DeleteGroupPolicy)||($.eventName=PutGroupPolicy)||($.eventName=AttachGroupPolicy)||($.eventName=DetachGroupPolicy) }",
      metric_transformation_name = "IAMGroupPolicyChange"
    },
    "iam_role_policy_change" = {
      metric_description         = "IAM Role policy update alert",
      pattern                    = "{($.eventName=DeleteRolePolicy)||($.eventName=PutRolePolicy)||($.eventName=AttachRolePolicy)||($.eventName=DetachRolePolicy)}",
      metric_transformation_name = "IAMRolePolicyChange"
    },
    "iam_user_policy_change" = {
      metric_description         = "IAM User policy update alert",
      pattern                    = "{($.eventName=DeleteUserPolicy)||($.eventName=PutUserPolicy)||($.eventName=AttachUserPolicy)||($.eventName=DetachUserPolicy)}",
      metric_transformation_name = "IAMUserPolicyChange"
    },
    "iam_policy_change" = {
      metric_description         = "IAM policy update alert",
      pattern                    = "{($.eventName=CreatePolicy)||($.eventName=DeletePolicy)||($.eventName=CreatePolicyVersion)||($.eventName=DeletePolicyVersion)}",
      metric_transformation_name = "IAMPolicyChange"
    },
    "iam_user_added_to_group" = {
      metric_description         = "IAM user is added to a group alert",
      pattern                    = "{($.eventName=AddUserToGroup)}",
      metric_transformation_name = "IAMUserAddedToGroup"
    },
    "role_creation_or_deletion" = {
      metric_description         = "IAM role creation or deletion alert",
      pattern                    = "{($.eventName=CreateRole)||($.eventName=DeleteRole)}",
      metric_transformation_name = "IAMRoleCreationOrDeletionEvent"
    }

  }
}

resource "aws_cloudwatch_log_metric_filter" "management_activities_filter" {
  for_each       = local.filter_metrics_type
  name           = each.key
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail_event_logs.name

  metric_transformation {
    name      = each.value.metric_transformation_name
    namespace = var.metric_namespace
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "management_activities_alarm" {
  for_each            = local.filter_metrics_type
  depends_on          = [aws_sns_topic.sg_sns_topic]
  alarm_name          = "${each.key}_alarm"
  metric_name         = each.value.metric_transformation_name
  threshold           = "1"
  statistic           = "Average"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  datapoints_to_alarm = "1"
  evaluation_periods  = "1"
  period              = "60"
  namespace           = var.metric_namespace
  alarm_actions       = [aws_sns_topic.sg_sns_topic.arn]
  alarm_description   = each.value.metric_description
}

resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name = var.cloudtrail_role_name

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "cloudtrail.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "cloudtrail_role_policy" {
  name = var.cloudtrail_role_policy_name
  role = aws_iam_role.cloudtrail_cloudwatch_role.id

  # "arn:aws:logs:us-east-1:000000000000:log-group:${aws_cloudwatch_log_group.cloudtrail_event_logs.id}:*"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AWSCloudTrailCreateLogStream2014110",
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogStream"
      ],
      "Resource": [
        "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
      ]
    },
    {
      "Sid": "AWSCloudTrailPutLogEvents20141101",
      "Effect": "Allow",
      "Action": [
        "logs:PutLogEvents"
      ],
      "Resource": [
        "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
      ]
    }
  ]
}
EOF
}

resource "aws_cloudwatch_log_group" "cloudtrail_event_logs" {
  name = var.log_group_name
}

resource "aws_cloudtrail" "event_logs" {
  depends_on                    = [aws_s3_bucket_policy.cloudtrail_access_s3]
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_event_logs.id
  s3_key_prefix                 = ""
  include_global_service_events = true # Default is true
  is_multi_region_trail         = true # Default is false
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_role.arn

  # Exclude KMS and RDS event logs.
  event_selector {
    read_write_type                  = "All"
    include_management_events        = true
    exclude_management_event_sources = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "cloudtrail" {
  description         = "CMK for ${var.trail_name} CloudTrail"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountRoot"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudTrailToEncryptLogs"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "kms:GenerateDataKey*"
        Resource  = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/*"
          }
        }
      },
      {
        Sid       = "AllowCloudTrailToDescribeKey"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "kms:DescribeKey"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "cloudtrail_event_logs" {
  bucket        = "${var.trail_bucket_name}-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_event_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_event_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_event_logs" {
  bucket = aws_s3_bucket.cloudtrail_event_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

# Attach S3 bucket policy
resource "aws_s3_bucket_policy" "cloudtrail_access_s3" {
  bucket     = aws_s3_bucket.cloudtrail_event_logs.id
  depends_on = [aws_s3_bucket.cloudtrail_event_logs]
  policy     = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AWSCloudTrailAclCheck",
      "Effect": "Allow",
      "Principal": { "Service": "cloudtrail.amazonaws.com" },
      "Action": "s3:GetBucketAcl",
      "Resource": "${aws_s3_bucket.cloudtrail_event_logs.arn}"
    },
    {
      "Sid": "AWSCloudTrailWrite",
      "Effect": "Allow",
      "Principal": { "Service": "cloudtrail.amazonaws.com" },
      "Action": "s3:PutObject",
      "Resource": "${aws_s3_bucket.cloudtrail_event_logs.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*",
      "Condition": {
        "StringEquals": {
          "s3:x-amz-acl": "bucket-owner-full-control"
        }
      }
    }
  ]
}
POLICY
}

provider "aws" {
  region = var.awsRegion
}

# terraform {
#   backend "s3" {}
# }

resource "aws_kms_key" "sg_sns_topic" {
  description         = "CMK for ${var.sns_topic_name} SNS topic"
  enable_key_rotation = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountRoot"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action    = "kms:*"
        Resource  = "*"
        Condition = { StringEquals = { "kms:CallerAccount" = data.aws_caller_identity.current.account_id } }
      },
      {
        Sid       = "AllowCloudWatchToPublish"
        Effect    = "Allow"
        Principal = { Service = "cloudwatch.amazonaws.com" }
        Action    = ["kms:Decrypt", "kms:GenerateDataKey*"]
        Resource  = "*"
      }
    ]
  })
}

resource "aws_sns_topic" "sg_sns_topic" {
  name              = var.sns_topic_name
  kms_master_key_id = aws_kms_key.sg_sns_topic.key_id
}

resource "aws_sns_topic_subscription" "user_updates_sqs_target" {
  for_each   = toset(var.email_list)
  depends_on = [aws_sns_topic.sg_sns_topic]
  topic_arn  = aws_sns_topic.sg_sns_topic.arn
  protocol   = "email"
  endpoint   = each.value
}

variable "awsRegion" {
  type    = string
  default = "us-east-1"
}

variable "cloudtrail_role_name" {
  type    = string
  default = "cloudtrail_to_cloudwatch"
}

variable "cloudtrail_role_policy_name" {
  type    = string
  default = "cloudtrail_to_cloudwatch_policy"
}

variable "log_group_name" {
  type    = string
  default = "cloudtrail_to_cloudwatch_logs"
}

variable "trail_name" {
  type    = string
  default = "monitor_account_activities"
}

variable "trail_bucket_name" {
  type    = string
  default = "cloudtrail-monitor-management-event-logs"
}

variable "metric_namespace" {
  type    = string
  default = "management_activities"
}

variable "sns_topic_name" {
  type    = string
  default = "management-updates"
}

variable "email_list" {
  type        = list(string)
