#--------------------------------------------------------------
# module variables
#--------------------------------------------------------------
variable "is_enabled" {
  type        = bool
  description = "(Optional) A boolean flag to enable/disable AWS Config. Defaults true."
  default     = true
}
variable "name_prefix" {
  type        = string
  description = "(Optional) Prefix of config name."
  default     = ""
}
variable "tags" {
  type        = map(any)
  description = "(Optional) Key-value map of resource tags."
  default     = null
}

#--------------------------------------------------------------
# Terraform Provider
#--------------------------------------------------------------
terraform {
  required_version = "~>1.4"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~>4.67.0"
    }
  }
}

resource "aws_cognito_user_pool" "pool" {
  name              = "fiap-hackathon-cognito-pool"
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration = "OFF"

  tags = {
    fiap = "hackathon",
  }

  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true

    string_attribute_constraints {
      min_length = 2
      max_length = 100
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                   = 8
    require_lowercase                = false
    require_numbers                  = false
    require_symbols                  = false
    require_uppercase                = false
    temporary_password_validity_days = 365
  }

  username_configuration {
    case_sensitive = false
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name                  = "cognito-pool-client"
  generate_secret       = false
  explicit_auth_flows   = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_ADMIN_USER_PASSWORD_AUTH"]
  auth_session_validity = 15
  user_pool_id = aws_cognito_user_pool.pool.id
}

output "user_pool_endpoint" {
  value = aws_cognito_user_pool.pool.endpoint
}

output "user_pool_client_id" {
  value = aws_cognito_user_pool_client.client.id
}

# aws_iam_role.sentinel_oidc:

resource "aws_iam_role" "sentinel_oidc" {
  assume_role_policy = jsonencode(
    {
      Statement = [
        {
          Action = "sts:AssumeRoleWithWebIdentity"
          Condition = {
            StringEquals = {
              "${local.url}:aud" = local.azure_client_id
            }
          }
          Effect = "Allow"
          Principal = {
            Federated = aws_iam_openid_connect_provider.azure.arn
          }
        },
      ]
      Version = "2012-10-17"
    }
  )
  description = "for sentinel function apps"
  name        = "Sentinel-OIDC-Organizations-ReadOnly"
}

resource "aws_iam_role_policy_attachment" "sentinel_role_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
  role       = aws_iam_role.sentinel_oidc.name
}

locals {
  azure_tenet_id  = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
  azure_client_id = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
  url             = "sts.windows.net/${local.azure_tenet_id}/"
  url_https       = "https://${local.url}"
}

data "tls_certificate" "thumprint" {
  url = local.url_https
}

# aws_iam_openid_connect_provider.azure:
resource "aws_iam_openid_connect_provider" "azure" {
  client_id_list = [
    local.azure_client_id,
  ]
  thumbprint_list = [
    data.tls_certificate.thumprint.certificates.0.sha1_fingerprint,
  ]
  url = local.url_https
}

