provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "s3_frontend_nft_maker_v2" {
  bucket = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"

}

resource "aws_s3_bucket_public_access_block" "s3_frontend_nft_maker_v2" {
  bucket                  = aws_s3_bucket.s3_frontend_nft_maker_v2.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3_frontend_nft_maker_v2" {
  description         = "CMK for s3-frontend-nft-maker-v2 S3 bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "s3_frontend_nft_maker_v2" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_frontend_nft_maker_v2.arn
    }
  }
}

resource "aws_cloudfront_origin_access_identity" "s3_frontend_nft_maker_v2" {
  comment = "OAI for s3-frontend-nft-maker-v2"
}

resource "aws_s3_bucket_policy" "s3_frontend_nft_maker_v2_policy" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id
  policy = data.aws_iam_policy_document.s3_frontend_nft_maker_v2_policy_document.json
}

data "aws_iam_policy_document" "s3_frontend_nft_maker_v2_policy_document" {
  statement {

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.s3_frontend_nft_maker_v2.iam_arn]
    }

    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.s3_frontend_nft_maker_v2.arn,
      "${aws_s3_bucket.s3_frontend_nft_maker_v2.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_cors_configuration" "s3_frontend_nft_maker_v2_cors_config" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["PUT", "POST", "GET", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_website_configuration" "s3_frontend_nft_maker_v2_website_config" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_wafv2_web_acl" "s3_frontend_nft_maker_v2" {
  name        = "s3-frontend-nft-maker-v2"
  description = "Web ACL for the s3-frontend-nft-maker-v2 CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "s3-frontend-nft-maker-v2"
    sampled_requests_enabled   = true
  }
}

resource "aws_cloudfront_distribution" "s3_distribution" {
  origin {
    domain_name = aws_s3_bucket.s3_frontend_nft_maker_v2.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.s3_frontend_nft_maker_v2.cloudfront_access_identity_path
    }
  }

  web_acl_id = aws_wafv2_web_acl.s3_frontend_nft_maker_v2.arn

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Some comment"
  default_root_object = "index.html"

  # logging_config {
  #   include_cookies = false
  #   bucket          = "mylogs.s3.amazonaws.com"
  #   prefix          = "myprefix"
  # }

  # aliases = []

  default_cache_behavior {
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  # Cache behavior with precedence 0
  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }

    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 31536000
    compress               = true
    viewer_protocol_policy = "redirect-to-https"
  }

  # Cache behavior with precedence 1
  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
    viewer_protocol_policy = "redirect-to-https"
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "none"
      # locations        = ["US", "CA", "GB", "DE"]
    }
  }

  tags = {
    Environment = "production"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

######## Terraform State managemnet s3 bucket
resource "aws_s3_bucket" "terraform_state_bucket" {
    bucket = "near-frontend-${lower(var.AWS_ENVIRONMENT_NAME)}-terraform-state-${data.aws_caller_identity.current.account_id}"

    tags = {
        Name = "S3 Remote Terraform State Store"
        Environment = var.AWS_ENVIRONMENT_NAME
    }
}

resource "aws_s3_bucket_ownership_controls" "terraform_state_bucket" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "terraform_state_bucket_securing" {
  depends_on = [aws_s3_bucket_ownership_controls.terraform_state_bucket]
  bucket     = aws_s3_bucket.terraform_state_bucket.id
  acl        = "private"
}

resource "aws_s3_bucket_public_access_block" "terraform_state_bucket" {
  bucket                  = aws_s3_bucket.terraform_state_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "terraform_state_bucket_versioning" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "terraform_state_bucket_kms_key" {
  description             = "This key is used to encrypt bucket objects"
  deletion_window_in_days = 10
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_bucket_encryption" {
  bucket = aws_s3_bucket.terraform_state_bucket.bucket

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_bucket_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

######## Terraform State managemnet dynmodb
resource "aws_dynamodb_table" "terraform-lock" {
    name           = "near-frontend-terraform-state"
    read_capacity  = 5
    write_capacity = 5
    hash_key       = "LockID"
    attribute {
        name = "LockID"
        type = "S"
    }
    tags = {
        "Name" = "DynamoDB Terraform State Lock Table"
        Environment = var.AWS_ENVIRONMENT_NAME
    }
}

variable "AWS_ACCESS_KEY_ID" {
  type = string
  default = ""
}

variable "AWS_SECRET_ACCESS_KEY" {
  type = string
  default = ""
}

variable "AWS_ENVIRONMENT_NAME" {
  type = string
  default = ""
}

# --------------------------------------------------------------------------
# Cache Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "cache" {
  for_each = var.cache ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  availability_zone = "${data.aws_region.current.name}${each.key}"
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(aws_vpc.vpc.cidr_block, var.k8s ? 6 : 4, ((var.k8s ? 19 : 4) * var.zones) + index(keys(var.az_number), each.key))


  tags = merge(local.cache_subnet_tags, {
    "Name" = "${var.cache_subnet_name}-${data.aws_region.current.name}${each.key}"
    }
  )

  timeouts {
    delete = "30m"
  }
}


# --------------------------------------------------------------------------
# Route Table
# --------------------------------------------------------------------------
resource "aws_route_table" "cache" {
  count = var.cache ? 1 : 0

  vpc_id = aws_vpc.vpc.id

  tags = local.cache_subnet_tags

  lifecycle {
    ignore_changes = [
      route
    ]
  }
}


# --------------------------------------------------------------------------
# Associate Route Table with Cache Subnets
# --------------------------------------------------------------------------
resource "aws_route_table_association" "cache" {
  for_each = var.cache ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  subnet_id      = element([for s in aws_subnet.cache : s.id], index(keys(var.az_number), each.key))
  route_table_id = aws_route_table.cache.0.id
}


# --------------------------------------------------------------------------
# ElastiCache Cache Subnet Group
# --------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "cache" {
  count = var.cache ? 1 : 0

  name        = "${var.name}-elasticache"
  description = "ElastiCache subnet group for ${var.name}"
  subnet_ids  = [for s in aws_subnet.cache : s.id]
}

# --------------------------------------------------------------------------
# Locals - Data Sources
# --------------------------------------------------------------------------

# Determine all of the available availability zones in the
# current AWS region.
data "aws_availability_zones" "available" {
  state = "available"
}

# This additional data source determines some additional
# details about each VPC, including its suffix letter.
data "aws_availability_zone" "all" {
  count = var.zones

  name = data.aws_availability_zones.available.names[count.index]
}

# Get the current AWS region name
data "aws_region" "current" {}

# --------------------------------------------------------------------------
# Database Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "db" {
  for_each = var.db ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  availability_zone = "${data.aws_region.current.name}${each.key}"
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(aws_vpc.vpc.cidr_block, var.k8s ? 6 : 4, ((var.k8s ? 18 : 3) * var.zones) + index(keys(var.az_number), each.key))


  tags = merge(local.db_subnet_tags, {
    "Name" = "${var.db_subnet_name}-${data.aws_region.current.name}${each.key}"
    }
  )

  timeouts {
    delete = "30m"
  }
}


# --------------------------------------------------------------------------
# Route Table
# --------------------------------------------------------------------------
resource "aws_route_table" "db" {
  count = var.db ? 1 : 0

  vpc_id = aws_vpc.vpc.id

  tags = local.db_subnet_tags

  lifecycle {
    ignore_changes = [
      route
    ]
  }
}


# --------------------------------------------------------------------------
# Associate Route Table to Database Subnets
# --------------------------------------------------------------------------
resource "aws_route_table_association" "db" {
  for_each = var.db ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  subnet_id      = element([for s in aws_subnet.db : s.id], index(keys(var.az_number), each.key))
  route_table_id = aws_route_table.db.0.id
}


# --------------------------------------------------------------------------
# RDS Database Subnet Group
# --------------------------------------------------------------------------
resource "aws_db_subnet_group" "db" {
  count = var.db == true ? 1 : 0

  name       = "${var.name}-db"
  subnet_ids = [for s in aws_subnet.db : s.id]

  tags = local.db_subnet_tags
}

# --------------------------------------------------------------------------
# internal Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "internal" {
  for_each = var.internal ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  availability_zone = "${data.aws_region.current.name}${each.key}"
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(aws_vpc.vpc.cidr_block, var.k8s ? 6 : 4, ((var.k8s ? 17 : 2) * var.zones) + index(keys(var.az_number), each.key))


  tags = merge(local.internal_subnet_tags, {
    "Name" = "${var.internal_subnet_name}-${data.aws_region.current.name}${each.key}"
    }
  )

  timeouts {
    delete = "30m"
  }
}


# --------------------------------------------------------------------------
# Route Table
# --------------------------------------------------------------------------
resource "aws_route_table" "internal" {
  count = var.internal ? 1 : 0

  vpc_id = aws_vpc.vpc.id

  tags = local.internal_subnet_tags

  lifecycle {
    ignore_changes = [
      route
    ]
  }
}


# --------------------------------------------------------------------------
# Associate Route Table to Internal Subnets
# --------------------------------------------------------------------------
resource "aws_route_table_association" "internal" {
  for_each = var.internal ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  subnet_id      = element([for s in aws_subnet.internal : s.id], index(keys(var.az_number), each.key))
  route_table_id = aws_route_table.internal.0.id
}

# --------------------------------------------------------------------------
# Locals - Tagging
# --------------------------------------------------------------------------
locals {
  cluster_name = substr(lower(var.cluster_name), 0, 99)
  tags = merge(
    var.tags,
    {
      "Name"   = var.name
      "Module" = "terraform-aws-stackx-network"
      "Github" = "https://github.com/ventx/terraform-aws-stackx-network"
    }
  )
  cache_subnet_tags = merge(
    var.tags,
    var.cache_subnet_tags,
  )
  db_subnet_tags = merge(
    var.tags,
    var.db_subnet_tags
  )
  internal_subnet_tags = merge(
    var.tags,
    var.internal_subnet_tags
  )
  private_subnet_tags = merge(
    var.tags,
    var.private_subnet_tags,
    var.k8s ?
    {
      "karpenter.sh/discovery"                      = local.cluster_name
      "kubernetes.io/cluster/${local.cluster_name}" = "shared",
      "kubernetes.io/role/internal-elb"             = "1",
    } : null
  )
  public_subnet_tags = merge(
    var.tags,
    var.public_subnet_tags,
    var.k8s ?
    {
      "kubernetes.io/cluster/${local.cluster_name}" = "shared",
      "kubernetes.io/role/elb"                      = "1",
    } : null
  )
  nat_gateway_count = var.single_nat_gateway ? 1 : var.zones
}


# --------------------------------------------------------------------------
# VPC
# --------------------------------------------------------------------------
resource "aws_vpc" "vpc" {
  cidr_block                       = cidrsubnet("10.0.0.0/8", 8, var.region_number[var.region] + var.vpc_cidr_add)
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = var.ipv6 ? true : false

  tags = local.tags
}


# --------------------------------------------------------------------------
# Internet Gateway
# --------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

  tags = local.tags
}


# --------------------------------------------------------------------------
# EIPs
# --------------------------------------------------------------------------
# Elastic IP addresses (EIP) for NAT Gateways
resource "aws_eip" "eip" {
  count = local.nat_gateway_count

  tags = var.single_nat_gateway ? local.private_subnet_tags : merge(
    local.private_subnet_tags, {
      "Name" = "${var.private_subnet_name}-${data.aws_availability_zones.available.names[count.index]}"
    }
  )
}


# --------------------------------------------------------------------------
# NAT Gateways
# --------------------------------------------------------------------------
resource "aws_nat_gateway" "natgw" {
  count = local.nat_gateway_count

  allocation_id = element(
    aws_eip.eip.*.id,
  var.single_nat_gateway ? 0 : count.index)

  subnet_id = element(
    [for s in aws_subnet.public : s.id],
  var.single_nat_gateway ? 0 : count.index)

  tags = var.single_nat_gateway ? local.private_subnet_tags : merge(
    local.private_subnet_tags, {
      "Name" = "${var.private_subnet_name}-${data.aws_availability_zones.available.names[count.index]}"
    }
  )
}


# --------------------------------------------------------------------------
# IPV6 Egress-only Gateway
# --------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "ipv6" {
  count = var.ipv6 ? 1 : 0

  vpc_id = aws_vpc.vpc.id
}

output "azs" {
  description = "Number of Availability Zones specified"
  value       = var.zones
}

output "number_azs" {
  description = "Number of Availability Zones specified"
  value       = var.zones
}

output "zones" {
  description = "Number of Availability Zones specified"
  value       = var.zones
}

# --------------------------------------------------------------------------
# VPC
# --------------------------------------------------------------------------
output "vpc_arn" {
  description = "AWS VPC ID ARN"
  value       = aws_vpc.vpc.arn
}

output "vpc_id" {
  description = "AWS VPC ID"
  value       = aws_vpc.vpc.id
}

output "vpc_cidr" {
  description = "AWS VPC IPv4 CIDR"
  value       = aws_vpc.vpc.cidr_block
}

output "vpc_dns" {
  description = "VPC DNS Server IP"
  value       = cidrhost(aws_vpc.vpc.cidr_block, 2)
}


output "vpc_ipv6_cidr" {
  description = "AWS VPC IPv6 CIDR"
  value       = aws_vpc.vpc.ipv6_cidr_block
}

output "vpc_ipv6_association_id" {
  description = "AWS VPC aassociation ID for the IPv6 CIDR block"
  value       = aws_vpc.vpc.ipv6_association_id
}

output "igw_id" {
  description = "Internet Gateway ID"
  value       = aws_internet_gateway.igw.id
}

output "egress_only_internet_gateway_id" {
  description = "ID of IPv6 Egress-Only Internet Gateway"
  value       = var.ipv6 ? aws_egress_only_internet_gateway.ipv6.0.id : null
}


# --------------------------------------------------------------------------
# Cache Subnets
# --------------------------------------------------------------------------
output "cache_azs" {
  description = "Availability Zones for Cache Subnets"
  value       = [for s in aws_subnet.cache : s.availability_zone]
}

output "cache_subnets" {
  description = "Number of Cache Subnet IDs"
  value       = length([for s in aws_subnet.cache : s.id])
}

output "cache_subnet_arns" {
  description = "Cache Subnet ARNs"
  value       = [for s in aws_subnet.cache : s.arn]
}

output "cache_subnet_ids" {
  description = "Number of Cache Subnet IDs"
  value       = [for s in aws_subnet.cache : s.id]
}

output "cache_subnet_cidrs" {
  description = "Cache Subnet CIDRs"
  value       = [for s in aws_subnet.cache : s.cidr_block]
}

output "cache_subnet_ipv6_cidr_blocks" {
  description = "Cache Subnet IPv6 CIDR blocks"
  value       = [for s in aws_subnet.cache : s.ipv6_cidr_block]
}

output "cache_rt_ids" {
  description = "Cache Route Table IDs"
  value       = [for s in aws_route_table.cache : s.id]
}

# --------------------------------------------------------------------------
# Database Subnets
# --------------------------------------------------------------------------
output "db_azs" {
  description = "Availability Zones for Database Subnets"
  value       = [for s in aws_subnet.db : s.availability_zone]
}

output "db_subnets" {
  description = "Number of Database Subnet IDs"
  value       = length([for s in aws_subnet.db : s.id])
}

output "db_subnet_arns" {
  description = "Database Subnet ARNs"
  value       = [for s in aws_subnet.db : s.arn]
}

output "db_subnet_ids" {
  description = "Number of Database Subnet IDs"
  value       = [for s in aws_subnet.db : s.id]
}

output "db_subnet_cidrs" {
  description = "Database Subnet CIDRs"
  value       = [for s in aws_subnet.db : s.cidr_block]
}

output "db_subnet_ipv6_cidr_blocks" {
  description = "Database Subnet IPv6 CIDR blocks"
  value       = [for s in aws_subnet.db : s.ipv6_cidr_block]
}

output "db_rt_ids" {
  description = "Database Route Table IDs"
  value       = [for s in aws_route_table.db : s.id]
}

# --------------------------------------------------------------------------
# Internal Subnets
# --------------------------------------------------------------------------
output "internal_azs" {
  description = "Availability Zones for Internal Subnets"
  value       = [for s in aws_subnet.internal : s.availability_zone]
}

output "internal_subnets" {
  description = "Number of Internal Subnet IDs"
  value       = length([for s in aws_subnet.internal : s.id])
}

output "internal_subnet_arns" {
  description = "Internal Subnet ARNs"
  value       = [for s in aws_subnet.internal : s.arn]
}

output "internal_subnet_ids" {
  description = "Number of Internal Subnet IDs"
  value       = [for s in aws_subnet.internal : s.id]
}

output "internal_subnet_cidrs" {
  description = "Internal Subnet CIDRs"
  value       = [for s in aws_subnet.internal : s.cidr_block]
}

output "internal_subnet_ipv6_cidr_blocks" {
  description = "Internal Subnet IPv6 CIDR blocks"
  value       = [for s in aws_subnet.internal : s.ipv6_cidr_block]
}

output "internal_rt_ids" {
  description = "Internal Route Table IDs"
  value       = [for s in aws_route_table.internal : s.id]
}

# --------------------------------------------------------------------------
# Private Subnets
# --------------------------------------------------------------------------
output "private_azs" {
  description = "Availability Zones for Private Subnets"
  value       = [for s in aws_subnet.private : s.availability_zone]
}

output "private_subnets" {
  description = "Number of Private Subnet IDs"
  value       = length([for s in aws_subnet.private : s.id])
}

output "private_subnet_arns" {
  description = "Private Subnet ARNs"
  value       = [for s in aws_subnet.private : s.arn]
}

output "private_subnet_ids" {
  description = "Number of Private Subnet IDs"
  value       = [for s in aws_subnet.private : s.id]
}

output "private_subnet_cidrs" {
  description = "Private Subnet CIDRs"
  value       = [for s in aws_subnet.private : s.cidr_block]
}

output "private_subnet_ipv6_cidr_blocks" {
  description = "Private Subnet IPv6 CIDR blocks"
  value       = [for s in aws_subnet.private : s.ipv6_cidr_block]
}

output "private_rt_ids" {
  description = "Private Route Table IDs"
  value       = [for s in aws_route_table.private : s.id]
}

output "nat_gateway_count" {
  description = "Number of NAT Gateways"
  value       = length(aws_nat_gateway.natgw.*.id)
}

output "nat_gateway_public_ips" {
  description = "Public IPs of NAT Gateways"
  value       = aws_nat_gateway.natgw.*.public_ip
}

output "eip_public_ips" {
  description = "Public IPv4 of EIP addresses"
  value       = aws_eip.eip.*.public_ip
}

# --------------------------------------------------------------------------
# Public Subnets
# --------------------------------------------------------------------------
output "public_azs" {
  description = "Availability Zones for Public Subnets"
  value       = [for s in aws_subnet.public : s.availability_zone]
}

output "public_subnets" {
  description = "Number of Public Subnets"
  value       = length([for s in aws_subnet.public : s.id])
}

output "public_subnet_arns" {
  description = "Public Subnet ARNs"
  value       = [for s in aws_subnet.public : s.arn]
}

output "public_subnet_ids" {
  description = "Number of Public Subnet IDs"
  value       = [for s in aws_subnet.public : s.id]
}

output "public_subnet_cidrs" {
  description = "Public Subnets CIDRs"
  value       = [for s in aws_subnet.public : s.cidr_block]
}

output "public_subnet_ipv6_cidr_blocks" {
  description = "Public Subnet IPv6 CIDR blocks"
  value       = [for s in aws_subnet.public : s.ipv6_cidr_block]
}

output "public_rt_ids" {
  description = "Public Route Table IDs"
  value       = aws_route_table.public.*.id
}

# --------------------------------------------------------------------------
# VPC Endpoints
# --------------------------------------------------------------------------
output "vpc_endpoint_s3_id" {
  description = "ID of VPC endpoint for S3"
  value       = var.s3_endpoint ? aws_vpc_endpoint.s3.0.id : null
}

output "vpc_endpoint_s3_pl_id" {
  description = "Prefix list ID for the S3 VPC endpoint"
  value       = var.s3_endpoint ? aws_vpc_endpoint.s3.0.prefix_list_id : null
}

# --------------------------------------------------------------------------
# Private Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "private" {
  for_each = var.private ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  availability_zone = "${data.aws_region.current.name}${each.key}"
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(aws_vpc.vpc.cidr_block, var.k8s ? 2 : 4, (0 * var.zones) + index(keys(var.az_number), each.key))


  tags = merge(local.private_subnet_tags, {
    "Name" = "${var.private_subnet_name}-${data.aws_region.current.name}${each.key}"
    }
  )

  timeouts {
    delete = "30m"
  }
}


# --------------------------------------------------------------------------
# Route Table
# --------------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = var.private ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  vpc_id = aws_vpc.vpc.id

  tags = var.single_nat_gateway ? local.private_subnet_tags : merge(
    local.private_subnet_tags, {
      "Name" = "${var.private_subnet_name}-${data.aws_availability_zones.available.names[index(keys(var.az_number), each.key)]}"
    }
  )

  lifecycle {
    ignore_changes = [
      route
    ]
  }
}


# --------------------------------------------------------------------------
# NAT Gateway route
# --------------------------------------------------------------------------
resource "aws_route" "private_nat_gateway" {
  count = var.private ? local.nat_gateway_count : 0

  route_table_id         = element([for s in aws_route_table.private : s.id], count.index)
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element([for s in aws_nat_gateway.natgw : s.id], count.index)

  timeouts {
    create = "5m"
  }
}


# --------------------------------------------------------------------------
# IPv6 Route
# --------------------------------------------------------------------------
resource "aws_route" "private_ipv6_egress" {
  for_each = var.private && var.ipv6 ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  route_table_id              = element([for s in aws_route_table.private : s.id], index(keys(var.az_number), each.key))
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.ipv6.0.id
}


# --------------------------------------------------------------------------
# Associate Route Table to Private Subnets
# --------------------------------------------------------------------------
resource "aws_route_table_association" "private" {
  for_each = var.private ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  subnet_id      = element([for s in aws_subnet.private : s.id], index(keys(var.az_number), each.key))
  route_table_id = element([for s in aws_route_table.private : s.id], var.single_nat_gateway ? 0 : index(keys(var.az_number), each.key))
}

# --------------------------------------------------------------------------
# Public Subnets
# --------------------------------------------------------------------------
resource "aws_subnet" "public" {
  for_each = var.public ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  availability_zone = "${data.aws_region.current.name}${each.key}"
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(aws_vpc.vpc.cidr_block, var.k8s ? 6 : 4, ((var.k8s ? 16 : 1) * var.zones) + index(keys(var.az_number), each.key))

  tags = merge(local.public_subnet_tags, {
    "Name" = "${var.public_subnet_name}-${data.aws_region.current.name}${each.key}"
    }
  )

  timeouts {
    delete = "30m"
  }
}


# --------------------------------------------------------------------------
# Route Table
# --------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count = var.public ? 1 : 0

  vpc_id = aws_vpc.vpc.id

  tags = local.public_subnet_tags

  lifecycle {
    ignore_changes = [route]
  }
}


# --------------------------------------------------------------------------
# Internet Gateway Route
# --------------------------------------------------------------------------
resource "aws_route" "public_internet_gateway" {
  count                  = var.public ? 1 : 0
  route_table_id         = aws_route_table.public.0.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id

  timeouts {
    create = "5m"
  }
}


# --------------------------------------------------------------------------
# IPv6 Route
# --------------------------------------------------------------------------
resource "aws_route" "public_internet_gateway_ipv6" {
  for_each = var.public && var.ipv6 ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  route_table_id              = aws_route_table.public.0.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.ipv6.0.id
}


# --------------------------------------------------------------------------
# Associate Route Table to Private Subnets
# --------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  for_each = var.public ? toset(slice(keys(var.az_number), 0, var.zones)) : toset([])

  subnet_id      = element([for s in aws_subnet.public : s.id], index(keys(var.az_number), each.key))
  route_table_id = aws_route_table.public.0.id
}

variable "name" {
  description = "Base Name for all resources (preferably generated by terraform-null-label)"
  type        = string
  default     = "stackx-network"
}

variable "tags" {
  description = "User specific Tags / Labels to attach to resources (will be merged with module tags)"
  type        = map(string)
  default     = {}
}

# --------------------------------------------------------------------------
# Important Settings
# --------------------------------------------------------------------------
variable "k8s" {
  description = "Enable / Disable usage for Kubernetes (adding tags to subnets and resources, increase private subnetes size)"
  type        = bool
  default     = true
}

variable "cluster_name" {
  description = "EKS Cluster name to add in tags for ELB and cluster-autoscaler / karpenter discovery of subnets / VPC"
  type        = string
  default     = "stackx"
  validation {
    condition     = length(var.cluster_name) < 100
    error_message = "Cluster Name can not exceeed 100 characters."
  }
}

variable "ipv6" {
  description = "Enable / Disable IPv6 in your VPC and subnets"
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = "Should be true if you want to provision a single shared NAT Gateway across all of your private networks (cost efficiency)"
  type        = bool
  default     = false
}

# --------------------------------------------------------------------------
# VPC
# --------------------------------------------------------------------------
variable "region" {
  description = "AWS Region (e.g. `eu-central-1`)"
  type        = string
  default     = "eu-central-1"
}

variable "zones" {
  description = "Number of AWS Availability Zones to use for every subnet"
  type        = number
  default     = 3
  validation {
    condition     = contains([1, 2, 3], var.zones)
    error_message = "Number of AZs must be one of `1`, `2` or `3`."
  }
}

variable "az_number" {
  # Assign a number to each AZ letter used in our configuration
  default = {
    a = 1
    b = 2
    c = 3
    d = 4
    e = 5
    f = 6
  }
}

variable "region_number" {
  # Arbitrary mapping of region name to number to use in a VPC's CIDR prefix.
  default = {
    eu-central-1   = 1
    eu-west-2      = 2
    us-east-1      = 3
    us-west-2      = 4
    ap-east-1      = 5
    ap-southeast-1 = 6
    ap-southeast-2 = 7
  }
}

variable "vpc_cidr_add" {
  description = "Add this number to the VPC CIDR to allow for multiple same region VPCs with different CIDRs"
  default     = 0
  type        = number
  validation {
    condition     = var.vpc_cidr_add < 10
    error_message = "The number to add to the VPC CIDR subnet mask must be >10 (to not conflict with other default region CIDRs - see `var.region_number`)."
  }

}

# --------------------------------------------------------------------------
# VPC Endpoints
# --------------------------------------------------------------------------
variable "cache_endpoints" {
  description = "Enable / Disable VPC Endpoints for Cache Subnets"
  type        = bool
  default     = false
}

variable "db_endpoints" {
  description = "Enable / Disable VPC Endpoints for Database Subnets"
  type        = bool
  default     = false
}

variable "private_endpoints" {
  description = "Enable / Disable VPC Endpoints for Private Subnets"
  type        = bool
  default     = true
}

variable "public_endpoints" {
  description = "Enable / Disable VPC Endpoints for Public Subnets"
  type        = bool
  default     = false
}

variable "internal_endpoints" {
  description = "Enable / Disable VPC Endpoints for Internal Subnets"
  type        = bool
  default     = false
}

variable "s3_endpoint" {
  description = "Enable / Disable VPC Endpoint (Gateway) - S3"
  type        = bool
  default     = true
}

# --------------------------------------------------------------------------
# Private Subnets
# --------------------------------------------------------------------------
variable "private" {
  description = "Enable / Disable Private Subnets"
  type        = bool
  default     = true
}

variable "private_subnet_name" {
  description = "Name for Private subnets and dependent resources (will be prefixed with `var.name-`)"
  type        = string
  default     = "private"
}

variable "private_subnet_tags" {
  description = "Tags as map for Private subnets and dependent resources (preferably generated by terraform-null-label)"
  type        = map(string)
  default = {
    "type" = "private"
  }
}

# --------------------------------------------------------------------------
# Cache Subnets
# --------------------------------------------------------------------------
variable "cache" {
  description = "Enable / Disable Cache Subnets"
  type        = bool
  default     = false
}

variable "cache_subnet_name" {
  description = "Name for Cache subnets and dependent resources  (will be prefixed with `var.name-`)"
  type        = string
  default     = "cache"
}

variable "cache_subnet_tags" {
  description = "Tags as map for Cache subnets and dependent resources (preferably generated by terraform-null-label)"
  type        = map(string)
  default = {
    "type" = "cache"
  }
}

# --------------------------------------------------------------------------
# Database Subnets
# --------------------------------------------------------------------------
variable "db" {
  description = "Enable / Disable Database Subnets"
  type        = bool
  default     = false
}

variable "db_subnet_name" {
  description = "Name for Database subnets and dependent resources  (will be prefixed with `var.name-`)"
  type        = string
  default     = "database"
}

variable "db_subnet_tags" {
  description = "Tags as map for Database subnets and dependent resources (preferably generated by terraform-null-label)"
  type        = map(string)
  default = {
    "type" = "database"
  }
}

# --------------------------------------------------------------------------
# Internal (no internet) Subnets
# --------------------------------------------------------------------------
variable "internal" {
  description = "Enable / Disable Internal Subnets"
  type        = bool
  default     = false
}

variable "internal_subnet_name" {
  description = "Name for Internal subnets and dependent resources  (will be prefixed with `var.name-`)"
  type        = string
  default     = "internal"
}

variable "internal_subnet_tags" {
  description = "Tags as map for Internal subnets and dependent resources (preferably generated by terraform-null-label)"
  type        = map(string)
  default = {
    "type" = "internal"
  }
}

# --------------------------------------------------------------------------
# Public Subnets
# --------------------------------------------------------------------------
variable "public" {
  description = "Enable / Disable Public Subnets"
  type        = bool
  default     = true
}

variable "public_subnet_name" {
  description = "Name for Public subnets and dependent resources  (will be prefixed with `var.name-`)"
  type        = string
  default     = "public"
}

variable "public_subnet_tags" {
  description = "Tags as map for Public subnets and dependent resources (preferably generated by terraform-null-label)"
  type        = map(string)
  default = {
    "type" = "public"
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.45.0"
    }
  }
}

# --------------------------------------------------------------------------
# VPC Endpoint (Gateway) - S3
# --------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  count = var.s3_endpoint ? 1 : 0

  vpc_id       = aws_vpc.vpc.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"

  tags = merge(
    local.tags,
    tomap({
      "Name" = "${var.name}-s3"
    })
  )

}

resource "aws_vpc_endpoint_route_table_association" "private_s3" {
  count = var.s3_endpoint && var.private_endpoints ? var.zones : 0

  vpc_endpoint_id = aws_vpc_endpoint.s3.0.id
  route_table_id  = element([for s in aws_route_table.private : s.id], count.index)
}

resource "aws_vpc_endpoint_route_table_association" "public_s3" {
  count = var.s3_endpoint && var.public_endpoints ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.s3.0.id
  route_table_id  = aws_route_table.public.0.id
}

resource "aws_vpc_endpoint_route_table_association" "internal_s3" {
  count = var.s3_endpoint && var.internal_endpoints ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.s3.0.id
  route_table_id  = aws_route_table.internal.0.id
}

resource "aws_vpc_endpoint_route_table_association" "db_s3" {
  count = var.s3_endpoint && var.db_endpoints ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.s3[0].id
  route_table_id  = aws_route_table.db[0].id
}

resource "aws_vpc_endpoint_route_table_association" "cache_s3" {
  count = var.s3_endpoint && var.cache_endpoints ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.s3[0].id
  route_table_id  = aws_route_table.cache[0].id
}

resource "aws_athena_database" "database_gold" {
  name   = "silver"
  bucket = aws_s3_bucket.lake_silver.id

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.data_lake.arn
  }
}

data "aws_iam_policy_document" "allow_cloudwatch_to_execute_policy" {
  statement {
    actions = [
      "sts:AssumeRole"
    ]

    principals {
      type = "Service"
      identifiers = [
        "states.amazonaws.com",
        "events.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role" "allow_cloudwatch_to_execute_role" {
  name               = "aws-events-invoke-StepFunction"
  assume_role_policy = data.aws_iam_policy_document.allow_cloudwatch_to_execute_policy.json
}

resource "aws_iam_role_policy" "state_execution" {
  name = "state_execution_policy"
  role = aws_iam_role.allow_cloudwatch_to_execute_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "Stmt1647307985962",
      "Action": [
        "states:StartExecution"
      ],
      "Effect": "Allow",
      "Resource": "${aws_sfn_state_machine.aws_step_function_workflow.arn}"
    }
  ]
}
EOF
}

resource "aws_cloudwatch_event_rule" "stf_trigger_rule" {
  name                = "stf_trigger_rule"
  schedule_expression = var.schedulerColetaClima
  description         = "Sample Event for Glue terraform example"
}

resource "aws_cloudwatch_event_target" "cloudwatch_event_target" {
  rule     = aws_cloudwatch_event_rule.stf_trigger_rule.name
  arn      = aws_sfn_state_machine.aws_step_function_workflow.arn
  role_arn = aws_iam_role.allow_cloudwatch_to_execute_role.arn
}

# Outputs
output "aws_cloudwatch_event_rule_arn" {
  value = aws_cloudwatch_event_rule.stf_trigger_rule.arn
}

#-----------------------------------------------------------------------------------------
#--- Politica IAM para o Serviço de Ingestão de dados do Glue
#-----------------------------------------------------------------------------------------
data "aws_iam_policy_document" "glue_role_ingestion" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "glue_policy_ingestion" {
  version = "2012-10-17"
  statement {
    effect = "Allow"
    resources = [
      "*"
    ]
    actions = [
      "secretsmanager:*",
      "cloudwatch:*",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "glue:GetTable",
      "glue:*"
    ]
  }
  statement {
    effect = "Allow"
    resources = [
      "${aws_s3_bucket.artefact_glue.arn}",
      "${aws_s3_bucket.artefact_glue.arn}/*",
      "${aws_s3_bucket.lake_staging.arn}",
      "${aws_s3_bucket.lake_staging.arn}/*",
      "${aws_s3_bucket.lake_bronze.arn}",
      "${aws_s3_bucket.lake_bronze.arn}/*",
      "${aws_s3_bucket.lake_silver.arn}",
      "${aws_s3_bucket.lake_silver.arn}/*",
      "${aws_s3_bucket.lake_gold.arn}",
      "${aws_s3_bucket.lake_gold.arn}/*",
      "${aws_s3_bucket.logdir.arn}",
      "${aws_s3_bucket.logdir.arn}/*"
    ]
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
  }
}

resource "aws_glue_job" "etl_jobs" {
  name     = var.glueJobName
  role_arn = aws_iam_role.glue_role_ingestion_resource.arn

  command {
    python_version  = var.python_version
    script_location = "s3://${var.bucket_artefact_glue}-${local.account_id}/glueClima/extraiDados.py"
  }
  default_arguments = {
    "--TempDir"                          = "s3://${var.bucket_log}-${local.account_id}/tempClima"
    "--enable-continuous-cloudwatch-log" = "True"
    "--enable-glue-datacatalog"          = "True"
    "--enable-metrics"                   = "True"
    "--enable-spark-ui"                  = "True"
    "--job-language"                     = "python"
  }
  execution_property {
    max_concurrent_runs = 2
  }
  glue_version      = "4.0"
  max_retries       = 0
  worker_type       = "G.1X"
  number_of_workers = 20
  timeout           = 2880
  tags              = local.common_tags
}

resource "aws_glue_job" "transforma_job" {
  name     = var.glueJobNameTransforma
  role_arn = aws_iam_role.glue_role_ingestion_resource.arn

  command {
    python_version  = var.python_version
    script_location = "s3://${var.bucket_artefact_glue}-${local.account_id}/glueClima/transformaDados.py"
  }
  default_arguments = {
    "--TempDir"                          = "s3://${var.bucket_log}-${local.account_id}/tempClima"
    "--enable-continuous-cloudwatch-log" = "True"
    "--enable-glue-datacatalog"          = "True"
    "--enable-metrics"                   = "True"
    "--enable-spark-ui"                  = "True"
    "--job-language"                     = "python"
    "--additional-python-modules"        = "requests,uuid,pyarrow,deltalake"
    "--continuous-log-logGroup"          = "transformaClima"
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${var.bucket_artefact_glue}-${local.account_id}/glueClima/lib.zip"
  }
  execution_property {
    max_concurrent_runs = 2
  }
  glue_version      = "4.0"
  max_retries       = 0
  worker_type       = "G.1X"
  number_of_workers = 20
  timeout           = 2880
  tags              = local.common_tags
}

#-------------------------------------------------------------------------------------
#-- Role Glue para Ingestão de Dados
#-------------------------------------------------------------------------------------
resource "aws_iam_role" "glue_role_ingestion_resource" {
  name               = "${var.glueingestionrole}-${local.account_id}"
  assume_role_policy = data.aws_iam_policy_document.glue_role_ingestion.json
}


resource "aws_iam_role_policy" "policylambdabronze" {
  name   = "${var.glueingestionpolicy}-${local.account_id}"
  role   = aws_iam_role.glue_role_ingestion_resource.id
  policy = data.aws_iam_policy_document.glue_policy_ingestion.json
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

locals {
  common_tags = {
    manage_by = "terraform",
    owner     = "tavares"
  }
}

terraform {
  required_version = ">= 1.6.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.42.0"
    }
  }

}

provider "aws" {
  region = "us-east-2"
  default_tags {
    tags = {
      owner      = "tavares"
      managed-by = "terraform"
      enviroment = "data-plataform"
    }
  }
}

#-------------------------------------------------------------------------------------
# Bucket Artefatos Jobs Glue
#-------------------------------------------------------------------------------------
resource "aws_s3_bucket" "artefact_glue" {
  bucket = "${var.bucket_artefact_glue}-${local.account_id}"
}

resource "aws_s3_bucket_versioning" "artefact_glue_versioning" {
  bucket = aws_s3_bucket.artefact_glue.id
  versioning_configuration {
    status = "Enabled"
  }
}

#-------------------------------------------------------------------------------------
# Buckets Data Lake
#-------------------------------------------------------------------------------------
resource "aws_s3_bucket" "lake_staging" {
  bucket = "${var.bucket_staging_lake}-${local.account_id}"
}

resource "aws_s3_bucket" "lake_bronze" {
  bucket = "${var.bucket_bronze_lake}-${local.account_id}"
}
resource "aws_s3_bucket_versioning" "lake_versioning_bronze" {
  bucket = aws_s3_bucket.lake_bronze.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "lake_silver" {
  bucket = "${var.bucket_silver_lake}-${local.account_id}"
}
resource "aws_s3_bucket_versioning" "lake_versioning_silver" {
  bucket = aws_s3_bucket.lake_silver.id
  versioning_configuration {
    status = "Enabled"
  }
}
resource "aws_s3_bucket" "lake_gold" {
  bucket = "${var.bucket_gold_lake}-${local.account_id}"
}
resource "aws_s3_bucket_versioning" "lake_versioning_gold" {
  bucket = aws_s3_bucket.lake_gold.id
  versioning_configuration {
    status = "Enabled"
  }
}
resource "aws_s3_bucket" "logdir" {
  bucket = "${var.bucket_log}-${local.account_id}"
}


## Copia Script Glue para o Bucket artefact_glue
resource "aws_s3_object" "artefact_glue" {
  depends_on = [aws_s3_bucket_versioning.artefact_glue_versioning]
  for_each   = fileset("glueClima/", "**")
  bucket     = aws_s3_bucket.artefact_glue.id
  key        = "glueClima/${each.value}"
  source     = "glueClima/${each.value}"
  etag       = filemd5("glueClima/${each.value}")
}

#-------------------------------------------------------------------------------------
# Shared CMK for S3/Athena encryption at rest
#-------------------------------------------------------------------------------------
resource "aws_kms_key" "data_lake" {
  description         = "CMK for data-lake S3 buckets and Athena database encryption"
  enable_key_rotation = true
}

resource "aws_kms_alias" "data_lake" {
  name          = "alias/${var.bucket_artefact_glue}-data-lake"
  target_key_id = aws_kms_key.data_lake.key_id
}

#-------------------------------------------------------------------------------------
# Public access block (AWS-0086/0087/0091/0093) for every bucket
#-------------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "artefact_glue" {
  bucket                  = aws_s3_bucket.artefact_glue.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "lake_staging" {
  bucket                  = aws_s3_bucket.lake_staging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "lake_bronze" {
  bucket                  = aws_s3_bucket.lake_bronze.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "lake_silver" {
  bucket                  = aws_s3_bucket.lake_silver.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "lake_gold" {
  bucket                  = aws_s3_bucket.lake_gold.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logdir" {
  bucket                  = aws_s3_bucket.logdir.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

#-------------------------------------------------------------------------------------
# Server-side encryption with the CMK above (AWS-0132) for every bucket
#-------------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "artefact_glue" {
  bucket = aws_s3_bucket.artefact_glue.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lake_staging" {
  bucket = aws_s3_bucket.lake_staging.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lake_bronze" {
  bucket = aws_s3_bucket.lake_bronze.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lake_silver" {
  bucket = aws_s3_bucket.lake_silver.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lake_gold" {
  bucket = aws_s3_bucket.lake_gold.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logdir" {
  bucket = aws_s3_bucket.logdir.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }
  }
}

# AWS Step Functions IAM roles and Policies
resource "aws_iam_role" "aws_stf_role" {
  name               = "aws-stf-role"
  assume_role_policy = <<EOF
{
   "Version":"2012-10-17",
   "Statement":[
      {
         "Action":"sts:AssumeRole",
         "Principal":{
            "Service":[
                "states.amazonaws.com"
            ]
         },
         "Effect":"Allow",
         "Sid":"StepFunctionAssumeRole"
      }
   ]
}
EOF
}

resource "aws_iam_role_policy" "step_function_policy" {
  name = "aws-stf-policy"
  role = aws_iam_role.aws_stf_role.id

  policy = <<EOF
{
   "Version":"2012-10-17",
   "Statement":[
      {
         "Action":[
                "glue:StartJobRun",
                "glue:GetJobRun",
                "glue:GetJobRuns",
                "glue:BatchStopJobRun"
         ],
         "Effect":"Allow",
         "Resource":[
         "${aws_glue_job.etl_jobs.arn}",
         "${aws_glue_job.transforma_job.arn}"
         ]
      }
  ]
}

EOF
}

# AWS Step function definition
resource "aws_sfn_state_machine" "aws_step_function_workflow" {
  name       = "aws-step-function-workflow"
  role_arn   = aws_iam_role.aws_stf_role.arn
  definition = <<EOF
{
    "Comment":"A description of the sample glue job state machine using Terraform",
    "StartAt":"Glue StartJobRun",
    "States": {

        "Glue StartJobRun": {
            "Type":"Task",
            "Resource":"arn:aws:states:::glue:startJobRun.sync",
            "Parameters": {
                "JobName":"${aws_glue_job.etl_jobs.name}",
                "Arguments": {
                    "--cidade":"${var.Cidade_API_Clima}",
                    "--bucketDataLakeStaging":"${var.bucket_staging_lake}-${local.account_id}",
                    "--pastaArqs":"clima",
                    "--api_key":"${var.key_api}"
                }
            },
            "Next": "Processa Dados"
         },

        "Processa Dados": {
            "Type":"Task",
            "Resource":"arn:aws:states:::glue:startJobRun.sync",
            "Parameters": {
                "JobName":"${aws_glue_job.transforma_job.name}",
                "Arguments": {
                    "--bucketDataLakeStaging":"${var.bucket_staging_lake}-${local.account_id}",
                    "--bucketDataLakeBronze":"${var.bucket_bronze_lake}-${local.account_id}",
                    "--bucketDataLakeSilver":"${var.bucket_silver_lake}-${local.account_id}",
                    "--pastaArqs":"clima",
                    "--key":"${var.keyTraduz}"
               }
            },
            "End":true
        }
    }
}
EOF

}

