variable "glueingestionpolicy" {
  description = "Policy IAM para o serviço de ingestão de dados no Glue"
  type        = string
  default     = "glue-ingestion-policy"
}

variable "glueingestionrole" {
  description = "Role IAM para o serviço de ingestão de dados no Glue"
  type        = string
  default     = "glue-ingestion-role"
}

variable "glueJobName" {
  description = "Nome Job Glue"
  type        = string
  default     = "glue-job-extrai-dados"
}

variable "glueJobNameTransforma" {
  description = "Nome Job Glue"
  type        = string
  default     = "glue-job-transforma-dados"
}

variable "python_version" {
  description = "Versão Python do Job Glue"
  type        = string
  default     = "3"
}

variable "bucket_artefact_glue" {
  description = "Bucket S3 Armazenamento Scripts Glue"
  type        = string
  default     = "benchmark-glue-artefacts"
}

variable "bucket_staging_lake" {
  description = "Bucket S3 Armazenamento Dados Camada Staging"
  type        = string
  default     = "benchmark-datalake-staging"
}

variable "bucket_bronze_lake" {
  description = "Bucket S3 Armazenamento Dados Camada Bronze"
  type        = string
  default     = "benchmark-datalake-bronze"
}

variable "bucket_silver_lake" {
  description = "Bucket S3 Armazenamento Dados Camada Bronze"
  type        = string
  default     = "benchmark-datalake-silver"
}

variable "bucket_gold_lake" {
  description = "Bucket S3 Armazenamento Dados Camada Bronze"
  type        = string
  default     = "benchmark-datalake-gold"
}

variable "bucket_log" {
  description = "Bucket S3 Armazenamento os Logs"
  type        = string
  default     = "benchmark-datalake-logs"
}

variable "key_api" {
  description = "Key API Clima"
  type        = string
  default     = "benchmark-placeholder-api-key"
}

variable "Cidade_API_Clima" {
  description = "Cidade para coleta de temperatura API"
  type        = string
  default     = "Sao Paulo"
}

variable "schedulerColetaClima" {
  description = "Schedulaer para Coleta do Clima"
  type        = string
  default     = "cron(0 * * * ? *)"
}

variable "keyTraduz" {
  description = "Key API Tradução Azure"
  type        = string
  default     = "benchmark-placeholder-key"
}

/*
title: basic-cicd-s3-pipeline
desc: Builds a codepipeline and codebuild job attached to an S3 backed cloudfront distribution to deploy changes as the source code changes.
partners: static-site, github-status-updater
*/

provider "aws" {
  region = var.aws_region
}

terraform {
}

data "aws_caller_identity" "current" {}

# Self-contained: the original template looked up a pre-existing bucket by
# name via a data source (a genuine external-dependency gap); create one
# instead so this scenario doesn't require an already-existing S3 bucket.
resource "aws_s3_bucket" "target_bucket" {
  bucket = "${var.s3_bucket}-${data.aws_caller_identity.current.account_id}"
}

resource "aws_kms_key" "s3_buckets" {
  description         = "CMK for the CI/CD pipeline's S3 buckets"
  enable_key_rotation = true
}

resource "aws_s3_bucket_public_access_block" "block_target_bucket_pub_access" {
  bucket = aws_s3_bucket.target_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "encrypt_target_bucket" {
  bucket = aws_s3_bucket.target_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_buckets.arn
    }
  }
}

# Self-contained: gh_secret_sm_param_name/gh_token_sm_param_name looked up
# pre-existing SSM parameters the original template never created (a genuine
# external-dependency gap); create placeholder ones instead.
resource "aws_ssm_parameter" "gh_secret" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name  = var.gh_secret_sm_param_name != "" ? var.gh_secret_sm_param_name : "/benchmark/${var.site_name}/gh-webhook-secret"
  type  = "SecureString"
  value = "benchmark-placeholder-webhook-secret"
}

resource "aws_ssm_parameter" "gh_token" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name  = var.gh_token_sm_param_name != "" ? var.gh_token_sm_param_name : "/benchmark/${var.site_name}/gh-oauth-token"
  type  = "SecureString"
  value = "benchmark-placeholder-oauth-token"
}

data "aws_ssm_parameter" "gh_secret" {
  count      = var.codestar_connection_arn == "" ? 1 : 0
  depends_on = [aws_ssm_parameter.gh_secret]

  name = aws_ssm_parameter.gh_secret[0].name
}

data "aws_ssm_parameter" "gh_token" {
  count      = var.codestar_connection_arn == "" ? 1 : 0
  depends_on = [aws_ssm_parameter.gh_token]

  name = aws_ssm_parameter.gh_token[0].name
}

resource "aws_s3_bucket_server_side_encryption_configuration" "encrypt_bucket" {
  count = var.encrypt_buckets == true ? 1 : 0

  bucket = aws_s3_bucket.build_bucket.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_buckets.arn
    }
  }
}

resource "aws_s3_bucket_logging" "bucket_logging" {
  count = var.access_log_bucket == "" ? 0 : 1

  bucket = aws_s3_bucket.build_bucket.id
  target_bucket = var.access_log_bucket
  target_prefix = var.access_log_prefix
}

resource "aws_s3_bucket" "build_bucket" {

  tags = {
    Name = "Static site build bucket"
    Site = var.site_name
  }

  force_destroy = true

}

resource "aws_s3_bucket_policy" "require_secure_transport" {
  bucket = aws_s3_bucket.build_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "BUCKET-POLICY"
    Statement = [
      {
        Sid       = "EnforceTls"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "${aws_s3_bucket.build_bucket.arn}/*",
          "${aws_s3_bucket.build_bucket.arn}",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

resource "aws_s3_bucket_public_access_block" "block_build_bucket_pub_access" {
  bucket = aws_s3_bucket.build_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "code_build_assume_policy" {
  statement {
    sid    = ""
    effect = "Allow"

    principals {
      identifiers = ["codebuild.amazonaws.com"]
      type        = "Service"
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "code_pipeline_assume_policy" {
  statement {
    sid    = ""
    effect = "Allow"

    principals {
      identifiers = ["codepipeline.amazonaws.com"]
      type        = "Service"
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "code_build_policy_document" {
  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/*"
    ]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.target_bucket.arn,
      "${aws_s3_bucket.target_bucket.arn}/*",
      aws_s3_bucket.build_bucket.arn,
      "${aws_s3_bucket.build_bucket.arn}/*"
    ]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = ["cloudfront:CreateInvalidation"]
    resources = ["*"]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "ssm:GetParameters",
      "ssm:GetParameter"
    ]
    //resources = formatlist("arn:aws:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:parameter%s", var.secure_build_environment)
    resources = ["*"]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.s3_buckets.arn]
  }
}

data "aws_iam_policy_document" "code_pipeline_policy_document" {
  statement {
    sid     = ""
    effect  = "Allow"
    actions = ["s3:PutObject"]
    resources = [
      aws_s3_bucket.build_bucket.arn,
      "${aws_s3_bucket.build_bucket.arn}/*"
    ]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.s3_buckets.arn]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning"
    ]
    resources = ["*"]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild"
    ]
    resources = ["*"]
  }

  statement {
    sid     = ""
    effect  = "Allow"
    actions = [
      "codestar-connections:UseConnection"
    ]
    resources = [
      "arn:aws:codestar-connections:${var.aws_region}:${data.aws_caller_identity.current.account_id}:connection/*"
    ]
  }
}

resource "aws_iam_policy" "code_build_policy" {
  policy = data.aws_iam_policy_document.code_build_policy_document.json
}

resource "aws_iam_policy" "code_pipeline_policy" {
  policy = data.aws_iam_policy_document.code_pipeline_policy_document.json
}

resource "aws_iam_role" "code_build_role" {
  assume_role_policy = data.aws_iam_policy_document.code_build_assume_policy.json
}

resource "aws_iam_role" "code_pipeline_role" {
  assume_role_policy = data.aws_iam_policy_document.code_pipeline_assume_policy.json
}

resource "aws_iam_policy_attachment" "attach_cb_policy_to_role" {
  name        = "basic-cicd-build-${var.site_name}-${var.cf_distribution}-cb-attach"
  roles       = [aws_iam_role.code_build_role.name]
  policy_arn  = aws_iam_policy.code_build_policy.arn
}

resource "aws_iam_policy_attachment" "attach_cp_policy_to_role" {
  name        = "basic-cicd-build-${var.site_name}-${var.cf_distribution}-cp-attach"
  roles       = [aws_iam_role.code_pipeline_role.name]
  policy_arn  = aws_iam_policy.code_pipeline_policy.arn
}

resource "aws_iam_role_policy_attachment" "cb_role_user_policies" {
  count       = length(var.build_role_policies)

  role        = aws_iam_role.code_build_role.name
  policy_arn  = element(var.build_role_policies, count.index)
}

resource "aws_codebuild_project" "codebuild_project" {
  name          = "basic-cicd-build-${var.gh_repo}-${var.gh_branch}-${var.cf_distribution}"
  description   = "build site ${var.site_name} for CF dist ${var.cf_distribution} from repo ${var.gh_repo} using branch ${var.gh_branch}"
  build_timeout = var.build_timeout
  service_role  = aws_iam_role.code_build_role.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type = "NO_CACHE"
  }

  environment {
    compute_type                = var.build_compute_type
    image                       = var.build_image
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = var.allow_root

    environment_variable {
      name  = "TARGET_BUCKET"
      value = var.s3_bucket
    }

    environment_variable {
      name  = "INVALIDATE"
      value = var.cf_invalidate
    }

    environment_variable {
      name  = "DISTRIBUTION_ID"
      value = var.cf_distribution
    }

    dynamic "environment_variable" {
      for_each = var.build_environment

      content {
        name  = environment_variable.value.name
        value = environment_variable.value.value
      }
    }

    dynamic "environment_variable" {
      for_each = var.secure_build_environment

      content {
        name  = environment_variable.value.name
        value = environment_variable.value.value
        type  = environment_variable.value.type
      }
    }

  }

  source {
    type = "CODEPIPELINE"
  }
}

resource "random_uuid" "notify_name" { }

resource "aws_codestarnotifications_notification_rule" "notifications" {
  count = var.send_notifications == true ? 1 : 0

  detail_type     = "FULL"
  event_type_ids  = var.notifications_to_send
  name            = random_uuid.notify_name.result
  resource        = aws_codepipeline.buildpipeline.arn

  target {
    address = var.sns_topic_for_notifications
  }
}

resource "aws_codepipeline" "buildpipeline" {
  name        = "basic-cicd-pipeline-${var.gh_repo}-${var.gh_branch}-${var.cf_distribution}"
  role_arn    = aws_iam_role.code_pipeline_role.arn

  artifact_store {
    location  = aws_s3_bucket.build_bucket.bucket
    type      = "S3"
  }

  stage {
    name = "Source"

    // this is the GH v1 connection
    dynamic "action" {
      for_each = var.codestar_connection_arn == "" ? [ "blah" ] : []

      content {
        name              = "Source"
        category          = "Source"
        owner             = "ThirdParty"
        provider          = "GitHub"
        version           = "1"
        output_artifacts  = [ var.gh_branch ]

        configuration = {
          Owner                 = var.gh_username
          Repo                  = var.gh_repo
          Branch                = var.gh_branch
          OAuthToken            = data.aws_ssm_parameter.gh_token.0.value
          PollForSourceChanges  = false
        }
      }
    }

    // this is the GH v2 connection
    dynamic "action" {
      for_each = var.codestar_connection_arn != "" ? [ "blah" ] : []

      content {
        name              = "Source"
        category          = "Source"
        owner             = "AWS"
        provider          = "CodeStarSourceConnection"
        version           = "1"
        output_artifacts  = [var.gh_branch]

        configuration = {
          ConnectionArn    = var.codestar_connection_arn
          FullRepositoryId = "${var.gh_username}/${var.gh_repo}"
          BranchName       = var.gh_branch
          DetectChanges    = true
        }
      }
    }
  }

  stage {
    name = "Build"

    action {
      name            = "Build"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      input_artifacts = [var.gh_branch]
      version         = "1"

      configuration = {
        ProjectName = "basic-cicd-build-${var.gh_repo}-${var.gh_branch}-${var.cf_distribution}"
      }
    }
  }
}

resource "aws_codepipeline_webhook" "webhook" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name            = "github-${var.gh_repo}-${var.gh_branch}-${var.cf_distribution}"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.buildpipeline.name

  authentication_configuration {
    secret_token = data.aws_ssm_parameter.gh_secret.0.value
  }

  filter {
    json_path     = "$.ref"
    match_equals  = "refs/heads/{Branch}"
  }
}

output "webhook_url" {
    value = var.codestar_connection_arn != "" ? "" : aws_codepipeline_webhook.webhook.0.url
}

variable "aws_region" {
  type = string
  description = "region where provisioning should happen"
  default = "us-east-1"
}

variable "gh_username" {
  type = string
  description = "GitHub username used to access your site source code repo"
  default = "benchmark-user"
}

variable "gh_secret_sm_param_name" {
  type = string
  default = ""
  description = "name of SSM parameter where GitHub webhook secret is stored"
}

variable "gh_token_sm_param_name" {
  type = string
  default = ""
  description = "name of SSM parameter where the GitHub Oauth token is stored"
}

variable "gh_repo" {
  type = string
  description = "name of repo containing site source and buildspec.yml file"
  default = "benchmark-site-repo"
}

variable "gh_branch" {
  type = string
  default = "master"
  description = "branch of git repo to use for changes"
}

variable "site_name" {
  type = string
  description = "FQDN of site e.g. www.example.com"
  default = "benchmark.example.com"
}

variable "cf_distribution" {
  type = string
  description = "ID of the CF distribution to be updated on each deployment"
  default = "BENCHMARKCFDIST"
}

variable "s3_bucket" {
  type = string
  description = "S3 bucket where the files behind the CF distribution are placed"
  default = "benchmark-cicd-target"
}

variable "build_timeout" {
  default = 5
  type = number
  description = "how long should we wait (in minutes) before assuming a build has failed"
}

variable "cf_invalidate" {
  default = "yes"
  type = string
  description = "should the CF distribution be invalidated for each deployment"
}

variable "encrypt_buckets" {
  type = bool
  default = true
  description = "encrypt buckets with default AWS keys"
}

variable "allow_root" {
  type = bool
  default = false
  description = "allow build process to become root (sudo)"
}

variable "build_image" {
  type = string
  default = "aws/codebuild/standard:2.0"
  description = "what build image should be used to run the build job"
}

variable "send_notifications" {
  type = bool
  default = false
  description = "should pipeline notifications be sent"
}

variable "sns_topic_for_notifications" {
  type = string
  description = "arn for sns topic to send notifications to"
  default = ""
}

variable "notifications_to_send" {
  type = list(string)
  description = "which notifications should we send, for values see here https://docs.aws.amazon.com/codestar-notifications/latest/userguide/concepts.html#concepts-api"
  default = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-canceled",
    "codepipeline-pipeline-pipeline-execution-started",
    "codepipeline-pipeline-pipeline-execution-resumed",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-superseded"
  ]
} 

variable "access_log_bucket" {
  type = string
  default = ""
  description = "bucket to be used for access logging on the pipeline s3 bucket"
}

variable "access_log_prefix" {
  type = string
  default = ""
  description = "prefix to use for pipeline bucket access logs where that is enabled"
}

variable "build_role_policies" {
  description = "list of ARNs of policies to attach to the build role"
  default = []
  type = list(string)
}

variable "build_environment" {
  description = "non secret build environment variables"
  default = []
  type = list(object({
    name = string,
    value = string
  }))
}

variable "secure_build_environment" {
  description = "secret build environment variables"
  default = []
  type = list(object({
    name = string,
    value = string,
    type = string
  }))
}

variable "build_compute_type" {
  type = string
  default = "BUILD_GENERAL1_SMALL"
  description = "compute type for the build job"
}

variable "codestar_connection_arn" {
  type = string
  description = "ARN for the codestar connection to use to access github"
  default = ""
}

locals {
  subnets_with_db_subnet_group = { for subnet in var.subnets : subnet.db_subnet_group_name => subnet if can(subnet.db_subnet_group_name) }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  for_each = local.subnets_with_db_subnet_group

  name        = each.key
  subnet_ids  = [for subnet in local.subnets : aws_subnet.subnet[subnet.cidr_block].id if subnet.db_subnet_group_name == each.key]
  description = try(each.value.description, "Managed by mineiros-io/vpc/aws Terraform Module")

  tags = merge(var.module_tags, try(each.value.tags, {}))
}

locals {
  subnets_with_elasticache_subnet_group = { for subnet in var.subnets : subnet.elasticache_subnet_group_name => subnet if can(subnet.elasticache_subnet_group_name) }
}

resource "aws_elasticache_subnet_group" "elasticache_subnet_group" {
  for_each = local.subnets_with_elasticache_subnet_group

  name        = each.key
  subnet_ids  = [for subnet in local.subnets : aws_subnet.subnet[subnet.cidr_block].id if subnet.elasticache_subnet_group_name == each.key]
  description = try(each.value.description, "Managed by mineiros-io/vpc/aws Terraform Module")

  tags = merge(var.module_tags, try(each.value.tags, {}))
}

# ---------------------------------------------------------------------------------------------------------------------
# CREATE intra ROUTING AND AN INTERNET GATEWAY IF A intra SUBNETS IS DEFINED
# ---------------------------------------------------------------------------------------------------------------------

locals {
  intra_subnets = [for subnet in local.subnets : subnet if subnet.class == "intra"]

  intra_groups = try(distinct(local.intra_subnets.*.group), [])

  intra_subnets_by_group = {
    for group in local.intra_groups : group => [
      for subnet in local.intra_subnets : subnet if subnet.group == group
    ]
  }
}

resource "aws_route_table" "intra" {
  for_each = var.module_enabled ? local.intra_subnets_by_group : {}

  vpc_id = aws_vpc.vpc[0].id

  # propagating_vgws = try(local.subnets[each.key].propagating_vgws, null)

  tags = merge(
    {
      Name = "${var.vpc_name}-intra-${each.key}"

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name"         = var.vpc_name
      "mineiros-io/aws/vpc/routetable-name"  = "${var.vpc_name}-intra-${each.key}"
      "mineiros-io/aws/vpc/routetable-class" = "intra"
    },
    var.module_tags,
    var.route_table_tags,
    var.intra_route_table_tags,
  )

  depends_on = [var.module_depends_on]
}

resource "aws_route_table_association" "intra" {
  for_each = var.module_enabled ? {
    for subnet in flatten(values(local.intra_subnets_by_group)) : subnet.cidr_block => subnet
  } : {}

  subnet_id      = aws_subnet.subnet[each.key].id
  route_table_id = aws_route_table.intra[each.value.group].id

  depends_on = [var.module_depends_on]
}

# ---------------------------------------------------------------------------------------------------------------------
# DEPLOY AND MANAGE A VPC
# ---------------------------------------------------------------------------------------------------------------------

# ---------------------------------------------------------------------------------------------------------------------
# When you create a VPC, we recommend that you specify a CIDR block (of /16 or smaller) from the private IPv4 address
# ranges as specified in RFC 1918 (http://www.faqs.org/rfcs/rfc1918.html):
# - 10.0.0.0 - 10.255.255.255 (10/8 prefix)
# - 172.16.0.0 - 172.31.255.255 (172.16/12 prefix)
# - 192.168.0.0 - 192.168.255.255 (192.168/16 prefix)
#
# The first four IP addresses and the last IP address in each subnet CIDR block are not available for you to use, and
# cannot be assigned to an instance. For example, in a subnet with CIDR block 10.0.0.0/24, the following five IP
# addresses are reserved:
# - 10.0.0.0: Network address.
# - 10.0.0.1: Reserved by AWS for the VPC router.
# - 10.0.0.2: Reserved by AWS. The IP address of the DNS server is the base of the VPC network range plus two.
# ---------------------------------------------------------------------------------------------------------------------

data "aws_region" "region" {
  count = var.module_enabled ? 1 : 0
}

locals {
  region = try(data.aws_region.region[0].name, "")
}

resource "aws_vpc" "vpc" {
  count = var.module_enabled ? 1 : 0

  # We convert the cidr_block to its cannonical form because AWS would do it in the API anyway
  # and we want to ensure this is not showing a constant change when planning.
  # We will do the same for all created subnets.
  # We will do the same for all created routes.
  cidr_block = cidrsubnet(var.cidr_block, 0, 0)

  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_classiclink               = var.enable_classiclink
  enable_classiclink_dns_support   = var.enable_classiclink_dns_support
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block

  tags = merge(
    {
      Name = var.vpc_name

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name" = var.vpc_name
    },
    var.module_tags,
    var.vpc_tags,
  )

  depends_on = [var.module_depends_on]
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUT CALCULATED VARIABLES (prefer full objects)
# ----------------------------------------------------------------------------------------------------------------------

locals {
  public_aws_subnets_by_group = {
    for group, subnets in local.public_subnets_by_group : group => [
      for subnet in aws_subnet.subnet : subnet if contains(subnets.*.cidr_block, subnet.cidr_block)
    ]
  }

  private_aws_subnets_by_group = {
    for group, subnets in local.private_subnets_by_group : group => [
      for subnet in aws_subnet.subnet : subnet if contains(subnets.*.cidr_block, subnet.cidr_block)
    ]
  }

  intra_aws_subnets_by_group = {
    for group, subnets in local.intra_subnets_by_group : group => [
      for subnet in aws_subnet.subnet : subnet if contains(subnets.*.cidr_block, subnet.cidr_block)
    ]
  }

  public_subnet_ids_by_group = {
    for group, subnets in local.public_aws_subnets_by_group : group => subnets.*.id
  }

  private_subnet_ids_by_group = {
    for group, subnets in local.private_aws_subnets_by_group : group => subnets.*.id
  }

  intra_subnet_ids_by_group = {
    for group, subnets in local.intra_aws_subnets_by_group : group => subnets.*.id
  }

  public_route_table_ids_by_group = {
    for group, subnet_ids in local.public_subnet_ids_by_group : group => distinct([
      for rta in try(values(aws_route_table_association.public), []) :
      rta.route_table_id if contains(subnet_ids, rta.subnet_id)
    ])
  }

  private_route_table_ids_by_group = {
    for group, subnet_ids in local.private_subnet_ids_by_group : group => distinct([
      for rta in try(values(aws_route_table_association.private), []) :
      rta.route_table_id if contains(subnet_ids, rta.subnet_id)
    ])
  }

  intra_route_table_ids_by_group = {
    for group, subnet_ids in local.intra_subnet_ids_by_group : group => distinct([
      for rta in try(values(aws_route_table_association.intra), []) :
      rta.route_table_id if contains(subnet_ids, rta.subnet_id)
    ])
  }
}


output "public_subnets_by_group" {
  description = "A map of lists of public subnets keyed by group. (aws_subnet)"
  value       = local.public_aws_subnets_by_group
}

output "public_route_table_ids_by_group" {
  description = "A map of lists of public route table IDs keyed by group."
  value       = local.public_route_table_ids_by_group
}

output "public_subnet_ids_by_group" {
  description = "A map of lists of public subnet IDs keyed by group."
  value       = local.public_subnet_ids_by_group
}

output "private_subnets_by_group" {
  description = "A map of lists of private subnets keyed by group. (aws_subnet)"
  value       = local.private_aws_subnets_by_group
}

output "private_route_table_ids_by_group" {
  description = "A map of lists of private route table IDs keyed by group."
  value       = local.private_route_table_ids_by_group
}

output "private_subnet_ids_by_group" {
  description = "A map of lists of private subnet IDs keyed by group."
  value       = local.private_subnet_ids_by_group
}

output "intra_subnets_by_group" {
  description = "A map of lists of intra aws_subnet keyed by group. (aws_subnet)"
  value       = local.intra_aws_subnets_by_group
}

output "intra_route_table_ids_by_group" {
  description = "A map of lists of intra route table IDs keyed by group."
  value       = local.intra_route_table_ids_by_group
}

output "intra_subnet_ids_by_group" {
  description = "A map of lists of intra subnet IDs keyed by group."
  value       = local.intra_subnet_ids_by_group
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUT ALL RESOURCES AS FULL OBJECTS
# ----------------------------------------------------------------------------------------------------------------------

output "vpc" {
  description = "The VPC. (aws_vpc)"
  value       = try(aws_vpc.vpc[0], null)
}

output "intra_route_tables" {
  description = "A map of intra route tables keyed by group. (aws_route_table)"
  value       = try(aws_route_table.intra, null)
}

output "intra_route_table_associations" {
  description = "A map of intra route table associations keyed by the subnets CIDR Blocks. (aws_route_table_association)"
  value       = try(aws_route_table_association.intra, null)
}

output "eips" {
  description = "A map of Elastic IP Adresses (EIPs) keyed by availability zone. (aws_eip)"
  value       = try(aws_eip.eip, null)
}

output "nat_gateways" {
  description = "A map of NAT gatweways keyed by availability zone. (aws_nat_gateway)"
  value       = try(aws_nat_gateway.nat_gateway, null)
}

output "private_route_tables" {
  description = "A map of private route tables keyed by group. (aws_route_table)"
  value       = try(aws_route_table.private, null)
}

output "private_route_table_associations" {
  description = "A map of private route table associations keyed by the subnets CIDR Blocks. (aws_route_table_association)"
  value       = try(aws_route_table_association.private, null)
}

output "routes_to_nat_gateways" {
  description = "A map of routes to the NAT Gateways keyed by group. (aws_route)"
  value       = try(aws_route.nat_gateway, null)
}

output "internet_gateway" {
  description = "The Internet Gateway. (aws_internet_gateway)"
  value       = try(aws_internet_gateway.internet_gateway[0], null)
}

output "public_route_tables" {
  description = "A map of public route tables keyed by group. (aws_route_table)"
  value       = try(aws_route_table.public, null)
}

output "public_route_table_associations" {
  description = "A map of public route table associations keyed by the subnets CIDR Blocks. (aws_route_table_association)"
  value       = try(aws_route_table_association.public, null)
}

output "routes_to_internet_gateway" {
  description = "A map of routes to the Internet Gateway keyed by group. (aws_route)"
  value       = try(aws_route.internet_gateway, null)
}

output "subnets" {
  description = "A map of subnets keyed by CIDR Blocks. (aws_subnet)"
  value       = try(aws_subnet.subnet, null)
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUT ALL INPUT VARIABLES
# ----------------------------------------------------------------------------------------------------------------------

output "module_inputs" {
  description = "A map of all module arguments. Set to the provided values or calculated default values."
  value = {
    vpc_name                         = var.vpc_name
    cidr_block                       = var.cidr_block
    assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block
    enable_classiclink               = var.enable_classiclink
    enable_classiclink_dns_support   = var.enable_classiclink_dns_support
    enable_dns_support               = var.enable_dns_support
    enable_dns_hostnames             = var.enable_dns_hostnames
    instance_tenancy                 = var.instance_tenancy

    subnets = var.subnets

    nat_gateway_mode = var.nat_gateway_mode

    vpc_tags              = merge(var.module_tags, var.vpc_tags)
    internet_gateway_tags = merge(var.module_tags, var.internet_gateway_tags)
    eip_tags              = merge(var.module_tags, var.eip_tags)
    nat_gateway_tags      = merge(var.module_tags, var.nat_gateway_tags)

    subnet_tags         = merge(var.module_tags, var.subnet_tags)
    public_subnet_tags  = merge(var.module_tags, var.subnet_tags, var.public_subnet_tags)
    private_subnet_tags = merge(var.module_tags, var.subnet_tags, var.private_subnet_tags)
    intra_subnet_tags   = merge(var.module_tags, var.subnet_tags, var.intra_subnet_tags)

    route_table_tags         = merge(var.module_tags, var.route_table_tags)
    public_route_table_tags  = merge(var.module_tags, var.route_table_tags, var.public_route_table_tags)
    private_route_table_tags = merge(var.module_tags, var.route_table_tags, var.private_route_table_tags)
    intra_route_table_tags   = merge(var.module_tags, var.route_table_tags, var.intra_route_table_tags)
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUT MODULE CONFIGURATION
# ----------------------------------------------------------------------------------------------------------------------

output "module_enabled" {
  description = "Whether the module is enabled."
  value       = var.module_enabled
}

output "module_tags" {
  description = "A map of tags that will be applied to all created resources that accept tags."
  value       = var.module_tags
}

# ---------------------------------------------------------------------------------------------------------------------
# CREATE PRIVATE ROUTING AND NAT GATEWAYS IF A PRIVATE SUBNETS IS DEFINED
# ---------------------------------------------------------------------------------------------------------------------

locals {
  private_subnets = [for subnet in local.subnets : subnet if subnet.class == "private"]

  private_group_azs = try(distinct(local.private_subnets.*.group_az), [])

  public_azs  = try(distinct(local.public_subnets.*.availability_zone), [])
  private_azs = try(distinct(local.private_subnets.*.availability_zone), [])

  private_groups = try(distinct(local.private_subnets.*.group), [])

  private_subnets_by_group = {
    for group in local.private_groups : group => [
      for subnet in local.private_subnets : subnet if subnet.group == group
    ]
  }

  private_subnets_by_group_az = {
    for group_az in local.private_group_azs : group_az => [
      for subnet in local.private_subnets : subnet if subnet.group_az == group_az
    ]
  }

  public_subnets_by_az = {
    for az in local.public_azs : az => [
      for subnet in local.public_subnets : subnet if subnet.availability_zone == az
    ]
  }

  # hacky assertion
  assert_each_private_subnet_has_a_public_in_same_az = {
    for az in local.missing_public_subnet_azs[var.nat_gateway_mode] : "Missing public subnet in az" => local.public_subnets_by_az[az]
  }

  nat_gateway_single_zones = var.nat_gateway_single_mode_zone != null ? ["${local.region}${var.nat_gateway_single_mode_zone}"] : try([local.matching_azs[0]], [])

  matching_azs = sort(setintersection(local.public_azs, local.private_azs))
  nat_azs = {
    one_per_az = local.matching_azs
    single     = local.nat_gateway_single_zones
    none       = []
  }

  nat_azs_set = toset(local.nat_azs[var.nat_gateway_mode])

  create_eips = length(keys(var.nat_gateway_eip_allocation_ids)) == 0

  missing_public_subnet_azs = {
    one_per_az = sort(setsubtract(local.private_azs, local.public_azs))
    single     = length(local.matching_azs) == 0 ? sort(setsubtract(local.private_azs, local.public_azs)) : []
    none       = []
  }
}

resource "aws_eip" "eip" {
  for_each = var.module_enabled && local.create_eips ? local.nat_azs_set : []

  vpc = true

  tags = merge(
    {
      Name = "${var.vpc_name}-nat-private-${each.key}"

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name"   = var.vpc_name
      "mineiros-io/aws/vpc/natgw-name" = "${var.vpc_name}-${each.key}"
      "mineiros-io/aws/vpc/eip-name"   = "${var.vpc_name}-nat-private-${each.key}"
    },
    var.module_tags,
    var.eip_tags,
  )

  depends_on = [var.module_depends_on]
}

locals {
  nat_gateway_eip_allocation_ids = { for k, v in var.nat_gateway_eip_allocation_ids : "${local.region}${k}" => v }

  eip_allocation_ids = { for k, v in aws_eip.eip : k => v.id }

  allocation_ids = local.create_eips ? local.eip_allocation_ids : local.nat_gateway_eip_allocation_ids
}

resource "aws_nat_gateway" "nat_gateway" {
  for_each = var.module_enabled ? local.nat_azs_set : []

  allocation_id = local.allocation_ids[each.key]
  subnet_id     = aws_subnet.subnet[local.public_subnets_by_az[each.key][0].cidr_block].id

  tags = merge(
    {
      Name = "${var.vpc_name}-${each.key}"

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name"   = var.vpc_name
      "mineiros-io/aws/vpc/natgw-name" = "${var.vpc_name}-${each.key}"
    },
    var.module_tags,
    var.nat_gateway_tags,
  )

  depends_on = [var.module_depends_on]
}

resource "aws_route_table" "private" {
  for_each = var.module_enabled ? local.private_subnets_by_group_az : {}

  vpc_id = aws_vpc.vpc[0].id

  # propagating_vgws = try(local.subnets[each.key].propagating_vgws, null)

  tags = merge(
    {
      Name = "${var.vpc_name}-private-${each.key}"

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name"         = var.vpc_name
      "mineiros-io/aws/vpc/routetable-name"  = "${var.vpc_name}-private-${each.key}"
      "mineiros-io/aws/vpc/routetable-class" = "private"
    },
    var.module_tags,
    var.route_table_tags,
    var.private_route_table_tags,
  )

  depends_on = [var.module_depends_on]
}

resource "aws_route_table_association" "private" {
  for_each = var.module_enabled ? {
    for subnet in flatten(values(local.private_subnets_by_group_az)) : subnet.cidr_block => subnet
  } : {}

  subnet_id      = aws_subnet.subnet[each.key].id
  route_table_id = aws_route_table.private[each.value.group_az].id

  depends_on = [var.module_depends_on]
}

locals {
  nat_routes = { for k, v in aws_route_table.private : "${var.nat_gateway_mode}/${k}" => v }
}

resource "aws_route" "nat_gateway" {
  for_each = length(local.nat_azs_set) > 0 ? local.nat_routes : {}

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id = try(
    aws_nat_gateway.nat_gateway[local.private_subnets_by_group_az[each.key][0].availability_zone].id,
    element(values(aws_nat_gateway.nat_gateway)[*].id, 0),
    null,
  )

  # Workaround for https://github.com/terraform-providers/terraform-provider-aws/issues/338
  timeouts {
    create = "10m"
  }

  # we depend on nat gateways to be available for setting and updating routes
  # the implicit dependency does not work, when changing nat gateway mode as we will
  # only depend on the new gateway implictly and not on the one being removed.
  # (e.g. when switching nat_gateway_mode)
  depends_on = [
    var.module_depends_on,
    aws_nat_gateway.nat_gateway,
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# CREATE PUBLIC ROUTING AND AN INTERNET GATEWAY IF A PUBLIC SUBNET IS DEFINED
# ---------------------------------------------------------------------------------------------------------------------

locals {
  public_subnets = [for subnet in local.subnets : subnet if subnet.class == "public"]

  public_groups = try(distinct(local.public_subnets.*.group), [])

  public_subnets_by_group = {
    for group in local.public_groups : group => [
      for subnet in local.public_subnets : subnet if subnet.group == group
    ]
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  count = var.module_enabled && length(local.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.vpc[0].id

  tags = merge(
    {
      Name = var.vpc_name

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name" = var.vpc_name
      "mineiros-io/aws/vpc/igw-name" = var.vpc_name
    },
    var.module_tags,
    var.internet_gateway_tags,
  )

  depends_on = [var.module_depends_on]
}

resource "aws_route_table" "public" {
  for_each = var.module_enabled ? local.public_subnets_by_group : {}

  vpc_id = aws_vpc.vpc[0].id

  # propagating_vgws = try(local.subnets[each.key].propagating_vgws, null)

  tags = merge(
    {
      Name = "${var.vpc_name}-public-${each.key}"

      # special mineiros.io tags that can be used in data sources
      "mineiros-io/aws/vpc/vpc-name"         = var.vpc_name
      "mineiros-io/aws/vpc/routetable-name"  = "${var.vpc_name}-public-${each.key}"
      "mineiros-io/aws/vpc/routetable-class" = "public"
    },
    var.module_tags,
    var.route_table_tags,
    var.public_route_table_tags,
  )

  depends_on = [var.module_depends_on]
}

resource "aws_route_table_association" "public" {
  for_each = var.module_enabled ? {
    for subnet in flatten(values(local.public_subnets_by_group)) : subnet.cidr_block => subnet
  } : {}

  subnet_id      = aws_subnet.subnet[each.key].id
  route_table_id = aws_route_table.public[each.value.group].id

  depends_on = [var.module_depends_on]
}

resource "aws_route" "internet_gateway" {
  for_each = aws_route_table.public

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway[0].id

  # Workaround for https://github.com/terraform-providers/terraform-provider-aws/issues/338
  timeouts {
    create = "10m"
  }

  depends_on = [var.module_depends_on]
}

# ---------------------------------------------------------------------------------------------------------------------
# CREATE PUBLIC, PRIVATE, AND INTRA SUBNETS WITHIN THE VPC
# ---------------------------------------------------------------------------------------------------------------------

locals {

  # hacky assertion
  assert_subnet_have_unique_group_class_combination = {
    for subnet in var.subnets :
    "${subnet.group}-${subnet.class}" => "class/group combination must be unique in all subnets. See the module's README.md for details."
  }

  subnet_tags = {
    public  = var.public_subnet_tags
    private = var.private_subnet_tags
    intra   = var.intra_subnet_tags
  }

  # The following creates a list of subnets by constructing multi-level lists and flattening them in the end.
  subnets_tmp = flatten(
    [
      for subnet in var.subnets : [
        for az, netnums in subnet.netnums_by_az : [
          for idx, netnum in netnums : {
            cidr_block        = cidrsubnet(try(subnet.cidr_block, var.cidr_block), try(subnet.newbits, 8), netnum)
            availability_zone = "${local.region}${az}"

            map_public_ip_on_launch = try(subnet.map_public_ip_on_launch, subnet.class == "public", false)

            group_az = "${try(subnet.group, "default")}-${local.region}${az}"

            group = try(subnet.group, "default")
            class = try(subnet.class, "private")

            db_subnet_group_name          = try(subnet.db_subnet_group_name, null)
            elasticache_subnet_group_name = try(subnet.elasticache_subnet_group_name, null)

            # routes = try(subnet.routes, [])

            tags = merge(
              {
                Name = "${var.vpc_name}-${subnet.group}-${subnet.class}-${az}-${idx}"

                # special mineiros.io tags that can be used in data sources
                "mineiros-io/aws/vpc/vpc-name"     = var.vpc_name
                "mineiros-io/aws/vpc/subnet-name"  = "${var.vpc_name}-${try(subnet.group, "default")}-${try(subnet.class, "private")}-${az}-${idx}"
                "mineiros-io/aws/vpc/subnet-group" = try(subnet.group, "default")
                "mineiros-io/aws/vpc/subnet-class" = try(subnet.class, "private")
              },
              local.subnet_tags[try(subnet.class, "private")],
              try(subnet.tags, {}),
            )
          }
        ]
      ]
    ]
  )

  subnets = {
    for subnet in local.subnets_tmp : subnet.cidr_block => subnet
  }
}

resource "aws_subnet" "subnet" {
  for_each = var.module_enabled ? local.subnets : {}

  vpc_id = aws_vpc.vpc[0].id

  # We convert the cidr_block to its cannonical form. This is actually not needed as we
  # already calculate the cidr_block, but to be future proof we do it again anyway.
  cidr_block = cidrsubnet(each.value.cidr_block, 0, 0)

  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.map_public_ip_on_launch

  ipv6_cidr_block                 = try(cidrsubnet(each.value.ipv6_cidr_block, 0, 0), null)
  assign_ipv6_address_on_creation = try(each.value.assign_ipv6_address_on_creation, null)

  tags = merge(
    var.module_tags,
    var.subnet_tags,
    each.value.tags,
  )

  depends_on = [var.module_depends_on]
}

# ----------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set when using this module.
# ----------------------------------------------------------------------------------------------------------------------

# ----------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These variables have defaults, but may be overridden.
# ----------------------------------------------------------------------------------------------------------------------

variable "vpc_name" {
  description = "(Optional) The name of the VPC. Default is \"main\"."
  type        = string
  default     = "main"
}

variable "cidr_block" {
  description = "(Optional) The CIDR block for the VPC. The permissible size of the block ranges between a /16 netmask and a /28 netmask. We advice you to use a CIDR block reserved for private address space as recommended in RFC 1918 http://www.faqs.org/rfcs/rfc1918.html. Default is \"10.0.0.0/16\""
  type        = string
  default     = "10.0.0.0/16"
}

variable "assign_generated_ipv6_cidr_block" {
  description = "(Optional) Requests an AWS-provided IPv6 CIDR block with a /56 prefix length for the VPC. You cannot specify the range of IP addresses, or the size of the CIDR block. Default is false."
  type        = bool
  default     = false
}

variable "enable_classiclink" {
  description = "(Optional) Whether or not to enable ClassicLink for the VPC. Only valid in regions and accounts that support EC2 Classic. Read more: https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/vpc-classiclink.html. Default is false."
  type        = bool
  default     = false
}

variable "enable_classiclink_dns_support" {
  description = "(Optional) Whether or not to enable ClassicLink DNS Support for the VPC. Only valid in regions and accounts that support EC2 Classic. Default is false."
  type        = bool
  default     = false
}

variable "enable_dns_support" {
  description = "(Optional) Whether or not to enable DNS support in the VPC. Default is true."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "(Optional) Whether or not to enable DNS hostnames in the VPC. Default is false."
  type        = bool
  default     = false
}

variable "instance_tenancy" {
  description = "(Optional) A tenancy option for instances launched into the VPC. Default is \"default\"."
  type        = string
  default     = "default"
}

variable "vpc_tags" {
  description = "(Optional) A map of tags to apply to the created VPC. Default is {}."
  type        = map(string)
  default     = {}
}

variable "subnets" {
  description = "(Optional) List of subnet definitions. See README.md for details. Default is []."
  type        = any
  default     = []
}

variable "subnet_tags" {
  description = "(Optional) A map of tags to apply to the created Subnet. Default is {}."
  type        = map(string)
  default     = {}
}

variable "public_subnet_tags" {
  description = "(Optional) A map of tags to apply to the created Public Subnets. Default is {}."
  type        = map(string)
  default     = {}
}

variable "private_subnet_tags" {
  description = "(Optional) A map of tags to apply to the created Private Subnets. Default is {}."
  type        = map(string)
  default     = {}
}

variable "intra_subnet_tags" {
  description = "(Optional) A map of tags to apply to the created Intra Subnets. Default is {}."
  type        = map(string)
  default     = {}
}

variable "route_table_tags" {
  description = "(Optional) A map of tags to apply to the created Public Route Table. Default is {}."
  type        = map(string)
  default     = {}
}

variable "public_route_table_tags" {
  description = "(Optional) A map of tags to apply to the created Public Route Table. Default is {}."
  type        = map(string)
  default     = {}
}

variable "private_route_table_tags" {
  description = "(Optional) A map of tags to apply to the created Private Route Table. Default is {}."
  type        = map(string)
  default     = {}
}

variable "intra_route_table_tags" {
  description = "(Optional) A map of tags to apply to the created Intra Route Table. Default is {}."
  type        = map(string)
  default     = {}
}

variable "nat_gateway_mode" {
  description = "(Optional) Set the mode for the NAT Gateways. Possible inputs are \"none\" (create no NAT Gateways at all), \"single\" (create a single NAT Gateway inside the first defined Public Subnet) and \"one_per_az\" (create one NAT Gateway inside the first Public Subnet in each Availability Zone). Default is \"single\"."
  type        = string
  default     = "single"
}

variable "nat_gateway_single_mode_zone" {
  description = "(Optional) Define the zone (short name) of the NAT gateway when nat_gateway_mode is \"single\" (e.g. \"a\", \"b\", or \"c\"). The AWS region will be added as a prefix. Defaults to a random zone."
  type        = string
  default     = null
}

variable "nat_gateway_eip_allocation_ids" {
  description = "(Optional) A map of EIP allocation ids to use for nat gateways keyed by short zone name (e.g. \"a\", \"b\", or \"c\")."
  type        = map(string)
  default     = {}
}

variable "nat_gateway_tags" {
  description = "(Optional) A map of tags to apply to the created NAT Gateways. Default is {}."
  type        = map(string)
  default     = {}
}

variable "eip_tags" {
  description = "(Optional) A map of tags to apply to the created NAT Gateway Elastic IP Addresses. Default is {}."
  type        = map(string)
  default     = {}
}

variable "internet_gateway_tags" {
  description = "(Optional) A map of tags to apply to the created Internet Gateway. Default is {}."
  type        = map(string)
  default     = {}
}


# ----------------------------------------------------------------------------------------------------------------------
# MODULE CONFIGURATION PARAMETERS
# These variables are used to configure the module.
# See https://medium.com/mineiros/the-ultimate-guide-on-how-to-write-terraform-modules-part-1-81f86d31f024
# ----------------------------------------------------------------------------------------------------------------------

variable "module_enabled" {
  type        = bool
  description = "(Optional) Whether to create resources within the module or not. Default is true."
  default     = true
}

variable "module_depends_on" {
  type        = any
  description = "(Optional) A list of external resources the module depends_on. Default is []."
  default     = []
}

variable "module_tags" {
  description = "(Optional) A map of default tags to apply to all resources created which support tags. Default is {}."
  type        = map(string)
  default     = {}
}

# ----------------------------------------------------------------------------------------------------------------------
# SET TERRAFORM AND PROVIDER REQUIREMENTS FOR RUNNING THIS MODULE
# ----------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 0.12.20, < 2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.45, < 4.0"
    }
  }
}

/**
* # IAM Module
*
* For generic IAM roles and instance profiles
*/

data "aws_iam_policy" "ssm" {
  arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "ssm" {
  name               = "ec2-ssm-association"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ssm.name
  policy_arn = data.aws_iam_policy.ssm.arn
}

resource "aws_iam_instance_profile" "ssm" {
  name = "ec2-s3-ssm-association"
  role = aws_iam_role.ssm.name
}

output "ssm_instance_profile" {
  description = "The name of the instance profile to associate"
  value       = aws_iam_instance_profile.ssm.name
}

output "metrics_key_arn" {
  value = aws_kms_key.metrics_key.arn
}

output "dead_letter_queue_arn" {
  value = aws_sqs_queue.aggregation_lambda_dead_letter.arn
}

output "dead_letter_queue_url" {
  value = aws_sqs_queue.aggregation_lambda_dead_letter.id
}

resource "aws_sqs_queue" "aggregation_lambda_dead_letter" {
  name                              = "aggregation-lambda-dead-letter-queue"
  kms_master_key_id                 = aws_kms_key.metrics_key.arn
  kms_data_key_reuse_period_seconds = 86400
  message_retention_seconds         = 1209600
}




resource "aws_kms_key" "metrics_key" {
  description         = "Metrics key"
  enable_key_rotation = true
}

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0
  name        = var.name
  name_prefix = var.name_prefix
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  message_retention_seconds   = var.message_retention_seconds
  max_message_size            = var.max_message_size
  delay_seconds               = var.delay_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  policy                      = var.policy
  redrive_policy              = var.redrive_policy
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  tags = var.tags
}
data "aws_arn" "this" {
  count = var.create ? 1 : 0
  arn = aws_sqs_queue.this[0].arn
}

output "this_sqs_queue_id" {
  description = "The URL for the created Amazon SQS queue"
  value = element(
    concat(
      aws_sqs_queue.this.*.id,
      [""],
    ),
    0,
  )
}
output "this_sqs_queue_arn" {
  description = "The ARN of the SQS queue"
  value = element(
    concat(
      aws_sqs_queue.this.*.arn,
      [""],
    ),
    0,
  )
}
output "this_sqs_queue_name" {
  description = "The name of the SQS queue"
  value = element(
    concat(
      data.aws_arn.this.*.resource,
      [""],
    ),
    0,
  )
}

variable "create" {
  description = "Whether to create SQS queue"
  type        = bool
  default     = true
}
variable "name" {
  description = "This is the human-readable name of the queue. If omitted, Terraform will assign a random name."
  type        = string
  default     = null
}
variable "name_prefix" {
  description = "A unique name beginning with the specified prefix."
  type        = string
  default     = null
}
variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue. An integer from 0 to 43200 (12 hours)"
  type        = number
  default     = 30
}
variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message. Integer representing seconds, from 60 (1 minute) to 1209600 (14 days)"
  type        = number
  default     = 345600
}
variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it. An integer from 1024 bytes (1 KiB) up to 262144 bytes (256 KiB)"
  type        = number
  default     = 262144
}
variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed. An integer from 0 to 900 (15 minutes)"
  type        = number
  default     = 0
}
variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling) before returning. An integer from 0 to 20 (seconds)"
  type        = number
  default     = 0
}
variable "policy" {
  description = "The JSON policy for the SQS queue"
  type        = string
  default     = ""
}
variable "redrive_policy" {
  description = "The JSON policy to set up the Dead Letter Queue, see AWS docs. Note: when specifying maxReceiveCount, you must specify it as an integer (5), and not a string (\"5\")"
  type        = string
  default     = ""
}
variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}
variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}
variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}
variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again. An integer representing seconds, between 60 seconds (1 minute) and 86,400 seconds (24 hours)"
  type        = number
  default     = 300
}
variable "tags" {
  description = "A mapping of tags to assign to all resources"
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 0.12.7"
  required_providers {
    aws = ">= 2.30"
  }
}

locals {
  output_data = {
    default_sender_id_string              = var.default_sender_id_string
    default_sms_type                      = var.default_sms_type
    delivery_status_success_sampling_rate = var.delivery_status_success_sampling_rate
    iam_role_arn_delivery_status          = var.iam_role_arn_delivery_status
    monthly_spend_limit                   = var.monthly_spend_limit
    usage_report_s3_bucket                = var.usage_report_s3_bucket
  }
}

resource "aws_sns_sms_preferences" "sms_preferences" {
  monthly_spend_limit                   = var.monthly_spend_limit
  delivery_status_iam_role_arn          = var.iam_role_arn_delivery_status
  delivery_status_success_sampling_rate = var.delivery_status_success_sampling_rate
  default_sender_id                     = var.default_sender_id_string
  default_sms_type                      = var.default_sms_type
  usage_report_s3_bucket                = var.usage_report_s3_bucket
}

output "data" {
  value = local.output_data
}

variable "default_sender_id_string" {
  type    = string
  default = null
}

variable "default_sms_type" {
  type    = string
  default = "Transactional"
  validation {
    condition     = contains(["Promotional", "Transactional"], var.default_sms_type)
    error_message = "Invalid SMS type"
  }
}

variable "delivery_status_success_sampling_rate" {
  type    = number
  default = 0
}

variable "iam_role_arn_delivery_status" {
  type    = string
  default = null
}

variable "monthly_spend_limit" {
  type    = number
  default = null
}

variable "usage_report_s3_bucket" {
  type    = string
  default = null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
  required_version = ">= 1.3"
}

resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.main.arn
  version =  var.out_of_date ? "1.14" : null

  vpc_config {
    subnet_ids =  ["${var.main_subnet_id}","${var.secondary_subnet_id}"]
    endpoint_public_access = var.publicly_accessible
    # public_access_cidrs = "${var.globally_accessible ? ["0.0.0.0/0"] : ["127.0.0.0/8"]}"
  }

  enabled_cluster_log_types = var.no_logs ? [] : ["api","audit","authenticator","controllerManager","scheduler"]

  depends_on = [
    aws_iam_role_policy_attachment.example-AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.example-AmazonEKSServicePolicy,
  ]

  count = (var.out_of_date || var.no_logs || var.publicly_accessible || var.globally_accessible) ? 1 : 0

}

resource "aws_iam_role" "main" {
  name = "eks-cluster-sadcloud-example"

  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "eks.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "example-AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.main.name
}

resource "aws_iam_role_policy_attachment" "example-AmazonEKSServicePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = aws_iam_role.main.name
}



variable "name" {
  description = "eks cluster name"
  type        = string
  default     = "sadcloud"
}

variable "out_of_date" {
  description = "EKS Cluster Version is out of date"
  type        = string
  default     = false
}

variable "no_logs" {
  description = "EKS Cluster lacks audit logging"
  type        = string
  default     = false
}

variable "publicly_accessible" {
  description = "EKS Cluster is publically accessible"
  type        = string
  default     = false
}

variable "globally_accessible" {
  description = "EKS Cluster is globally accessible"
  type        = string
  default     = false
}

############## Network ##############

variable "vpc_id" {
  description = "ID of created VPC"
  default = "default_vpc_id"
}

variable "main_subnet_id" {
  description = "ID of main subnet"
  default = "default_main_subnet_id"
}

variable "secondary_subnet_id" {
  description = "ID of secondary subnet"
  default = "default_secondary_subnet_id"
