### default values

locals {
  log_group = var.log_group == null ? {} : var.log_group
}

### frigga name
module "frigga" {
  source  = "Young-ook/spinnaker/aws//modules/frigga"
  version = "2.3.5"
  name    = var.name == null || var.name == "" ? "logs" : var.name
  petname = var.name == null || var.name == "" ? true : false
}

locals {
  namespace      = lookup(local.log_group, "namespace", null)
  name           = module.frigga.name
  log_group_name = local.namespace == null ? local.name : join("/", [local.namespace, local.name])
  default-tags = merge(
    { "terraform.io" = "managed" },
    { "Name" = local.name },
  )
}

### aws cloudwatch logs

### security/policy
resource "aws_iam_policy" "write" {
  name        = format("%s-logs-write", local.name)
  description = format("Allow to push and write logs to the cloudwatch logs")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "logs:CreateLogStream",
        "logs:DescribeLogStreams",
        "logs:PutLogEvents",
      ]
      Effect   = "Allow"
      Resource = [aws_cloudwatch_log_group.logs.arn]
    }]
    Version = "2012-10-17"
  })
}

### observability/log
resource "aws_cloudwatch_log_group" "logs" {
  name              = local.log_group_name
  tags              = merge(local.default-tags, var.tags)
  retention_in_days = lookup(local.log_group, "retension_days", 7)
}

resource "aws_cloudwatch_log_metric_filter" "filters" {
  for_each       = var.log_metric_filters != null ? { for k, v in var.log_metric_filters : k => v } : {}
  name           = lookup(each.value, "name", each.key)
  pattern        = lookup(each.value, "pattern", null)
  log_group_name = aws_cloudwatch_log_group.logs.name

  metric_transformation {
    name          = lookup(each.value, "name", null)
    namespace     = lookup(each.value, "namespace", null)
    value         = lookup(each.value, "value", 1)
    default_value = lookup(each.value, "default_value", null)
  }
}

### output variables

output "log_group" {
  description = "The attributes of generated log group"
  value       = aws_cloudwatch_log_group.logs
}

output "policy_arns" {
  description = "A map of IAM polices to allow access this log group. If you want to make an IAM role or instance-profile has permissions to manage this repository, please attach the `poliy_arn` of this output on your side."
  value       = zipmap(["write"], [aws_iam_policy.write.arn])
}

output "log_metric_filters" {
  description = "The log metric transform filters"
  value       = aws_cloudwatch_log_metric_filter.filters
}

### log
variable "log_group" {
  description = "Log group configuration"
  type        = map(any)
  default     = {}
}

variable "log_metric_filters" {
  description = "Log metric tranform filters"
  type        = list(any)
  default     = []
}

### description
variable "name" {
  description = "Log group name"
  type        = string
  default     = null
}

### tags
variable "tags" {
  description = "The key-value maps for tagging"
  type        = map(string)
  default     = {}
}

## requirements

terraform {
  required_version = ">= 0.13"
}

#--------------------------------------------------------------
# For SSM Automation
#--------------------------------------------------------------
# Enable CloudWatch logging for SSM Automation to comply with SSM.6 control
# https://docs.aws.amazon.com/systems-manager/latest/userguide/automation-action-logging.html

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  region = coalesce(var.region, data.aws_region.current.region)
}

# Create CloudWatch Log Group for SSM Automation
resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.is_enabled ? 1 : 0

  region            = local.region
  name              = var.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_group_retention_in_days
  kms_key_id        = var.cloudwatch_log_group_kms_key_id

  tags = var.tags
}

# Set the log destination to CloudWatch
# SSM.6 control
resource "aws_ssm_service_setting" "automation_log_destination" {
  count = var.is_enabled ? 1 : 0

  region        = local.region
  setting_id    = "/ssm/automation/customer-script-log-destination"
  setting_value = "CloudWatch"

  depends_on = [aws_cloudwatch_log_group.ssm_automation]
}

# Set the log group name for SSM Automation
resource "aws_ssm_service_setting" "automation_log_group_name" {
  count = var.is_enabled ? 1 : 0

  region        = local.region
  setting_id    = "/ssm/automation/customer-script-log-group-name"
  setting_value = var.cloudwatch_log_group_name

  depends_on = [aws_cloudwatch_log_group.ssm_automation]
}

# Disable public sharing of SSM Automation documents
# SSM.7 control
# https://docs.aws.amazon.com/systems-manager/latest/userguide/ssm-automation-sharing.html
resource "aws_ssm_service_setting" "automation_public_sharing_permission" {
  count = var.is_enabled ? 1 : 0

  region        = local.region
  setting_id    = "/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

output "log_group_name" {
  description = "Name of the CloudWatch Log Group for SSM Automation."
  value       = var.is_enabled ? aws_cloudwatch_log_group.ssm_automation[0].name : null
}

output "log_group_arn" {
  description = "ARN of the CloudWatch Log Group for SSM Automation."
  value       = var.is_enabled ? aws_cloudwatch_log_group.ssm_automation[0].arn : null
}

#--------------------------------------------------------------
# module variables
#--------------------------------------------------------------
variable "region" {
  type        = string
  description = "(Optional) AWS region for SSM Service Settings. Uses current region if not specified."
  default     = null
}

variable "is_enabled" {
  type        = bool
  description = "(Optional) A boolean flag to enable/disable settings of SSM Automation. Defaults true."
  default     = true
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "(Optional) Name of the CloudWatch Log Group for SSM Automation. Defaults to '/aws/ssm/automation/executeScript'."
  default     = "/aws/ssm/automation/executeScript"
}

variable "cloudwatch_log_group_retention_in_days" {
  type        = number
  description = "(Optional) Specifies the number of days you want to retain log events in the specified log group. Defaults to 14."
  default     = 14
}

variable "cloudwatch_log_group_kms_key_id" {
  type        = string
  description = "(Optional) The ARN of the KMS Key to use when encrypting log data. Defaults to null."
  default     = null
}

variable "tags" {
  type        = map(any)
  description = "(Optional) Key-value map of resource tags."
  default     = null
}

#--------------------------------------------------------------
# Terraform Provider
#--------------------------------------------------------------
terraform {
  required_version = ">= 1.5.7"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

# common data sources and resources
data "aws_iam_policy_document" "lambda_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      identifiers = ["lambda.amazonaws.com"]
      type        = "Service"
    }
  }
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["arn:aws:logs:*:*:*"]
    effect    = "Allow"
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name   = "lambda_logging"
  policy = data.aws_iam_policy_document.lambda_logging.json
}

# create ddb backup role
resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_trust.json
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  path        = "/"
  description = "IAM policy for creating ddb backups from a lambda"

  policy = jsonencode({
    Version : "2012-10-17",
    Statement : [
      {
        Action : [
          "dynamodb:CreateBackup",
        ],
        Resource : "arn:aws:dynamodb:*:*:*",
        Effect : "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_lambda_logging_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_create_ddb_backup_policy_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

# remove ddb backup role
resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_trust.json
}

resource "aws_iam_policy" "remove_ddb_backup" {
  name        = "remove_ddb_backup_policy"
  path        = "/"
  description = "IAM policy for removing ddb backups from a lambda"

  policy = jsonencode({
    Version : "2012-10-17",
    Statement : [
      {
        Action : [
          "dynamodb:ListBackups",
          "dynamodb:DeleteBackup",
        ],
        Resource : "arn:aws:dynamodb:*:*:*",
        Effect : "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_lambda_logging_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_remove_ddb_backup_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup.arn
}

output "create_ddb_backup_role" {
  value = aws_iam_role.create_ddb_backup_role
}

output "remove_ddb_backup_role" {
  value = aws_iam_role.remove_ddb_backup_role
}

/* IAM GROUPS */
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/"
