}

resource "aws_iam_group_policy_attachment" "developer_iam_policy" {
  group      = "${aws_iam_group.developer.name}"
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

/* Use the below as a sample code to setup quick users 
* This will create a user with the name "username"
* Create a login profile (allowing an initial passport to be set )
* Use Keybase Username for encryption of the secret key and the password
* Set a version1 Access key and Secret key, setting way for easy key rotations
* Replace "username" with the user you want to create
* Ensure that the keybase_username variable contains the keybase user you want to encrypt with
******** 

resource "aws_iam_user" "username" {
  name          = "username"
  path          = "/"
  force_destroy = true
}

resource "aws_iam_user_login_profile" "username" {
  user    = "${aws_iam_user.username.name}"
  pgp_key = "keybase:${var.keybase_username}"
}

resource "aws_iam_access_key" "username_key_v1" {
  user    = "${aws_iam_user.username.name}"
  pgp_key = "keybase:${var.keybase_username}"
}

*/

/* Uncomment the following outputs to get the outputs of the user you created in iam_users file
* The three outputs are standard and can be used in conjunction with the code in iam_users.tf file
* They provide with the users password and secret key (encrypted with the keybase user's pgp key)
* And a non encrypted Access key. 
* Replace 'username' with the name of the user to be created

output "username_password" {
  value = "${aws_iam_user_login_profile.username.encrypted_password}"
}

output "username_access_key_v1" {
  value = ["${aws_iam_access_key.username_key_v1.id}"]
}

output "username_encrypted_secret_key_v1" {
  value = ["${aws_iam_access_key.username_key_v1.encrypted_secret}"]
}

*/

variable keybase_username {
    description = "Username / identity on Keybase.io to be used for encryption"
    default = ""
}

/**
 * # terraform-aws-github-oidc
 *
 * Configuring OpenID for GitHub Connect in Amazon Web Services
 *
 * ## Reference
 *
 * - [Configuring OpenID Connect in Amazon Web Services \- GitHub Docs](https://docs.github.com/ja/actions/deployment/security-hardening-your-deployments/configuring-openid-connect-in-amazon-web-services)
 * - [configure\-aws\-credentials](https://github.com/aws-actions/configure-aws-credentials)
 *
 */

data "tls_certificate" "this" {
  url = "https://${var.github_oidc_domain}"
}

locals {
  github_thumbprints = sort(distinct(concat(
    [for x in data.tls_certificate.this.certificates : x.sha1_fingerprint if x.is_ca],
    var.github_oidc_thumbprints
  )))
}

data "aws_iam_openid_connect_provider" "this" {
  for_each = var.create_oidc_provider ? {} : { oidc_provider = false }

  url = data.tls_certificate.this.url
}

resource "aws_iam_openid_connect_provider" "this" {
  for_each = var.create_oidc_provider ? { oidc_provider = true } : {}

  url             = data.tls_certificate.this.url
  client_id_list  = [var.github_oidc_audience]
  thumbprint_list = local.github_thumbprints
  tags = merge(var.tags, {
    Name = "github.com"
  })
}

locals {
  aws_iam_openid_connect_provider = var.create_oidc_provider ? aws_iam_openid_connect_provider.this["oidc_provider"] : data.aws_iam_openid_connect_provider.this["oidc_provider"]
}

data "aws_iam_policy_document" "this_assume_role_policy" {
  for_each = var.iam_roles

  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = [local.aws_iam_openid_connect_provider.arn]
    }
    actions = [
      "sts:AssumeRoleWithWebIdentity",
    ]
    condition {
      test     = "StringEquals"
      variable = "${var.github_oidc_domain}:aud"
      values   = [var.github_oidc_audience]
    }
    condition {
      test     = "StringLike"
      variable = "${var.github_oidc_domain}:sub"
      values   = each.value.oidc_claims
    }
  }
}

resource "aws_iam_role" "this" {
  for_each            = var.iam_roles
  name                = each.key
  assume_role_policy  = data.aws_iam_policy_document.this_assume_role_policy[each.key].json
  managed_policy_arns = each.value.policy_arns
  tags = merge(var.tags, {
    Name = each.key
  })
}

output "oidc_provider" {
  value = var.create_oidc_provider ? aws_iam_openid_connect_provider.this["oidc_provider"] : data.aws_iam_openid_connect_provider.this["oidc_provider"]
}

output "oidc_iam_roles" {
  value = aws_iam_role.this
}

variable "create_oidc_provider" {
  description = "Create a new identity provider."
  type        = bool
  default     = true
}

variable "github_oidc_domain" {
  description = "The domain of the identity provider. Corresponds to the iss claim."
  type        = string
  default     = "token.actions.githubusercontent.com"
}

variable "github_oidc_audience" {
  description = "Also known as client ID, audience is a value that identifies the application that is registered with an OpenID Connect provider."
  type        = string
  default     = "sts.amazonaws.com"
}

variable "github_oidc_thumbprints" {
  description = "A list of known thumbprints for the OpenID Connect (OIDC). ref.[GitHub Actions – Update on OIDC integration with AWS](https://github.blog/changelog/2023-06-27-github-actions-update-on-oidc-integration-with-aws/)"
  type        = list(string)
  default     = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

variable "iam_roles" {
  description = <<-EOT
    {
        "iam_role_name": {
            #e.g. `["repo:{GitHubOrg}/{RepositoryName}:\*", "repo:octo-org/octo-repo:ref:refs/heads/octo-branch"]`
            oidc_claims = ["A list of server certificate thumbprints for the OpenID Connect (OIDC) identity provider's server certificate(s)."]
            #e.g. `["arn:aws:iam::aws:policy/ReadOnlyAccess"]`
            policy_arns = ["Set of IAM policy ARNs to attach to the IAM role."]
        }
    }
  EOT
  type = map(object({
    oidc_claims = list(string)
    policy_arns = list(string)
  }))
  default = {}
}

variable "tags" {
  description = "A mapping of tags to assign to resources."
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.2"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.27"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Configure the AWS Provider
provider "aws" {
  region = "us-east-1"
}

# vpc
resource "aws_vpc" "myvpc" {
  cidr_block       = "10.0.0.0/16" #65536
  instance_tenancy = "default"

  tags = {
    Name = "projectvpc"
  }
}

#pub subnet
resource "aws_subnet" "pubsub" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = "10.0.1.0/24" #256
  availability_zone = "us-east-1a"
  tags = {
    Name = "pub-sub"
  }
}
#pvt subnet
resource "aws_subnet" "pvtsub" {
  vpc_id     = aws_vpc.myvpc.id
  cidr_block = "10.0.2.0/24" #256
  availability_zone = "us-east-1b"

  tags = {
    Name = "pub-sub"
  }
}

#IGW
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.myvpc.id

  tags = {
    Name = "main"
  }
}

#Pub Route Table
resource "aws_route_table" "pubrt" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT-PUB"
  }
}
#Pvt Route Table
resource "aws_route_table" "pvtrt" {
  vpc_id = aws_vpc.myvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "RT-PUB"
  }
}


#Rt-ass
#pub-rt
resource "aws_route_table_association" "pubasc" {
  subnet_id      = aws_subnet.pubsub.id
  route_table_id = aws_route_table.pubrt.id
}
#pvt-rt
resource "aws_route_table_association" "pvtasc" {
  subnet_id      = aws_subnet.pvtsub.id
  route_table_id = aws_route_table.pvtrt.id
}

#Eip
resource "aws_eip" "eip" {
 vpc = true
}

#Natgateway
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.eip.id
  subnet_id     = aws_subnet.pubsub.id

  tags = {
    Name = "gw NAT"
  }
}

provider "aws" {
  region = "us-east-1"
}
data "aws_availability_zones" "available" {}
data "aws_region" "current" {}
resource "aws_vpc" "vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name        = var.vpc_name
    Environment = "Dev"
    Created_By  = "Terraform"
  }
}

# Creating Prvate Subnet
resource "aws_subnet" "private_subnets" {
  for_each          = var.private_subnet
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.value + 10)
  availability_zone = tolist(data.aws_availability_zones.available.names)[each.value]
  tags = {
    Name       = each.key
    Created_By = "Terraform"
  }
}
resource "aws_subnet" "public_subnets" {
  for_each          = var.public_subnet
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.value + 100)
  availability_zone = tolist(data.aws_availability_zones.available.names)[each.value]
  tags = {
    Name       = each.key
    Created_By = "Terraform"
  }
}

#Xreating Internet Gateway
resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "Dev_igw"
  }
}

#Creating EIP For Nat Gateway
resource "aws_eip" "nat_gateway_eip" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.internet_gateway]
  tags = {
    Name = "Dev_igw_eip"
  }
}
#Creating NAT Gateway
resource "aws_nat_gateway" "nat_gateway" {
  depends_on    = [aws_subnet.public_subnets]
  allocation_id = aws_eip.nat_gateway_eip.id
  subnet_id     = aws_subnet.public_subnets["public_subnet_1"].id
  tags = {
    Name = "Dev_nat_gateway"
  }
}

#Creating Route table
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }
  tags = {
    Name       = "dev_public_rtb"
    Created_By = "Terraform"
  }
}
resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.vpc.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gateway.id
  }
  tags = {
    Name       = "dev_privat_rtb"
    Created_By = "Terraform"
  }
}

resource "aws_route_table_association" "public" {
  depends_on     = [aws_subnet.public_subnets]
  route_table_id = aws_route_table.public_route_table.id
  for_each       = aws_subnet.public_subnets
  subnet_id      = each.value.id
}
resource "aws_route_table_association" "private" {
  depends_on     = [aws_subnet.private_subnets]
  route_table_id = aws_route_table.private_route_table.id
  for_each       = aws_subnet.private_subnets
  subnet_id      = each.value.id
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}
variable "vpc_name" {
  type    = string
  default = "demo-vpc"
}
variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}
variable "private_subnet" {
  default = {
    "private_subnet_1" = 1
    "private_subnet_2" = 2
    "provate_subnet_3" = 3
  }
}
variable "public_subnet" {
  default = {
    "public_subnet_1" = 1
    "public_subnet_2" = 2
    "public_subnet_3" = 3
  }
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_vpc" "vpcs" {
  for_each = var.vpcs
  depends_on = [
    module.vpcs]
  filter {
    name = "tag:Name"
    values = [
      each.key]
  }
}

data "aws_route_table" "public-tables" {
  depends_on = [
    module.vpcs]
  for_each = var.vpcs
  filter {
    name = "tag:Name"
    values = [
      "${each.key}-public"]
  }
}

data "aws_route_table" "private-tables" {
  depends_on = [
    module.vpcs]
  for_each = local.peers_private
  filter {
    name = "tag:Name"
    values = [
      each.key]
  }
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

locals {
  // there are usually at most three zones
  zones = [
    0,
    1,
    2]

  zone_names = toset(slice(data.aws_availability_zones.available.names, 0, var.zones))

  peers = tomap({for i, pair in var.peers: i => pair})
  peers_doubled = merge([for i, peer in var.peers: tomap({
    (peer[0]) = [
      i,
      peer[1]],
    (peer[1]) = [
      i,
      peer[0]]
  })]...)

  peers_private = merge([for i, peer in var.peers:
  merge([for pair in setproduct(peer, local.zone_names): tomap({
    "${pair[0]}-private-${pair[1]}" = [
      i,
      setsubtract(peer, [
        pair[0]])]
  })]...)]...)
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

output "dev-vpc-id" {
  value = data.aws_vpc.vpcs["dev"].id
}

output "dev-vpc-cidr" {
  value = data.aws_vpc.vpcs["dev"].cidr_block
}

output "test-vpc-id" {
  value = data.aws_vpc.vpcs["test"].id
}

output "test-vpc-cidr" {
  value = data.aws_vpc.vpcs["test"].cidr_block
}

output "peer-id" {
  value = aws_vpc_peering_connection.peers[0].id
}

output "dev-public-route-table-id" {
  value = data.aws_route_table.public-tables["dev"].id
}

output "test-public-route-table-id" {
  value = data.aws_route_table.public-tables["test"].id
}

