provider "aws" {
  default_tags {
    tags = {
      Description = "Managed by Terraform"
    }
  }
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

resource "aws_route" "peer-public-routes" {
  for_each = local.peers_doubled
  route_table_id = data.aws_route_table.public-tables[each.key].id
  destination_cidr_block = data.aws_vpc.vpcs[each.value[1]].cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.peers[each.value[0]].id
}

resource "aws_route" "peer-private-routes" {
  for_each = local.peers_private
  route_table_id = data.aws_route_table.private-tables[each.key].id
  destination_cidr_block = data.aws_vpc.vpcs[one(each.value[1])].cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.peers[each.value[0]].id
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

resource "aws_vpc_peering_connection" "peers" {
  for_each = local.peers
  vpc_id = data.aws_vpc.vpcs[each.value[0]].id
  peer_vpc_id = data.aws_vpc.vpcs[each.value[1]].id
  auto_accept = true

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  tags = {
    Name = "${each.value[0]}-${each.value[1]}-vpc-peer"
  }
}

// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: MIT-0

module "vpcs" {
  for_each = var.vpcs
  source = "terraform-aws-modules/vpc/aws"

  name = each.key
  cidr = each.value.cidr

  create_database_subnet_group = false
  enable_dns_hostnames = true
  enable_dns_support = true
  enable_nat_gateway = each.value.nat_gateway

  azs = [
  for i in slice(local.zones, 0, var.zones):
  data.aws_availability_zones.available.names[i]
  ]

  public_subnets = [
  for i in slice(local.zones, 0, var.zones):
  cidrsubnet(each.value.cidr, each.value.bit_mask, i + each.value.public_index)
  ]

  private_subnets = [
  for i in slice(local.zones, 0, var.zones):
  cidrsubnet(each.value.cidr, each.value.bit_mask, i + each.value.private_index)
  ]
}

