        "sqs:GetQueueAttributes",
        "sqs:ListQueues",
        "storagegateway:List*",
        "storagegateway:Describe*",
        "workspaces:Describe*"
      ],
      "Resource": "*"
    }
  POLICY
}

variable "default-reservation-policy" {
  default = <<POLICY
    {
      "Effect": "Allow",
      "Action": [
        "ec2:ModifyReservedInstances"
      ],
      "Resource": "*"
    }
  POLICY
}

variable "default-actions-policy" {
  default = <<POLICY
    {
      "Effect": "Allow",
      "Action": [
        "ec2:DeleteSnapshot",
        "ec2:DeleteVolume",
        "ec2:TerminateInstances",
        "ec2:StartInstances",
        "ec2:StopInstances",
        "ec2:RebootInstances",
        "lambda:InvokeFunction",
        "ec2:ReleaseAddress"
      ],
      "Resource": "*"
    }
  POLICY
}

output "cloudhealth-role-arn" {
  value = aws_iam_role.cht_iam_role.arn
}

output "external-id" {
  value = var.external-id
}

output "cloudhealth-policy-arn" {
  value = aws_iam_policy.cht_iam_policy.arn
}

#Setting up internal variables

locals {
  default-s3-billing-bucket-policy = <<POLICY
{
          "Effect": "Allow",
          "Action": [
            "s3:Get*",
            "s3:List*"
          ],
          "Resource": [ "arn:aws:s3:::${var.s3-billing-bucket}", "arn:aws:s3:::${var.s3-billing-bucket}/*" ]
        }
  POLICY

  default-s3-cloudtrail-bucket-policy = <<POLICY
{
          "Effect": "Allow",
          "Action": [
            "s3:Get*",
            "s3:List*"
          ],
          "Resource": [ "arn:aws:s3:::${var.s3-cloudtrail-bucket}", "arn:aws:s3:::${var.s3-cloudtrail-bucket}/*" ]
        }
  POLICY

  default-s3-cur-bucket-policy = <<POLICY
{
          "Effect": "Allow",
          "Action": [
            "s3:Get*",
            "s3:List*"
          ],
          "Resource": [ "arn:aws:s3:::${var.s3-cur-bucket}", "arn:aws:s3:::${var.s3-cur-bucket}/*" ]
        }
  POLICY

  default-s3-config-bucket-policy = <<POLICY
{
          "Effect": "Allow",
          "Action": [
            "s3:Get*",
            "s3:List*"
          ],
          "Resource": [ "arn:aws:s3:::${var.s3-config-bucket}", "arn:aws:s3:::${var.s3-config-bucket}/*" ]
        }
  POLICY

  default-s3-ecs-bucket-policy = <<POLICY
{
          "Effect": "Allow",
          "Action": [
            "s3:Get*",
            "s3:List*"
          ],
          "Resource": [ "arn:aws:s3:::${var.s3-ecs-bucket}", "arn:aws:s3:::${var.s3-ecs-bucket}/*" ]
        }
  POLICY
}

resource "aws_iam_role" "cht_iam_role" {
  name = var.role-name
  path = "/"

  assume_role_policy = <<POLICY
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Condition": {
                "StringEquals": {
                    "sts:ExternalId": "${var.external-id}"
                }
            },
            "Principal": {
                "AWS": "arn:aws:iam::454464851268:root"
            },
            "Action": [
                "sts:AssumeRole"
            ]
        }
    ]
}
POLICY
}

resource "aws_iam_policy" "cht_iam_policy" {
  name = var.role-name

  policy = <<POLICY
{
  "Id": "cloudhealth-iam-policy",
  "Version": "2012-10-17",
  "Statement": [
    ${var.default-readonly-policy}
    ${var.s3-billing-bucket == "" ? "" : format(",%s", local.default-s3-billing-bucket-policy)}
    ${var.s3-cloudtrail-bucket == "" ? "" : format(",%s", local.default-s3-cloudtrail-bucket-policy)}
    ${var.s3-cur-bucket == "" ? "" : format(",%s", local.default-s3-cur-bucket-policy)}
    ${var.s3-config-bucket == "" ? "" : format(",%s", local.default-s3-config-bucket-policy)}
    ${var.s3-ecs-bucket == "" ? "" : format(",%s", local.default-s3-ecs-bucket-policy)}
    ${var.automated-ri-modification-enabled ? format(",%s", var.default-reservation-policy) : ""}
    ${var.automated-actions-enabled ? format(",%s", var.default-actions-policy) : ""}
    ${var.additional-policy == "" ? "" : format(",%s", var.additional-policy)}
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "cht_aws_iam_role_policy_attachment" {
  role       = aws_iam_role.cht_iam_role.name
  policy_arn = aws_iam_policy.cht_iam_policy.arn
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  # Just extra safety incase someone passes in a url with `https://`
  provider_url = replace(var.provider_url, "https://", "")

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

################################################################################
# GitHub OIDC Role
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create ? 1 : 0

  statement {
    sid    = "GithubOidcAuth"
    effect = "Allow"
    actions = [
      "sts:TagSession",
      "sts:AssumeRoleWithWebIdentity"
    ]

    principals {
      type        = "Federated"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:oidc-provider/${local.provider_url}"]
    }

    condition {
      test     = "ForAllValues:StringEquals"
      variable = "${local.provider_url}:iss"
      values   = ["https://${local.provider_url}"]
    }

    condition {
      test     = "ForAllValues:StringEquals"
      variable = "${local.provider_url}:aud"
      values   = [var.audience]
    }

    condition {
      test     = "StringLike"
      variable = "${local.provider_url}:sub"
      # Strip `repo:` to normalize for cases where users may prepend it
      values = [for subject in var.subjects : "repo:${trimprefix(subject, "repo:")}"]
    }
  }
}

resource "aws_iam_role" "this" {
  count = var.create ? 1 : 0

  name        = var.name
  name_prefix = var.name_prefix
  path        = var.path
  description = var.description

  assume_role_policy    = data.aws_iam_policy_document.this[0].json
  max_session_duration  = var.max_session_duration
  permissions_boundary  = var.permissions_boundary_arn
  force_detach_policies = var.force_detach_policies

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = { for k, v in var.policies : k => v if var.create }

  role       = aws_iam_role.this[0].name
  policy_arn = each.value
}

################################################################################
# GitHub OIDC Role
################################################################################

output "arn" {
  description = "ARN of IAM role"
  value       = try(aws_iam_role.this[0].arn, null)
}

output "name" {
  description = "Name of IAM role"
  value       = try(aws_iam_role.this[0].name, null)
}

output "path" {
  description = "Path of IAM role"
  value       = try(aws_iam_role.this[0].path, null)
}

output "unique_id" {
  description = "Unique ID of IAM role"
  value       = try(aws_iam_role.this[0].unique_id, null)
}

variable "create" {
  description = "Controls if resources should be created (affects all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to the resources created"
  type        = map(any)
  default     = {}
}

################################################################################
# GitHub OIDC Role
################################################################################

variable "name" {
  description = "Name of IAM role"
  type        = string
  default     = null
}

variable "path" {
  description = "Path of IAM role"
  type        = string
  default     = "/"
}

variable "permissions_boundary_arn" {
  description = "Permissions boundary ARN to use for IAM role"
  type        = string
  default     = null
}

variable "description" {
  description = "IAM Role description"
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "IAM role name prefix"
  type        = string
  default     = null
}

variable "policies" {
  description = "Policies to attach to the IAM role in `{'static_name' = 'policy_arn'}` format"
  type        = map(string)
  default     = {}
}

variable "force_detach_policies" {
  description = "Whether policies should be detached from this role when destroying"
  type        = bool
  default     = true
}

variable "max_session_duration" {
  description = "Maximum CLI/API session duration in seconds between 3600 and 43200"
  type        = number
  default     = null
}

variable "audience" {
  description = "Audience to use for OIDC role. Defaults to `sts.amazonaws.com` for use with the [official AWS GitHub action](https://github.com/aws-actions/configure-aws-credentials)"
  type        = string
  default     = "sts.amazonaws.com"
}

variable "subjects" {
  description = "List of GitHub OIDC subjects that are permitted by the trust policy. You do not need to prefix with `repo:` as this is provided. Example: `['my-org/my-repo:*', 'octo-org/octo-repo:ref:refs/heads/octo-branch']`"
  type        = list(string)
  default     = []
}

variable "provider_url" {
  description = "The URL of the identity provider. Corresponds to the iss claim"
  type        = string
  default     = "token.actions.githubusercontent.com"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  partition = data.aws_partition.current.partition
}

data "aws_iam_policy_document" "this" {

  statement {
    sid    = "AllowBasicVisibilityWithoutMfa"
    effect = "Allow"
    actions = [
      "iam:ListUsers",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
      "iam:ListVirtualMFADevices",
      "iam:GetAccountPasswordPolicy"
    ]
    resources = ["*", ]
  }

  statement {
    sid    = "MFAPersonalCreate"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:mfa/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowIndividualUserToDeactivateOnlyTheirOwnMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:mfa/&{aws:username}",
      "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true", ]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:GetUser",
      "iam:ListGroupsForUser",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:ListGroups",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:group/",
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:ListGroupPolicies",
      "iam:ListAttachedGroupPolicies",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:group/*",
    ]
  }

  statement {
    sid    = "AllowToListOnlyOwnMFA"
    effect = "Allow"
    actions = [
      "iam:ListMFADevices",
    ]
    resources = [
      "arn:${local.partition}:iam::*:mfa/*",
      "arn:${local.partition}:iam::*:user/&{aws:username}"
    ]

  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:ListAccessKeys",
      "iam:UpdateUser",
      "iam:ListAttachedUserPolicies",
      "iam:ListSSHPublicKeys",
      "iam:ListAccessKeys",
      "iam:GetLoginProfile",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowUserToManageOwnMFA"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]

    resources = [
      "arn:${local.partition}:iam::*:mfa/&{aws:username}",
      "arn:${local.partition}:iam::*:user/&{aws:username}"
    ]
  }

  statement {
    sid    = "KeysAndCertificates"
    effect = "Allow"
    actions = [
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:GetSSHPublicKey",
    ]
    resources = [
      "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowUserToDeactivateOnlyOwnMFAWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::*:mfa/&{aws:username}",
      "arn:${local.partition}:iam::*:user/&{aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowBasicVisibilityWhenLoggedInWithMFA"
    effect = "Allow"
    actions = [
      "iam:ListUserTags",
      "iam:ListGroupsForUser",
      "iam:ListPolicies",
      "iam:GetGroup",
      "iam:GenerateServiceLastAccessedDetails",
      "iam:ListUserPolicies",
      "iam:GetUser",
      "iam:ListServiceSpecificCredentials",
      "iam:ListAttachedUserPolicies",
    ]
    resources = ["*", ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true", ]
    }
  }

  dynamic "statement" {
    for_each = var.manage_own_access_keys ? [1] : []

    content {
      sid    = "AllowManageOwnAccessKeys"
      effect = "Allow"
      actions = [
        "iam:CreateAccessKey",
        "iam:DeleteAccessKey",
        "iam:ListAccessKeys",
        "iam:UpdateAccessKey",
      ]
      resources = [
        "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}"
      ]
      condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"
        values   = [var.manage_own_access_keys, ]
      }
    }
  }

  dynamic "statement" {
    iterator = item
    for_each = var.manage_own_signing_certificates ? [1] : []

    content {
      sid    = "AllowManageOwnSigningCertificates"
      effect = "Allow"
      actions = [
        "iam:DeleteSigningCertificate",
        "iam:ListSigningCertificates",
        "iam:UpdateSigningCertificate",
        "iam:UploadSigningCertificate",
      ]
      resources = [
        "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}"
      ]
      condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"
        values   = [var.manage_own_signing_certificates, ]
      }
    }
  }

  dynamic "statement" {
    for_each = var.manage_own_ssh_public_keys ? [1] : []

    content {
      sid    = "AllowManageOwnSSHPublicKeys"
      effect = "Allow"
      actions = [
        "iam:DeleteSSHPublicKey",
        "iam:UpdateSSHPublicKey",
        "iam:UploadSSHPublicKey"
      ]
      resources = [
        "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}"
      ]
      condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"
        values   = [var.manage_own_ssh_public_keys, ]
      }
    }
  }

  dynamic "statement" {
    for_each = var.manage_own_git_credentials ? [1] : []

    content {
      sid    = "AllowManageOwnGitCredentials"
      effect = "Allow"
      actions = [
        "iam:CreateServiceSpecificCredential",
        "iam:DeleteServiceSpecificCredential",
        "iam:ListServiceSpecificCredentials",
        "iam:ResetServiceSpecificCredential",
        "iam:UpdateServiceSpecificCredential",
      ]
      resources = [
        "arn:${local.partition}:iam::${var.account_id}:user/&{aws:username}"
      ]
      condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"

        values = [
          var.manage_own_git_credentials,
        ]
      }
    }
  }

  # Deny

  dynamic "statement" {
    for_each = var.manage_explicit_deny ? [1] : []

    content {
      sid    = "DenyAllExceptListedIfNoMFA"
      effect = "Deny"
      not_actions = [
        "iam:CreateVirtualMFADevice",
        "iam:EnableMFADevice",
        "iam:GetUser",
        "iam:ListMFADevices",
        "iam:ListVirtualMFADevices",
        "iam:ResyncMFADevice",
        "sts:GetSessionToken"
      ]
      resources = ["*"]
      condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["false", ]
      }
    }
  }
}

resource "aws_iam_policy" "this" {
  name        = var.policy_name
  path        = var.path
  description = "Policy to allow MFA management"
  policy      = data.aws_iam_policy_document.this.json
}

resource "aws_iam_group_policy_attachment" "to_groups" {
  count      = length(var.groups)
  group      = element(var.groups, count.index)
  policy_arn = aws_iam_policy.this.arn
}

output "id" {
  description = "The policy's ID."
  value       = aws_iam_policy.this.id
}

output "arn" {
  description = "The policy's ARN."
  value       = aws_iam_policy.this.arn
}

output "groups" {
  description = "The groups to which policy is attached"
  value       = element(concat(aws_iam_group_policy_attachment.to_groups.*.group, tolist([""])), 0)
}

output "policy_json" {
  description = "The above arguments serialized as a standard JSON policy document."
  value       = data.aws_iam_policy_document.this.json
  sensitive   = true
}

variable "policy_name" {
  default     = "managed-force-mfa-policy"
  description = "The name of the policy."
  type        = string
}

variable "account_id" {
  default     = "*"
  description = "Account identification. (Optional, default '*')"
  type        = string
}

variable "manage_own_access_keys" {
  default     = false
  description = "Allow a new AWS secret access key and corresponding AWS access key ID for the specified user."
  type        = bool
}

variable "manage_own_signing_certificates" {
  default     = false
  description = "Allow managing signing certificates."
  type        = bool
}

variable "manage_own_ssh_public_keys" {
  default     = false
  description = "Allow managing ssh public keys."
  type        = bool
}

variable "manage_own_git_credentials" {
  default     = false
  description = "Allow managing git credentials."
  type        = bool
}

variable "manage_explicit_deny" {
  default     = false
  description = "Manage explicit deny."
  type        = bool
}


variable "groups" {
  default     = []
  description = "Enforce MFA for the members in these groups. (Optional, default '[]')"
  type        = list(string)
}

variable "path" {
  default     = "/"
  description = "Path in which to create the policy. (Optional, default '/')"
  type        = string
}

