  value = {
    "username" = aws_iam_user.billing.name
    "password" = aws_iam_user_login_profile.billing.password
  }
  sensitive = true
}
output "admin_user" {
  value = {
    "username" = aws_iam_user.admin.name
    "password" = aws_iam_user_login_profile.admin.password
  }
  sensitive = true
}
output "maintenance_user" {
  value = {
    "username" = aws_iam_user.suport.name
    "password" = aws_iam_user_login_profile.suport.password
  }
  sensitive = true
}

variable "minimum_password_length" {
  type = number
  description = "Minimum password length"
  default = 8
}

#(empty)

resource "aws_efs_file_system" "main" {
  creation_token         = var.creation_token
  availability_zone_name = var.availability_zone_name
  encrypted              = var.encrypted
  kms_key_id             = var.kms_key_id

  dynamic "lifecycle_policy" {
    for_each = length(var.transition_to_ia) > 0 ? [1] : []
    content {
      transition_to_ia = try(var.transition_to_ia[0], null)
    }
  }
  dynamic "lifecycle_policy" {
    for_each = length(var.transition_to_primary_storage_class) > 0 ? [1] : []
    content {
      transition_to_primary_storage_class = try(var.transition_to_primary_storage_class[0], null)
    }
  }

  performance_mode                = var.performance_mode
  provisioned_throughput_in_mibps = var.provisioned_throughput_in_mibps
  throughput_mode                 = var.throughput_mode

  tags = merge(
    {
      "Name" = var.creation_token
    },
    var.tags,
  )
}

resource "aws_efs_mount_target" "main" {
  count           = length(var.mount_target_subnet_ids) > 0 ? length(var.mount_target_subnet_ids) : 0
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = var.mount_target_subnet_ids[count.index]
  ip_address      = var.mount_target_ip_addresses[count.index]
  security_groups = concat(var.external_security_groups, aws_security_group.main.*.id)
}

resource "aws_efs_file_system_policy" "main" {
  count                              = var.file_system_policy != "" ? 1 : 0
  file_system_id                     = aws_efs_file_system.main.id
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  policy                             = var.file_system_policy
}

resource "aws_efs_backup_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  backup_policy {
    status = var.backup_policy_status
  }
}

# Efs Security Group
resource "aws_security_group" "main" {
  count       = length(var.mount_target_subnet_ids) > 0 && var.create_security_group ? 1 : 0
  name        = "${var.creation_token}-security-group"
  description = "Efs security Group for ${var.creation_token}"
  vpc_id      = var.vpc_id

  dynamic "ingress" {
    for_each = var.security_group_ingress
    content {
      description      = lookup(ingress.value, "description", "Rule to allow port ${try(ingress.value.from_port, null)} inbound traffic")
      from_port        = try(ingress.value.from_port, null)
      to_port          = try(ingress.value.to_port, null)
      protocol         = try(ingress.value.protocol, null)
      cidr_blocks      = try(ingress.value.cidr_blocks, [])
      ipv6_cidr_blocks = try(ingress.value.ipv6_cidr_blocks, [])
    }
  }

  dynamic "egress" {
    for_each = var.egress_rules
    content {
      description      = try(egress.value.description, 0)
      from_port        = try(egress.value.from_port, 0)
      to_port          = try(egress.value.to_port, 0)
      protocol         = try(egress.value.protocol, "-1")
      cidr_blocks      = try(egress.value.cidr_blocks, ["0.0.0.0/0"])
      ipv6_cidr_blocks = try([egress.value.ipv6_cidr_blocks], ["::/0"])
    }
  }

  tags = merge(
    {
      "Name" = var.creation_token
    },
    var.tags,
  )
}

output "efs_file_system_arn" {
  value       = aws_efs_file_system.main.arn
  description = "Amazon Resource Name of the file system."
}

output "file_system_availability_zone_id" {
  value       = aws_efs_file_system.main.availability_zone_id
  description = "The identifier of the Availability Zone in which the file system's One Zone storage classes exist."
}

output "file_system_id" {
  value       = aws_efs_file_system.main.id
  description = "The ID that identifies the file system `(e.g., fs-ccfc0d65)`."
}

output "file_system_dns_name" {
  value       = aws_efs_file_system.main.dns_name
  description = "The DNS name for the filesystem"
}

output "file_system_owner_id" {
  value       = aws_efs_file_system.main.owner_id
  description = "The AWS account that created the file system. If the file system was createdby an IAM user, the parent account to which the user belongs is the owner."
}

output "file_system_size_in_bytes" {
  value       = aws_efs_file_system.main.size_in_bytes
  description = "The latest known metered size (in bytes) of data stored in the file system, the value is not the exact size that the file system was at any point in time."
}

output "tags_all" {
  value       = aws_efs_file_system.main.tags_all
  description = "A map of tags assigned to the resource, including those inherited from the provider default_tags configuration block."
}

output "mount_target_dns_name" {
  value       = aws_efs_mount_target.main.*.mount_target_dns_name
  description = "The DNS name for the given subnet/AZ"
}

output "mount_target_id" {
  value       = aws_efs_mount_target.main.*.id
  description = "The ID of the mount target."
}

output "mount_target_network_interface_id" {
  value       = aws_efs_mount_target.main.*.network_interface_id
  description = "The ID of the network interface that Amazon EFS created when it created the mount target."
}

output "mount_target_availability_zone_name" {
  value       = aws_efs_mount_target.main.*.availability_zone_name
  description = "The name of the Availability Zone (AZ) that the mount target resides in."
}

output "mount_target_availability_zone_id" {
  value       = aws_efs_mount_target.main.*.availability_zone_id
  description = "The unique and consistent identifier of the Availability Zone (AZ) that the mount target resides in."
}

output "security_group_arn" {
  description = "ARN of the security group."
  value       = aws_security_group.main.*.arn
}

output "security_group_id" {
  description = "ID of the security group."
  value       = aws_security_group.main.*.id
}

output "security_group_owner_id" {
  description = "Owner ID. of the security group."
  value       = aws_security_group.main.*.owner_id
}

# efs file system
variable "availability_zone_name" {
  type        = string
  description = "(Optional) the AWS Availability Zone in which to create the file system. Used to create a file system that uses One Zone storage classes. See user guide for more information."
  default     = null
}

variable "creation_token" {
  type        = string
  description = "(Optional) A unique name (a maximum of 64 characters are allowed) used as reference when creating the Elastic File System to ensure idempotent file system creation. By default generated by Terraform. See Elastic File System user guide for more information."
  default     = null
}

variable "encrypted" {
  type        = bool
  description = "(Optional) If true, the disk will be encrypted."
  default     = true
}

variable "kms_key_id" {
  type        = string
  description = "(Optional) The ARN for the KMS encryption key. When specifying kms_key_id, encrypted needs to be set to `true`."
  default     = null
}

variable "transition_to_ia" {
  type        = list(string)
  description = "(Optional) Indicates how long it takes to transition files to the IA storage class. Valid values: `AFTER_7_DAYS`, `AFTER_14_DAYS`, `AFTER_30_DAYS`, `AFTER_60_DAYS`, or `AFTER_90_DAYS`."
  default     = []
}

variable "transition_to_primary_storage_class" {
  type        = list(string)
  description = "(Optional) Describes the policy used to transition a file from infequent access storage to primary storage. Valid values: `AFTER_1_ACCESS`."
  default     = []
  #default     = "AFTER_1_ACCESS"
}

variable "performance_mode" {
  type        = string
  description = "(Optional) The file system performance mode. Can be either `generalPurpose` or `maxIO` (Default: `generalPurpose`)"
  default     = "generalPurpose"
}

variable "provisioned_throughput_in_mibps" {
  type        = string
  description = "(Optional) The throughput, measured in MiB/s, that you want to provision for the file system. Only applicable with throughput_mode set to `provisioned`."
  default     = null
}

variable "throughput_mode" {
  type        = string
  description = "(Optional) Throughput mode for the file system. Defaults to `bursting`. Valid values: `bursting`, `provisioned`. When using `provisioned`, also set `provisioned_throughput_in_mibps`."
  default     = "bursting"
}

variable "mount_target_subnet_ids" {
  type        = list(string)
  description = "(Required) The IDs of subnets to add the mount target in."
  default     = []
}

variable "mount_target_ip_addresses" {
  type        = list(string)
  description = "The addresses (within the address range of the specified subnet) at which the file system may be mounted via the mount target."
  default     = []
}

variable "bypass_policy_lockout_safety_check" {
  type        = string
  description = "(Optional) A flag to indicate whether to bypass the `aws_efs_file_system_policy` lockout safety check. The policy lockout safety check determines whether the policy in the request will prevent the principal making the request will be locked out from making future `PutFileSystemPolicy` requests on the file system. Set `bypass_policy_lockout_safety_check` to `true` only when you intend to prevent the principal that is making the request from making a subsequent `PutFileSystemPolicy` request on the file system. The default value is `false`"
  default     = false
}

variable "file_system_policy" {
  type        = string
  description = "(Required) The JSON formatted file system policy for the EFS file system."
  default     = ""
}

variable "backup_policy_status" {
  type        = string
  description = "(Required) A status of the backup policy. Valid values: `ENABLED`, `DISABLED`."
  default     = "ENABLED"
}

variable "tags" {
  type        = map(string)
  description = " (Optional) A map of tags to assign to the file system. If configured with a provider default_tags configuration block present, tags with matching keys will overwrite those defined at the provider-level."
  default     = {}
}

# Security Group
variable "vpc_id" {
  description = "(Optional, Forces new resource) VPC ID."
  type        = string
  default     = null
}

variable "create_security_group" {
  type        = bool
  description = "whether to create security group using module"
  default     = true
}

variable "security_group_ingress" {
  description = "Specify the ingress rule for the security group"
  type        = any
  default     = {}
}

variable "egress_rules" {
  description = "(Optional) egress rules to add to the security group"
  type        = any
  default     = {}
}

## Other external security groups
variable "external_security_groups" {
  type        = list(string)
  description = "IDs of other security groups. NOTE: All these security groups must be in the same vpc as the subnets where the efs is mounted. A maximum of 5 Security Group IDs is allowed."
  default     = []
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.45.0"
    }
  }

  required_version = ">= 0.14.11"
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"

  tags = {
    Name = "Terraform State Bucket"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state_versioning" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "terraform_state" {
  description             = "CMK for the terraform_state S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
  }
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name = "Terraform Lock Table"
  }
}

# Glue Service Role
resource "aws_iam_role" "glue_service_role" {
  name = "glue-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "glue.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy_attachment" "glue_service_role_policy" {
  name       = "glue-service-role-policy"
  roles       = [aws_iam_role.glue_service_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3_access_policy" {
  name = "GlueS3AccessPolicy"
  role = aws_iam_role.glue_service_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:aws:s3:::nlp-pipeline-bucket/*"
      }
    ]
  })
}

# Comprehend Service Role
resource "aws_iam_role" "comprehend_service_role" {
  name = "comprehend-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "comprehend.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "comprehend_s3_access_policy" {
  name = "ComprehendS3AccessPolicy"
  role = aws_iam_role.comprehend_service_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:aws:s3:::nlp-pipeline-bucket/*"
      }
    ]
  })
}

# Lambda Execution Role
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy_attachment" "lambda_basic_execution" {
  name       = "lambda-basic-execution"
  roles       = [aws_iam_role.lambda_execution_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_custom_policy" {
  name = "LambdaCustomPolicy"
  role = aws_iam_role.lambda_execution_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "dynamodb:PutItem",
          "dynamodb:BatchWriteItem",
          "stepfunctions:StartExecution"
        ]
        Resource = [
          "arn:aws:s3:::nlp-pipeline-bucket/*",
          "arn:aws:dynamodb:${var.aws_region}:${var.aws_account_id}:table/NLPResults",
          "arn:aws:states:${var.aws_region}:${var.aws_account_id}:stateMachine:YourStateMachineName"
        ]
      }
    ]
  })
}

# Step Functions Service Role
resource "aws_iam_role" "step_functions_service_role" {
  name = "step-functions-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "states.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name = "StepFunctionsPolicy"
  role = aws_iam_role.step_functions_service_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "glue:StartJobRun"
        ]
        Resource = [
          "arn:aws:lambda:${var.aws_region}:${var.aws_account_id}:function:*",
          "arn:aws:glue:${var.aws_region}:${var.aws_account_id}:job/*"
        ]
      }
    ]
  })
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region to deploy resources in"
  type        = string
  default     = "eu-central-1"
}

variable "aws_account_id" {
  description = "Your AWS Account ID"
  type        = string
  default     = "970837487748"
}

