# DEPRECATION WARNING: This code has been deprecated
# The maintained & current code can be found at src/mlstacks/terraform/
# under the same relative location.

# variables for creating a ZenML stack configuration file
variable "zenml-version" {
  description = "The version of ZenML being used"
  default     = "0.12.0"
  type        = string
}

#https://github.com/terraform-aws-modules/terraform-aws-atlantis
data "aws_region" "current" {}
locals {
    tags = merge(
    {
      "Name" = var.name
    },
    var.tags,
  )
}
data "aws_iam_policy_document" "ecs_tasks" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = compact(distinct(concat(["ecs-tasks.amazonaws.com"], var.trusted_principals)))
    }

    dynamic "principals" {
      for_each = length(var.trusted_entities) > 0 ? [true] : []

      content {
        type        = "AWS"
        identifiers = var.trusted_entities
      }
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {

  name                 = format("%s-ecs_task_execution-%s", var.name,var.id)
  assume_role_policy   = data.aws_iam_policy_document.ecs_tasks.json
  permissions_boundary = var.permissions_boundary

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  count = length(var.policies_arn)

  role       = aws_iam_role.ecs_task_execution.id
  policy_arn = element(var.policies_arn, count.index)
}

resource "aws_secretsmanager_secret" "repo_secret" {
  name        = format("%s-reposecret-%s", var.name,var.id)
  description = "nginx_secret_crt"
}

resource "aws_secretsmanager_secret_version" "repo_secret" {
  secret_id     = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({ username : "AWS", password : var.token })
}

# ref: https://docs.aws.amazon.com/AmazonECS/latest/developerguide/specifying-sensitive-data.html
data "aws_iam_policy_document" "ecs_task_access_secrets" {
  statement {
    effect = "Allow"

    resources = flatten([
      aws_secretsmanager_secret.repo_secret.*.arn
    ])

    actions = [
      "secretsmanager:GetSecretValue"
    ]
  }
}

// data "aws_iam_policy_document" "ecs_task_access_secrets_with_kms" {

//   source_json = data.aws_iam_policy_document.ecs_task_access_secrets.json

//   statement {
//     sid       = "AllowKMSDecrypt"
//     effect    = "Allow"
//     actions   = ["kms:Decrypt"]
//     resources = [var.ssm_kms_key_arn]
//   }
// }
data "aws_iam_policy_document" "ecs_task_access_s3" {
  statement {
    effect = "Allow"

    resources = flatten([
      "arn:aws:s3:::prod-${data.aws_region.current.name}-starport-layer-bucket/*"
    ])

    actions = [
      "s3:GetObject"
    ]
  }
}
resource "aws_iam_role_policy" "ecs_task_access_secrets" {

  name = "ECSTaskAccessSecretsPolicy"

  role = aws_iam_role.ecs_task_execution.id

  policy = element(
    compact(
      concat(
        // data.aws_iam_policy_document.ecs_task_access_secrets_with_kms.*.json,
        data.aws_iam_policy_document.ecs_task_access_secrets.*.json,
        data.aws_iam_policy_document.ecs_task_access_s3.*.json,
      ),
    ),
    0,
  )
}

output "role_arn" {
  value = aws_iam_role.ecs_task_execution.arn
}
output "secret_arn" {
  value = aws_secretsmanager_secret_version.repo_secret.arn
}

#https://github.com/terraform-aws-modules/terraform-aws-atlantis
variable "trusted_principals" {
  description = "A list of principals, in addition to ecs-tasks.amazonaws.com, that can assume the task role"
  type        = list(string)
  default     = []
}

variable "trusted_entities" {
  description = "A list of  users or roles, that can assume the task role"
  type        = list(string)
  default     = []
}

variable "name" {
  description = "Name to use on all resources created (VPC, ALB, etc)"
  type        = string
  default     = "nim"
}
variable "id" {
  description = "random id in hex for suffix"
  type        = string
  default     = ""
}
variable "token" {
  default = ""
}
variable "tags" {
  description = "A map of tags to use on all resources"
  type        = map(string)
  default     = {}
}
variable "permissions_boundary" {
  description = "If provided, all IAM roles will be created with this permissions boundary attached."
  type        = string
  default     = null
}
variable "policies_arn" {
  description = "A list of the ARN of the policies you want to apply"
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

resource "aws_organizations_organization" "org" {
  feature_set          = var.feature_set
  enabled_policy_types = var.enabled_policy_types
}

locals {
  # ["a", "/a/", "b/c/", "/b/d", "e/f/g/"] => ["a", "b/c", "b/d", "e/f/g"]
  trimmed_ous = distinct([for ou in var.ous : trim(ou, "/")])
  # ["a", "b/c", "b/d", "e/f/g"] => [["a"], ["b", "c"], ["b", "d"], ["e", "f", "g"]]
  safe_ous = distinct([for ou in local.trimmed_ous : split("/", ou)])

  # [["a"], ["b", "c"], ["b", "d"], ["e", "f", "g"]] => [["a"], ["b"], ["e"]]
  l0_ou_paths = distinct([for ou in local.safe_ous : slice(ou, 0, 1)])
  # [["a"], ["b", "c"], ["b", "d"], ["e", "f", "g"]] => [["b", "c"], ["b", "d"], ["e", "f"]]
  l1_ou_paths = distinct([for ou in local.safe_ous : slice(ou, 0, 2) if length(ou) > 1])
  # [["a"], ["b", "c"], ["b", "d"], ["e", "f", "g"]] => [["e", "f", "g"]]
  l2_ou_paths = distinct([for ou in local.safe_ous : slice(ou, 0, 3) if length(ou) > 2])
  l3_ou_paths = distinct([for ou in local.safe_ous : slice(ou, 0, 4) if length(ou) > 3])
  l4_ou_paths = distinct([for ou in local.safe_ous : slice(ou, 0, 5) if length(ou) > 4])

  # [["a"], ["b"], ["e"]] =>
  #   {a = {name = "a"}, b = {name = "b"}, e = {name = "e"}}
  l0_ous = { for ou_path in local.l0_ou_paths :
    join("/", ou_path) => {
      name = element(ou_path, length(ou_path) - 1)
    }
  }
  # [["b", "c"], ["b", "d"], ["e", "f"]] =>
  #   {b/c = {name = "c", parent_name = "b"}, b/d = {name = "d", parent_name = "b"}, e/f = {name = "f", parent_name = "e"}}
  l1_ous = { for ou_path in local.l1_ou_paths :
    join("/", ou_path) => {
      name = element(ou_path, length(ou_path) - 1)
      # parent_name = element(ou_path, length(ou_path) - 2)
      parent_name = join("/", slice(ou_path, 0, length(ou_path) - 1))
    }
  }
  # [["e", "f", "g"]] => {e/f/g = {name = "g", parent_name = "e/f"}}
  l2_ous = { for ou_path in local.l2_ou_paths :
    join("/", ou_path) => {
      name        = element(ou_path, length(ou_path) - 1)
      parent_name = join("/", slice(ou_path, 0, length(ou_path) - 1))
    }
  }
  l3_ous = { for ou_path in local.l3_ou_paths :
    join("/", ou_path) => {
      name        = element(ou_path, length(ou_path) - 1)
      parent_name = join("/", slice(ou_path, 0, length(ou_path) - 1))
    }
  }
  l4_ous = { for ou_path in local.l4_ou_paths :
    join("/", ou_path) => {
      name        = element(ou_path, length(ou_path) - 1)
      parent_name = join("/", slice(ou_path, 0, length(ou_path) - 1))
    }
  }

  # {a/b/c = {level = 2, name = c}}
  ous_helper = {
    for p in concat(
      local.l0_ou_paths,
      local.l1_ou_paths,
      local.l2_ou_paths,
      local.l3_ou_paths,
      local.l4_ou_paths,
    ) : join("/", p) => { level = length(p) - 1 }
  }
  # {a/b/c = resource.2["a/b/c"]}
  ous = { for ou_path_str, ou in local.ous_helper : ou_path_str =>
    ou["level"] == 0 ? aws_organizations_organizational_unit.l0[ou_path_str] :
    ou["level"] == 1 ? aws_organizations_organizational_unit.l1[ou_path_str] :
    ou["level"] == 2 ? aws_organizations_organizational_unit.l2[ou_path_str] :
    ou["level"] == 3 ? aws_organizations_organizational_unit.l3[ou_path_str] :
    aws_organizations_organizational_unit.l4[ou_path_str]
  }
}

resource "aws_organizations_organizational_unit" "l0" {
  for_each  = local.l0_ous
  name      = each.value["name"]
  parent_id = aws_organizations_organization.org.roots[0].id
}

resource "aws_organizations_organizational_unit" "l1" {
  for_each  = local.l1_ous
  name      = each.value["name"]
  parent_id = aws_organizations_organizational_unit.l0[each.value["parent_name"]].id
}

resource "aws_organizations_organizational_unit" "l2" {
  for_each  = local.l2_ous
  name      = each.value["name"]
  parent_id = aws_organizations_organizational_unit.l1[each.value["parent_name"]].id
}

resource "aws_organizations_organizational_unit" "l3" {
  for_each  = local.l3_ous
  name      = each.value["name"]
  parent_id = aws_organizations_organizational_unit.l2[each.value["parent_name"]].id
}

resource "aws_organizations_organizational_unit" "l4" {
  for_each  = local.l4_ous
  name      = each.value["name"]
  parent_id = aws_organizations_organizational_unit.l3[each.value["parent_name"]].id
}

output "org" {
  description = "aws_organizations_organization resource"
  value       = resource.aws_organizations_organization.org
}

output "ous" {
  description = "map of organizational units - keys are ou paths as string, values are aws_organizations_organizational_unit resources"
  value       = local.ous
}

variable "feature_set" {
  description = "Enable all features (\"ALL\") or only consolidated billing (\"CONSOLIDATED_BILLING\")."
  type        = string
  default     = "ALL"
}

variable "enabled_policy_types" {
  description = "Policy types to enable in the organization root. See Organizations `EnablePolicyType` api."
  type        = list(string)
  default     = ["AISERVICES_OPT_OUT_POLICY", "BACKUP_POLICY", "SERVICE_CONTROL_POLICY", "TAG_POLICY"]
}

variable "ous" {
  description = "List of organizational units specified as '/' delimited paths. Intermediate paths do not need to be declared individually. Example: [\"core\", \"workloads/nonprod\", \"workloads/prod\"]"
  type        = list(string)
  default     = []
}

variable "accounts" {
  description = "Map of AWS account definitions - keys are account names, values are aws_organizations_account arguments. Additionally supported keys: `ou_path`."
  type        = map(any)
  default     = {}
}

variable "organization_account_access_role_name_default" {
  description = "Defualt administrator role name to be created in accounts, assumable by the management account. This can be overridden in the `accounts` variable."
  type        = string
  default     = "OrganizationAccountAccessRole"
}

locals {  
  resource_group_name = var.resource_group_name != "" && var.resource_group_name != null ? var.resource_group_name : "default"
  prefix_name     = var.name_prefix != "" && var.name_prefix != null ? var.name_prefix : local.resource_group_name
  vpc_name        = var.name != "" ? var.name : "${local.prefix_name}-vpc"
  vpc_id          = var.provision ? data.aws_vpc.vpc[0].id : ""
  cidr_block      = var.provision ? data.aws_vpc.vpc[0].cidr_block : ""
  arn             = var.provision ? data.aws_vpc.vpc[0].arn : ""
  security_group_id  = length(data.aws_security_group.default_aws_security_group) > 0 ? data.aws_security_group.default_aws_security_group[0].id : ""
  security_group_arn = length(data.aws_security_group.default_aws_security_group) > 0 ? data.aws_security_group.default_aws_security_group[0].arn : ""

  acl_id          = var.provision && data.aws_network_acls.default-vpc-network-acls != null && length(tolist(data.aws_network_acls.default-vpc-network-acls[0].ids))>0 ? tolist(data.aws_network_acls.default-vpc-network-acls[0].ids)[0] : ""
}

# Create a VPC
resource "aws_vpc" "vpc" {
  count                = var.provision ? 1 : 0

  cidr_block           = var.internal_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = local.vpc_name
    ResourceGroup = local.resource_group_name
  }
}

data "aws_vpc" "vpc" {
  depends_on = [aws_vpc.vpc]
  count = var.provision ? 1 : 0

  tags = {
    Name = local.vpc_name
  }
}

data "aws_network_acls" "default-vpc-network-acls" {
  depends_on = [aws_vpc.vpc]  
  count = var.provision ? 1 : 0

  #count = var.provision && var._count > 0 ?  1 : 0
  vpc_id = local.vpc_id

  filter {
    name   = "default"
    values = ["true"]
  }
}

resource "aws_default_network_acl" "default" {

  depends_on = [aws_vpc.vpc, data.aws_network_acls.default-vpc-network-acls]
  count = var.provision ? 1 : 0
  #count = var.provision && var._count > 0 ?  1 : 0
  default_network_acl_id = local.acl_id

  # if no rules defined, deny all traffic in this ACL
  egress {          #allow_internal_egress
    protocol   = -1 # -1 'all' protocol
    rule_no    = 100
    action     = "allow"
    cidr_block = local.cidr_block
    from_port  = 0
    to_port    = 0
  }

  ingress {         #allow_internal_ingress
    protocol   = -1 #-1 'all' protocol 
    rule_no    = 200
    action     = "allow"
    cidr_block = local.cidr_block
    from_port  = 0
    to_port    = 0
  }

  ingress {            #deny_external_ssh
    protocol   = "tcp" #-1 'all' protocol 
    rule_no    = 300
    action     = "deny"
    cidr_block = var.external_cidr //"0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {            #deny_external_rdp
    protocol   = "tcp" # -1 'all' protocol
    rule_no    = 400
    action     = "deny"
    cidr_block = var.external_cidr //"0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  tags = {
    Name = "${local.vpc_name}-default_acl"
    ResourceGroup = local.resource_group_name
  }
}

resource "aws_default_security_group" "default_security_group" {
  count = var.provision  ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${local.vpc_name}-default_sg"
    ResourceGroup = local.resource_group_name
  }
}

resource "aws_security_group_rule" "default_inbound_ping" {
  count = var.provision  ? 1 : 0


  type              = "ingress"
  from_port         = 8
  to_port           = 8
  protocol          = "icmp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = element(aws_default_security_group.default_security_group.*, 0).id
}

resource "aws_security_group_rule" "default_inbound_http" {
  count = var.provision  ? 1 : 0

  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = element(aws_default_security_group.default_security_group.*, 0).id
}

data "aws_security_group" "default_aws_security_group" {
  count = var.provision ? 1 : 0

  vpc_id = local.vpc_id

  filter {
    name   = "group-name"
    values = ["default"]
  }
}

output "vpc" {

  depends_on  = [aws_vpc.vpc]
  value = data.aws_vpc.vpc[0]

}

output "vpc_name" {
  depends_on  = [aws_vpc.vpc]
  value= data.aws_vpc.vpc[0].tags["Name"]
}

output "vpc_id" {
  depends_on  = [aws_vpc.vpc]
  value = local.vpc_id
  description = "The id for the vpc network"
}

output "vpc_arn" {
  depends_on  = [aws_vpc.vpc]
  value       = local.arn
  description = "The arn of the vpc"
}

output "default_network_acl_id" {
  depends_on  = [aws_vpc.vpc, data.aws_network_acls.default-vpc-network-acls] 
  value  = local.acl_id
  #value  = ""
  description = "The id for the default network acl"
}

output "default_security_group_id" {
  depends_on  = [aws_vpc.vpc]   
  value       = local.security_group_id
  description = "The id of the default security group."
}

output "default_security_group_arn" {
  depends_on  = [aws_vpc.vpc]   
  value       = local.security_group_arn
  description = "The arn of the default security group."
}

output "vpc_cidr" {
  depends_on  = [aws_vpc.vpc]   
  value = var.internal_cidr
  description = "The internal vpc cidr."

}

variable "name" {
  type        = string
  description = "The name of the VPC instance"
  default     = ""
}

variable "internal_cidr" {  
  type        = string
  description = "The cidr range of the internal network for the AWS VPC. Either provide manually or chose from AWS IPAM poolsß"
  default     = "10.0.0.0/16"
}

variable "external_cidr" {
  type        = string
  description = "The cidr range of the external network for the AWS VPC."
  default     = "0.0.0.0/0"
}

variable "provision" {
  type        = bool
  description = "Flag indicating that the instance should be provisioned. If false then an existing instance will be looked up"
  default     = true
}

variable "instance_tenancy" {
  type        = string
  description = "Instance is shared / dedicated, etc. #[default, dedicated, host]"
  default     = "default"
}

variable "name_prefix" {
  type        = string
  description = "Prefix to be added to the names of resources which are being provisioned"
  default     = "swe"
}

variable "enable_dns_support" {
  type        = string
  description = "default is true. [true, false]]"
  default     = true
}

variable "enable_dns_hostnames" {
  type        = string
  description = "Default is true. [true, false]]. ROSA cluster requires this to be set as true"
  default     = true
}

variable "resource_group_name" {
  type        = string
  description = "The name of the resource group where the VPC is deployed. On AWS this value becomes a tag."
  default     = "default"
}

