# create route
resource "aws_route" "route-dev-public" {
  route_table_id              = aws_vpc.vpc_dev.default_route_table_id
  destination_ipv6_cidr_block = "::/0"
  destination_cidr_block      = "0.0.0.0/0"
  gateway_id                  = aws_internet_gateway.gatway_dev.id
}

resource "aws_route" "route-rec-public" {
  route_table_id              = aws_vpc.vpc_rec.default_route_table_id
  destination_ipv6_cidr_block = "::/0"
  destination_cidr_block      = "0.0.0.0/0"
  gateway_id      = aws_internet_gateway.gatway_rec.id
}

# outputs
output "vpc_ids" {
  value = {
    dev = aws_vpc.vpc_dev.id
    rec = aws_vpc.vpc_rec.id
  }
  description = "ids des vpcs créer"
  sensitive = false
}

locals {
  create_kms_key = var.kms_key_arn == "" ? true : false
  kms_key_arn    = coalesce(var.kms_key_arn, aws_kms_key.kms_key[0].arn)

  name = var.name == "sudo-backup" ? "sudo-backup-${random_string.random.result}" : var.name

  secondary_vault_cold_storage_after = var.secondary_vault_cold_storage_after != null ? var.secondary_vault_cold_storage_after : var.cold_storage_after
  secondary_vault_delete_after       = var.secondary_vault_delete_after != null ? var.secondary_vault_delete_after : var.delete_after

}

resource "random_string" "random" {
  length  = 6
  special = false
  upper   = false
}

resource "aws_kms_key" "kms_key" {
  count               = local.create_kms_key ? 1 : 0
  description         = "KMS key for Backup Encryption at rest"
  enable_key_rotation = true

  tags = {
    Name = "${local.name}-backup-encryption-key"
  }
}

resource "aws_backup_vault" "vault" {
  name        = "${local.name}-backup-vault"
  kms_key_arn = local.kms_key_arn
  tags = {
    Name = "${local.name}-backup-vault"
  }
}


resource "aws_backup_plan" "plan" {
  name = "${local.name}-backup-plan"
  tags = {
    Name = "${local.name}-backup-plan"
  }

  rule {
    rule_name         = "${local.name}-backup-rule"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = var.backup_schedule

    dynamic "lifecycle" {
      for_each = var.cold_storage_after != null || var.delete_after != null ? [1] : []
      content {
        cold_storage_after = var.cold_storage_after
        delete_after       = var.delete_after
      }
    }
    dynamic "copy_action" {
      for_each = var.secondary_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.secondary_vault_arn
        dynamic "lifecycle" {
          for_each = local.secondary_vault_cold_storage_after != null || local.secondary_vault_delete_after != null ? [1] : []
          content {
            cold_storage_after = local.secondary_vault_cold_storage_after
            delete_after       = local.secondary_vault_delete_after
          }
        }
      }
    }

    recovery_point_tags = {
      Name = "${local.name}-backup-recovery-point"
    }

  }
}

resource "aws_iam_role" "iam_role" {
  name               = "${local.name}-backup-role"
  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": ["sts:AssumeRole"],
      "Effect": "allow",
      "Principal": {
        "Service": ["backup.amazonaws.com"]
      }
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "iam_role_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.iam_role.name
}


resource "aws_backup_selection" "selection" {
  name         = "${local.name}-backup-selection"
  iam_role_arn = aws_iam_role.iam_role.arn

  plan_id = aws_backup_plan.plan.id

  dynamic "selection_tag" {
    for_each = var.selection_tags
    content {
      type  = lookup(selection_tag.value, "type", "STRINGEQUALS")
      key   = lookup(selection_tag.value, "key", "backup")
      value = lookup(selection_tag.value, "value", "true")
    }
  }
}

output "vault_arn" {
  value       = aws_backup_vault.vault.arn
  description = "ARN of the backup vault."
}

output "plan_arn" {
  value       = aws_backup_plan.plan.arn
  description = "ARN of the Backup Plan"
}

output "iam_role_arn" {
  value       = aws_iam_role.iam_role.arn
  description = "ARN of the IAM role created for Backup"
}

output "kms_key_arn" {
  value       = local.create_kms_key ? aws_kms_key.kms_key[0].arn : null
  description = "ARN of the KMS Key if created, otherwise null"
}

variable "name" {
  type        = string
  description = "(Optional) Specify the name for the backup configuration. Default: sudo-backup-<randomstring>"
  default     = "sudo-backup"
}


variable "backup_schedule" {
  type        = string
  description = "(Optional) Backup schedule in cron format. Default: cron(0 12 * * ? *)"
  default     = "cron(0 12 * * ? *)" # Take backup at UTC 12noon i.e 4am PST
}

variable "kms_key_arn" {
  type        = string
  description = "(optional) Existing KMS Key ARN. Default: \"\""
  default     = ""
}

variable "cold_storage_after" {
  type        = number
  description = "(Optional) Specifies the number of days after creation that a recovery point is moved to cold storage."
  default     = null
}

variable "delete_after" {
  type        = number
  description = "(Optional) Specifies the number of days after creation that a recovery point is deleted. Must be 90 days greater than cold_storage_after"
  default     = null
}

variable "secondary_vault_arn" {
  type        = string
  description = "(Optional) Specifies the ARN of the secondary vault for DR."
  default     = null
}

variable "secondary_vault_cold_storage_after" {
  type        = number
  description = "(Optional) Specifies the number of days after creation that a recovery point is moved to cold storage for Secondary Vault. Default uses the value from primary vault."
  default     = null
}

variable "secondary_vault_delete_after" {
  type        = number
  description = "(Optional) Specifies the number of days after creation that a recovery point is deleted for secondary Vault. Must be 90 days greater than cold_storage_after. Default uses the value from primary vault."
  default     = null
}

# # Example
#   selection_tags = [{
#     type  = "STRINGEQUALS"
#     key   = "foo"
#     value = "bar"
#   }]
variable "selection_tags" {
  type        = list(any)
  description = "(Optional) List of objects containing tag key value and type (comparison operator)."
  default = [{

  }]
}

terraform {
  required_version = ">= 0.13.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.1.3"
    }
  }
}

#####################################################
# COGNITO USER POOL
#####################################################

resource "aws_cognito_user_pool" "twitter_user_pool" {
  name = var.app_name

  # auto_verified_attributes = ["email"]
  admin_create_user_config  {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length = 6
    require_numbers = true
    require_uppercase = true
    require_symbols = true
  }
}

resource "aws_cognito_user_pool_domain" "twitter_domain_user_pool" {
  domain = "${var.app_name}-domain"
  user_pool_id = aws_cognito_user_pool.twitter_user_pool.id
}


#####################################################
# COGNITO IDENTITY POOL
#####################################################

resource "aws_cognito_identity_pool" "twitter_id_pool" {
  identity_pool_name               = replace(var.app_name, "-", " ")
  allow_unauthenticated_identities = false

  lifecycle {
    ignore_changes = all
  }
}

resource "aws_cognito_identity_pool_roles_attachment" "id_pool_roles" {
  identity_pool_id = aws_cognito_identity_pool.twitter_id_pool.id

  roles = {
    "authenticated" = aws_iam_role.cognito_auth.arn
    "unauthenticated" = aws_iam_role.cognito_unauth.arn
  }
}


##################################################################
# AUTH CONGNITO ROLE
##################################################################

data "aws_iam_policy_document" "cognito_auth_assume" {

  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    effect = "Allow"

    principals {
      type = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values = [aws_cognito_identity_pool.twitter_id_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values = ["authenticated"]
    }
    }
}

data "aws_iam_policy_document" "cognito_auth" {

  statement {
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*"
    ]

    resources = [
      "*"
    ]
  }
}

resource "aws_iam_role" "cognito_auth" {
  name = "${var.app_name}_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_auth_assume.json
}

resource "aws_iam_policy" "cognito_auth" {
  name   = "cognito_kibana_auth_${var.app_name}"
  policy = data.aws_iam_policy_document.cognito_auth.json
}

resource "aws_iam_role_policy_attachment" "cognito_auth" {
  role       = aws_iam_role.cognito_auth.name
  policy_arn = aws_iam_policy.cognito_auth.arn
}


##################################################################
# UNAUTH CONGNITO ROLE
##################################################################

data "aws_iam_policy_document" "cognito_unauth_assume" {

  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    effect = "Allow"

    principals {
      type = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values = [aws_cognito_identity_pool.twitter_id_pool.id]
    }
    condition {
        test     = "ForAnyValue:StringLike"
        variable = "cognito-identity.amazonaws.com:amr"
      values = ["unauthenticated"]
  }
}
}

data "aws_iam_policy_document" "cognito_unauth" {

  statement {
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
    ]

    resources = [
      "*"
    ]
  }
}

resource "aws_iam_role_policy_attachment" "cognito_unauth" {
  role       = aws_iam_role.cognito_unauth.name
  policy_arn = aws_iam_policy.cognito_unauth.arn
}


resource "aws_iam_policy" "cognito_unauth" {
  name   = "cognito_kibana_unauth_${var.app_name}"
  policy = data.aws_iam_policy_document.cognito_auth.json
}

resource "aws_iam_role" "cognito_unauth" {
  name = "${var.app_name}_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_unauth_assume.json
}

output "user_pool_id" {
  value = aws_cognito_user_pool.twitter_user_pool.id
}

output "identity_pool_id" {
  value = aws_cognito_identity_pool.twitter_id_pool.id
}

output "auth_role" {
  value = aws_iam_role.cognito_auth.arn
}

output "unauth_role" {
  value = aws_iam_role.cognito_unauth.arn
}

variable "app_name" {
  type        = string
  description = "The name of your application"
  default     = "coop-tweets"
}

/**
 * ## Usage
 *
 * Creates an AWS GuardDuty Detector, KMS Key for encrypting exports to S3, and CloudWatch rule to watch for findings.
 *
 * ```hcl
 * module "guardduty" {
 *   source = "dod-iac/guardduty/aws"
 *
 *   tags = {
 *     Application = var.application
 *     Environment = var.environment
 *     Automation  = "Terraform"
 *   }
 * }
 * ```
 *
 * You can customize the finding publishing frequency.
 *
 * ```hcl
 * module "guardduty" {
 *   source = "dod-iac/guardduty/aws"
 *
 *   enable = true
 *   finding_publishing_frequency = "SIX_HOURS"
 *   tags = {
 *     Application = var.application
 *     Environment = var.environment
 *     Automation  = "Terraform"
 *   }
 * }
 * ```
 *
 * You can exports GuardDuty findings to a S3 bucket using the s3_bucket_name variable.
 *
 * ```hcl
 * module "guardduty" {
 *   source = "dod-iac/guardduty/aws"
 *
 *   enable = true
 *   s3_bucket_name = module.logs.aws_logs_bucket
 *   tags = {
 *     Application = var.application
 *     Environment = var.environment
 *     Automation  = "Terraform"
 *   }
 * }
 * ```
 *
 * ## Terraform Version
 *
 * Terraform 0.12. Pin module version to ~> 1.0.0 . Submit pull-requests to master branch.
 *
 * Terraform 0.11 is not supported.
 *
 * ## License
 *
 * This project constitutes a work of the United States Government and is not subject to domestic copyright protection under 17 USC § 105.  However, because the project utilizes code licensed from contributors and other third parties, it therefore is licensed under the MIT License.  See LICENSE file for more information.
 */

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "key_policy" {
  policy_id = "key-consolepolicy"
  statement {
    sid = "Enable IAM User Permissions"
    actions = [
      "kms:*"
    ]
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        format(
          "arn:%s:iam::%s:root",
          data.aws_partition.current.partition,
          data.aws_caller_identity.current.account_id
        )
      ]
    }
    resources = ["*"]
  }
  statement {
    sid = "Allow GuardDuty to use the key"
    actions = [
      "kms:GenerateDataKey"
    ]
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = [
        "guardduty.amazonaws.com"
      ]
    }
    resources = ["*"]
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "Key used to encrypt GuardDuty findings."
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.key_policy.json
  enable_key_rotation     = true
  tags                    = var.kms_key_tags
}

resource "aws_kms_alias" "guardduty" {
  name          = var.kms_alias_name
  target_key_id = aws_kms_key.guardduty.key_id
}

resource "aws_guardduty_detector" "main" {
  enable                       = var.enable
  finding_publishing_frequency = var.finding_publishing_frequency
  depends_on = [
    aws_kms_key.guardduty,
    aws_kms_alias.guardduty
  ]
}

data "aws_s3_bucket" "main" {
  count  = length(var.s3_bucket_name) > 0 ? 1 : 0
  bucket = var.s3_bucket_name
}

# GuardDuty expects a folder to exist, otherwise it throws an error.
resource "aws_s3_bucket_object" "guardduty" {
  count  = length(var.s3_bucket_name) > 0 && length(var.s3_bucket_prefix) > 0 ? 1 : 0
  bucket = data.aws_s3_bucket.main.0.id
  acl    = "private"
  key = var.s3_bucket_prefix == "/" ? "/" : format("%s/", (
    substr(var.s3_bucket_prefix, 0, 1) == "/" ?
    substr(var.s3_bucket_prefix, 1, length(var.s3_bucket_prefix)) :
    var.s3_bucket_prefix
  ))
  source = "/dev/null"
}

resource "aws_guardduty_publishing_destination" "main" {
  count           = length(var.s3_bucket_name) > 0 ? 1 : 0
  detector_id     = aws_guardduty_detector.main.id
  destination_arn = format("%s%s", data.aws_s3_bucket.main.0.arn, (length(var.s3_bucket_prefix) > 0 ? var.s3_bucket_prefix : "/"))
  kms_key_arn     = aws_kms_key.guardduty.arn
  depends_on = [
    aws_s3_bucket_object.guardduty
  ]
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name          = "guardduty-finding-events"
  description   = "AWS GuardDuty event findings"
  event_pattern = <<EOF
  {
    "detail-type": [
      "GuardDuty Finding"
    ],
    "source": [
      "aws.guardduty"
    ]
  }
  EOF
}

output "aws_cloudwatch_event_rule_name" {
  description = "Name of the CloudWatch rule that watches for AWS GuardDuty findings."
  value       = aws_cloudwatch_event_rule.guardduty_findings.name
}

output "aws_guardduty_detector_id" {
  description = "The ID of the GuardDuty detector."
  value       = aws_guardduty_detector.main.id
}

variable "enable" {
  type        = bool
  description = "Enable monitoring and feedback reporting.  Setting to false is equivalent to \"suspending\" GuardDuty."
  default     = true
}

variable "finding_publishing_frequency" {
  type        = string
  description = "Specifies the frequency of notifications sent for subsequent finding occurrences.  If the detector is a GuardDuty member account, the value is determined by the GuardDuty master account and cannot be modified, otherwise defaults to SIX_HOURS.  For standalone and GuardDuty master accounts, it must be configured in Terraform to enable drift detection.  Valid values for standalone and master accounts: FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS. "
  default     = "FIFTEEN_MINUTES"
}

variable "kms_alias_name" {
  type        = string
  description = "The display name of the alias of the KMS key used to encrypt exports to S3. The name must start with the word \"alias\" followed by a forward slash (alias/)."
  default     = "alias/guardduty"
}

variable "kms_key_tags" {
  type        = map(string)
  description = "Tags to apply to the AWS KMS Key used to encrypt exports to S3."
  default     = {}
}

variable "s3_bucket_name" {
  type        = string
  description = "The name of the S3 bucket that receives findings from GuardDuty.  If blank, then GuardDuty does not export findings to S3."
  default     = ""
}

variable "s3_bucket_prefix" {
  type        = string
  description = "The prefix for where findings from GuardDuty are stored in the S3 bucket.  Should start with \"/\" if defined.  GuardDuty will build the full destination ARN using this format: <s3_bucket_arn><s3_bucket_prefix>/AWSLogs/<account_id>/GuardDuty/<region>."
  default     = "/guardduty"
}

terraform {
  required_version = ">= 0.13"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 3.0"
    }
  }
}

terraform {
  required_version = ">= 0.12"
}

# ---------------------------------------------------------------------------------------------------------------------
# Create S3 Bucket
# Provider Docs: https://www.terraform.io/docs/providers/aws/r/s3_bucket.html
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket = var.bucket
  tags   = var.tags

  force_destroy = var.force_destroy
}

# ---------------------------------------------------------------------------------------------------------------------
# Create a block on public access for S3 Bucket
# Note this does not affect a CloudFront distribution if configured correctly.
# By setting all values to true, will show as block all public access: ON in console.
# Provider Docs: # https://www.terraform.io/docs/providers/aws/r/s3_bucket_public_access_block.html
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ---------------------------------------------------------------------------------------------------------------------
# Create a versioning configuration resource on S3 Bucket.
#
# For MFA delete details, see:
# https://docs.aws.amazon.com/AmazonS3/latest/userguide/MultiFactorAuthenticationDelete.html
#
# Provider Doc: https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_versioning
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count = var.versioning_enabled ? 1 : 0

  bucket                = aws_s3_bucket.this.id
  expected_bucket_owner = var.versioning_expected_bucket_owner
  mfa                   = var.versioning_mfa

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.versioning_mfa_delete
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Create a server side encryption resource on S3 Bucket.
#
# For S3 Bucket keys to save KMS costs, see:
# https://docs.aws.amazon.com/AmazonS3/latest/userguide/bucket-key.html
#
# Provider Doc: https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_server_side_encryption_configuration
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket                = aws_s3_bucket.this.id
  expected_bucket_owner = var.versioning_expected_bucket_owner

  rule {
    bucket_key_enabled = var.bucket_key_enabled

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_id == null ? "AES256" : "aws:kms"
      kms_master_key_id = var.kms_key_id
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Create an access control list (ACL) resource on S3 Bucket.
#
# Provider Doc: https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_acl
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  bucket                = aws_s3_bucket.this.id
  expected_bucket_owner = var.versioning_expected_bucket_owner
  acl                   = var.acl

  depends_on = [
    aws_s3_bucket_ownership_controls.this
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# Create an ownership control resource on S3 Bucket, needed for setting ACL resource.
#
# Provider Doc: https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/s3_bucket_ownership_controls
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = var.object_ownership
  }
}

output "s3_bucket" {
  value = aws_s3_bucket.this
}

output "s3_bucket_public_access_block" {
  value = aws_s3_bucket_public_access_block.this
}

# ---------------------------------------------------------------------------------------------------------------------
# Required variables
# ---------------------------------------------------------------------------------------------------------------------

# ---------------------------------------------------------------------------------------------------------------------
# Optional variables
# ---------------------------------------------------------------------------------------------------------------------

variable "bucket" {
  description = "Bucket name to use, must be unique in region. Random name generated if omitted"
  type        = string
  default     = null
}

variable "block_public_acls" {
  description = "Whether or not to block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether or not to block public policies"
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Empty and remove bucket on destroy"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether or not to ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether or not to restrict public buckets"
  type        = bool
  default     = true
}

variable "versioning_enabled" {
  description = "Whether to enable bucket versioning so that deletions and versions are retained"
  type        = bool
  default     = true
}

variable "versioning_mfa_delete" {
  description = "Whether to require MFA when permanently deleting an object or changing versioning state"
  type        = string
  default     = "Disabled"
}

variable "versioning_mfa" {
  description = "MFA device if MFA delete is enabled"
  type        = string
  default     = null
}

variable "versioning_expected_bucket_owner" {
  description = "Account ID of the expected bucket owner"
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned access control policy options for the s3 bucket"
  type        = string
  default     = "private"
}

variable "object_ownership" {
  description = "Object ownership"
  type        = string
  default     = "BucketOwnerPreferred"
}

variable "tags" {
  description = "Map of key value pairs for tags"
  type        = map(string)
  default     = null
}

variable "kms_key_id" {
  description = "Existing kms key id"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether to use short-lived bucket keys to save on KMS costs"
  type        = bool
  default     = true
}

#############################
# Billing Full Access Group #
#############################

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_full_access_assume_role_policy_attachment" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.assume_role_billing_full_access_policy.arn
}

// Using a data resource validates that the users exist before applying
data "aws_iam_user" "billing_full_access_users" {
  count     = length(var.billing_full_access_users)
  user_name = var.billing_full_access_users[count.index]
}

resource "aws_iam_group_membership" "billing_full_access_users" {
  count = length(var.billing_full_access_users) > 0 ? 1 : 0

  name  = "billing_full_access_user_group_membership"
  group = aws_iam_group.billing_full_access.name
  users = data.aws_iam_user.billing_full_access_users[*].user_name
}

#############################
# Billing View Access Group #
#############################

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing_view_access_assume_role_policy_attachment" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.assume_role_billing_view_access_policy.arn
}

// Using a data resource validates that the users exist before applying
data "aws_iam_user" "billing_view_access_users" {
  count     = length(var.billing_view_access_users)
  user_name = var.billing_view_access_users[count.index]
}

resource "aws_iam_group_membership" "billing_view_access_users" {
  count = length(var.billing_view_access_users) > 0 ? 1 : 0

  name  = "billing_view_access_user_group_membership"
  group = aws_iam_group.billing_view_access.name
  users = data.aws_iam_user.billing_view_access_users[*].user_name
}

######################
# Assume Role Policy #
######################

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.account_id]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

#################
# Role Policies #
#################

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "BillingFullAccessPermissions"
    effect = "Allow"
    actions = [
      "aws-portal:*Billing",
      "aws-portal:*Usage",
      "aws-portal:*PaymentMethods",
      "budgets:*Budget",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Allows access to the 'billing-full-access' actions and resources."
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "BillingViewAccessPermissions"
    effect = "Allow"
    actions = [
      "aws-portal:ViewPaymentMethods",
      "aws-portal:ViewAccount",
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "budgets:ViewBudget",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Allows access to the 'billing-view-access' actions and resources."
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

############################
# Role Assumption Policies #
############################

# Allow assuming the "billing_full_access" role
data "aws_iam_policy_document" "assume_role_billing_full_access_policy_doc" {
  statement {
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

resource "aws_iam_policy" "assume_role_billing_full_access_policy" {
  name        = "billing-full-access-assume-role"
  path        = "/"
  description = "Allows the 'billing-full-access' role to be assumed."
  policy      = data.aws_iam_policy_document.assume_role_billing_full_access_policy_doc.json
}

# Allow assuming the "billing_view_access" role
data "aws_iam_policy_document" "assume_role_billing_view_access_policy_doc" {
  statement {
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_policy" "assume_role_billing_view_access_policy" {
  name        = "billing-view-access-assume-role"
  path        = "/"
  description = "Allows the 'billing-view-access' role to be assumed."
  policy      = data.aws_iam_policy_document.assume_role_billing_view_access_policy_doc.json
}

############################
# Billing Full Access Role #
############################

resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  description        = "Role for billing-full-access users to assume"
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

############################
# Billing View Access Role #
############################

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  description        = "Role for billing-view-access users to assume"
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

/**
 * ## Usage
 *
 * Creates IAM Billing Roles that can be assumed for billing operations.
 *
 * Read the more about [IAM Tutorial: Delegate access to the billing console](https://docs.aws.amazon.com/IAM/latest/UserGuide/tutorial_billing.html)
 *
 * ```hcl
 * module "billing_roles" {
 *   source = "dod-iac/iam-billing-roles/aws"
 *
 *   tags = {
 *     Application = var.application
 *     Environment = var.environment
 *     Automation  = "Terraform"
 *   }
 * }
 * ```
 *
 * ## Terraform Version
 *
 * Terraform 0.13. Pin module version to ~> 1.0.0 . Submit pull-requests to master branch.
 *
 * Terraform 0.11 and 0.12 are not supported.
 *
 * ## License
 *
 * This project constitutes a work of the United States Government and is not subject to domestic copyright protection under 17 USC § 105.  However, because the project utilizes code licensed from contributors and other third parties, it therefore is licensed under the MIT License.  See LICENSE file for more information.
 */

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

output "billing_full_access_role_arn" {
  description = "The Amazon Resource Name (ARN) of the billing-full-access role."
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "The Amazon Resource Name (ARN) of the billing-view-access role."
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "The Amazon Resource Name (ARN) of the billing-full-access group."
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "The Amazon Resource Name (ARN) of the billing-view-access group."
  value       = aws_iam_group.billing_view_access.arn
}

variable "billing_full_access_users" {
  type        = list(string)
  description = "The list of IAM users to assign to billing-full-access"
  default     = []
}

variable "billing_view_access_users" {
  type        = list(string)
  description = "The list of IAM users to assign to billing-view-access"
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Tags applied to the IAM resources."
  default     = {}
}

terraform {
  required_version = ">= 0.13"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 3.0"
    }
  }
}

### default values

### aws partitions
module "aws" {
  source = "Young-ook/spinnaker/aws//modules/aws-partitions"
}

locals {
  aws = {
    dns       = module.aws.partition.dns_suffix
    partition = module.aws.partition.partition
    region    = module.aws.region.name
    id        = module.aws.caller.account_id
  }
}

locals {
  default_auto_verified_attributes = ["email"]
  default_profile_schema = [
    {
      name                = "email"
      attribute_data_type = "String"
      mutable             = false
      required            = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
    {
      name                = "phone_number"
      attribute_data_type = "String"
      mutable             = false
      required            = false
      string_attribute_constraints = {
        min_length = 1
        max_length = 20
      }
    },
    {
      name                = "profile_user_id"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
    {
      name                = "profile_email"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
    {
      name                = "profile_first_name"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
    {
      name                = "profile_last_name"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
    {
      name                = "profile_gender"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 10
      }
    },
    {
      name                = "profile_age"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 3
      }
    },
    {
      name                = "profile_persona"
      attribute_data_type = "String"
      mutable             = true
      string_attribute_constraints = {
        min_length = 1
        max_length = 200
      }
    },
  ]
}

### frigga name
module "frigga" {
  source  = "Young-ook/spinnaker/aws//modules/frigga"
  version = "3.0.0"
  name    = var.name == null || var.name == "" ? "cognito" : var.name
  petname = var.name == null || var.name == "" ? true : false
}

