### requirements

terraform {
  # Terraform test is an experimental features introduced in Terraform CLI v0.15.0.
  # So, you'll need to upgrade to v0.15.0 or later to use terraform test.
  required_version = ">= 0.15"
}

resource "aws_batch_compute_environment" "default" {

  compute_environment_name = "${local.common_tags.Name}"

  compute_resources {
    instance_role = aws_iam_instance_profile.ecs_instance.arn

    allocation_strategy = "BEST_FIT"

    instance_type = var.instance_types

    ec2_configuration {
      # image_id_override omitted (was an undefaulted variable) -- image_type
      # alone already tells AWS Batch to use its own AWS-managed ECS-optimized
      # AMI, so no override is actually needed here. ECS_AL2 (Amazon Linux 2)
      # is end-of-life and rejected by AWS Batch for new compute environments
      # as of this account's real-AWS test (2026-09-15) -- use the current
      # AL2023-based managed AMI instead.
      image_type = "ECS_AL2023"
    }

    max_vcpus = var.max_cpu
    min_vcpus = 0

    security_group_ids = [
      aws_security_group.batch.id
    ]

    subnets = [
      aws_subnet.private.id
    ]

    type = "EC2"

  }

  type         = "MANAGED"
  state        = "ENABLED"

  # For preventing race condition during deletion. See:
  # https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/batch_compute_environment
  depends_on = [aws_iam_role_policy_attachment.batch_service]
}


resource "aws_batch_job_queue" "default" {
  name     = "${local.common_tags.Name}-queue"
  state    = "ENABLED"
  priority = 1
  compute_environments = [
    aws_batch_compute_environment.default.arn,
  ]
}

# Allow list/read of any bucket
# Allow full access only to result bucket
resource "aws_iam_policy" "ecs_s3_access" {
  name   = "ecs_s3_policy"
  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": [
                "s3:Get*",
                "S3:List*"
            ],
            "Resource": ["*"]
        },
        {
            "Effect": "Allow",
            "Action": [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject",
                "s3:ListBucket"
            ],
            "Resource": [
                "${aws_s3_bucket.results.arn}",
                "${aws_s3_bucket.results.arn}/*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
                "kms:Decrypt",
                "kms:GenerateDataKey"
            ],
            "Resource": ["${aws_kms_key.results_bucket.arn}"]
        }
    ]
}
EOF
}


resource "aws_iam_role" "ecs_instance" {

  name = "${local.common_tags.Name}-ecs-instance-role"

  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
    {
        "Action": "sts:AssumeRole",
        "Effect": "Allow",
        "Principal": {
            "Service": "ec2.amazonaws.com"
        }
    }
    ]
}
EOF
}


resource "aws_iam_role_policy_attachment" "ecs_for_ec2" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}


resource "aws_iam_role_policy_attachment" "ecs_s3_access" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3_access.arn
}


resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.common_tags.Name}-ecs-instance-role"
  role = aws_iam_role.ecs_instance.name
}


