data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block = "192.168.0.0/16"
}


resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  availability_zone = "${data.aws_region.current.name}b"
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  availability_zone = "${data.aws_region.current.name}b"
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 10)
  # Auto-assign-public-IP left off: the only resource in this subnet is the
  # NAT Gateway below, which gets its public address via an explicit EIP
  # association, not the subnet's own default.
}

resource "aws_security_group" "batch" {
  name        = "${local.common_tags.Name}-batch"
  description = "Allow all egress from batch instances"
  vpc_id      = aws_vpc.main.id
}


resource "aws_security_group_rule" "https_egress" {
  description       = "Allow HTTPS egress from batch instances within the VPC"
  security_group_id = aws_security_group.batch.id
  type              = "egress"
  from_port         = 443
  to_port            = 443
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}


resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

# The public subnet has an internet gateway to 
# allow the NAT gateway to go out.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

# traffic FROM instance out to internet is run
# through NAT (which will be placed in the public subnet)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.default.id
  }
}

resource "aws_route_table_association" "public" {
  route_table_id = aws_route_table.public.id
  subnet_id      = aws_subnet.public.id
}

resource "aws_route_table_association" "private" {
  route_table_id = aws_route_table.private.id
  subnet_id      = aws_subnet.private.id
}

resource "aws_nat_gateway" "default" {
  connectivity_type = "public"
  allocation_id     = aws_eip.default.id
  subnet_id         = aws_subnet.public.id

  # To ensure proper ordering, it is recommended to add an explicit dependency
  # on the Internet Gateway for the VPC.
  depends_on = [aws_internet_gateway.main]
}

resource "aws_eip" "default" {
  vpc = true
}

resource "aws_s3_bucket" "results" {
    bucket = "${var.result_bucket}-${data.aws_caller_identity.current.account_id}"
}

resource "aws_kms_key" "results_bucket" {
  description         = "CMK for the Batch results S3 bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.results_bucket.arn
    }
  }
}

variable "ami_id" {
  description = "The AMI ID to use in the AWS Batch compute environment. Should be compatible with ECS. (Unused now that ec2_configuration relies on AWS's own default ECS_AL2 AMI instead of an override; kept declared since Terraform still requires a value for every declared root variable.)"
  type        = string
  default     = "unused"
}

variable "result_bucket" {
  description = "A bucket into which we place results from pipeline tasks."
  type        = string
  default     = "benchmark-batch-results"
}

variable "max_cpu" {
  description = "The maximum number of vCPUs in the Batch environment"
  type        = number
  default     = 4
}

variable "instance_types" {
  description = "The types of instances that are available in the environment. Specific machines can be used to force parallelization in desired ways."
  type        = list(any)
  default     = ["optimal"]
}

data "aws_caller_identity" "current" {}

data "aws_kms_key" "aws_s3" {
  key_id = "alias/aws/s3"
}

resource "aws_iam_user" "this" {
  for_each = var.create_iam_user ? toset(var.iam_username) : []
  name     = each.value
  path     = var.iam_path
}

resource "aws_iam_policy" "bucket_access" {
  name        = "${var.bucket_name}-bucket-read-write-access"
  path        = var.iam_path
  description = "Single bucket access"
  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Sid" : "AllowListBucket",
        "Effect" : "Allow",
        "Action" : [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:ListBucketMultipartUploads",
          "s3:ListBucketVersions",
          "s3:GetBucketObjectLockConfiguration",
          "s3:PutBucketObjectLockConfiguration"
        ],
        "Resource" : aws_s3_bucket.this.arn
      },
      {
        "Sid" : "AllowBucketActions",
        "Effect" : "Allow",
        "Action" : [
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectVersionAcl",
          "s3:PutObjectRetention",
          "s3:RestoreObject"
        ],
        "Resource" : "${aws_s3_bucket.this.arn}/*"
      },
      {
        "Sid" : "AllowListAllMyBuckets",
        "Effect" : "Allow",
        "Action" : "s3:ListAllMyBuckets",
        "Resource" : aws_s3_bucket.this.arn
      },
      {
        "Sid" : "AllowKMSActions",
        "Effect" : "Allow",
        "Action" : [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ],
        "Resource" : var.kms_key_arn != null ? var.kms_key_arn : data.aws_kms_key.aws_s3.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "bucket_access" {
  for_each   = var.create_iam_user ? toset(var.iam_username) : []
  user       = aws_iam_user.this[each.value].name
  policy_arn = aws_iam_policy.bucket_access.arn
}

resource "aws_iam_access_key" "this" {
  for_each = var.create_access_keys ? toset(var.iam_username) : []
  user     = aws_iam_user.this[each.value].name
  pgp_key  = local.pgp_key
}

locals {
  pgp_key     = var.pgp_key_path == null ? var.pgp_key : file(var.pgp_key_path)
  bucket_name = var.bucket_append_account_id == true ? join("-", [var.bucket_name, data.aws_caller_identity.current.account_id]) : var.bucket_name
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = aws_s3_bucket.this.arn
}

output "s3_bucket_name" {
  description = "S3 bucket name"
  value       = aws_s3_bucket.this.bucket
}

output "iam_user_arn" {
  description = "IAM user ARN"
  value       = var.create_iam_user ? values(aws_iam_user.this)[*].arn : null
}

output "iam_user_name" {
  description = "IAM user name"
  value       = var.create_iam_user ? values(aws_iam_user.this)[*].name : null
}

output "access_key_create_date" {
  description = "Date and time in RFC3339 format that IAM user access key was created"
  value       = var.create_access_keys ? values(aws_iam_access_key.this)[*].create_date : null
}

output "access_key_id" {
  description = "IAM user access key id"
  sensitive   = true
  value       = var.create_access_keys ? values(aws_iam_access_key.this)[*].id : null
}

output "secret_access_key" {
  description = "IAM user secret access key"
  sensitive   = true
  value       = var.create_access_keys && local.pgp_key == null ? values(aws_iam_access_key.this)[*].secret : null
}

output "encrypted_secret_access_key" {
  description = "IAM user secret access key (Base64 encoded and PGP encrypted)"
  sensitive   = true
  value       = var.create_access_keys && local.pgp_key != null ? values(aws_iam_access_key.this)[*].encrypted_secret : null
}

output "pgp_key_fingerprint" {
  description = "Fingerprint of the PGP key used to encrypt the secret (not available for imported resources)"
  sensitive   = true
  value       = var.create_access_keys && local.pgp_key != null ? values(aws_iam_access_key.this)[*].key_fingerprint : null
}

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = false
  object_lock_enabled = var.object_lock_enabled
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "this" {
  count         = var.logging.enabled ? 1 : 0
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Sid" : "AllowTLSRequestsOnly",
        "Principal" : "*",
        "Action" : "s3:*",
        "Effect" : "Deny",
        "Resource" : [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ],
        "Condition" : {
          "Bool" : {
            "aws:SecureTransport" : "false"
          },
          "NumericLessThan" : {
            "s3:TlsVersion" : 1.2
          }
        }
      },
      {
        "Sid" : "ObjectLockBoundry",
        "Principal" : "*",
        "Action" : [
          "s3:PutObject",
          "s3:PutObjectRetention"
        ]
        "Effect" : "Deny",
        "Resource" : "${aws_s3_bucket.this.arn}/*",
        "Condition" : {
          "NumericGreaterThan" : {
            "s3:object-lock-remaining-retention-days" : var.max_compliance_lock_days
          },
          "StringEqualsIgnoreCase" : {
            "s3:object-lock-mode" : "COMPLIANCE"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.bucket
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = var.kms_key_arn
      sse_algorithm     = var.sse_algorithm
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled && var.default_lock_days > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = var.default_lock_days
    }
  }
}

variable "bucket_name" {
  description = "S3 bucket name, also used for IAM username and policy name"
  type        = string
  default     = "endpoint-backup"
}

variable "bucket_append_account_id" {
  description = "Append the AWS account ID to the S3 bucket name"
  type        = bool
  default     = true
}

variable "iam_username" {
  description = "IAM username (bucket name used by default)"
  type        = list(string)
  default     = ["endpoint-backup"]
}

variable "iam_path" {
  description = "IAM path identifier"
  type        = string
  default     = "/"
}

variable "transfer_acceleration" {
  description = "S3 transfer acceleration (`Enabled` or `Suspended`)"
  type        = string
  default     = "Suspended"
}

variable "logging" {
  description = "S3 bucket server access logging configuration"
  type = object({
    enabled       = bool
    target_bucket = string
    target_prefix = string
  })
  default = {
    enabled       = false
    target_bucket = null
    target_prefix = null
  }
}

variable "sse_algorithm" {
  description = "S3 server side encryption algorithm (`AES256` or `aws:kms`)"
  type        = string
  default     = "AES256"
}

variable "kms_key_arn" {
  description = "Optionally specify a KMS key ARN when using the `aws:kms` server side encryption algorithm (uses the default AWS managed key `aws/s3` when value is `null`"
  type        = string
  default     = null
}

variable "create_access_keys" {
  description = "Create IAM user access keys"
  type        = bool
  default     = false
}

variable "create_iam_user" {
  description = "Create IAM user"
  type        = bool
  default     = true
}

variable "pgp_key" {
  description = "Base-64 encoded PGP public key or Keybase username (`keybase:username`)"
  type        = string
  default     = null
}

variable "pgp_key_path" {
  description = "Path to a base-64 encoded PGP public key file"
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable S3 object locking (change forces recreation)"
  type        = bool
  default     = false
}

variable "default_lock_days" {
  description = "Default object Lock retention for all new objects when `object_lock_enabled` is set to `true` (`0` disables object locking by default but will still use the lock retention specified by `s3:PutObject` actions)"
  type        = number
  default     = 0
}

variable "max_compliance_lock_days" {
  description = "The maximum number of days an S3 object can be locked in compliance mode (does not apply to governance mode)"
  type        = number
  default     = 90
  validation {
    condition     = var.max_compliance_lock_days <= 1095
    error_message = <<EOF
    This module does not permit setting the S3 object compliance lock boundry to greater than 1095 days. This boundary is based on the use case of the module and the consequences on locking S3 objects in compliance mode. This restriction does not apply to objects locks using governance mode.

    In compliance mode, a protected object version can't be overwritten or deleted by any user, including the root user in your AWS account. When an object is locked in compliance mode, its retention mode can't be changed, and its retention period can't be shortened. Compliance mode helps ensure that an object version can't be overwritten or deleted for the duration of the retention period.

    Consider using Governance mode if you want to protect objects from being deleted by most users during a pre-defined retention period, but at the same time want some users with special permissions to have the flexibility to alter the retention settings or delete the objects.

    https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock.html
    https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock-managing.html
    EOF
  }
}

terraform {
  required_version = ">= 1.2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.43.0, < 6.0.0"
    }
  }
}

resource "aws_cognito_user_pool" "pool" {
  name = "unity-shared-services-user-pool"

  admin_create_user_config {
    invite_message_template {
      email_subject = var.customized_email__invitation_subject
      email_message = var.customized_email_invitation_message
      sms_message = var.customized_sms_text_invitation_message
    }

    allow_admin_create_user_only = true
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }
}

# Cognito user pool ID SSM Param for other resources to modify Cognito user pool
resource "aws_ssm_parameter" "shared_services_cognito_user_pool_id_parameter" {
  name       = format(var.ssm_param_shared_services_cognito_user_pool_id)
  type       = "String"
  value      = aws_cognito_user_pool.pool.id
  overwrite  = true
  depends_on = [aws_cognito_user_pool.pool]
}

# Configurations for unity-uds-distribution Cognito app client
resource "aws_cognito_user_pool_client" "unity-uds-distribution-user-pool-client" {
  name = "unity-uds-distribution-user-pool-client"
  user_pool_id = aws_ssm_parameter.shared_services_cognito_user_pool_id_parameter.value
  generate_secret = true
  callback_urls = var.unity_uds_distribution_callback_urls
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows = ["code"]
  allowed_oauth_scopes = ["email", "openid"]
  explicit_auth_flows = ["ALLOW_CUSTOM_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  supported_identity_providers = ["COGNITO"]
}

# Configurations for localhost-jupyterhub Cognito app client
resource "aws_cognito_user_pool_client" "localhost-jupyterhub-user-pool-client" {
  name = "localhost-jupyterhub-user-pool-client"
  user_pool_id = aws_ssm_parameter.shared_services_cognito_user_pool_id_parameter.value
  generate_secret = true
  callback_urls = var.localhost_jupyterhub_callback_urls
  logout_urls = var.localhost_jupyterhub_logout_urls
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows = ["code"]
  allowed_oauth_scopes = ["email", "openid"]
  explicit_auth_flows = ["ALLOW_CUSTOM_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  supported_identity_providers = ["COGNITO"]
}

# Configurations for unity-app-to-app-client Cognito app client
resource "aws_cognito_user_pool_client" "unity-app-to-app-client-user-pool-client" {
  name = "unity-app-to-app-client-user-pool-client"
  user_pool_id = aws_ssm_parameter.shared_services_cognito_user_pool_id_parameter.value
  generate_secret = true
