  supported_identity_providers = ["COGNITO"]
}

# Configurations for localhost-hysds-ui Cognito app client
resource "aws_cognito_user_pool_client" "localhost-hysds-ui-client-user-pool-client" {
  name = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id = aws_ssm_parameter.shared_services_cognito_user_pool_id_parameter.value
  callback_urls = var.localhost_hysds_ui_client_callback_urls
  logout_urls = var.localhost_hysds_ui_client_logout_urls
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows = ["code"]
  allowed_oauth_scopes = ["email", "openid"]
  explicit_auth_flows = ["ALLOW_CUSTOM_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  supported_identity_providers = ["COGNITO"]
}

# Cognito User Pool Domain
resource "aws_cognito_user_pool_domain" "unity_cognito_user_pool_domain" {
  domain       = var.user_pool_domain
  user_pool_id = aws_cognito_user_pool.pool.id
}

# List of Cognito User Groups
resource "aws_cognito_user_group" "unity-user-group-list" {
  count = length(var.unity_cognito_user_groups)

  name     = var.unity_cognito_user_groups[count.index].name
  user_pool_id = aws_ssm_parameter.shared_services_cognito_user_pool_id_parameter.value
  description = var.unity_cognito_user_groups[count.index].description
}

terraform {
#  backend "s3" {
#    bucket = "unity-cs-tf-state-dev"
#    key    = "project_api_gateway_tf_state"
#    region = "us-west-2"
#  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type        = string
  description = "Region"
  default     = "us-west-2"
}

variable "user_pool_name" {
  type        = string
  description = "Name of the Cognito User Pool"
  default     = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-name"
}

variable "user_pool_domain" {
  type        = string
  description = "Unique domain name for the Unity Shared Services Cognito Pool"
  default     = "unity-shared-services-test"
}

variable "customized_email__invitation_subject" {
  type        = string
  description = "Customized email subject to send the temporary password to users"
  default     = "[Unity Cognito] Your temporary password for Unity Shared Services - Test Cognito user pool"
}

variable "customized_email_invitation_message" {
  type        = string
  description = "Customized email invitation message to send the temporary password to users"
  default     =  "Your username is {username} and temporary password is {####} . You must change this password by accessing a Cognito Hosted UI of an application in this Cognito User Pool. If you are not sure about a Cognito Hosted UI of an application, please contact the Unity CS team to get a URL for a Cognito Hosted UI."
}

variable "customized_sms_text_invitation_message" {
  type        = string
  description = "Customized sms text message to send the temporary password to users"
  default     = "[Unity Cognito] Your username is {username} and temporary password is {####}"
}

variable "ssm_param_shared_services_cognito_user_pool_id" {
  type        = string
  description = "SSM Param for Shared Services Cognito User Pool ID"
  default     = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
}

variable "unity_uds_distribution_callback_urls" {
  type        = list(string)
  description = "Unity UDS Distribution - List of Callback Urls"
  default     = ["https://unity-shared-services-api-gatway-id.execute-api.us-west-2.amazonaws.com:9000/dev/"]
}

variable "uads_jupyter-development_client_callback_urls" {
  type        = list(string)
  description = "Jupyterhub - List of Callback Urls"
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "uads_jupyter-development_client_logout_urls" {
  type        = list(string)
  description = "Jupyterhub - List of Logout Urls"
  default     = ["http://localhost:8000/hub/oauth_callback/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  type        = list(string)
  description = "Localhost Jupyterhub - List of Callback Urls"
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  type        = list(string)
  description = "Localhost Jupyterhub - List of Logout Urls"
  default     = ["http://localhost:8000/hub/oauth_callback/logout"]
}

variable "hysds_ui_client_callback_urls" {
  type        = list(string)
  description = "HySDS UI Client - List of Callback Urls"
  default     = ["https://unity-shared-services-api-gatway-id.execute-api.us-west-2.amazonaws.com/dev/hysds-ui/"]
}

variable "hysds_ui_client_logout_urls" {
  type        = list(string)
  description = "HySDS UI Client - List of Logout Urls"
  default     = ["https://unity-shared-services-api-gatway-id.execute-api.us-west-2.amazonaws.com/dev/hysds-ui/logout"]
}

variable "localhost_hysds_ui_client_callback_urls" {
  type        = list(string)
  description = "Local HySDS UI Client - List of Callback Urls"
  default     = ["http://localhost:8080"]
}

variable "localhost_hysds_ui_client_logout_urls" {
  type        = list(string)
  description = "Local HySDS UI Client - List of Logout Urls"
  default     = ["http://localhost:8080/logout"]
}

variable "unity_cognito_user_groups" {
  description = "List of Unity Cognito User Groups"
  type = list(object({
    name          = string
    description   = string
  }))
  default = [
    {
      name = "Unity_Admin"
      description = "Unity_Admin Cognito User Group"
    },
    {
      name = "Unity_Viewer"
      description = "Unity_Viewer Cognito User Group"
    }
  ]
}

/*
 * Create VPC using app name and env to name it
 */
resource "aws_vpc" "vpc" {
  cidr_block                       = var.vpc_cidr_block
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = {
    Name     = "vpc-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

/*
 * Get default security group for reference later
 */
data "aws_security_group" "vpc_default_sg" {
  name   = "default"
  vpc_id = aws_vpc.vpc.id
}

/*
 * Create public and private subnets for each availability zone
 */

locals {
  ipv6_cidr_block = aws_vpc.vpc.ipv6_cidr_block
  public_subnets  = var.enable_ipv6 ? cidrsubnets(cidrsubnet(local.ipv6_cidr_block, 4, 0), 4, 4, 4, 4, 4, 4, 4, 4) : []
  private_subnets = var.enable_ipv6 ? cidrsubnets(cidrsubnet(local.ipv6_cidr_block, 4, 1), 4, 4, 4, 4, 4, 4, 4, 4) : []
}

resource "aws_subnet" "public_subnet" {
  count             = length(var.aws_zones)
  vpc_id            = aws_vpc.vpc.id
  availability_zone = element(var.aws_zones, count.index)
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  ipv6_cidr_block   = var.enable_ipv6 ? element(local.public_subnets, count.index) : null

  tags = {
    Name     = "public-${element(var.aws_zones, count.index)}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

resource "aws_subnet" "private_subnet" {
  count             = length(var.aws_zones)
  vpc_id            = aws_vpc.vpc.id
  availability_zone = element(var.aws_zones, count.index)
  cidr_block        = element(var.private_subnet_cidr_blocks, count.index)
  ipv6_cidr_block   = var.enable_ipv6 ? element(local.private_subnets, count.index) : null

  tags = {
    Name     = "private-${element(var.aws_zones, count.index)}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}


/*
 * Create internet gateway(s) for VPC
 */
resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name     = "IGW-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

resource "aws_egress_only_internet_gateway" "ipv6" {
  count = var.enable_ipv6 ? 1 : 0

  vpc_id = aws_vpc.vpc.id

  tags = {
    Name     = "egress-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

resource "aws_route" "private_ipv6" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.private_route_table.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = one(aws_egress_only_internet_gateway.ipv6[*].id)
}


/*
 * Create NAT gateway and allocate Elastic IP for it
 */
resource "aws_eip" "gateway_eip" {
  tags = {
    Name     = "EIP-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
  vpc = true
}

resource "aws_nat_gateway" "nat_gateway" {
  count = var.create_nat_gateway ? 1 : 0

  allocation_id = aws_eip.gateway_eip.id
  subnet_id     = aws_subnet.public_subnet[0].id
  depends_on    = [aws_internet_gateway.internet_gateway]

  tags = {
    Name     = "NAT-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

/*
 * Set use_transit_gateway to true create transit gateway attachments in the private subnets and
 * route traffic to the TGW instead of NAT GW.
 * Should be used when create_nat_gateway=false.
 */
resource "aws_ec2_transit_gateway_vpc_attachment" "transit_gateway" {
  count = var.use_transit_gateway ? 1 : 0

  subnet_ids                                      = aws_subnet.private_subnet.*.id
  transit_gateway_id                              = var.transit_gateway_id
  vpc_id                                          = aws_vpc.vpc.id
  transit_gateway_default_route_table_association = var.transit_gateway_default_route_table_association
  transit_gateway_default_route_table_propagation = var.transit_gateway_default_route_table_propagation

  tags = {
    Name     = "TGW-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

/*
 * Routes for private subnets to use NAT or Transit gateway
 */
resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name     = "RT-private-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

/*
 * Refactoring information to note that we renamed aws_route_table.nat_route_table to aws_route_table.private_route_table
 * This prevents the resource from being destroyed and recreated. Should be kept at least until the next major revision
 * but probably should remain permanently.
 */
moved {
  from = aws_route_table.nat_route_table
  to   = aws_route_table.private_route_table
}

resource "aws_route" "nat_route" {
  count = var.create_nat_gateway ? 1 : 0

  route_table_id         = aws_route_table.private_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = one(aws_nat_gateway.nat_gateway[*].id)
}

resource "aws_route" "transit_gateway" {
  count = var.use_transit_gateway ? 1 : 0

  route_table_id         = aws_route_table.private_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  transit_gateway_id     = var.transit_gateway_id
}

resource "aws_route_table_association" "private_route" {
  count          = length(var.aws_zones)
  subnet_id      = element(aws_subnet.private_subnet.*.id, count.index)
  route_table_id = aws_route_table.private_route_table.id
}

/*
 * Routes for public subnets to use internet gateway
 */
resource "aws_route_table" "igw_route_table" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name     = "RT-public-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

resource "aws_route" "igw_route" {
  route_table_id         = aws_route_table.igw_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}

resource "aws_route" "public_ipv6" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.igw_route_table.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.internet_gateway.id
}

resource "aws_route_table_association" "public_route" {
  count          = length(var.aws_zones)
  subnet_id      = element(aws_subnet.public_subnet.*.id, count.index)
  route_table_id = aws_route_table.igw_route_table.id
}

/*
 * Create DB Subnet Group for private subnets
 */
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-${var.app_name}-${var.app_env}"
  subnet_ids = aws_subnet.private_subnet.*.id

  tags = {
    Name     = "db-subnet-${var.app_name}-${var.app_env}"
    app_name = var.app_name
    app_env  = var.app_env
  }
}

output "id" {
  value = aws_vpc.vpc.id
}

output "ipv6_association_id" {
  value = aws_vpc.vpc.ipv6_association_id
}

output "ipv6_cidr_block" {
  value = aws_vpc.vpc.ipv6_cidr_block
}

output "vpc_default_sg_id" {
  value = data.aws_security_group.vpc_default_sg.id
}

output "public_subnet_ids" {
  value = aws_subnet.public_subnet.*.id
}

output "public_subnet_cidr_blocks" {
  value = aws_subnet.public_subnet.*.cidr_block
}

output "private_subnet_ids" {
  value = aws_subnet.private_subnet.*.id
}

output "private_subnet_cidr_blocks" {
  value = aws_subnet.private_subnet.*.cidr_block
}

output "db_subnet_group_name" {
  value = aws_db_subnet_group.db_subnet_group.name
}

output "aws_zones" {
  value = var.aws_zones
}

output "nat_gateway_ip" {
  value = one(aws_nat_gateway.nat_gateway[*].public_ip)
}

/*
 * Required variables
 */
variable "app_name" {
  type    = string
  default = "terraform"
}

variable "app_env" {
  type    = string
  default = "testing"
}

variable "aws_zones" {
  description = "A list of zones to create subnets (max 8)"
  type        = list(string)

  default = [
    "us-east-1c",
    "us-east-1d",
    "us-east-1e",
  ]
}

variable "enable_dns_hostnames" {
  type    = bool
  default = false
}

variable "create_nat_gateway" {
  description = "Set to false to remove NAT gateway and associated route"
  type        = bool
  default     = true
}

variable "use_transit_gateway" {
  description = "Set to true to create transit gateway attachments and route traffic to a TGW."
  type        = bool
  default     = false
}

variable "private_subnet_cidr_blocks" {
  description = "The CIDR blocks for the private subnets (one per AZ, in order). There must be at least as many private CIDRs as AZs, and they must not overlap the public CIDRs."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24", "10.0.44.0/24"]
}

variable "public_subnet_cidr_blocks" {
  description = "The CIDR blocks for the public subnets (one per AZ, in order). There must be at least as many public CIDRs as AZs, and they must not overlap the private CIDRs."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24", "10.0.40.0/24"]
}

variable "transit_gateway_id" {
  description = "The id of the transit gateway to attach to. Used in conjuction with use_transit_gateway."
  type        = string
  default     = ""
}

variable "transit_gateway_default_route_table_association" {
  description = "Whether or not to associate with the default route table of the transit gateway."
  type        = bool
  default     = true
}

variable "transit_gateway_default_route_table_propagation" {
  description = "Whether or not to send propagation of this route to the default route table of the transit gateway."
  type        = bool
  default     = true
}

variable "vpc_cidr_block" {
  description = "The block of IP addresses (as a CIDR) the VPC should use"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_ipv6" {
  description = "Add an IPv6 CIDR block to the VPC and IPv6 CIDR blocks to the public and private subnets"
  type        = bool
  default     = false
}

terraform {
  required_version = ">= 0.12"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0, < 5.0.0"
    }
  }
}

data "aws_region" "current" {}

locals {

  context_prefix = "gitops-bridge"

  gitops_workload_repo_name = var.gitops_workload_repo_name
  gitops_workload_org       = "ssh://${aws_iam_user_ssh_key.gitops.id}@git-codecommit.${data.aws_region.current.id}.amazonaws.com"
  gitops_workload_repo      = "v1/repos/${local.gitops_workload_repo_name}"

  gitops_platform_repo_name = var.gitops_platform_repo_name
  gitops_platform_org       = "ssh://${aws_iam_user_ssh_key.gitops.id}@git-codecommit.${data.aws_region.current.id}.amazonaws.com"
  gitops_platform_repo      = "v1/repos/${local.gitops_platform_repo_name}"

  gitops_addons_repo_name = var.gitops_addons_repo_name
  gitops_addons_org       = "ssh://${aws_iam_user_ssh_key.gitops.id}@git-codecommit.${data.aws_region.current.id}.amazonaws.com"
  gitops_addons_repo      = "v1/repos/${local.gitops_addons_repo_name}"

  ssh_key_basepath           = var.ssh_key_basepath
  git_private_ssh_key        = "${local.ssh_key_basepath}/gitops_ssh.pem"
  git_private_ssh_key_config = "${local.ssh_key_basepath}/config"
  ssh_host                   = "git-codecommit.*.amazonaws.com"
  ssh_config                 = <<-EOF
  # AWS Workshop https://github.com/aws-samples/argocd-on-amazon-eks-workshop.git
  Host ${local.ssh_host}
    User ${aws_iam_user.gitops.unique_id}
    IdentityFile ${local.git_private_ssh_key}
  EOF

}

resource "aws_codecommit_repository" "workloads" {
  repository_name = local.gitops_workload_repo_name
  description     = "CodeCommit repository for ArgoCD workloads"
}

resource "aws_codecommit_repository" "platform" {
  repository_name = local.gitops_platform_repo_name
  description     = "CodeCommit repository for ArgoCD platform"
}

resource "aws_codecommit_repository" "addons" {
  repository_name = local.gitops_addons_repo_name
  description     = "CodeCommit repository for ArgoCD addons"
}

resource "aws_iam_user" "gitops" {
  name = "${local.context_prefix}-gitops"
  path = "/"
}

resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops.public_key_openssh
}

resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "random_string" "secret_suffix" {
  length  = 5     # Length of the random string
  special = false # Set to true if you want to include special characters
  upper   = true  # Set to true if you want uppercase letters in the string
  lower   = true  # Set to true if you want lowercase letters in the string
  number  = true  # Set to true if you want numbers in the string
}
resource "aws_secretsmanager_secret" "codecommit_key" {
  name = "codecommit-key-${random_string.secret_suffix.result}"
}

resource "aws_secretsmanager_secret_version" "private_key_secret_version" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops.private_key_pem
}

resource "local_file" "ssh_private_key" {
  content         = tls_private_key.gitops.private_key_pem
  filename        = pathexpand(local.git_private_ssh_key)
  file_permission = "0600"
}

resource "local_file" "ssh_config" {
  count           = local.ssh_key_basepath == "/home/ec2-user/.ssh" ? 1 : 0
  content         = local.ssh_config
  filename        = pathexpand(local.git_private_ssh_key_config)
  file_permission = "0600"
}

resource "null_resource" "append_string_block" {
  count = local.ssh_key_basepath == "/home/ec2-user/.ssh" ? 0 : 1
  triggers = {
    always_run = "${timestamp()}"
    file       = pathexpand(local.git_private_ssh_key_config)
  }

  provisioner "local-exec" {
    when    = create
    command = <<-EOL
      start_marker="### START BLOCK AWS Workshop ###"
      end_marker="### END BLOCK AWS Workshop ###"
      block="$start_marker\n${local.ssh_config}\n$end_marker"
      file="${self.triggers.file}"

      if ! grep -q "$start_marker" "$file"; then
        echo "$block" >> "$file"
      fi
    EOL
  }

  provisioner "local-exec" {
    when    = destroy
    command = <<-EOL
      start_marker="### START BLOCK AWS Workshop ###"
      end_marker="### END BLOCK AWS Workshop ###"
      file="${self.triggers.file}"

      if grep -q "$start_marker" "$file"; then
        sed -i '' "/$start_marker/,/$end_marker/d" "$file"
      fi
    EOL

  }
}


data "aws_iam_policy_document" "gitops_access" {
  statement {
    sid = ""
    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush"
    ]
    effect = "Allow"
    resources = [
      aws_codecommit_repository.workloads.arn,
      aws_codecommit_repository.platform.arn,
      aws_codecommit_repository.addons.arn
    ]
  }
}

resource "aws_iam_policy" "gitops_access" {
  name   = "${local.context_prefix}-gitops"
  path   = "/"
  policy = data.aws_iam_policy_document.gitops_access.json
}

resource "aws_iam_user_policy_attachment" "gitops_access" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.gitops_access.arn
}

output "configure_argocd" {
  value = "argocd repo add ${local.gitops_workload_org}/${local.gitops_workload_repo} --ssh-private-key-path $${HOME}/.ssh/gitops_ssh.pem --insecure-ignore-host-key --upsert --name git-repo"
}
output "git_clone" {
  value = "git clone ${local.gitops_workload_org}/${local.gitops_workload_repo}"
}
output "ssh_config" {
  value = local.ssh_config
}
output "ssh_host" {
  value = local.ssh_host
}

output "git_private_ssh_key" {
  value = local.git_private_ssh_key
}

output "gitops_addons_url" {
  value = "${local.gitops_addons_org}/${local.gitops_addons_repo}"
}
output "gitops_addons_org" {
  description = "Git repository org/user contains for addons"
  value       = local.gitops_addons_org
}
output "gitops_addons_repo" {
  description = "Git repository contains for addons"
  value       = local.gitops_addons_repo
}
output "gitops_addons_basepath" {
  description = "Git repository base path for addons"
  value       = var.gitops_addons_basepath
}
output "gitops_addons_path" {
  description = "Git repository path for addons"
  value       = var.gitops_addons_path
}
output "gitops_addons_revision" {
  description = "Git repository revision/branch/ref for addons"
  value       = var.gitops_addons_revision
}

output "gitops_platform_url" {
  value = "${local.gitops_platform_org}/${local.gitops_platform_repo}"
}
output "gitops_platform_org" {
  description = "Git repository org/user contains for platform"
  value       = local.gitops_platform_org
}
output "gitops_platform_repo" {
  description = "Git repository contains for platform"
  value       = local.gitops_workload_repo
}
output "gitops_platform_basepath" {
  description = "Git repository base path for platform"
  value       = var.gitops_platform_basepath
}
output "gitops_platform_path" {
  description = "Git repository path for platform"
  value       = var.gitops_platform_path
}
output "gitops_platform_revision" {
  description = "Git repository revision/branch/ref for platform"
  value       = var.gitops_platform_revision
}

output "gitops_workload_url" {
  value = "${local.gitops_workload_org}/${local.gitops_workload_repo}"
}
output "gitops_workload_org" {
  description = "Git repository org/user contains for workload"
  value       = local.gitops_workload_org
}
output "gitops_workload_repo" {
  description = "Git repository contains for workload"
  value       = local.gitops_workload_repo
}
output "gitops_workload_basepath" {
  description = "Git repository base path for workload"
  value       = var.gitops_workload_basepath
}
output "gitops_workload_path" {
  description = "Git repository path for workload"
  value       = var.gitops_workload_path
}
output "gitops_workload_revision" {
  description = "Git repository revision/branch/ref for workload"
  value         = var.gitops_workload_revision
}
output "codecommit_key_id" {
  description = "Secret name that holds the SSH key for accessing CodeCommit"
  value       = aws_secretsmanager_secret.codecommit_key.id
}
output "codecommit_key_name" {
  description = "Secret name that holds the SSH key for accessing CodeCommit"
  value       = aws_secretsmanager_secret.codecommit_key.name
}

variable "ssh_key_basepath" {
  description = "path to .ssh directory"
  type        = string
  # For AWS EC2 override with
  # export TF_VAR_ssh_key_basepath="/home/ec2-user/.ssh"
  default = "~/.ssh"
}

variable "gitops_addons_basepath" {
  description = "Git repository base path for addons"
  default     = ""
}
variable "gitops_addons_path" {
  description = "Git repository path for addons"
  default     = "bootstrap"
}
variable "gitops_addons_revision" {
  description = "Git repository revision/branch/ref for addons"
  default     = "HEAD"
}
variable "gitops_addons_repo_name" {
  description = "Git repository name for addons"
  default     = "gitops-addons"
}

variable "gitops_platform_basepath" {
  description = "Git repository base path for platform"
  default     = ""
}
variable "gitops_platform_path" {
  description = "Git repository path for workload"
  default     = "bootstrap"
}
variable "gitops_platform_revision" {
  description = "Git repository revision/branch/ref for workload"
  default     = "HEAD"
}
variable "gitops_platform_repo_name" {
  description = "Git repository name for platform"
  default     = "gitops-platform"
}

variable "gitops_workload_basepath" {
  description = "Git repository base path for workload"
  default     = ""
}
variable "gitops_workload_path" {
  description = "Git repository path for workload"
  default     = ""
}
variable "gitops_workload_revision" {
  description = "Git repository revision/branch/ref for workload"
  default     = "HEAD"
}
variable "gitops_workload_repo_name" {
  description = "Git repository name for workload"
  default     = "gitops-apps"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.67.0"
    }
  }

  # ##  Used for end-to-end testing on project; update to suit your needs
  # backend "s3" {
  #   bucket = "terraform-state-duektsah"
  #   region = "eu-west-1"
  #   key    = "argocd-on-amazon-eks-workshop/codecommit"
  # }
}

# Restart dead or hung instance

resource "null_resource" "check_alarm_action" {
  count = local.instance_count

  triggers = {
    action = "arn:${data.aws_partition.default.partition}:swf:${local.region}:${data.aws_caller_identity.default.account_id}:${var.default_alarm_action}"
  }
}

resource "aws_cloudwatch_metric_alarm" "default" {
  count               = local.instance_count
  alarm_name          = module.label.id
  comparison_operator = var.comparison_operator
  evaluation_periods  = var.evaluation_periods
  metric_name         = var.metric_name
  namespace           = var.metric_namespace
  period              = var.applying_period
  statistic           = var.statistic_level
  threshold           = var.metric_threshold
  depends_on          = [null_resource.check_alarm_action]

  dimensions = {
    InstanceId = join("", aws_instance.default.*.id)
  }

  alarm_actions = [
    null_resource.check_alarm_action[count.index].triggers.action
  ]
}

locals {
  additional_ips_count = var.associate_public_ip_address && var.instance_enabled && var.additional_ips_count > 0 ? var.additional_ips_count : 0
}

resource "aws_network_interface" "additional" {
  count     = local.additional_ips_count
  subnet_id = local.effective_subnet_id

  security_groups = compact(
    concat(
      [
        var.create_default_security_group ? join("", aws_security_group.default.*.id) : ""
      ],
      var.security_groups
    )
  )

  tags = module.label.tags
}

resource "aws_network_interface_attachment" "additional" {
  count                = local.additional_ips_count
  instance_id          = join("", aws_instance.default.*.id)
  network_interface_id = aws_network_interface.additional[count.index].id
  device_index         = 1 + count.index
}

resource "aws_eip" "additional" {
  count             = local.additional_ips_count
  domain            = "vpc"
  network_interface = aws_network_interface.additional[count.index].id
}

locals {
  instance_count       = var.instance_enabled ? 1 : 0
  security_group_count = var.create_default_security_group ? 1 : 0
  region               = var.region != "" ? var.region : data.aws_region.default.name
  root_iops            = var.root_volume_type == "io1" ? var.root_iops : "0"
  ebs_iops             = var.ebs_volume_type == "io1" ? var.ebs_iops : "0"
  availability_zone    = var.availability_zone != "" ? var.availability_zone : data.aws_subnet.default.availability_zone
  ami                  = var.ami != "" ? var.ami : join("", data.aws_ami.default.*.image_id)
  ami_owner            = var.ami != "" ? var.ami_owner : join("", data.aws_ami.default.*.owner_id)
  root_volume_type     = var.root_volume_type != "" ? var.root_volume_type : data.aws_ami.info.root_device_type
  public_dns           = var.associate_public_ip_address && var.assign_eip_address && var.instance_enabled ? data.null_data_source.eip.outputs["public_dns"] : join("", aws_instance.default.*.public_dns)
}

data "aws_caller_identity" "default" {
}

data "aws_region" "default" {
}

data "aws_partition" "default" {
}

data "aws_subnet" "default" {
  id = local.effective_subnet_id
}

data "aws_iam_policy_document" "default" {
  statement {
    sid = ""

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    effect = "Allow"
  }
}

data "aws_ami" "default" {
  count       = var.ami == "" ? 1 : 0
  most_recent = "true"

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["099720109477"]
}

data "aws_ami" "info" {
  filter {
    name   = "image-id"
    values = [local.ami]
  }

  owners = [local.ami_owner]
}

module "label" {
  source      = "git::https://github.com/cloudposse/terraform-null-label.git?ref=tags/0.25.0"
  namespace   = var.namespace
  stage       = var.stage
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  enabled     = var.instance_enabled
  tags        = var.tags
}

resource "aws_iam_instance_profile" "default" {
  count = local.instance_count
  name  = module.label.id
  role  = join("", aws_iam_role.default.*.name)
}

resource "aws_iam_role" "default" {
  count                = local.instance_count
  name                 = module.label.id
  path                 = "/"
  assume_role_policy   = data.aws_iam_policy_document.default.json
  permissions_boundary = var.permissions_boundary_arn
}

resource "aws_instance" "default" {
  depends_on                  = [aws_key_pair.benchmark]
  count                       = local.instance_count
  ami                         = local.ami
  availability_zone           = local.availability_zone
  instance_type               = var.instance_type
  ebs_optimized               = var.ebs_optimized
  disable_api_termination     = var.disable_api_termination
  user_data                   = var.user_data
  iam_instance_profile        = join("", aws_iam_instance_profile.default.*.name)
  associate_public_ip_address = var.associate_public_ip_address
  key_name                    = var.ssh_key_pair
  subnet_id                   = local.effective_subnet_id
  monitoring                  = var.monitoring
  private_ip                  = var.private_ip != "" ? var.private_ip : null
  source_dest_check           = var.source_dest_check
  ipv6_address_count          = var.ipv6_address_count < 0 ? null : var.ipv6_address_count
  ipv6_addresses              = length(var.ipv6_addresses) == 0 ? null : var.ipv6_addresses

  vpc_security_group_ids = compact(
    concat(
      [
        var.create_default_security_group ? join("", aws_security_group.default.*.id) : "",
      ],
      var.security_groups
    )
  )

  root_block_device {
    volume_type           = local.root_volume_type
    volume_size           = var.root_volume_size
    iops                  = local.root_iops
    delete_on_termination = var.delete_on_termination
    encrypted             = true
  }

  metadata_options {
    http_tokens = "required"
  }

  tags = module.label.tags
}

resource "aws_eip" "default" {
  count             = var.associate_public_ip_address && var.assign_eip_address && var.instance_enabled ? 1 : 0
  network_interface = join("", aws_instance.default.*.primary_network_interface_id)
  domain            = "vpc"
  tags              = module.label.tags
}

data "null_data_source" "eip" {
  inputs = {
    public_dns = "ec2-${replace(join("", aws_eip.default.*.public_ip), ".", "-")}.${local.region == "us-east-1" ? "compute-1" : "${local.region}.compute"}.amazonaws.com"
  }
}

resource "aws_ebs_volume" "default" {
  count             = var.ebs_volume_count
  availability_zone = local.availability_zone
  size              = var.ebs_volume_size
  iops              = local.ebs_iops
  type              = var.ebs_volume_type
  tags              = module.label.tags
}

resource "aws_volume_attachment" "default" {
  count       = var.ebs_volume_count
  device_name = var.ebs_device_name[count.index]
  volume_id   = aws_ebs_volume.default.*.id[count.index]
  instance_id = join("", aws_instance.default.*.id)
}

output "public_ip" {
  description = "Public IP of instance (or EIP)"
  value       = concat(aws_eip.default.*.public_ip, aws_instance.default.*.public_ip, [""])[0]
}

output "private_ip" {
  description = "Private IP of instance"
  value       = join("", aws_instance.default.*.private_ip)
}

output "private_dns" {
  description = "Private DNS of instance"
  value       = join("", aws_instance.default.*.private_dns)
}

output "public_dns" {
  description = "Public DNS of instance (or DNS of EIP)"
  value       = local.public_dns
}

output "id" {
  description = "Disambiguated ID of the instance"
  value       = join("", aws_instance.default.*.id)
}

output "name" {
  description = "Instance name"
  value       = module.label.id
}

output "ssh_key_pair" {
  description = "Name of the SSH key pair provisioned on the instance"
  value       = var.ssh_key_pair
}

output "security_group_ids" {
  description = "IDs on the AWS Security Groups associated with the instance"
  value = compact(
    concat(
      [var.create_default_security_group == true ? join("", aws_security_group.default.*.id) : ""],
      var.security_groups
    )
  )
}

output "role" {
  description = "Name of AWS IAM Role associated with the instance"
  value       = join("", aws_iam_role.default.*.name)
}

output "alarm" {
  description = "CloudWatch Alarm ID"
  value       = join("", aws_cloudwatch_metric_alarm.default.*.id)
}

output "additional_eni_ids" {
  description = "Map of ENI to EIP"
  value = zipmap(
    aws_network_interface.additional.*.id,
    aws_eip.additional.*.public_ip
  )
}

output "ebs_ids" {
  description = "IDs of EBSs"
  value       = aws_ebs_volume.default.*.id
}

output "primary_network_interface_id" {
  description = "ID of the instance's primary network interface"
  value       = join("", aws_instance.default.*.primary_network_interface_id)
}

resource "aws_security_group" "default" {
  count       = local.security_group_count
  name        = module.label.id
  vpc_id      = local.effective_vpc_id
  description = "Instance default security group (only egress access is allowed)"
  tags        = module.label.tags

  lifecycle {
    create_before_destroy = true
  }
}

data "aws_vpc" "effective" {
  id = local.effective_vpc_id
}

resource "aws_security_group_rule" "egress" {
  count             = var.create_default_security_group ? 1 : 0
  type              = "egress"
  from_port         = 0
  to_port           = 65535
  protocol          = "-1"
  cidr_blocks       = [data.aws_vpc.effective.cidr_block]
  security_group_id = aws_security_group.default[0].id
}

resource "aws_security_group_rule" "ingress" {
  count             = var.create_default_security_group ? length(compact(var.allowed_ports)) : 0
  type              = "ingress"
  from_port         = var.allowed_ports[count.index]
  to_port           = var.allowed_ports[count.index]
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.default[0].id
}

variable "ssh_key_pair" {
  type        = string
  description = "SSH key pair to be provisioned on the instance"
  default     = "benchmark-d8bc612be4e0-key"
}

variable "associate_public_ip_address" {
  type        = bool
  description = "Associate a public IP address with the instance"
  default     = true
}

variable "assign_eip_address" {
  type        = bool
  description = "Assign an Elastic IP address to the instance"
  default     = true
}

variable "user_data" {
  type        = string
  description = "Instance user data. Do not pass gzip-compressed data via this argument"
  default     = ""
}

variable "instance_type" {
  type        = string
  description = "The type of the instance"
  default     = "t2.micro"
}

variable "vpc_id" {
  type        = string
  description = "The ID of the VPC that the instance security group belongs to"
  default     = ""
}

variable "security_groups" {
  description = "List of Security Group IDs allowed to connect to the instance"
  type        = list(string)
  default     = []
}

variable "allowed_ports" {
  type        = list(number)
  description = "List of allowed ingress ports"
  default     = []
}

variable "subnet" {
  type        = string
  description = "VPC Subnet ID the instance is launched in"
  default     = ""
}

variable "namespace" {
  type        = string
  description = "Namespace (e.g. `cp` or `cloudposse`)"
  default     = ""
}

variable "stage" {
  type        = string
  description = "Stage (e.g. `prod`, `dev`, `staging`"
  default     = ""
}

variable "environment" {
  type        = string
  description = "Environment, e.g. 'prod', 'staging', 'dev', 'pre-prod', 'UAT'"
  default     = ""
}

variable "name" {
  type        = string
  description = "Name  (e.g. `bastion` or `db`)"
  default     = "benchmark-instance"
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter to be used between `name`, `namespace`, `stage`, etc."
}

variable "attributes" {
  description = "Additional attributes (e.g. `1`)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "region" {
  type        = string
  description = "AWS Region the instance is launched in"
  default     = ""
}

variable "availability_zone" {
  type        = string
  description = "Availability Zone the instance is launched in. If not set, will be launched in the first AZ of the region"
  default     = ""
}

variable "ami" {
  type        = string
  description = "The AMI to use for the instance. By default it is the AMI provided by Amazon with Ubuntu 16.04"
  default     = ""
}

variable "ami_owner" {
  type        = string
  description = "Owner of the given AMI (ignored if `ami` unset)"
  default     = ""
}

variable "ebs_optimized" {
  type        = bool
  description = "Launched EC2 instance will be EBS-optimized"
  default     = false
}

variable "disable_api_termination" {
  type        = bool
  description = "Enable EC2 Instance Termination Protection"
  default     = false
}

variable "monitoring" {
  type        = bool
  description = "Launched EC2 instance will have detailed monitoring enabled"
  default     = true
}

variable "private_ip" {
  type        = string
  description = "Private IP address to associate with the instance in the VPC"
  default     = ""
}

variable "source_dest_check" {
  type        = bool
  description = "Controls if traffic is routed to the instance when the destination address does not match the instance. Used for NAT or VPNs"
  default     = true
}

variable "ipv6_address_count" {
  type        = number
  description = "Number of IPv6 addresses to associate with the primary network interface. Amazon EC2 chooses the IPv6 addresses from the range of your subnet (-1 to use subnet default)"
  default     = 0
}

variable "ipv6_addresses" {
  type        = list(string)
  description = "List of IPv6 addresses from the range of the subnet to associate with the primary network interface"
  default     = []
}

variable "root_volume_type" {
  type        = string
  description = "Type of root volume. Can be standard, gp2 or io1"
  default     = "gp2"
}

variable "root_volume_size" {
  type        = number
  description = "Size of the root volume in gigabytes"
  default     = 10
}

variable "root_iops" {
  type        = number
  description = "Amount of provisioned IOPS. This must be set if root_volume_type is set to `io1`"
  default     = 0
}

variable "ebs_device_name" {
  type        = list(string)
  description = "Name of the EBS device to mount"
  default     = ["/dev/xvdb", "/dev/xvdc", "/dev/xvdd", "/dev/xvde", "/dev/xvdf", "/dev/xvdg", "/dev/xvdh", "/dev/xvdi", "/dev/xvdj", "/dev/xvdk", "/dev/xvdl", "/dev/xvdm", "/dev/xvdn", "/dev/xvdo", "/dev/xvdp", "/dev/xvdq", "/dev/xvdr", "/dev/xvds", "/dev/xvdt", "/dev/xvdu", "/dev/xvdv", "/dev/xvdw", "/dev/xvdx", "/dev/xvdy", "/dev/xvdz"]
}

variable "ebs_volume_type" {
  type        = string
  description = "The type of EBS volume. Can be standard, gp2 or io1"
  default     = "gp2"
}

variable "ebs_volume_size" {
  type        = number
  description = "Size of the EBS volume in gigabytes"
  default     = 10
}

variable "ebs_iops" {
  type        = number
  description = "Amount of provisioned IOPS. This must be set with a volume_type of io1"
  default     = 0
}

variable "ebs_volume_count" {
  type        = number
  description = "Count of EBS volumes that will be attached to the instance"
  default     = 0
}

variable "delete_on_termination" {
  type        = bool
  description = "Whether the volume should be destroyed on instance termination"
  default     = true
}

variable "welcome_message" {
  type        = string
  default     = ""
  description = "Welcome message"
}

variable "comparison_operator" {
  type        = string
  description = "The arithmetic operation to use when comparing the specified Statistic and Threshold. Possible values are: GreaterThanOrEqualToThreshold, GreaterThanThreshold, LessThanThreshold, LessThanOrEqualToThreshold."
  default     = "GreaterThanOrEqualToThreshold"
}

variable "metric_name" {
  type        = string
  description = "The name for the alarm's associated metric. Allowed values can be found in https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/ec2-metricscollected.html"
  default     = "StatusCheckFailed_Instance"
}

variable "evaluation_periods" {
  type        = number
  description = "The number of periods over which data is compared to the specified threshold."
  default     = 5
}

variable "metric_namespace" {
  type        = string
  description = "The namespace for the alarm's associated metric. Allowed values can be found in https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/aws-namespaces.html"
  default     = "AWS/EC2"
}

variable "applying_period" {
  type        = number
  description = "The period in seconds over which the specified statistic is applied"
  default     = 60
}

variable "statistic_level" {
  type        = string
  description = "The statistic to apply to the alarm's associated metric. Allowed values are: SampleCount, Average, Sum, Minimum, Maximum"
  default     = "Maximum"
}

variable "metric_threshold" {
  type        = number
  description = "The value against which the specified statistic is compared"
  default     = 1
}

variable "default_alarm_action" {
  type        = string
  default     = "action/actions/AWS_EC2.InstanceId.Reboot/1.0"
  description = "Default alerm action"
}

variable "create_default_security_group" {
  type        = bool
  description = "Create default Security Group with only Egress traffic allowed"
  default     = true
}

variable "instance_enabled" {
  type        = bool
  description = "Flag to control the instance creation. Set to false if it is necessary to skip instance creation"
  default     = true
}

variable "additional_ips_count" {
  type        = number
  description = "Count of additional EIPs"
  default     = 0
}

variable "permissions_boundary_arn" {
  type        = string
  description = "Policy ARN to attach to instance role as a permissions boundary"
  default     = ""
}

terraform {
  required_version = ">= 0.12"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 2.0"
    }
  }
}

# Self-contained VPC/subnet fallback: var.vpc_id/var.subnet had no default in
# the original template (a genuine existing-infra reference), and this
# benchmark's real-AWS test account has no default VPC. Only create real
# infrastructure when the caller hasn't supplied their own.
resource "aws_vpc" "benchmark" {
  count                = var.vpc_id == "" ? 1 : 0
  cidr_block           = "10.70.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.name != "" ? var.name : "benchmark"}-vpc"
  }
}

data "aws_availability_zones" "benchmark" {
  state = "available"
}

resource "aws_subnet" "benchmark" {
  count                   = var.vpc_id == "" ? 1 : 0
  vpc_id                  = aws_vpc.benchmark[0].id
  cidr_block              = "10.70.0.0/24"
  availability_zone       = data.aws_availability_zones.benchmark.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name != "" ? var.name : "benchmark"}-subnet"
  }
}

resource "aws_internet_gateway" "benchmark" {
  count  = var.vpc_id == "" ? 1 : 0
  vpc_id = aws_vpc.benchmark[0].id
}

resource "aws_route_table" "benchmark" {
  count  = var.vpc_id == "" ? 1 : 0
  vpc_id = aws_vpc.benchmark[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.benchmark[0].id
  }
}

resource "aws_route_table_association" "benchmark" {
  count          = var.vpc_id == "" ? 1 : 0
  subnet_id      = aws_subnet.benchmark[0].id
  route_table_id = aws_route_table.benchmark[0].id
}

locals {
  effective_vpc_id    = var.vpc_id != "" ? var.vpc_id : aws_vpc.benchmark[0].id
  effective_subnet_id = var.subnet != "" ? var.subnet : aws_subnet.benchmark[0].id
}

# var.ssh_key_pair had no default in the original template (a real EC2 key
# pair name with no aws_key_pair resource creating it) -- disposable
# self-contained key so instance creation doesn't fail on a missing key pair.
resource "aws_key_pair" "benchmark" {
  key_name   = var.ssh_key_pair
  public_key = "ssh-rsa  benchmark-disposable-key"
}

data "aws_caller_identity" "replica1_bucket_owner" {
    provider = aws.replica1
}

resource "aws_kms_key" "replicakey1" {
    provider                = aws.replica1
    description             = "This key is used to encrypt dest bucket objects"
    deletion_window_in_days = 10
}

resource "aws_kms_alias" "replicakey1"  {
    provider      = aws.replica1
    name          = "alias/replicakey1"
    target_key_id = aws_kms_key.replicakey1.key_id
}

resource "aws_s3_bucket" "replica1" {
    provider         = aws.replica1
    count            = sum([for _, names in var.s3_bucket_names : length(names)])
    acl              = "private"
    bucket           = "${flatten([for _, names in var.s3_bucket_names : names ])[count.index]}-replica1-${data.aws_caller_identity.replica1_bucket_owner.account_id}"

    versioning {
        enabled = true
    }

    server_side_encryption_configuration {
        rule {
            apply_server_side_encryption_by_default {
                kms_master_key_id = aws_kms_key.replicakey1.arn
                sse_algorithm     = "aws:kms"
            }
        }
    }

    tags = {
        Env = var.env
    }
}
resource "aws_s3_bucket_public_access_block" "replica1" {
    provider = aws.replica1
    count    = sum([for _, names in var.s3_bucket_names : length(names)])
    bucket   = aws_s3_bucket.replica1[count.index].id

    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
}

data "aws_caller_identity" "replica2_bucket_owner" {
    provider = aws.replica2
}

resource "aws_kms_key" "replicakey2" {
    provider                = aws.replica2
    description             = "This key is used to encrypt dest bucket objects"
    deletion_window_in_days = 10
}

resource "aws_kms_alias" "replicakey2"  {
    provider      = aws.replica2
    name          = "alias/replicakey2"
    target_key_id = aws_kms_key.replicakey2.key_id
}

resource "aws_s3_bucket" "replica2" {
    provider         = aws.replica2
    count            = sum([for _, names in var.s3_bucket_names : length(names)])
    acl              = "private"
    bucket           = "${flatten([for _, names in var.s3_bucket_names : names ])[count.index]}-replica2-${data.aws_caller_identity.replica2_bucket_owner.account_id}"

    versioning {
        enabled = true
    }

    server_side_encryption_configuration {
        rule {
            apply_server_side_encryption_by_default {
                kms_master_key_id = aws_kms_key.replicakey2.arn
                sse_algorithm     = "aws:kms"
            }
        }
    }

    tags = {
        Env = var.env
    }
}
resource "aws_s3_bucket_public_access_block" "replica2" {
    provider = aws.replica2
    count    = sum([for _, names in var.s3_bucket_names : length(names)])
    bucket   = aws_s3_bucket.replica2[count.index].id

    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
}

output "varname" {
  value = var.s3_bucket_names
}

